// Now that thumbnails are generated by the backend's ffmpeg (off-process)
// instead of hidden <video> elements in the renderer, the renderer no
// longer competes with the main player for GPU decode slots. The bottleneck
// is backend ffmpeg subprocess throughput, not GPU contention.
//
// Concurrency was 8 originally, lowered to 4 after a VR user reported
// startup timeouts on 6K/8K HEVC content: software HEVC decode at 8K
// runs ~5-10 fps, and 8 simultaneous decodes saturate a typical desktop
// CPU so badly that each subprocess exceeds its 60s timeout. Halving to
// 4 keeps per-decode CPU headroom while still parallelising the common
// H.264 case. If you raise this again, benchmark against an 8K HEVC
// sample (`Test.mp4` is H.264 1080p — won't catch the regression).
const MAX_CONCURRENT_THUMBNAILS = 4;

/**
 * Resolve the seek percentage for a video's thumbnail from its optional
 * custom-thumbnail override. Returns the clamped 0..1 `seekPct` when the
 * user pinned a specific frame, else the default 10% mark. Kept pure +
 * exported so the override/clamp rules are unit-testable.
 *
 * @param {{seekPct?: number}|undefined|null} custom
 * @returns {number}
 */
export function resolveThumbSeekPct(custom) {
  const pct = custom?.seekPct;
  if (typeof pct === 'number' && isFinite(pct)) {
    return Math.min(0.999, Math.max(0, pct));
  }
  return 0.1;
}

/**
 * Build the backend thumbnail-request options for a video's optional
 * custom-thumbnail override. A user-picked frame requests `exact: true`
 * so the backend grabs the frame AT the picked timestamp (frame-accurate,
 * matching the picker's WYSIWYG preview) instead of the default fast path
 * (nearest keyframe + a 10s minimum seek), which silently produced a
 * different frame than the one chosen. Auto thumbs (no override) keep the
 * cheap default — the bulk library queue never pays the exact-decode cost.
 *
 * @param {{seekPct?: number}|undefined|null} custom
 * @returns {{seekPct: number, exact: boolean}}
 */
export function thumbRequestOpts(custom) {
  const hasPin = typeof custom?.seekPct === 'number' && isFinite(custom.seekPct);
  return { seekPct: resolveThumbSeekPct(custom), exact: hasPin };
}

/**
 * Resolve a user-uploaded custom thumbnail IMAGE from a video's override
 * entry. Returns the cached image path for `{ type: 'image', imagePath }`
 * entries, else null (frame pins and legacy `{ seekPct }` entries are
 * handled by `thumbRequestOpts`). Pure + exported so all thumb surfaces
 * (library, playlists, categories, Up Next) share one rule.
 *
 * @param {{type?: string, imagePath?: string}|undefined|null} custom
 * @returns {string|null}
 */
export function customThumbImagePath(custom) {
  return (custom?.type === 'image'
    && typeof custom.imagePath === 'string'
    && custom.imagePath.length > 0) ? custom.imagePath : null;
}

/**
 * Every funscript the scan found in `videoPath`'s own folder (not its
 * subfolders), by name in natural order ("Clip 2" before "Clip 10"). The
 * Associate dialog lists these when none of the library's unmatched scripts
 * matches the video's name: it used to say "No funscripts found in
 * directory" with 14 scripts next to the video (CB-17). Pure.
 *
 * @param {string} videoPath
 * @param {Array<{name: string, path: string}>} scripts — the scan's funscripts
 * @returns {Array<{name: string, path: string}>}
 */
export function funscriptsInFolderOf(videoPath, scripts) {
  const folderOf = (p) => {
    const c = canonicalPath(p).toLowerCase();
    return c.slice(0, Math.max(0, c.lastIndexOf('/')));
  };
  const folder = folderOf(videoPath);
  if (!folder || !Array.isArray(scripts)) return [];
  const seen = new Set();
  return scripts
    .filter((s) => s?.path && folderOf(s.path) === folder
      && !seen.has(canonicalPath(s.path).toLowerCase()) && seen.add(canonicalPath(s.path).toLowerCase()))
    .map((s) => ({ name: s.name || s.path.split(/[\\/]/).pop(), path: s.path }))
    .sort((a, b) => compareNames(a.name, b.name));
}

/**
 * Is the docked script editor open and on screen? It has its own Ctrl+A and
 * Esc, so the Library's Ctrl+A and a playlist's Select-mode keys stand back
 * while it is. Its panel is built at app start, and a closed one is only
 * inert (no `--open` class), never `[hidden]`: the old test,
 * `.script-editor:not([hidden])`, matched the CLOSED panel, so Ctrl+A in the
 * Library (also in v0.9.2) and Esc / Ctrl+A in a playlist's Select mode never
 * did anything in the real app (block E2 verify-1). An open editor is not on
 * screen while the pop-out holds it (the panel is `hidden`), behind another
 * view (the player view is `hidden`) or in the mini player (editor.css hides
 * it there).
 */
export function dockedEditorOnScreen(doc = document) {
  const panel = doc.querySelector('.script-editor.script-editor--open');
  return !!panel && !panel.closest('[hidden], .player-container--mini');
}

export class Library {
  constructor({ onPlayVideo, onBack, onAddSource, onTestDevice, onOpenVRFormat, getEmbeddedAxes, detectEmbeddedAxesForPath, onExtractEmbeddedAxes, onAddToQueue, onPlayAll, onToggleQueue, isQueueOpen, getPlayingScript, onPairScript, settings }) {
    this._onPlayVideo = onPlayVideo;
    // A script's "Pair with a video…" (the Scripts filter, 2026-11-26).
    this._onPairScript = onPairScript || null;
    this._onBack = onBack;
    // Play a list as an auto-advancing queue (shared with playlists'
    // Play-All). Used by the header Shuffle All button.
    this._onPlayAll = onPlayAll || null;
    // Toggle the queue panel from the library header (parity with the
    // player top-bar toggle; reachable while the detached player is open).
    this._onToggleQueue = onToggleQueue || null;
    // () => boolean. The header is rebuilt on every show(), so its queue
    // toggle has to ASK whether the panel is open: a hard-coded "false"
    // read unpressed over an open panel (V26).
    this._isQueueOpen = isQueueOpen || null;
    this._onAddSource = onAddSource || null;
    this._onTestDevice = onTestDevice || null;
    this._onOpenVRFormat = onOpenVRFormat || null;
    this._getEmbeddedAxes = getEmbeddedAxes || null;
    this._detectEmbeddedAxesForPath = detectEmbeddedAxesForPath || null;
    this._onExtractEmbeddedAxes = onExtractEmbeddedAxes || null;
    this._onAddToQueue = onAddToQueue || null;
    // (videoPath) => the script path playing for that video in the player,
    // or null: the Associate dialog marks that variation (FN-03).
    this._getPlayingScript = getPlayingScript || null;
    this._settings = settings;

    // Wire the manual VR override store. Per-call closure over `_settings`
    // so any setting change is reflected immediately on the next read —
    // no re-registration needed on writes. Settings layer caches reads
    // so this stays cheap even when called from filter passes that hit
    // every video in the library.
    //
    // Layering (Phase 1 of VR-flatten expansion, 2026-05-21):
    //   1. `library.vrFormat[path].projection === 'flat'` → 'flat' wins
    //      (user explicitly flagged as not VR via the new panel).
    //   2. Any other vrFormat projection → 'vr' wins (a manual VR
    //      projection implies the file IS VR — keeps the filter agreement).
    //   3. No vrFormat entry → fall back to the lightweight
    //      `library.manualVRType` toggle (existing kebab item).
    setVRTypeOverrideStore((path) => {
      const fmt = this._settings.get('library.vrFormat') || {};
      const entry = fmt[path];
      if (entry?.projection === 'flat') return 'flat';
      if (entry?.projection && entry.projection !== 'flat') return 'vr';
      const map = this._settings.get('library.manualVRType') || {};
      return map[path] || null;
    });
    this._container = null;
    this._videos = [];
    this._dirPath = null;
    this._durationCache = new Map(); // path → duration (survives re-scans)
    this._observer = null;
    this._pendingThumbnails = [];
    this._activeThumbnails = 0;
    // True between a completed scan and the initial-viewport thumbnail
    // queue fully draining. While true, an overlay blocks clicks on the
    // grid — prevents the user from starting playback during the window
    // when 3 concurrent hidden <video> decoders are still generating
    // thumbnails and would otherwise contend with the main player for
    // GPU decode slots (= visible jitter on the main playback).
    this._initialThumbsLoading = false;
    this._openMenu = null;
    this._boundCloseMenu = (e) => this._handleOutsideClick(e);
    // The video options dialog (DESIGN-video-options.md (b)): open from a
    // card's ⋮ until the user is done with it (a big action's reopen
    // included). While open, the background polls leave the grid alone and
    // say so in `_renderOwedOnClose`; the close renders once, then the
    // focus goes back to the ⋮, found by path.
    this._videoOptionsOpen = false;
    this._renderOwedOnClose = false;
    // Set by the keydown that makes a keyboard `contextmenu` (Shift+F10,
    // the Menu key), so that event opens the dialog, not the quick menu.
    this._contextMenuByKey = false;
    this._selectMode = false;
    this._selectedPaths = new Set();
    // Where a shift-click range starts. Set by a plain click, deliberately
    // NOT moved by a shift-click so a range can be extended repeatedly.
    this._selectionAnchor = null;
    this._unmatchedFunscripts = [];
    this._unmatchedSubtitles = [];
    this._activeTab = 'matched';
    // The Scripts filter's pills: the scripts no video uses, or every script
    // (2026-11-26). Unassigned at every start.
    this._scriptsScope = 'unassigned';
    this._searchQuery = '';
    this._sortKey = 'name:asc';
    // View mode + folder-browse persist across app restarts — searched queries
    // and filters are intentionally session-only, but layout preference isn't.
    this._viewMode = this._settings.get('library.viewMode') === 'list' ? 'list' : 'grid';
    this._folderBrowse = !!this._settings.get('library.folderBrowse');
    this._currentFolderPath = null; // null = root (one card per source). Canonical path otherwise.
    this._folderIndex = null;     // Map<canonicalPath, FolderNode> — built lazily from _videos after scan
    this._searchGlobalOverride = false; // when true + folder view + query: search the whole library, not just current folder
    this._unavailablePaths = new Set();
    this._scanning = false;
    this._lastScanKey = null;

    // Hover preview state (singleton video element — avoids Electron memory leak #18277)
    this._previewVideo = null;
    this._previewCanvas = null;
    this._previewCtx = null;
    this._previewRaf = null;
    this._previewCycleTimer = null;
    this._previewCycleIndex = 0;
    this._previewGeneration = 0;
    this._previewHoverTimer = null;
    this._isVideoPlaying = false; // set by app.js to gate preview

    // Right-click context menu for "Add to queue" / "Add to queue (next)".
    // Delegated on document so it catches cards across grid and list
    // views without per-card listener overhead. Resolves the card via
    // closest('.library__card, .library__list-item') and reads
    // dataset.videoPath. SCOPE-queue-panel.md §4.6.
    // Always on now: it also offers "All options…", and a keyboard
    // contextmenu on a card opens the video options dialog.
    document.addEventListener('contextmenu', (e) => this._handleCardContextMenu(e));
    // A keyboard contextmenu follows its keydown; a mouse one follows a
    // press. Remember which came last (capture: seen before anything else).
    document.addEventListener('keydown', (e) => {
      this._contextMenuByKey = e.key === 'ContextMenu' || (e.key === 'F10' && e.shiftKey && !e.ctrlKey && !e.altKey);
    }, true);
    document.addEventListener('mousedown', () => { this._contextMenuByKey = false; }, true);
    // Alt+Enter on a focused card control (the ⋮ is its Tab stop): the
    // video's options, as Windows' "Properties" key. Free in keyboard.js.
    document.addEventListener('keydown', (e) => this._handleCardOptionsKey(e));

    // Virtual-scroll resize handling. `_vsColumns` is computed once per
    // `_renderGrid` call; without a resize listener, going from a small
    // window to fullscreen leaves the cached column count stale and the
    // visible-range math misaligns (cards overlap / empty rows appear on
    // scroll). Debounced so maximise animation doesn't spawn one update
    // per animation frame.
    this._resizeDebounceTimer = null;
    this._resizeListenerAttached = false;
    // At the end of the grid when this burst of resize events began (E2-05
    // fix-up). Read on the FIRST event, not in the debounced handler: by
    // then Chromium's scroll anchoring has moved scrollTop as the narrower
    // grid grew, and its scroll event re-read `_vsAtEnd` against the grown
    // extent (false), so a big narrowing (2560 -> 1280 px, maximised ->
    // restored) landed 540-626 px short of the end (block E2 verify-2). The
    // resize event comes before that scroll event, so `_vsAtEnd` still holds
    // the user's last position here.
    this._resizeAtEndLatch = null;
    this._onResize = () => {
      if (this._resizeAtEndLatch === null) this._resizeAtEndLatch = !!this._vsAtEnd || !!this._vsTailPin;
      clearTimeout(this._resizeDebounceTimer);
      this._resizeDebounceTimer = setTimeout(() => this._handleResize(), 100);
    };
  }

  show(containerEl) {
    this._container = containerEl;

    // Wire the resize listener once per show. The cached `_vsColumns`
    // only updates inside `_renderGrid`; without this, a window resize
    // (tile → fullscreen, maximise, etc.) leaves virtual scroll using
    // the old column count → scroll goes haywire.
    if (!this._resizeListenerAttached) {
      window.addEventListener('resize', this._onResize);
      this._resizeListenerAttached = true;
    }

    // Ctrl/Cmd+A — select everything in the current filter.
    //
    // Bound once, on document, and gated three ways: the library must be the
    // visible view, the event must not come from a text field (or we hijack
    // "select all" while someone is editing the search box), and the script
    // editor must not be open (it has its own Ctrl+A for actions).
    if (!this._selectAllListenerAttached) {
      this._onSelectAllKey = (e) => {
        if (e.key !== 'a' && e.key !== 'A') return;
        if (!(e.ctrlKey || e.metaKey) || e.altKey || e.shiftKey) return;
        if (!this._container || this._container.offsetParent === null) return;
        const el = document.activeElement;
        const tag = el?.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA' || el?.isContentEditable) return;
        if (dockedEditorOnScreen()) return; // the editor's own Ctrl+A
        e.preventDefault();
        const n = this.selectAllVisible();
        import('../js/toast.js').then(({ showToast }) => {
          showToast(t('library.selectedAll', { count: n }), 'info');
        });
      };
      document.addEventListener('keydown', this._onSelectAllKey);
      this._selectAllListenerAttached = true;
    }

    // Re-translate dynamic strings on locale change. Most library text is
    // baked into innerHTML via `t()` at render time (kebab menu items,
    // empty states, sort/filter pickers, badges, etc.) — `translatePage()`
    // only catches `data-i18n` attributes, so without this, switching
    // language leaves the library partially in the old locale until the
    // user navigates away and back. Subscribed once per Library instance.
    // Repaint category marks when a category is edited.
    //
    // `category:changed` was emitted by dataService and NOBODY LISTENED, so
    // renaming a category or giving it an icon left every already-rendered
    // card showing the old mark until the view was rebuilt for some other
    // reason. Reported as "they don't change when edited".
    //
    // Only the colour/icon/rename actions need this; assign/unassign already
    // repaint their own card at the call site.
    if (!this._categoryListenerAttached) {
      eventBus.on('category:changed', ({ action } = {}) => {
        if (!this._container) return;
        if (!['icon', 'color', 'rename', 'add', 'delete'].includes(action)) return;
        this._repaintAllCategoryDots();
      });
      this._categoryListenerAttached = true;
    }

    if (!this._languageListenerAttached) {
      eventBus.on('language:changed', () => {
        if (!this._container) return;
        // Refresh the cached header title — t() captures the active locale
        // at call time, so the value set in show() is stale once the user
        // switches. Only refresh the generic "Library" label, not collection
        // names (those come from user-entered text and stay as-is).
        if (!this._activeCollectionId) {
          this._headerTitle = t('nav.library');
        }
        // Re-render the header + chip strip (covers Sort/Filters trigger
        // labels, view-toggle aria, selection-bar buttons, search aria,
        // and any t()-baked text in `_renderWithHeader`). The grid is
        // re-emitted by `_applyFilters` so kebab tooltips, badges, and
        // multi-axis labels pick up the new locale on the next pass.
        //
        // `_renderWithHeader` internally wires `_buildSortPicker` and
        // `_buildFiltersPicker` — don't call them again here, or
        // `_wirePickerDismissal` attaches duplicate document-level
        // listeners that fight each other (first closes the popover the
        // second just opened, making both triggers feel "dead").
        if (this._videos?.length > 0) {
          this._renderWithHeader();
          this._applyFilters();
        } else if (this._container.querySelector('.library__empty')) {
          // The empty library too: on a first launch the language is chosen
          // over it (test day 2026-11-24, B007: German chosen, the empty
          // state stayed English).
          this._renderEmpty();
        }
      });
      this._languageListenerAttached = true;
    }

    // Folder-previews toggle needs an immediate re-render (it changes what
    // already-rendered folder cards show). Moving-previews is a hover-time
    // gate so it doesn't need this. Subscribed once per instance.
    if (!this._folderPreviewsListenerAttached) {
      eventBus.on('settings:changed', ({ path }) => {
        if (path === 'library.folderPreviews' && this._videos?.length > 0) {
          this._applyFilters();
        }
      });
      this._folderPreviewsListenerAttached = true;
    }

    // A script the app's editor saved in place (same path) has to be read
    // again: a script read once this session is painted from what that read
    // left on the video (`_statsReadFor`, V81), so without this the speed
    // badge, heatmap, embedded-axes badge and the speed sorts kept the
    // pre-edit values until the next scan (V81 review).
    if (!this._scriptSavedListenerAttached) {
      eventBus.on('funscript:saved', ({ path } = {}) => this._forgetScriptRead(path));
      this._scriptSavedListenerAttached = true;
    }

    // The one tag index (design (e)) re-indexes when a tag map is written
    // (the dialog's Tags section, a Get tags, a download's record, the scan's
    // re-home) or the script files' own metadata changes (the harvest,
    // script-meta-store.js); the grid follows when the Tags filter or the
    // cards' tag line reads it. Subscribed once per instance.
    if (!this._tagDataListenerAttached) {
      eventBus.on('settings:changed', ({ path } = {}) => {
        if (TAG_DATA_KEYS.includes(path) || path === 'library' || isStashSettingPath(path)) this._onTagDataChanged();
      });
      onScriptMetaChanged(() => this._onTagDataChanged());
      // Stash S1: main's Stash data changed (a sync, a link, an Undo, a
      // re-home, Remove): its tags, performers and studios re-index.
      onStashChanged(() => this._onTagDataChanged());
      this._tagDataListenerAttached = true;
    }

    // Stash's sorts and filter (the "next" lot): its rows follow the switch,
    // and the grid follows the data while a Stash sort or filter reads it.
    if (!this._stashLibraryListenerAttached) {
      eventBus.on('settings:changed', ({ path } = {}) => {
        if (isStashSettingPath(path)) this._onStashLibraryChanged();
      });
      onStashChanged(() => this._onStashLibraryChanged());
      this._stashLibraryListenerAttached = true;
    }

    // Resolve which directories to scan — all enabled sources, excluding unavailable (disconnected drives).
    // `library.directory` is a legacy singleton setting that app.js migrates into `library.sources` on
    // startup, so there's no need to fall back to it here.
    const sources = this._settings.get('library.sources') || [];
    const unavailable = this._unavailablePaths || new Set();
    const activeSources = sources.filter(s => s.enabled !== false && !unavailable.has(s.path));

    const sourceMap = {}; // path → name for VR content server grouping
    for (const s of activeSources) sourceMap[s.path] = s.name;
    const scanPaths = activeSources.map(s => s.path);

    this._sourceMap = sourceMap;
    this._dirPath = scanPaths.length > 0 ? scanPaths[0] : null;

    // Determine header title and subtitle based on active view
    const availableSources = sources.filter(s => s.enabled !== false && !unavailable.has(s.path));
    if (this._activeCollectionId) {
      const collections = this._settings.get('library.collections') || [];
      const col = collections.find(c => c.id === this._activeCollectionId);
      this._headerTitle = col ? col.name : t('nav.library');
      // Prefer the sync folder for synced collections (more informative
      // than the common ancestor of a possibly-empty additive list).
      // Fall back to common-ancestor of the frozen videoPaths for
      // legacy collections, then to the source summary.
      const syncFolder = col?.syncSource?.folderPath
        || (col?.syncSource?.sourceId
              ? sources.find(s => s.id === col.syncSource.sourceId)?.path
              : null);
      const ancestor = syncFolder
        || (col?.videoPaths?.length ? commonAncestorOfFiles(col.videoPaths) : '');
      if (ancestor) {
        this._headerPath = ancestor;
      } else {
        this._headerPath = availableSources.length === 1
          ? availableSources[0].path
          : t('library.sourceCount', { count: availableSources.length }); // in the language chosen (B102)
      }
    } else {
      this._headerTitle = t('nav.library');
      this._headerPath = availableSources.length > 1
        ? availableSources.map(s => s.name).join(', ')
        : (this._dirPath || '');
    }

    // Check if we can skip re-scan (same paths, already have videos)
    const scanKey = scanPaths.sort().join('\0');
    const canSkip = this._lastScanKey === scanKey && this._videos.length > 0;

    if (scanPaths.length > 0) {
      this._renderWithHeader();
      if (canSkip) {
        // Re-render with cached videos (no re-scan needed)
        this._applyFilters();
      } else {
        this._lastScanKey = scanKey;
        // Returned so a caller that needs the result can wait for it (Recheck
        // reports what the rescan found). Every other caller ignores it.
        return this._scanDirectory(scanPaths.length === 1 ? scanPaths[0] : scanPaths, sourceMap);
      }
    } else {
      // No source switched on at all: no list of old videos behind the empty
      // state (R3-12). Sources that are on but all offline keep it.
      const noneOn = !sources.some((s) => s?.path && s.enabled !== false);
      if (noneOn) this._forgetVideosNoSource();
      // Saved streams (2026-11-23): a library of streams alone is still a
      // library, shown with its header (the folder menu adds a source).
      if (noneOn && (this._settings.get(SETTING_STREAMS) || []).length) {
        this._mergeStreams();
        this._lastScanKey = null;
        this._renderWithHeader();
        this._applyFilters();
        return;
      }
      this._renderEmpty();
    }
  }

  /**
   * Force a full library rescan, busting the per-source `_lastScanKey`
   * cache that normally skips re-scans when the configured source
   * paths haven't changed. Wired to the header refresh button.
   *
   * Picks up files added to source folders since the last scan (e.g.
   * the user dropped a video into a sync-with-folder source via File
   * Explorer). Synced collections automatically refresh their
   * membership because `expandSyncedMembership` runs on every
   * `_applyFilters` pass.
   *
   * Idempotent — multiple clicks during an in-flight scan no-op
   * (`_scanning` flag gates the rescan).
   */
  async refresh() {
    // A scan is running: run once more when it ends, so what changed since it
    // started (a folder back, a drive plugged in) is not missed. The press
    // was dropped (test day 2026-11-24, B023).
    if (this._scanning) { this._refreshAgain = true; return; }
    const btn = this._container?.querySelector('.library__refresh-btn');
    if (btn) btn.classList.add('library__refresh-btn--spinning');
    const { showToast } = await import('../js/toast.js');
    const beforePaths = new Set(this._videos?.map(v => v.path) || []);

    // Re-resolve the scan paths the same way show() does (mirrors
    // lines 119–125 — sources filtered to enabled + available). Direct
    // scan-call path avoids re-rendering the entire header DOM, so the
    // refresh button reference stays valid for the spinner class.
    const sources = this._settings.get('library.sources') || [];
    const unavailable = this._unavailablePaths || new Set();
    const activeSources = sources.filter(s => s.enabled !== false && !unavailable.has(s.path));
    const sourceMap = {};
    for (const s of activeSources) sourceMap[s.path] = s.name;
    const scanPaths = activeSources.map(s => s.path);
    if (scanPaths.length === 0) {
      if (btn) btn.classList.remove('library__refresh-btn--spinning');
      // Sources on but none reachable: say which, not "no source folders"
      // (test day 2026-11-26, B100).
      const offline = this._offlineSources();
      if (offline.length) showToast(t('library.sourceUnavailable', { names: offline.map(sourceLabel).join(', ') }), 'warn', 5000);
      else showToast(t('library.noSourcesToRefresh'), 'warn', 3000);
      return;
    }

    this._lastScanKey = scanPaths.sort().join('\0');
    // Look at the no-picture files again (N-05): one replaced by a real
    // video during the session would otherwise keep the logo tile until a
    // relaunch. The backend re-checks by size and mtime, so this costs one
    // cached answer per audio file.
    this._noVideoThumbs?.clear();
    try {
      await this._scanDirectory(scanPaths.length === 1 ? scanPaths[0] : scanPaths, sourceMap);
      // A Set both ways: `afterPaths.includes` inside the filter was
      // O(before x after), 2.4 million comparisons on a 1,547-video library.
      const afterPaths = new Set(this._videos?.map(v => v.path) || []);
      const added = [...afterPaths].filter(p => !beforePaths.has(p)).length;
      const removed = [...beforePaths].filter(p => !afterPaths.has(p)).length;
      if (added === 0 && removed === 0) {
        showToast(t('library.refreshedNoChanges'), 'info', 2500);
      } else {
        const parts = [];
        if (added > 0) parts.push(t('library.refreshNewVideos', { count: added }));
        if (removed > 0) parts.push(t('library.refreshRemoved', { count: removed }));
        showToast(t('library.refreshedSummary', { parts: parts.join(', ') }), 'info', 3000);
      }
    } catch (err) {
      console.error('[Library] refresh failed:', err);
      showToast(t('library.refreshFailed', { error: err?.message || 'unknown error' }), 'error', 4000);
    } finally {
      if (btn) btn.classList.remove('library__refresh-btn--spinning');
    }
  }

  hide() {
    this._closeMenu();
    this._exitSelectMode();
    this._stopPreview();
    // Preserve _activeTab, _searchQuery, _sortKey, _viewMode across hide/show
    if (this._observer) {
      this._observer.disconnect();
      this._observer = null;
    }
    this._pendingThumbnails = [];
    this._activeThumbnails = 0;
    if (this._resizeListenerAttached) {
      window.removeEventListener('resize', this._onResize);
      this._resizeListenerAttached = false;
    }
    clearTimeout(this._resizeDebounceTimer);
    this._resizeAtEndLatch = null; // a cancelled burst's reading is not the next one's
    // Snapshot grid scroll position so the next show() lands the user
    // back where they clicked the video instead of at the top. The
    // wrapper is about to be destroyed by the innerHTML clear below, so
    // capture before that.
    const wrapper = this._container?.querySelector('.library__grid-wrapper');
    if (wrapper) {
      this._savedScrollOnHide = wrapper.scrollTop;
      // ...and whether that was the bottom, which the rebuilt grid cannot
      // tell the next render (see `keepTail` in _renderGrid, V81).
      this._savedScrollAtBottom = !!this._virtualActive
        && wrapper.scrollTop >= wrapper.scrollHeight - wrapper.clientHeight - Math.max(this._vsRowHeight || 0, 1);
    }
    this._vsTailPin = 0; // the grid it held is going (FT-089)
    if (this._container) {
      this._container.innerHTML = '';
    }
  }

  /**
   * The sources switched on whose location cannot be reached now (the
   * periodic probe, or a scan that just failed). Empty when none is on, or
   * when at least one on is reachable: only then is the library empty
   * because of them (B100).
   * @returns {Array<{path: string, name?: string}>}
   */
  _offlineSources() {
    const on = (this._settings?.get?.('library.sources') || []).filter((s) => s?.path && s.enabled !== false);
    const unavailable = this._unavailablePaths || new Set();
    const failed = this._failedScanPaths || new Set();
    const off = on.filter((s) => unavailable.has(s.path) || failed.has(s.path));
    return on.length > 0 && off.length === on.length ? off : [];
  }

  _renderEmpty() {
    // Sources there, every one switched off: "Add a source folder" was not
    // true (R3 fix-up, real-app verifier 2). The button still adds one.
    const sources = this._settings?.get?.('library.sources') || [];
    const allOff = sources.some((s) => s?.path) && !sources.some((s) => s?.path && s.enabled !== false);
    // Sources on, none of them reachable (a drive unplugged, a folder moved):
    // "Add a source folder" was not true either. Say which, and that the
    // videos come back by themselves (test day 2026-11-26, B100).
    const offline = allOff ? [] : this._offlineSources();
    const text = allOff
      ? t('library.sourcesAllOff', { settings: t('settingsPanel.modalTitle'), tab: t('settingsPanel.tabLibrary') })
      : offline.length
        ? t('library.sourceUnavailable', { names: offline.map(sourceLabel).join(', ') })
        : t('library.noSourcesEmpty');
    const hint = offline.length
      ? `<div class="library__empty-hint">${this._escapeHtml(t('library.sourcesOfflineHint'))}</div>`
      : '';
    this._container.innerHTML = `
      <div class="library__empty">
        <div class="library__empty-icon"></div>
        <div class="library__empty-text">${this._escapeHtml(text)}</div>
        ${hint}
        <button class="library__empty-btn">${this._escapeHtml(t('library.addSourceFolder'))}</button>
      </div>
    `;
    this._container.querySelector('.library__empty-icon')
      .appendChild(icon(FolderOpen, { width: 48, height: 48 }));
    this._container.querySelector('.library__empty-btn')
      .addEventListener('click', () => { if (this._onAddSource) this._onAddSource(); });
  }

  _renderWithHeader() {
    // Header layout was a horizontally-packed strip of `<select>` /
    // tab buttons (Matched, Unmatched, sort, VR filter). Replaced
    // 2026-04-27 with a Sort + Filters trigger pair (each opens its
    // own picker dropdown) plus an active-filter chip strip below.
    // Same pattern the web-remote uses — single source of truth in
    // `renderer/js/filter-chips.js`. Rationale: Nielsen #6 recognition
    // over recall + #8 minimalist design + Shneiderman #6 reversibility
    // (per-chip × undoes that one filter without dismissing all).
    // See SCOPE-desktop-redesign.md §4.4.
    const queueOpen = String(!!this._isQueueOpen?.());
    this._container.innerHTML = `
      <div class="library__header">
        <span class="library__title">${this._escapeHtml(this._headerTitle || t('nav.library'))}</span>
        <span class="library__dir-path" title="${this._escapeHtml(this._headerPath || '')}">${this._escapeHtml(this._headerPath || '')}</span>
        <span class="library__video-count"></span>
        <div class="library__search">
          <span class="library__search-icon" aria-hidden="true"></span>
          <input type="text" class="library__search-input" data-i18n-placeholder="library.search" placeholder="${this._escapeHtml(t('library.search'))}" aria-label="${this._escapeHtml(t('library.searchAria'))}">
          <button class="library__search-clear" hidden aria-label="${this._escapeHtml(t('library.clearSearchAria'))}"></button>
        </div>
        <div class="library__picker library__picker--sort">
          <button class="library__picker-btn" id="library-sort-btn" aria-haspopup="listbox" aria-expanded="false">
            <span class="library__picker-icon" aria-hidden="true"></span>
            <span class="library__picker-label" data-i18n="library.sort">${this._escapeHtml(t('library.sort'))}</span>
            <span class="library__sort-hint" hidden></span>
          </button>
          <div class="library__picker-pop" id="library-sort-pop" role="listbox" hidden></div>
        </div>
        <div class="library__picker library__picker--filters">
          <button class="library__picker-btn" id="library-filters-btn" aria-haspopup="dialog" aria-expanded="false">
            <span class="library__picker-icon" aria-hidden="true"></span>
            <span class="library__picker-label" data-i18n="library.filters">${this._escapeHtml(t('library.filters'))}</span>
            <span class="library__picker-badge" id="library-filters-badge" hidden></span>
          </button>
          <div class="library__picker-pop library__picker-pop--filters" id="library-filters-pop" role="dialog" aria-label="${this._escapeHtml(t('library.filtersPopAria'))}" hidden></div>
        </div>
        <div class="view-toggle-group">
          <button class="view-toggle view-toggle--grid" aria-label="${this._escapeHtml(t('library.gridView'))}" title="${this._escapeHtml(t('library.gridView'))}"></button>
          <button class="view-toggle view-toggle--list" aria-label="${this._escapeHtml(t('library.listView'))}" title="${this._escapeHtml(t('library.listView'))}"></button>
        </div>
        <button class="folder-browse-btn view-toggle--folder" aria-label="${this._escapeHtml(t('library.folderBrowse'))}" title="${this._escapeHtml(t('library.folderBrowse'))}"></button>
        <button class="library__shuffle-btn" aria-label="${this._escapeHtml(t('library.shuffleAll'))}" title="${this._escapeHtml(t('library.shuffleAllTitle'))}"></button>
        <button class="library__play-options-btn" aria-haspopup="dialog" aria-label="${this._escapeHtml(t('library.playOptions.openTitle'))}" title="${this._escapeHtml(t('library.playOptions.openTitle'))}"></button>
        <button class="library__refresh-btn" aria-label="${this._escapeHtml(t('library.refresh'))}" title="${this._escapeHtml(t('library.refreshTitle'))}"></button>
        <button class="library__select-mode-btn">${this._escapeHtml(t('library.select'))}</button>
        <button class="library__queue-toggle" data-queue-toggle aria-controls="queue-panel" aria-label="${this._escapeHtml(t('queuePanel.toggleAria'))}" title="${this._escapeHtml(t('queuePanel.toggleTooltip'))}" aria-pressed="${queueOpen}" aria-expanded="${queueOpen}"></button>
      </div>
      <!-- Stacking order under the header (top to bottom):
             1. Selection bar (multi-select mode)
             2. Breadcrumb (folder-browse mode)
             3. Search-scope pill (folder mode + search)
             4. Active-filter chips
             5. Grid
           Selection bar is OUTERMOST because it represents an
           ephemeral mode the user is actively in (Nielsen #1 —
           current state surfaced first). Breadcrumb tells where the
           user is; chips tell what is narrowing the view; both
           belong closer to the cards they are filtering. Each
           element uses the hidden attribute when empty so unused
           contexts collapse cleanly. -->
      <div class="library__selection-bar" hidden>
        <span class="library__selection-count">${this._escapeHtml(t('library.selectionCount', { count: 0 }))}</span>
        <button class="library__selection-action" data-action="playlist">${this._escapeHtml(t('library.addToPlaylist'))}</button>
        <button class="library__selection-action" data-action="category">${this._escapeHtml(t('library.assignCategory'))}</button>
        <button class="library__selection-action" data-action="collection">${this._escapeHtml(t('library.addToCollection'))}</button>
        <button class="library__selection-action" data-action="script">${this._escapeHtml(t('library.assignScriptBulk'))}</button>
        <button class="library__selection-action" data-action="vrtype">${this._escapeHtml(t('library.vrType'))}</button>
        <button class="library__selection-cancel">${this._escapeHtml(t('library.cancelSelect'))}</button>
      </div>
      <div class="library__breadcrumb" hidden></div>
      <div class="library__search-scope" hidden></div>
      <div class="library__folder-scope" hidden></div>
      <div class="library__chips" id="library-chips" hidden></div>
      <div class="library__grid-wrapper">
        <div class="library__grid"></div>
      </div>
    `;

    // Re-render the breadcrumb whenever the header DOM is rebuilt — the
    // template above sets `library__breadcrumb` to `hidden` by default, and
    // `_applyFilters` only re-shows it inside the collection-state-changed
    // branch. Without this call, returning from the player resets the
    // breadcrumb to invisible even though `_currentFolderPath` is still set
    // and the grid renders the right folder. Workaround was to toggle
    // folder-browse off and on; this removes the need for that.
    this._renderBreadcrumb();

    // Search — restore previous query
    const searchInput = this._container.querySelector('.library__search-input');
    const searchClear = this._container.querySelector('.library__search-clear');
    const searchIconSlot = this._container.querySelector('.library__search-icon');
    if (searchIconSlot) {
      // Visible search affordance — magnifier icon at the left of the
      // input. Complements the placeholder which disappears on focus
      // (Norman signifier; Nielsen #6 recognition over recall).
      searchIconSlot.appendChild(icon(Search, { width: 14, height: 14 }));
    }
    searchClear.appendChild(icon(X, { width: 14, height: 14 }));
    if (this._searchQuery) {
      searchInput.value = this._searchQuery;
      searchClear.hidden = false;
    }
    // Debounce keystroke filtering — cheap on small libraries, essential
    // on big ones where every char would trigger a full filter+re-render.
    let searchDebounce = null;
    searchInput.addEventListener('input', () => {
      this._searchQuery = searchInput.value;
      searchClear.hidden = !searchInput.value;
      if (this._scanning) return;
      clearTimeout(searchDebounce);
      searchDebounce = setTimeout(() => this._applyFilters(), 120);
    });
    searchClear.addEventListener('click', () => {
      searchInput.value = '';
      this._searchQuery = '';
      this._searchGlobalOverride = false; // reset scope escape so next search starts folder-scoped
      searchClear.hidden = true;
      if (!this._scanning) this._applyFilters();
    });

    // Sort + Filters pickers — replace the prior inline `<select>` and
    // tabs. Each is a popover anchored to its trigger button. State
    // commits go through the same callbacks as before so downstream
    // logic (relevance hint, speed-sort disable on unmatched tab,
    // _applyFilters) is unchanged.
    this._buildSortPicker();
    this._buildFiltersPicker();
    // Active filter chips — single source of truth for what's filtered.
    this._renderFilterChips();
    this._syncSortForActiveTab();

    // View toggle — restore previous mode
    const btnGrid = this._container.querySelector('.view-toggle--grid');
    const btnList = this._container.querySelector('.view-toggle--list');
    const btnFolder = this._container.querySelector('.view-toggle--folder');
    btnGrid.appendChild(icon(LayoutGrid, { width: 16, height: 16 }));
    btnList.appendChild(icon(LayoutList, { width: 16, height: 16 }));
    btnFolder.appendChild(icon(Folder, { width: 16, height: 16 }));
    btnGrid.classList.toggle('view-toggle--active', this._viewMode !== 'list');
    btnList.classList.toggle('view-toggle--active', this._viewMode === 'list');
    btnFolder.classList.toggle('view-toggle--active', this._folderBrowse);
    btnGrid.addEventListener('click', () => this._setViewMode('grid'));
    btnList.addEventListener('click', () => this._setViewMode('list'));
    btnFolder.addEventListener('click', () => this._toggleFolderBrowse());

    // Refresh button — pick up new files added to source folders since
    // the app launched. Was a real bug: the library scan cache (gated
    // on `_lastScanKey === scanPaths.sort().join('\0')`) skipped a
    // re-scan whenever the source paths hadn't changed, so users who
    // dropped a video into a sync-with-folder source had to restart
    // the app to see it. The refresh button busts the cache and
    // re-runs the scan; synced collections automatically pick up the
    // new files because `expandSyncedMembership` runs on render.
    const btnRefresh = this._container.querySelector('.library__refresh-btn');
    if (btnRefresh) {
      btnRefresh.appendChild(icon(RotateCcw, { width: 16, height: 16 }));
      btnRefresh.addEventListener('click', () => this.refresh());
    }

    // Shuffle All — play every currently-visible (filtered) video in a
    // random, no-repeat order. Uses the same Play-All queue path as
    // playlists (bag-model shuffle, reshuffle on loop wrap) so behaviour
    // is consistent. Respects the active search/filters/folder scope:
    // it shuffles exactly what the user is looking at.
    const btnShuffle = this._container.querySelector('.library__shuffle-btn');
    if (btnShuffle) {
      btnShuffle.appendChild(icon(Shuffle, { width: 16, height: 16 }));
      btnShuffle.addEventListener('click', () => this._shuffleAllVisible());
    }

    // Play options for Shuffle All and a category's Play all / Shuffle all
    // (#381): Loop, equal turn per script, prefer unwatched. The playlist
    // Advanced dialog's rows, global here. Tinted while any option is on,
    // so a changed shuffle is never a surprise (Nielsen #1).
    const btnPlayOptions = this._container.querySelector('.library__play-options-btn');
    if (btnPlayOptions) {
      btnPlayOptions.appendChild(icon(SlidersHorizontal, { width: 16, height: 16 }));
      this._paintPlayOptionsButton(btnPlayOptions);
      btnPlayOptions.addEventListener('click', () => this._openPlayOptions(btnPlayOptions));
    }

    // Queue panel toggle — far-right of the header for location parity with
    // the player's top-bar queue toggle. Reaches the same queue panel (now
    // a top-level slide-in), so it works while the detached player is open.
    const btnQueue = this._container.querySelector('.library__queue-toggle');
    if (btnQueue) {
      btnQueue.appendChild(icon(Columns2, { width: 16, height: 16 }));
      btnQueue.addEventListener('click', () => { if (this._onToggleQueue) this._onToggleQueue(); });
    }

    // Multi-select
    this._container.querySelector('.library__select-mode-btn')
      .addEventListener('click', () => this._toggleSelectMode());
    this._container.querySelector('.library__selection-cancel')
      .addEventListener('click', () => this._exitSelectMode());
    this._container.querySelector('[data-action="playlist"]')
      .addEventListener('click', () => this._bulkAddToPlaylist());
    this._container.querySelector('[data-action="category"]')
      .addEventListener('click', () => this._bulkAssignCategory());
    this._container.querySelector('[data-action="collection"]')
      .addEventListener('click', () => this._bulkAddToCollection());
    this._container.querySelector('[data-action="vrtype"]')
      .addEventListener('click', () => this._bulkPromptVRType());
    this._container.querySelector('[data-action="script"]')
      .addEventListener('click', () => this._bulkAssignScript());
  }

  /**
   * Shuffle All — play every currently-visible (filtered) video as a
   * random, no-repeat auto-advancing queue. Honours the active
   * search/filter/folder scope by shuffling `_filteredVideos` (exactly
   * what's on screen), then hands off to the shared Play-All path.
   */
  _shuffleAllVisible() {
    const videos = this._filteredVideos || [];
    if (videos.length === 0) {
      import('../js/toast.js').then(({ showToast }) => {
        showToast(t('library.shuffleEmpty'), 'warn');
      });
      return;
    }
    if (!this._onPlayAll) return;
    const videoList = videos.map((v) => ({
      name: v.name || (v.path ? v.path.split(/[\\/]/).pop() : ''),
      path: v.path,
      funscriptPath: v.funscriptPath || null,
    }));
    // The Library's play options (#381), read at click time. All off (the
    // default) this is the request Shuffle All always made.
    this._onPlayAll(videoList, {
      ...libraryPlayRequest(this._settings),
      shuffle: true,
      sourceLabel: this._headerTitle || t('nav.library'),
      sourceContext: { kind: 'library-shuffle' },
    });
  }

  /** Tint the play-options button while any option is on. */
  _paintPlayOptionsButton(btn) {
    btn?.classList.toggle('library__play-options-btn--on', anyLibraryPlayOption(this._settings));
  }

  /** The play-options dialog (#381); each change is saved as it is made. */
  _openPlayOptions(btn) {
    return openPlayOptionsModal({
      title: t('library.playOptions.title'),
      values: readLibraryPlayOptions(this._settings),
      includeLoop: true,
      shuffleOn: true,
      note: t('library.playOptions.shuffleNote'),
      onChange: (key, on) => {
        setLibraryPlayOption(this._settings, key, on);
        this._paintPlayOptionsButton(btn);
      },
    });
  }

  async _scanDirectory(_dirPath, _sourceMap) {
    this._scanning = true;
    this._showLoadingState();
    const _scanT0 = performance.now();

    // try/finally: if ensureScanned throws (permission denied, IPC crash,
    // disk error), we MUST reset _scanning. The flag gates _applyFilters
    // and the scanning-done render path — leaving it stuck at true would
    // freeze every filter, search, and tab-switch until the user
    // restarted the app.
    try {
      await this.ensureScanned({ forceRescan: true });
    } catch (err) {
      console.error('[Library] Scan failed:', err);
      const { showToast } = await import('../js/toast.js');
      showToast(t('library.scanFailed', { error: err.message || err }), 'error', 6000);
    } finally {
      this._scanning = false;
      record(`library scan (${this._videos?.length || 0} videos)`, performance.now() - _scanT0);
      // A Refresh pressed while this scan ran (B023): one more, after it.
      if (this._refreshAgain) {
        this._refreshAgain = false;
        setTimeout(() => { this.refresh?.(); }, 0);
      }
    }

    if (!this._videos || this._videos.length === 0) {
      const countEl = this._container?.querySelector('.library__video-count');
      if (countEl) countEl.textContent = t('library.videoCount', { count: 0 });
      const gridWrapper = this._container?.querySelector('.library__grid-wrapper');
      if (gridWrapper) {
        // Empty-source-dir state — adds an icon + actionable hint
        // (Nielsen #6 recognition over recall + #9 help users recover).
        // Was a single line of text; gave the user no idea what to do
        // next when their source happens to be empty (or filtered to
        // a video-less subfolder).
        gridWrapper.innerHTML = `
          <div class="library__empty">
            <div class="library__empty-icon"></div>
            <div class="library__empty-text">${this._escapeHtml(t('library.emptyTitle'))}</div>
            <div class="library__empty-hint">${this._escapeHtml(t('library.emptyHint'))}</div>
          </div>
        `;
        gridWrapper.querySelector('.library__empty-icon')
          ?.appendChild(icon(FolderOpen, { width: 48, height: 48 }));
      }
      return;
    }

    // Cards and their thumbnail queue are rendered by _applyFilters below.
    // Flip the initial-thumbs flag BEFORE rendering; the phase ends (marks
    // logged, background passes kicked) the first time the queue drains.
    this._initialThumbsLoading = true;
    this._applyFilters();
    this._beginInitialThumbsPhase();
  }

  /**
   * Populate the in-memory video list from the configured sources. Idempotent
   * by default — call with `{ forceRescan: true }` to bypass the populated
   * cache. Used by both the library UI and the VR companion bridge so the
   * matching logic and manual-association application live in one place.
   */
  async ensureScanned({ forceRescan = false } = {}) {
    if (!forceRescan && this._videos?.some((v) => !v._stream)) return;

    const sources = this._settings.get('library.sources') || [];
    const unavailable = this._unavailablePaths || new Set();
    const activeSources = sources.filter(s => s.enabled !== false && !unavailable.has(s.path));

    if (activeSources.length === 0) {
      // Nothing to scan because no source is switched on any more: the
      // library holds nothing, rather than the last scan's videos (R3-12).
      // Sources that are on but all offline keep the list, as before.
      if (!sources.some((s) => s?.path && s.enabled !== false)) this._forgetVideosNoSource();
      return;
    }

    const sourceMap = {};
    for (const s of activeSources) sourceMap[s.path] = s.name;
    const scanPaths = activeSources.map(s => s.path);

    const dirPathArg = scanPaths.length === 1 ? scanPaths[0] : scanPaths;
    // The newest scan wins. Two can overlap (the start-up scan and a Refresh
    // during it): the older one, begun while a folder was missing, finished
    // LAST and wrote its stale list over the newer one, and on to the backend
    // (the phone) and the missing-source guard (test day 2026-11-24, B023).
    const gen = (this._scanGen = (this._scanGen || 0) + 1);
    const result = await window.funsync.scanDirectory(dirPathArg, sourceMap);
    if (gen !== this._scanGen) {
      console.log('[Library] a newer scan started meanwhile: this scan\'s result is dropped');
      return;
    }

    const videos = Array.isArray(result) ? result : (result?.videos || []);
    this._unmatchedFunscripts = Array.isArray(result) ? [] : (result?.unmatchedFunscripts || []);
    this._unmatchedSubtitles = Array.isArray(result) ? [] : (result?.unmatchedSubtitles || []);
    this._allFunscripts = Array.isArray(result) ? [] : (result?.allFunscripts || []);
    this._videos = videos;
    this._videosByPath = new Map(videos.map(v => [v.path, v]));
    // Saved streams join the scanned videos (2026-11-23, SCOPE-saved-streams.md).
    this._mergeStreams();
    this._emptiedNoSource = false; // a scan's list again (R3-12)

    // Sources that FAILED TO SCAN this pass (ENOENT on a disconnected drive).
    //
    // This used to be shown as a toast and then thrown away, which is how
    // 325 association script pointers were nulled on 2026-08-11: the scan
    // knew `D:unsc` had failed, said so in the log, and the association
    // validator was never told — so every script on that drive looked
    // "missing" and got pruned 375ms later.
    //
    // A failed scan is the STRONGEST evidence a location is unreachable,
    // stronger than the periodic probe, because it just tried and failed.
    // It must feed the same guard.
    const failedPaths = Array.isArray(result) ? [] : (result?.failedPaths || []);
    this._failedScanPaths = new Set(failedPaths);
    if (failedPaths.length > 0) {
      const { showToast } = await import('../js/toast.js');
      const names = failedPaths.map(p => p.split(/[\\/]/).pop());
      showToast(t('library.sourceUnavailable', { names: names.join(', ') }), 'warn', 5000);
    }

    // Subfolders the scan could not open (a permission-denied folder, a
    // drive-root system folder) inside a source that otherwise scanned fine.
    // The source is NOT unavailable, so no toast; main.js logs them. But the
    // files in them are missing from this scan for a reason other than
    // deletion, and inside a folder we cannot list, `fs.access` on a file
    // fails with EPERM, which the existence probe reported as "absent" until
    // FT-002 (it is "unknown" now, see path-status.js; this guard stays the
    // first line of defence). So they join the prune guard exactly like a
    // failed source (forum #360, app test V04). Before the scan walked per
    // folder, the whole source failed and was guarded that way.
    this._skippedScanPaths = new Set(Array.isArray(result) ? [] : (result?.skippedPaths || []));

    // Source roots we scanned SUCCESSFULLY this pass. Used as positive
    // evidence when deciding whether a stored association's video is really
    // gone: if its folder was walked and the file was not there, it is gone.
    // A removed source contributes nothing here, which is the point — absence
    // from the list is not evidence of anything. See _isProvablyGone.
    this._scannedSourceRoots = activeSources
      .map((src) => src.path)
      .filter((sp) => sp && !this._failedScanPaths.has(sp) && !this._unavailablePaths?.has(sp));

    this._applyManualAssociations();

    // Restore cached durations from previous scans within the same session
    for (const video of this._videos) {
      const cached = this._durationCache.get(video.path);
      if (cached && !video.duration) video.duration = cached;
    }

    // Hydrate speed stats from the persistent cache. First-session
    // computation is one-time; subsequent launches read the values
    // back instantly so sort-by-speed works without waiting.
    this._hydrateSpeedStatsCache();

    // Same trick for durations — the backend probes via ffprobe after
    // every register, but without a persistent cache the renderer had
    // to wait for that probe on every launch for Sort-by-Duration to
    // work. Keyed by video path.
    this._hydrateDurationCache();

    // Re-register with backend for VR server (with manual associations applied)
    this._registerWithBackend();

    // Build folder-tree index from the freshly-populated video list. Used
    // only by folder-browse view; other views ignore it. Reuses the
    // `sources` list already fetched earlier in this function.
    this._folderIndex = buildFolderIndex(this._videos, sources);

    // Following playlists take in what this scan found (zaikechi #381).
    this.onScanned?.();
  }

  /**
   * No source is switched on any more (the last one removed or switched off,
   * from any view): the library holds no videos, and the phone and VR are
   * told so (R3-12). `ensureScanned` used to return early with nothing to
   * scan and the Library view to draw its empty state over the old list, so
   * `_videos`, everything built from it and the backend registry (GET
   * /api/remote/videos, HereSphere) kept the old videos for the session.
   *
   * Only the in-memory lists change. Nothing stored per video is touched:
   * no association, category, tag, resume position or playlist entry is
   * pruned, and no association pass runs (absence is never destructive).
   * `_emptiedNoSource` tells Up Next this empty list is KNOWN (no source to
   * scan), not "not scanned yet", which it reads as "anything may play"
   * (app.js `_isUpNextPlayable`); set only when there was a list to drop, so
   * a library that never had a source keeps that reading. A scan clears it.
   */
  /**
   * Take a saved stream out of the library (the user's Remove, never an
   * absence): its record, its picture, its place in playlists and its
   * categories. The page itself is not touched.
   */
  removeStream(key) {
    if (!isStreamPath(key)) return false;
    const list = this._settings.get(SETTING_STREAMS) || [];
    if (!list.some((e) => e?.key === key)) return false;
    this._settings.set(SETTING_STREAMS, list.filter((e) => e?.key !== key));
    const thumbs = { ...(this._settings.get('library.customThumbnails') || {}) };
    if (thumbs[key]) { delete thumbs[key]; this._settings.set('library.customThumbnails', thumbs); }
    for (const pl of this._settings.getPlaylists?.() || []) {
      if ((pl.videoPaths || []).includes(key)) this._settings.removeVideoFromPlaylist?.(pl.id, key);
    }
    for (const catId of this._settings.getVideoCategories?.(key) || []) this._settings.unassignCategory?.(key, catId);
    this.onStreamsChanged({ thumb: key });
    return true;
  }

  /**
   * Delete a video's files (2026-11-23, EroScripts #434; DESIGN.md §2.18).
   * Main lists the files that belong to it by name; the plan adds what the
   * library knows and locks anything another video uses; the dialog says
   * exactly what goes and how (Recycle Bin by default, permanent only after
   * its warning and tick box). Then main deletes, the player lets go first
   * if it holds the video, FunSync forgets the video's records, and the
   * library rescans. Never for a saved stream (Remove from library does that).
   * @param {object} video a library video
   * @returns {Promise<boolean>} whether the video was deleted
   */
  async deleteVideo(video) {
    if (!video?.path || video._stream || isStreamPath(video.path)) return false;
    let candidates = [];
    try { candidates = (await window.funsync?.listVideoFiles?.(video.path)) || []; } catch { candidates = []; }
    const settings = {};
    for (const k of ['associations', 'manualVariants', 'subtitleAssociations']) settings[k] = this._settings.get(`library.${k}`) || {};
    const rows = planDeletion({ video, candidates, videos: this._videos || [], settings });
    const { openDeleteDialog } = await import('./delete-files-dialog.js');
    const choice = await openDeleteDialog({
      title: t('library.deleteFiles.title', { name: video.name || '' }),
      intro: t('library.deleteFiles.intro'),
      rows,
      platform: window.funsync?.platform,
      forget: this._forgetDownloadOption(rows.map((r) => r.path)),
    });
    if (!choice) return false;
    return this._runDelete(choice, { videoPath: video.path, subjectPath: video.path });
  }

  /**
   * Delete a script no video uses (the "Scripts without a video" list).
   * The same dialog, with that one file.
   * @param {{ name: string, path: string }} script
   * @returns {Promise<boolean>}
   */
  async deleteLooseScript(script) {
    if (!script?.path) return false;
    let size = Number.isFinite(script.size) ? script.size : null;
    if (size == null) {
      try { size = (await window.funsync?.statVideoFiles?.([script.path]))?.[script.path]?.size ?? null; } catch { size = null; }
    }
    const { openDeleteDialog } = await import('./delete-files-dialog.js');
    const choice = await openDeleteDialog({
      title: t('library.deleteFiles.title', { name: script.name || '' }),
      intro: t('library.deleteFiles.introScript'),
      rows: [{ path: script.path, name: script.name || script.path.split(/[\\/]/).pop(), kind: 'script', label: null,
        size, checked: true, locked: true, subject: true, sharedWith: [], outside: false }],
      platform: window.funsync?.platform,
      forget: this._forgetDownloadOption([script.path]),
    });
    if (!choice) return false;
    return this._runDelete(choice, { videoPath: null, subjectPath: script.path });
  }

  /**
   * Delete what the dialog chose, say what happened, forget a deleted video,
   * rescan. Returns whether the thing being deleted (`subjectPath`: the video,
   * or a loose script) really went.
   */
  /**
   * The delete dialog's offer to forget the EroScripts download of these
   * files (Dave, 2026-11-25: deleted, the post still showed as downloaded on
   * the EroScripts tab), or null when none of them came from a post.
   */
  _forgetDownloadOption(paths) {
    const posts = downloadsFor(this._settings.get(DOWNLOADED_KEY), paths);
    if (!posts.length) return null;
    const title = posts[0].title || '';
    return {
      label: t('library.deleteFiles.forgetDownload'),
      hint: posts.length === 1 && title
        ? t('library.deleteFiles.forgetDownloadHint', { title })
        : t('library.deleteFiles.forgetDownloadHintMany', { count: posts.length }),
      checked: true,
    };
  }

  async _runDelete({ paths, permanent, forget = false }, { videoPath = null, subjectPath = videoPath } = {}) {
    const { showToast } = await import('../js/toast.js');
    try { await this.onBeforeDelete?.(paths); } catch (err) { console.warn('[Delete] releasing the player failed:', err?.message || err); }
    let results = [];
    try {
      results = (await window.funsync.deleteVideoFiles(paths, { permanent })) || [];
    } catch (err) {
      showToast(t('library.deleteFiles.failedAll', { error: err?.message || String(err) }), 'error', 8000);
      return false;
    }
    const done = results.filter((r) => r.ok);
    const failed = results.filter((r) => !r.ok);
    const os = binOs();
    if (done.length) {
      const size = formatFileSize(totalSize(done)) || '';
      showToast(t(permanent ? 'library.deleteFiles.donePermanent' : 'library.deleteFiles.doneBin', { count: done.length, size, os }), 'success', 6000);
    }
    // Never silent (Nielsen #9): which files stayed, and why, in plain words.
    if (failed.length) {
      const why = [...new Set(failed.map((r) => t(`library.deleteFiles.reason.${DELETE_REASON_KEYS[r.reason] || 'other'}`, { os })))].join('; ');
      showToast(t('library.deleteFiles.someFailed', { count: failed.length, reasons: why }), 'error', 10000);
      console.warn('[Delete] not deleted:', failed);
    }
    const videoGone = !!videoPath && done.some((r) => r.path === videoPath);
    if (videoGone) {
      const changed = forgetVideo(this._settings, videoPath);
      console.log(`[Delete] forgot the deleted video's records: ${changed.join(', ') || 'none'}`);
    }
    const donePaths = done.map((r) => r.path);
    if (forget && donePaths.length) {
      const posts = forgetDownloads(this._settings, donePaths);
      if (posts.length) console.log(`[Delete] forgot the EroScripts download of post(s) ${posts.join(', ')}`);
    }
    // The EroScripts tab keeps "this file is there" for the session: it asks again.
    if (donePaths.length) eventBus.emit('library:filesDeleted', { paths: donePaths });
    if (done.length) {
      try { await this.ensureScanned({ forceRescan: true }); } catch (err) { console.warn('[Delete] rescan failed:', err?.message || err); }
    }
    return !!subjectPath && done.some((r) => r.path === subjectPath);
  }

  /** A saved stream's script: kept on its record (library.streams), the list updated. */
  setStreamScript(key, scriptPath) {
    const list = this._settings.get(SETTING_STREAMS) || [];
    if (!list.some((e) => e?.key === key)) return false;
    this._settings.set(SETTING_STREAMS, list.map((e) => (e?.key === key ? { ...e, scriptPath: scriptPath || null } : e)));
    this._mergeStreams();
    return true;
  }

  /** The link icon of a saved stream; its tooltip says where it streams from. */
  _streamBadge(video, extraClass = '') {
    const b = document.createElement('span');
    b.className = `library__stream-badge${extraClass ? ` ${extraClass}` : ''}`;
    const label = video.site ? t('library.streams.badgeSite', { site: video.site }) : t('library.streams.badge');
    b.title = label;
    b.setAttribute('aria-label', label);
    b.appendChild(icon(Link, { width: 13, height: 13, 'stroke-width': 2.5 }));
    return b;
  }

  /**
   * Saved streams in the video list (2026-11-23, SCOPE-saved-streams.md):
   * the scanned files, then every saved stream as a video whose path is its
   * 'stream:' key. Replaced on every scan and every save or removal.
   */
  _mergeStreams() {
    const files = (this._videos || []).filter((v) => !v?._stream);
    const streams = streamVideos(this._settings?.get?.(SETTING_STREAMS));
    // A script paired in the video options dialog (an association under the
    // stream's key) wins over the record's own, as it does for a file.
    const assoc = this._settings?.get?.('library.associations') || {};
    for (const v of streams) {
      if (!assoc[v.path]) continue;
      const resolved = resolveActiveConfig(normalizeAssociation(assoc[v.path]));
      if (resolved?.kind === 'single' && resolved.config) {
        Object.assign(v, { funscriptPath: resolved.config, hasFunscript: true, _manualAssociation: true });
      } else if (resolved?.kind === 'multi' && resolved.config?.main) {
        Object.assign(v, { funscriptPath: resolved.config.main, hasFunscript: true, _manualAssociation: true,
          _multiAxis: { axes: { ...(resolved.config.axes || {}) } } });
      }
    }
    this._videos = [...files, ...streams];
    this._videosByPath = new Map(this._videos.map((v) => [v.path, v]));
  }

  /**
   * A stream was saved, removed or given its picture: the list again, and the
   * grid when it is showing. `thumb`: that stream's card picture changed.
   */
  onStreamsChanged({ thumb = null } = {}) {
    this._mergeStreams();
    if (thumb) thumbCache.remove(thumb, 0);
    if (this._container?.isConnected && !this._scanning) this._applyFilters();
  }

  _forgetVideosNoSource() {
    const had = this._videos.length > 0;
    if (had) this._emptiedNoSource = true;
    this._videos = [];
    this._videosByPath = new Map();
    this._filteredVideos = [];
    this._unmatchedFunscripts = [];
    this._unmatchedSubtitles = [];
    this._allFunscripts = [];
    this._failedScanPaths = new Set();
    this._skippedScanPaths = new Set();
    this._scannedSourceRoots = [];
    this._folderIndex = buildFolderIndex([], this._settings.get('library.sources') || []);
    this._mergeStreams();
    this._lastScanKey = null;
    // The registry only ever holds what a scan or this sent, so with nothing
    // dropped here there is nothing to tell it.
    if (had) this._registerWithBackend();
  }

  /**
   * Apply manual funscript + subtitle associations from settings to the
   * current `_videos` array. Uses exact path match first, then filename
   * fallback so drive-letter changes don't orphan associations.
   */
  _applyManualAssociations() {
    const associations = this._settings.get('library.associations') || {};
    let assocMigrated = false;

    // Re-home entries whose video MOVED, before the per-video pass below.
    // Done up front over the whole set rather than per-video, because the
    // safety rule needs to see both sides at once: a move is only inferred
    // when exactly one orphaned entry and exactly one entry-less video
    // share a filename. The old per-video version matched on basename and
    // took the first hit, which could rob a live video of its association
    // (and delete it) whenever two files shared a name. See
    // association-rehome.js for the full rationale.
    const moves = planAssociationRehome({
      storedPaths: Object.keys(associations),
      scannedPaths: this._videos.map((v) => v.path),
      isUnavailable: (p) => this._isUnderUnavailableSource(p),
      isProvablyGone: (p) => this._isProvablyGone(p),
    });
    for (const { from, to, keepSource } of moves) {
      associations[to] = associations[from];
      // Only delete the old key when the scan PROVED the old file is gone.
      // A removed source looks exactly like a moved file from here, and
      // deleting on that basis means re-adding the source brings the video
      // back with its association silently attached to a different one.
      if (!keepSource) delete associations[from];
      assocMigrated = true;
      console.log(
        `[Associations] Re-homed moved video: ${from} → ${to}`
        + (keepSource ? ' (original kept — its absence is unproven)' : ''),
      );
    }

    for (const video of this._videos) {
      const raw = associations[video.path];
      if (!raw) continue;

      // Upgrade any legacy shape (string / bare multi / {mode:'custom'}) to
      // the new parallel-slot shape on first read, so subsequent reads and
      // writes all work with the same shape. Mark for persistence only if
      // the serialized form actually changed.
      const entry = normalizeAssociation(raw);
      const wasNew = raw && typeof raw === 'object' && 'active' in raw;
      if (!wasNew) {
        associations[video.path] = entry;
        assocMigrated = true;
      }

      const resolved = resolveActiveConfig(entry);
      if (!resolved) continue;

      // What the scan paired by name, before any association replaces it.
      this._rememberOwnScript(video);

      if (resolved.kind === 'single') {
        // The user's choice wins over the scan's same-name sidecar, like a
        // multi or custom association always did (R4-06). This applied only
        // `if (!video.hasFunscript)`, so a script associated under another
        // name was dropped at every scan or reload once the video also had
        // its own `<video>.funscript`. Every 'single' write is a user action
        // (Associate / Change Funscript, bulk assign, an EroScripts download;
        // a legacy bare string came from the first manual Associate). The
        // sidecar stays a variant.
        this._showUserSingle(video, resolved.config);
      } else if (resolved.kind === 'custom') {
        const routes = resolved.config.routes || [];
        const mainRoute = routes.find(r => r.role === 'main');
        if (mainRoute?.scriptPath) {
          video.hasFunscript = true;
          video.funscriptPath = mainRoute.scriptPath;
          video._manualAssociation = true;
          video._customRouting = routes;
          this._leadVariantsWithPlayed(video, mainRoute.scriptPath);
        }
      } else if (resolved.kind === 'multi') {
        const multi = resolved.config;
        const hasAnyScript = !!multi.main || Object.values(multi.axes || {}).some(Boolean);
        if (hasAnyScript) {
          video.hasFunscript = true;
          video.funscriptPath = multi.main || null;
          video._manualAssociation = true;
          // Auto-promoted (or extracted from an auto-paired script): the
          // badge says auto, not manual (V41).
          video._autoAssigned = !!multi.autoAssigned;
          video._multiAxis = multi;
          this._leadVariantsWithPlayed(video, multi.main);
        }
      }

      // Backfill an empty `single` slot from the active mode's main script,
      // so users who were auto-promoted to multi (or manually moved to
      // multi / custom from an auto-pair) on a previous build can still
      // round-trip back to single losslessly. Older write paths left
      // `single: null` for these entries; the modal then showed "No
      // script associated" and the fuzzy search couldn't surface the
      // script either (matched scripts aren't in `_unmatchedFunscripts`).
      // Forward writes now preserve the carry-over; this pass fixes the
      // already-saved entries.
      if (!entry.single) {
        let singleFallback = null;
        if (resolved.kind === 'multi') {
          singleFallback = resolved.config.main || null;
        } else if (resolved.kind === 'custom') {
          const routes = resolved.config.routes || [];
          const mainRoute = routes.find((r) => r.role === 'main');
          singleFallback = mainRoute?.scriptPath || null;
        }
        if (singleFallback) {
          associations[video.path] = buildAssociationEntry(
            entry.active,
            singleFallback,
            entry.multi,
            entry.custom,
          );
          entry.single = singleFallback;
          assocMigrated = true;
        }
      }
    }
    // Auto-promote eligible un-set videos to multi-axis if the user has
    // the global preference set. Sacred associations (single / multi /
    // custom) are skipped — eligibility is `active === null` only. See
    // `notes/features/SCOPE-multi-axis-default.md` for the full matrix.
    const autoPromoted = this._autoPromoteEligibleVideos(associations);

    if (assocMigrated || autoPromoted > 0) {
      this._settings.set('library.associations', associations);
    }

    // Background validation pass — heals or prunes stale associations
    // and manualVariants BEFORE any card renders one. Async + non-blocking
    // so the library appears immediately; if the user happens to interact
    // with a stale entry before validation finishes, the per-read resilient
    // helper catches it as a fallback.
    this._validateAssociationsInBackground();
    this._validateManualVariantsInBackground();

    const subAssociations = this._settings.get('library.subtitleAssociations') || {};
    let subMigrated = false;
    // Subtitles re-home under the SAME guarded planner as the funscript
    // associations above. This was still the first-basename-match-wins loop
    // that association-rehome.js was written to replace: any scanned video
    // without an entry took the first stored entry sharing its filename and
    // DELETED the original. Unplug E: holding E:\VR\x.mp4 with a manual
    // subtitle, keep a C:\Downloads\x.mp4 copy, and the next scan moved the
    // subtitle to C: for good; a live video could lose its own the same way.
    // Offline entries are not candidates, and the old key is deleted only when
    // the scan proves the old file is gone.
    const subMoves = planAssociationRehome({
      storedPaths: Object.keys(subAssociations).filter((p) => subAssociations[p]),
      scannedPaths: this._videos.map((v) => v.path),
      isUnavailable: (p) => this._isUnderUnavailableSource(p),
      isProvablyGone: (p) => this._isProvablyGone(p),
    });
    for (const { from, to, keepSource } of subMoves) {
      subAssociations[to] = subAssociations[from];
      if (!keepSource) delete subAssociations[from];
      subMigrated = true;
      console.log(
        `[Associations] Re-homed moved video's subtitle: ${from} → ${to}`
        + (keepSource ? ' (original kept — its absence is unproven)' : ''),
      );
    }
    for (const video of this._videos) {
      const subPath = subAssociations[video.path];
      if (!video.hasSubtitle && subPath) {
        video.hasSubtitle = true;
        video.subtitlePath = subPath;
        video._manualSubtitle = true;
      }
    }
    if (subMigrated) this._settings.set('library.subtitleAssociations', subAssociations);

    this._rehomeTagsAndCategories();
  }

  /**
   * The video's EroScripts tag record (`settings.library.scriptTags`) and its
   * categories (the ROOT `videoCategories` map, reached through DataService)
   * follow a moved video, under the same planner and the same guards as the
   * associations and subtitles above (FT-005, 2026-11-05; in v0.9.2 too).
   * Nothing re-homed either map before, so moving a video into a subfolder
   * dropped it out of every category it was in, and its tags stayed under a
   * path that no longer existed.
   *
   * Absence is never destructive: a path on an offline source is never a
   * candidate, a filename shared by two stored entries or by two entry-less
   * videos never moves, a video that already has categories (or a tag record)
   * keeps its own, and the old key is deleted only when the scan PROVES the
   * old file is gone. Anything less is a copy.
   *
   * The other per-path maps (manualVRType, vrFormat, customThumbnails,
   * resumePositions, playlist and collection videoPaths, ...) have the same
   * gap and are listed for Dave in notes/TODO.md; this is deliberately only
   * these.
   *
   * Your own tags (`userTags`) and the tags you hid on a video
   * (`hiddenTags`) follow it too (Round 3, 2026-11-18, design (e) "Re-home
   * on move"), planned ONCE with the EroScripts record over the union of the
   * three maps' paths: a video's tag data moves together or not at all. Two
   * old paths of that name in any of the maps is ambiguous (nothing moves,
   * so two old videos' tags never land on one), and a video that already
   * has tag data in any of them keeps its own. A moved EroScripts record
   * that names the old video's same-name script, on a video that now plays
   * its own same-name script, names the new one (the sidecar moved with the
   * video); any other `scriptPath` is kept as it was.
   */
  _rehomeTagsAndCategories() {
    const scannedPaths = this._videos.map((v) => v.path);
    const guards = {
      isUnavailable: (p) => this._isUnderUnavailableSource(p),
      isProvablyGone: (p) => this._isProvablyGone(p),
    };

    this._rehomeTagMaps(scannedPaths, guards);

    // Categories live at the config ROOT, not under settings, so
    // `_settings.get('library.videoCategories')` is always empty (the FT-046
    // search bug). Assign and unassign are DataService's own writes, which
    // keep its cache, main's store and every category view in step.
    const svc = this._settings;
    if (typeof svc.getAllVideoCategories !== 'function'
      || typeof svc.assignCategory !== 'function'
      || typeof svc.unassignCategory !== 'function') return;
    const cats = svc.getAllVideoCategories() || {};
    const catMoves = planAssociationRehome({
      storedPaths: Object.keys(cats).filter((p) => Array.isArray(cats[p]) && cats[p].length > 0),
      scannedPaths,
      ...guards,
    });
    for (const { from, to, keepSource } of catMoves) {
      const ids = [...cats[from]];
      for (const id of ids) svc.assignCategory(to, id);
      if (!keepSource) for (const id of ids) svc.unassignCategory(from, id);
      console.log(
        `[Associations] Re-homed moved video's categories: ${from} → ${to}`
        + (keepSource ? ' (original kept — its absence is unproven)' : ''),
      );
    }
  }

  /**
   * `_rehomeTagsAndCategories`' tag part: `userTags`, `hiddenTags` and
   * `scriptTags` under one plan (see there). A map that is not a plain
   * object (a damaged config) is neither read nor written; an entry counts
   * only when it holds something (a non-empty list, a record object). Each
   * changed map is written once, as a new object; each moved entry is its
   * own copy.
   *
   * Stash S1 (DESIGN-stash-s1.md (c) "Re-home on move"): a video's Stash
   * link, choice or refusal (main's stash/library.json, as the renderer's
   * copy holds it) is tag data too, so its path joins the union and it moves
   * with the rest or not at all. Those moves go to main in ONE call
   * (stash-store.js rehomeStash): main moves them, marks the link to be
   * verified at the next sync, and writes once. Nothing Stash moves here.
   */
  _rehomeTagMaps(scannedPaths, guards) {
    // library.disabledVideos (zaikechi #381) moves with the video too: its value is the time it was disabled.
    const KEYS = ['library.userTags', 'library.hiddenTags', 'library.scriptTags', 'library.disabledVideos'];
    const isMap = (m) => m != null && typeof m === 'object' && !Array.isArray(m);
    const holds = (key, value) => (key === 'library.scriptTags'
      ? value != null && typeof value === 'object' && !Array.isArray(value)
      : key === 'library.disabledVideos' ? value != null
        : Array.isArray(value) && value.length > 0);
    const maps = {};
    const stored = new Set();
    for (const key of KEYS) {
      const map = this._settings.get(key);
      if (!isMap(map)) continue;
      maps[key] = map;
      for (const p of Object.keys(map)) if (holds(key, map[p])) stored.add(p);
    }
    const stashPaths = this._stashDataPaths();
    for (const p of stashPaths) stored.add(p);
    if (stored.size === 0) return;
    const moves = planAssociationRehome({ storedPaths: [...stored], scannedPaths, ...guards });
    if (moves.length === 0) return;

    const next = {};
    const stashMoves = [];
    for (const { from, to, keepSource } of moves) {
      if (stashPaths.has(from)) stashMoves.push({ from, to, keepSource: keepSource === true });
      for (const key of Object.keys(maps)) {
        const map = maps[key];
        if (!Object.prototype.hasOwnProperty.call(map, from) || !holds(key, map[from])) continue;
        // `to` has no tag data in any map (the plan's destination side).
        if (!next[key]) next[key] = { ...map };
        // Its own copy: the two keys must not share one object.
        let entry = structuredClone(map[from]);
        if (key === 'library.scriptTags') entry = this._rehomedTagRecord(entry, from, to);
        next[key][to] = entry;
        if (!keepSource) delete next[key][from];
      }
      console.log(
        `[Associations] Re-homed moved video's tags: ${from} → ${to}`
        + (keepSource ? ' (original kept — its absence is unproven)' : ''),
      );
    }
    for (const key of KEYS) if (next[key]) this._settings.set(key, next[key]);
    if (stashMoves.length > 0) rehomeStash(stashMoves);
  }

  /** The video paths main's Stash data holds something for (a link, a check, a refusal). */
  _stashDataPaths() {
    const out = new Set();
    let data = null;
    try { data = stashData(); } catch { data = null; }
    for (const key of ['links', 'check', 'refused']) {
      const map = data?.[key];
      if (map == null || typeof map !== 'object' || Array.isArray(map)) continue;
      for (const p of Object.keys(map)) {
        const entry = map[p];
        if (p && entry != null && typeof entry === 'object' && !Array.isArray(entry)) out.add(p);
      }
    }
    return out;
  }

  /**
   * A moved EroScripts record's `scriptPath`: the old video's same-name
   * script becomes the new video's, but only when the moved video plays its
   * own same-name script now (the sidecar moved with it). A record naming
   * any other script, or a video that still plays the old file (a hand
   * pairing re-homed with it), keeps the record as it was.
   */
  _rehomedTagRecord(record, from, to) {
    const named = typeof record?.scriptPath === 'string' ? record.scriptPath : '';
    if (!named || !sameScriptPath(named, sameNameScriptPath(from))) return record;
    const playing = this._videosByPath?.get?.(to)?.funscriptPath
      || this._videos?.find?.((v) => v?.path === to)?.funscriptPath || null;
    if (!playing || !sameScriptPath(playing, sameNameScriptPath(to))) return record;
    return { ...record, scriptPath: playing };
  }

  /**
   * Auto-promote videos with detected axis-companion files to
   * multi-axis playback when the user has set Default playback to
   * "Multi-axis when available". Idempotent: only runs against
   * `active === null` entries, so already-set videos (single, multi,
   * custom) are never touched. Mutates the supplied `associations` map
   * AND the in-memory `_videos` so playback picks up immediately.
   * Returns the number of videos that were promoted.
   *
   * Per SCOPE-multi-axis-default.md §1: the toggle is a one-shot
   * promoter, not a runtime preference. Once a video has `active` set
   * (by anything), the global toggle never touches it again — that's
   * how "user had it set previously, toggling off shouldn't revert"
   * works for free.
   */
  _autoPromoteEligibleVideos(associations) {
    if (this._settings.get('player.preferMultiAxis') !== 'multi') return 0;
    if (!this._videos || this._videos.length === 0) return 0;

    const allPaths = (this._allFunscripts || []).map((f) => f.path);
    if (allPaths.length === 0) return 0;

    // Indexed once, not re-walked per video — see buildCompanionIndex.
    const companionIndex = buildCompanionIndex(allPaths);

    let promotedCount = 0;
    for (const video of this._videos) {
      if (!video.hasFunscript || !video.funscriptPath) continue;
      // The first script of a one-video folder (FT-102) is offered, never
      // stored: promoting it saved "Round 1" + its axes as the video's
      // association, which stayed after the setting was switched off.
      if (video._folderVariantMain) continue;
      const entry = normalizeAssociation(associations[video.path]);
      if (entry.active !== null) continue; // sacred — skip
      // A Multi Axis set you saved, which an Unpair kept with nothing active
      // (video-options-model.js `planUnpair`): yours, and Change… can use it
      // again. Promoting would put an auto-paired set over it for good.
      if (handMadeSlots(associations[video.path]).includes('multi')) continue;

      const companions = detectCompanionFilesIndexed(video.funscriptPath, companionIndex);
      if (companions.length === 0) continue;

      const axes = {};
      for (const c of companions) {
        // First-wins per axis suffix — `detectCompanionFiles` doesn't
        // currently de-dupe across directories, but in practice this
        // is an unrealistic edge case for a real library layout.
        if (!axes[c.axis.suffix]) axes[c.axis.suffix] = c.path;
      }

      const multi = {
        main: video.funscriptPath,
        axes,
        buttplugVib: false,
        // Provenance: FunSync paired these by name, the user picked
        // nothing. Kept in the slot so it survives a relaunch; any save
        // through the association modal builds a fresh slot without it.
        // Drives the funscript badge only (V41) — `_manualAssociation`
        // still gates Remove, the modal and the prune logic.
        autoAssigned: true,
      };
      associations[video.path] = buildAssociationEntry(
        'multi',
        // Carry the auto-paired script into the single slot so a later
        // switch back to single via the modal is lossless. Without this,
        // round-tripping multi → single forced the user to re-pick the
        // script (and fuzzy search couldn't surface it either, because
        // matched scripts aren't in `_unmatchedFunscripts`).
        entry.single || video.funscriptPath || null,
        multi,
        entry.custom,
      );

      // Reflect in the in-memory video object so the very next play
      // picks up the multi config without waiting on a rescan.
      video._multiAxis = multi;
      video._manualAssociation = true;
      video._autoAssigned = true;
      promotedCount++;
    }
    return promotedCount;
  }

  /**
   * Count how many videos in the current `_videos` would be promoted by
   * `_autoPromoteEligibleVideos` if the setting were on. Used by the
   * confirmation modal in the settings panel so the user knows the
   * scale of the action before committing. Read-only; does not mutate.
   */
  _countAutoPromotionEligible({ detail = false } = {}) {
    // `detail` also counts the videos WITH companions that already have a
    // playback mode (promoted earlier, or set by the user). With only the
    // eligible count, the confirm said "No videos … have detected companion
    // files" to a library full of them (V39).
    const result = (eligible, assigned) => (detail ? { eligible, assigned } : eligible);
    if (!this._videos || this._videos.length === 0) return result(0, 0);
    const allPaths = (this._allFunscripts || []).map((f) => f.path);
    if (allPaths.length === 0) return result(0, 0);
    const associations = this._settings.get('library.associations') || {};
    // This one runs synchronously from the settings dropdown's `change`
    // handler, so its cost is felt as a frozen window. Index, don't re-walk.
    const companionIndex = buildCompanionIndex(allPaths);
    let count = 0;
    let assigned = 0;
    for (const video of this._videos) {
      if (!video.hasFunscript || !video.funscriptPath) continue;
      const entry = normalizeAssociation(associations[video.path]);
      if (entry.active !== null && !detail) continue;
      // Never promoted (see _autoPromoteEligibleVideos), so never counted.
      if (entry.active === null && video._folderVariantMain) continue;
      if (entry.active === null && handMadeSlots(associations[video.path]).includes('multi')) continue;
      const companions = detectCompanionFilesIndexed(video.funscriptPath, companionIndex);
      if (companions.length === 0) continue;
      if (entry.active === null) count++;
      else assigned++;
    }
    return result(count, assigned);
  }

  /**
   * Re-run the auto-promotion pass from app.js when the user toggles
   * the preference on. Reads the current associations map, mutates it,
   * and writes back if anything changed. No-op when the setting is
   * off (kept defensive — caller is responsible for the on-toggle
   * trigger).
   */
  _reapplyAutoPromotion() {
    if (this._settings.get('player.preferMultiAxis') !== 'multi') return 0;
    const associations = this._settings.get('library.associations') || {};
    const promoted = this._autoPromoteEligibleVideos(associations);
    if (promoted > 0) {
      this._settings.set('library.associations', associations);
      // The multi badge is built when a card renders, and Settings is a
      // modal over the library: closing it re-renders nothing. Without
      // this the promoted cards showed no badge until some unrelated
      // re-render (a view toggle, a filter) (V38). `hide()` empties the
      // container, so a grid present means the library is on screen; a
      // hidden library renders fresh on its next show().
      if (!this._scanning && this._container?.querySelector('.library__grid')) {
        this._applyFilters();
      }
    }
    return promoted;
  }

  /**
   * Undo the auto-promotion when Default playback is switched to Single
   * (Dave, 2026-11-20: switching back to Single puts the videos FunSync paired
   * by itself back). It matters since the one-time v0.10.1 migration moved the
   * 'single' that old releases wrote into every config to 'multi': anyone who
   * had Single on purpose would otherwise be left multi-axis for good.
   *
   * Only `active: 'multi'` entries with `multi.autoAssigned` (written by
   * `_autoPromoteEligibleVideos`, and dropped by any save through the
   * association modal) go back; anything set by hand is never touched. Each
   * goes back to how the scan found it: no pairing, playing its same-name
   * script. A single script picked by hand, or a custom routing, kept in the
   * entry stays there, inactive (for Change…), as an Unpair keeps them; an
   * entry with nothing else in it is removed. Returns how many were put back.
   */
  _revertAutoPromotion() {
    if (this._settings.get('player.preferMultiAxis') === 'multi') return 0;
    const stored = this._settings.get('library.associations') || {};
    const associations = { ...stored };
    const byPath = new Map((this._videos || []).map((v) => [v.path, v]));
    let reverted = 0;
    for (const [videoPath, raw] of Object.entries(stored)) {
      const entry = normalizeAssociation(raw);
      if (entry.active !== 'multi' || !entry.multi?.autoAssigned) continue;
      const video = byPath.get(videoPath);
      const own = video?.funscriptPath || entry.multi.main || null;
      const [singleSlot, , customSlot] = associationSlots(raw, { ownScriptPath: own });
      const keepSingle = singleSlot.hand ? entry.single : null;
      const keepCustom = customSlot.held ? entry.custom : null;
      if (keepSingle || keepCustom) {
        associations[videoPath] = buildAssociationEntry(null, keepSingle, null, keepCustom);
      } else {
        delete associations[videoPath];
      }
      // The three fields promotion set (see _autoPromoteEligibleVideos): the
      // next play is the same-name script alone, with no rescan.
      if (video) {
        video._multiAxis = null;
        video._manualAssociation = false;
        video._autoAssigned = false;
      }
      reverted++;
    }
    if (reverted > 0) {
      this._settings.set('library.associations', associations);
      // The multi badge goes with it (see _reapplyAutoPromotion, V38).
      if (!this._scanning && this._container?.querySelector('.library__grid')) {
        this._applyFilters();
      }
    }
    return reverted;
  }

  /**
   * Look up a library video by a path reported by a VR headset. Assumes
   * `ensureScanned()` has been called. Exact normalised-basename match first,
   * then fuzzy fallback with the same 70% threshold the old inline code used.
   * @returns {object|null}
   */
  findVideoByVRPath(normalizedName, rawPath) {
    const files = (this._videos || []).filter((v) => !v._stream);
    if (!files.length) return null;

    const basename = (normalizedName || '').toLowerCase();
    const normalize = (s) => (s || '').replace(/\.[^/.]+$/, '').toLowerCase()
      .replace(/[_.\-]/g, ' ').replace(/\s+/g, ' ').trim();

    const exact = files.find(v => normalize(v.name) === basename);
    if (exact) return exact;

    const displayName = (rawPath || '').split(/[\\/]/).pop() || normalizedName || '';
    let best = null;
    let bestScore = 0;
    for (const v of files) {
      const score = fuzzyMatchScore(displayName, v.name);
      if (score > bestScore) { bestScore = score; best = v; }
    }
    return bestScore >= 70 ? best : null;
  }

  /**
   * findVideoByVRPath, plus FunSync's own URLs (V63). A headset streaming
   * from FunSync's content server can report the stream or scene URL as the
   * playing path, and those name the video by registry id only, so name
   * matching found nothing and the user got "no script" for a video FunSync
   * itself was serving. The backend that minted the id says which file it is.
   * Any other path, or an id the backend cannot resolve, falls through to
   * name matching unchanged.
   */
  async resolveVRVideo(normalizedName, rawPath) {
    const id = funsyncVideoIdFromVRPath(rawPath);
    if (id && this._videos?.length) {
      const path = await this._backendVideoPath(id);
      const hit = path ? this._videos.find(v => v.path === path) : null;
      if (hit) return hit;
    }
    return this.findVideoByVRPath(normalizedName, rawPath);
  }

  async _backendVideoPath(id) {
    const port = this._settings.get('backend.port') || 5123;
    try {
      const res = await fetch(`http://127.0.0.1:${port}/api/media/video/${encodeURIComponent(id)}`,
        { signal: AbortSignal.timeout?.(3000) });
      if (!res.ok) return null;
      const body = await res.json();
      return typeof body?.path === 'string' && body.path ? body.path : null;
    } catch {
      return null;
    }
  }

  _showLoadingState() {
    const countEl = this._container?.querySelector('.library__video-count');
    if (countEl) countEl.textContent = t('library.loading');
    const grid = this._container?.querySelector('.library__grid');
    if (grid) {
      // Scan-phase loader: three accent dots popping in sequence (replaced
      // the spinner + hardcoded "Scanning library..." text — the dots need
      // no copy, and the aria-label reuses the localized library.loading key).
      grid.innerHTML = `
        <div class="library__loading" role="status" aria-label="${this._escapeHtml(t('library.loading'))}">
          <div class="library__loading-dots" aria-hidden="true">
            <span></span><span></span><span></span>
          </div>
        </div>
      `;
    }
  }

  /**
   * Start of the initial-thumbnails phase. Historically this raised a
   * blocking "Generating previews..." overlay to stop clicks while 3
   * hidden <video> decoders fought the GPU — that decode path is gone
   * (backend ffmpeg + skeleton shimmer on each pending card now), so the
   * grid stays interactive and this phase only exists for its timing
   * marks + the deferred background passes.
   */
  _beginInitialThumbsPhase() {
    // Nothing to wait for — the all-cached case (everything already in
    // thumbCache from this session) and the empty-filter case (0 visible
    // cards, nothing queued). Fire the deferred passes here since the
    // "after thumbs settle" hook in _finishInitialThumbsPhase won't run.
    if (this._pendingThumbnails.length === 0 && this._activeThumbnails === 0) {
      this._initialThumbsLoading = false;
      mark('initial thumbnails complete (cache hit / no thumbs needed)');
      // Kick off speed-stats and duration hydration in parallel — both
      // poll the backend independently, no ordering dependency.
      this._precomputeDurationsInBackground();
      this._precomputeSpeedStatsInBackground().then(() => {
        mark('speed-stats precompute complete');
        import('../js/startup-timer.js').then(m => m.logSummary());
      });
    }
    // Cards render with skeleton placeholders that shimmer until their
    // thumbnail lands (see library.css / modern.css) — nothing to mount.
  }

  _finishInitialThumbsPhase() {
    this._initialThumbsLoading = false;
    mark('initial thumbnails complete');
    // Now that the initial UI is settled and the thumbnail decoders
    // have released the renderer + main process, kick off the speed-
    // stats background pass for any video missing stats. Deferring
    // until here avoids competing with thumbnail/scan IPC at startup
    // (which was felt as the whole app freezing for a few seconds).
    // Cached entries hydrated earlier are skipped automatically.
    this._precomputeDurationsInBackground();
    this._precomputeSpeedStatsInBackground().then(() => {
      mark('speed-stats precompute complete');
      // After the deferred work is done, dump the timing summary so
      // we can see the full startup picture in the log.
      import('../js/startup-timer.js').then(m => m.logSummary());
    });
  }

  _renderGrid(videos) {
    const grid = this._container.querySelector('.library__grid');
    const wrapper = this._container.querySelector('.library__grid-wrapper');
    if (!grid || !wrapper) return;

    // We're about to do `grid.innerHTML = ''` below, which detaches every
    // card. If a kebab menu is open, its refs (`_openMenu`, `_openMenuCard`)
    // would survive on a detached subtree — tiny mem leak until the next
    // outside-click fires, and the user sees a ghost menu that just
    // vanished when they changed tab / sort / search.
    this._closeMenu();

    // Snapshot scroll position so we can restore it after rebuilding
    // the grid. Without this, every `_applyFilters()` call (which
    // happens after kebab actions, association edits, etc.) snapped
    // the user back to the top of the library — `grid.innerHTML = ''`
    // collapses content height, the browser resets scrollTop to 0,
    // and the virtual-scroll renderer then computes ranges from
    // scrollTop=0 instead of the user's actual position.
    let savedScrollTop = wrapper.scrollTop;
    // First render after a hide() (e.g. returning from the player) —
    // the wrapper was just rebuilt by `_renderWithHeader` and reads as
    // 0. Pull in the position captured on the way out so the user
    // lands where they clicked the last video.
    let fromHide = false;
    if (savedScrollTop === 0 && this._savedScrollOnHide) {
      savedScrollTop = this._savedScrollOnHide;
      this._savedScrollOnHide = 0;
      fromHide = true;
    }

    // Was the user at the real bottom of the virtual grid? Only the grid as
    // it stands can say (or hide(), for a grid rebuilt since): once emptied
    // below it has no extent, and reading the empty one is how every render
    // came to build every card (V81). Carried into the first range so a
    // re-render at the bottom keeps the last row on screen, even when the
    // row estimate is off.
    const keepTail = fromHide
      ? !!this._savedScrollAtBottom
      : !!this._virtualActive && this._bottomSpacer?.parentNode === grid
        && wrapper.scrollTop >= wrapper.scrollHeight - wrapper.clientHeight - Math.max(this._vsRowHeight || 0, 1);
    this._savedScrollAtBottom = false;
    this._vsTailPin = 0; // set again below for a virtual render that keeps the tail (FT-089)
    this._vsAtEnd = keepTail; // until the next scroll says otherwise (E2-05)

    grid.classList.add('library__grid--loading');
    grid.innerHTML = '';
    grid.classList.toggle('library__grid--list', this._viewMode === 'list');

    // `videos` may be a mixed array of videos and { isFolder, node, count }
    // entries in folder-browse mode. `_filteredVideos` retains the video-only
    // subset that downstream code (thumbnails, hover preview) expects.
    const items = videos || [];
    this._filteredItems = items;
    this._filteredVideos = items.filter(i => !i.isFolder);
    this._pendingThumbnails = [];
    this._activeThumbnails = 0;

    // Emit so dependent surfaces (queue panel "Up next" derivation) can
    // re-read the post-sort/post-filter video list. Sort/filter changes
    // mid-playback recompute upcoming live per SCOPE §3.4.
    eventBus.emit('library:filtered', { count: this._filteredVideos.length });
    if (this._observer) this._observer.disconnect();

    // No-results-due-to-filters state. The "no videos at all in source"
    // path is handled upstream in `_render` (line ~378). Here we catch
    // the case where the source HAS videos but the active search /
    // tab / filters are hiding them all — distinct from "empty source"
    // because the user-actionable fix is "clear filters", not "add
    // videos" (Nielsen #9 / #10 — help users recover with the right
    // affordance, not a generic "nothing here"). Skipped if `_videos`
    // is also empty (upstream will own that state).
    if (items.length === 0 && this._videos && this._videos.length > 0) {
      const filtersActive = !!this._searchQuery || this._activeTab === 'unmatched' || this._activeTab === 'scripts' || (this._vrFilter && this._vrFilter !== 'all')
        || (this._mediaFilter && this._mediaFilter !== 'all')
        || tagFilterActive(this._tagFilter) || this._stashFilterOn();
      const empty = document.createElement('div');
      empty.className = 'library__empty';
      const text = document.createElement('div');
      text.className = 'library__empty-text';
      const noScripts = this._activeTab === 'scripts' && !this._searchQuery;
      const allScope = this._scriptsScope === 'all';
      text.textContent = noScripts ? t(allScope ? 'library.scripts.emptyAllTitle' : 'library.scripts.emptyTitle')
        : filtersActive ? t('library.emptyFilteredTitle') : t('library.emptyTitle');
      empty.appendChild(text);
      if (filtersActive) {
        const hint = document.createElement('div');
        hint.className = 'library__empty-hint';
        hint.textContent = noScripts ? t(allScope ? 'library.scripts.emptyAllHint' : 'library.scripts.emptyHint') : t('library.emptyFilteredHint');
        empty.appendChild(hint);
        const clearBtn = document.createElement('button');
        clearBtn.className = 'library__empty-btn';
        clearBtn.textContent = t('library.emptyFilteredCta');
        clearBtn.addEventListener('click', () => this._clearAllFilters());
        empty.appendChild(clearBtn);
      }
      grid.appendChild(empty);
      grid.classList.remove('library__grid--loading');
      return;
    }

    // Disconnect previous scroll handler
    if (this._scrollHandler) {
      wrapper.removeEventListener('scroll', this._scrollHandler);
    }

    // For small lists (< 60 items), skip virtual scroll — render all directly
    if (items.length < 60) {
      this._virtualActive = false;
      for (const item of items) {
        const el = this._createItemEl(item);
        grid.appendChild(el);
      }
      this._lazyLoadVisibleThumbnails(grid);
      // Restore scroll position post-render. Defer one frame so layout
      // settles (so the wrapper accepts the value); otherwise scrollTop
      // can clamp to the new content height before card sizes apply.
      if (savedScrollTop > 0) {
        requestAnimationFrame(() => { wrapper.scrollTop = savedScrollTop; });
      }
      requestAnimationFrame(() => grid.classList.remove('library__grid--loading'));
      return;
    }

    // Virtual scroll for large lists
    this._virtualActive = true;

    // Compute grid dimensions. Row height starts as a rough estimate; after
    // the first render we measure an actual card and replace the estimate
    // so the scrollbar stays honest (the old 300px was roughly 2x reality).
    const isListMode = this._viewMode === 'list';
    const rowHeight = isListMode ? 50 : (this._vsMeasuredRowHeight || 180);
    const columns = isListMode ? 1 : this._measureGridColumns(grid, wrapper);

    // Create spacers
    if (!this._topSpacer) {
      this._topSpacer = document.createElement('div');
      this._topSpacer.className = 'library__virtual-spacer';
    }
    if (!this._bottomSpacer) {
      this._bottomSpacer = document.createElement('div');
      this._bottomSpacer.className = 'library__virtual-spacer';
    }

    this._vsColumns = columns;
    this._vsRowHeight = rowHeight;
    this._vsLastState = null;

    // Stash the scrollTop snapshot taken at the top of _renderGrid so
    // _virtualScrollUpdate can use it for the FIRST render — at this
    // point grid is still empty (we cleared it above), so reading
    // wrapper.scrollTop now would give 0 and we'd lose position.
    this._pendingScrollRestore = savedScrollTop;
    this._vsKeepTail = keepTail;
    this._virtualScrollUpdate(wrapper, grid);
    this._vsKeepTail = false;

    // A render that kept the tail keeps it until the layout has settled
    // (FT-089). The restore above lands on the end of the extent as it is
    // one frame later, but the row measure below can still change the row
    // height (list to grid: the 180px guess becomes the real ~197px), and
    // its re-render kept the old scrollTop, a row or more short of the new
    // end (571 px at 1280x800 in real Chromium). `_vsTailPin` names this
    // render's pin; a scroll up off the end clears it (the scroll handler).
    if (keepTail) {
      this._vsTailPinSeq = (this._vsTailPinSeq || 0) + 1;
      this._vsTailPin = this._vsTailPinSeq;
      this._vsTailPinTop = wrapper.scrollTop;
    }

    // Measure an actual card after layout and correct the row-height estimate.
    // `_virtualScrollUpdate` also re-arms this while it is still unmeasured.
    this._scheduleRowHeightMeasure(wrapper, grid);
    if (this._vsTailPin) this._settleTailPin(this._vsTailPin);

    // Throttled scroll handler with preview suppression.
    //
    // `_scrolling` still means "the view is moving" (previews stay suppressed
    // for the whole gesture). What changed is that LOADING is no longer gated
    // on it: `_scrollVelocity` decides that, so a slow continuous scroll —
    // trackpad, or dragging the scrollbar — fills tiles as it goes instead of
    // waiting for a full stop that a continuous gesture never produces.
    // See scroll-load-policy.js for the reasoning.
    let ticking = false;
    this._scrollVelocity = 0;
    this._lastScrollTop = wrapper.scrollTop;
    this._scrollHandler = () => {
      // At the end? Kept for a later window resize (E2-05), which can only
      // ask once the grid has re-laid out at the new width: by then a
      // narrower window has grown the extent under an unchanged scrollTop,
      // and the end it was at no longer reads as the end.
      this._vsAtEnd = wrapper.scrollTop >= wrapper.scrollHeight - wrapper.clientHeight - Math.max(this._vsRowHeight || 0, 1);
      // Scrolled UP, away from the end: that is the user, stop holding the
      // end for them (FT-089). The pin's own scrolls only ever move down
      // (the restore, the settle), and a clamp of a shrinking extent lands
      // ON the end. "Not at the end" alone is not enough: cards that lay
      // out between the restore and its scroll event grow the extent, and
      // the restore then reads a few px short (9 px in real Chromium).
      if (this._vsTailPin) {
        const top = wrapper.scrollTop;
        if (top < this._vsTailPinTop - 1 && top < wrapper.scrollHeight - wrapper.clientHeight - 2) {
          this._vsTailPin = 0;
        } else {
          this._vsTailPinTop = top;
        }
      }
      this._scrolling = true;
      clearTimeout(this._previewHoverTimer);
      clearTimeout(this._scrollEndTimer);
      this._scrollEndTimer = setTimeout(() => {
        this._scrolling = false;
        this._scrollVelocity = 0;
        // Settled: fire anything still deferred. Fast flings land here.
        this._drainPendingThumbnailsOnScrollEnd();
      }, 150);
      if (!ticking) {
        ticking = true;
        requestAnimationFrame(() => {
          // Measure per FRAME, not per scroll event — event cadence varies by
          // input device, frames don't.
          const top = wrapper.scrollTop;
          this._scrollVelocity = smoothVelocity(
            this._scrollVelocity, top - (this._lastScrollTop || 0),
          );
          this._lastScrollTop = top;

          this._virtualScrollUpdate(wrapper, grid);

          // Below the fling threshold, keep feeding the queue mid-scroll.
          if (!shouldDeferLoads(this._scrollVelocity)) {
            this._drainPendingThumbnailsOnScrollEnd();
          }
          ticking = false;
        });
      }
    };
    wrapper.addEventListener('scroll', this._scrollHandler, { passive: true });

    requestAnimationFrame(() => grid.classList.remove('library__grid--loading'));
  }

  /**
   * The virtual-scroll column count must match what CSS actually lays out,
   * so read the RESOLVED grid tracks instead of re-deriving them. The old
   * formula `floor((clientWidth - 32) / 236)` disagreed with the grid's
   * `repeat(auto-fill, minmax(220px, 1fr))` whenever
   * `(clientWidth - 32) mod 236 >= 220` — auto-fill gets the column gap
   * back for the last track, the formula doesn't — a 16px-wide band of
   * window widths (~7% of them) where CSS packed one MORE column per row
   * than the spacer math assumed. Every row boundary was then wrong:
   * content height shrank each time the range re-rendered at the bottom,
   * the browser clamped scrollTop, the range receded, the spacer re-grew
   * the height — the reported "last row flickers and scroll snaps back to
   * the last complete row", with the final partial row unreachable
   * (Sylvain-Et-Un, EroScripts #300). Chromium resolves auto-fill tracks
   * from container width even while the grid is EMPTY (verified), so this
   * is safe to call right after `grid.innerHTML = ''`. The formula stays
   * only as a fallback for a hidden grid (`display: none` computes to
   * 'none').
   */
  _measureGridColumns(grid, wrapper) {
    try {
      const tracks = window.getComputedStyle(grid).gridTemplateColumns;
      if (tracks && tracks !== 'none' && !tracks.includes('repeat')) {
        const n = tracks.split(' ').filter(Boolean).length;
        if (n > 0) return n;
      }
    } catch { /* fall through to the formula */ }
    return Math.max(1, Math.floor((wrapper.clientWidth - 32) / 236));
  }

  /**
   * Measure one grid row: a card's height plus the grid's row gap.
   *
   * Prefers the card's own border-box height, but falls back to the sum of
   * its children when the two disagree by more than a rounding error. They
   * disagree exactly when the row has been STRETCHED — a grid distributes
   * surplus container height into auto-sized rows, so a card can report
   * 260px while its thumbnail + heatmap + info stack measures 173px. Taking
   * the stretched number is how the estimate ends up "correcting" itself to
   * whatever it already was, and the error then survives forever behind the
   * `!this._vsMeasuredRowHeight` guard (Sylvain-Et-Un #315 territory —
   * an over-estimated row height means `floor(scrollTop / rowHeight)` can
   * never reach the final row, because the real scrollable height is smaller
   * than the arithmetic assumes).
   *
   * `align-content: start` in library.css stops the stretch at source; this
   * is the belt to that pair of braces, and it also covers any future layout
   * that reintroduces one.
   *
   * @returns {number|null} row height in px, or null if nothing measurable
   */
  _measureRowHeight(grid) {
    if (!grid) return null;
    const card = grid.querySelector('.library__card, .library__folder-card');
    if (!card || card.offsetHeight <= 0) return null;

    const gridStyle = window.getComputedStyle(grid);
    const rowGap = parseFloat(gridStyle.rowGap || gridStyle.gap) || 16;
    this._vsRowGap = rowGap; // remembered for the spacer leading-gap fix

    const boxHeight = card.offsetHeight;
    let contentHeight = 0;
    for (const child of card.children) contentHeight += child.offsetHeight;

    // Trust the smaller of the two: a card is never SHORTER than its
    // content, so a box taller than the stack is stretch, not substance.
    const natural = (contentHeight > 0 && boxHeight - contentHeight > 1)
      ? contentHeight
      : boxHeight;

    return natural + rowGap;
  }

  /**
   * Measure a real card and replace the row-height estimate, once per grid
   * layout. Only in grid mode (list rows are a known 50px; folder rows same),
   * and only while nothing has been measured yet.
   *
   * TWO frames, not one. The first frame after a render can still report a
   * stretched card — see `_measureRowHeight` — and a single rAF sampled
   * exactly that frame, baking a 46%-too-large row height in permanently
   * (measured live: 276px cached against a true 189px). Sampling once more
   * on the following frame and taking the settled value costs nothing.
   *
   * A sample that finds no card leaves the estimate unmeasured, and
   * `_virtualScrollUpdate` calls this again once it has rendered cards. It
   * used to be one shot from `_renderGrid`: a render that showed nothing
   * (list -> grid while scrolled deep) kept the 180px guess until a resize
   * (V30). One measurement in flight at a time.
   */
  _scheduleRowHeightMeasure(wrapper, grid) {
    if (this._viewMode === 'list' || this._vsMeasuredRowHeight || this._vsMeasurePending) return;
    this._vsMeasurePending = true;
    requestAnimationFrame(() => {
      this._measureRowHeight(grid);          // warm-up sample, deliberately discarded
      requestAnimationFrame(() => {
        this._vsMeasurePending = false;
        if (this._viewMode !== 'list' && !this._vsMeasuredRowHeight) {
          const measured = this._measureRowHeight(grid);
          if (measured) {
            this._vsMeasuredRowHeight = measured;
            this._vsRowHeight = measured;
            // Recompute the spacer-based layout with the corrected estimate
            this._vsLastState = null;
            // A kept tail is anchored to the end again, as `_renderGrid`
            // anchors it: past the last row, which the range clamps to the
            // last screenful and the restore to the real end (FT-089).
            if (this._vsTailPin) {
              const rows = Math.ceil((this._filteredItems?.length || 0) / Math.max(1, this._vsColumns));
              this._pendingScrollRestore = rows * measured;
            }
            this._virtualScrollUpdate(wrapper, grid);
          }
        }
        if (this._vsTailPin) this._settleTailPin(this._vsTailPin);
      });
    });
  }

  /**
   * Hold a kept tail at the real end of the scroll extent for two frames
   * once nothing is left to re-measure, then let go (FT-089). Waits while a
   * row measure is in flight (it re-anchors and calls this again), and does
   * nothing once the pin is gone: cleared by a scroll away from the end, or
   * replaced by a newer render's.
   *
   * @param {number} pin — the `_vsTailPin` this was scheduled for
   * @param {number} [frames=2]
   */
  _settleTailPin(pin, frames = 2) {
    requestAnimationFrame(() => {
      if (this._vsTailPin !== pin || this._vsMeasurePending) return;
      const wrapper = this._container?.querySelector('.library__grid-wrapper');
      if (!wrapper) return;
      const end = wrapper.scrollHeight - wrapper.clientHeight;
      if (wrapper.scrollTop < end - 1) wrapper.scrollTop = end;
      if (frames > 1) this._settleTailPin(pin, frames - 1);
      else this._vsTailPin = 0;
    });
  }

  _virtualScrollUpdate(wrapper, grid) {
    const items = this._filteredItems;
    if (!items || items.length === 0) return;

    // If _renderGrid stashed a scrollTop to restore (kebab action,
    // association edit, anything that re-runs _applyFilters), use it
    // for range computation INSTEAD of wrapper.scrollTop. The wrapper
    // was just emptied so its scrollTop is 0; reading it now would
    // render the top of the list and lose the user's position.
    let pendingRestore = this._pendingScrollRestore;
    let effectiveScrollTop = pendingRestore != null
      ? pendingRestore
      : wrapper.scrollTop;

    // The spacers are what give the grid its extent: until they are in the
    // grid, its extent is just the viewport (see FORCE THE TAIL below).
    const extentKnown = this._bottomSpacer?.parentNode === grid;
    // `_renderGrid` saw the user at the bottom before it emptied the grid:
    // keep them at the bottom of THIS list. Anchor the window to its end
    // rather than extending one from the old offset to the end: when the list
    // grew (the Matched chip off), the view changed (grid to list) or the user
    // came back from hide() into a bigger list, that offset is mid-list, and
    // the "window" was most of the library again, 900-1,150 cards (V81
    // review). computeGridRange clamps an offset past the end to the last
    // screenful; the restore below lands on the real bottom the same way.
    if (!extentKnown && this._vsKeepTail) {
      effectiveScrollTop = Math.ceil(items.length / Math.max(1, this._vsColumns)) * this._vsRowHeight;
      pendingRestore = effectiveScrollTop;
    }

    const state = computeGridRange({
      totalItems: items.length,
      columns: this._vsColumns,
      rowHeight: this._vsRowHeight,
      viewportHeight: wrapper.clientHeight,
      scrollTop: effectiveScrollTop,
      overscan: 3,
    });

    // FORCE THE TAIL. If the user is within one row of the real bottom of the
    // scroll range, render everything to the end regardless of what the row
    // arithmetic concluded.
    //
    // This is the one guarantee that does not depend on `_vsRowHeight` being
    // right, because it reads the DOM's ACTUAL scroll extent rather than the
    // estimate. Every other fix here makes the estimate accurate; this makes
    // "the last row is unreachable" impossible even when it isn't. That
    // failure mode is unfalsifiable from a bug report — the user sees missing
    // cards, and nothing in the log disagrees — so it is worth closing off
    // structurally rather than trusting the measurement twice.
    //
    // Costs at most one extra row of cards, and only at the very bottom.
    //
    // Only against a grid that HAS an extent. `_renderGrid` empties the grid
    // before its first update, so the DOM's extent then is just the viewport:
    // `maxScrollTop` read 0 and every render forced the tail, i.e. rendered
    // every card. On a 1,546-video library with card heatmaps that was 6-12 s
    // per sort, filter or background refresh (Dave, V81). The spacers are
    // what give the grid its extent, so until they are in the grid the
    // answer comes from `_renderGrid`, which read the grid before emptying
    // it (`_vsKeepTail`). Every scroll after that reads the real extent.
    let nearBottom = !!this._vsKeepTail;
    if (extentKnown) {
      const maxScrollTop = wrapper.scrollHeight - wrapper.clientHeight;
      nearBottom = maxScrollTop <= 0
        || effectiveScrollTop >= maxScrollTop - Math.max(this._vsRowHeight, 1);
    }
    if (nearBottom && state.endIndex < items.length) {
      state.endIndex = items.length;
      state.endRow = state.totalRows;
      state.bottomSpacer = 0;
      state.visibleCount = state.endIndex - state.startIndex;
    }

    if (!hasRangeChanged(this._vsLastState, state)) {
      // Even on no-op range, still apply pending scroll restore.
      if (pendingRestore != null) {
        this._pendingScrollRestore = null;
        wrapper.scrollTop = pendingRestore;
      }
      return;
    }
    this._vsLastState = state;

    // Scroll moved the visible range — about to detach cards. Close any
    // open kebab menu first so its refs don't hang on a detached subtree.
    // Also matches standard popover UX (scroll away = menu closes).
    this._closeMenu();

    // Rebuild visible cards only
    grid.innerHTML = '';
    // The top spacer is a full-width grid item, so the grid's row-gap adds a
    // phantom gap BELOW it — i.e. above the first visible card row. At the top
    // (spacer = 0) that's a dead band above row 1; when scrolled it pushes
    // every row down by one gap. Fix: hide the spacer entirely when it would
    // be zero (no leading gap at the top), and subtract one row-gap from its
    // height when shown (the grid's own gap makes up the difference, so the
    // first visible row lands exactly where the scroll math intends).
    const rowGap = this._vsRowGap || 16;
    if (state.topSpacer > 0) {
      this._topSpacer.style.display = '';
      this._topSpacer.style.height = Math.max(0, state.topSpacer - rowGap) + 'px';
    } else {
      this._topSpacer.style.display = 'none';
      this._topSpacer.style.height = '0px';
    }
    this._bottomSpacer.style.height = state.bottomSpacer + 'px';

    grid.appendChild(this._topSpacer);
    for (let i = state.startIndex; i < state.endIndex && i < items.length; i++) {
      const el = this._createItemEl(items[i]);
      grid.appendChild(el);
    }
    grid.appendChild(this._bottomSpacer);

    // Apply the saved scroll position now that the spacers are in
    // place and the wrapper accepts the value. Defer one frame so the
    // browser settles layout — without the rAF, scrollTop sometimes
    // gets clamped to a stale content height before the spacers
    // register their dimensions.
    if (pendingRestore != null) {
      this._pendingScrollRestore = null;
      requestAnimationFrame(() => {
        if (wrapper.scrollTop !== pendingRestore) {
          wrapper.scrollTop = pendingRestore;
        }
      });
    }

    // Load thumbnails for visible cards
    this._lazyLoadVisibleThumbnails(grid);

    // Still on the row-height guess (the last sample found no card, V30):
    // there are cards now, so measure one.
    if (!this._vsMeasuredRowHeight && state.endIndex > state.startIndex) {
      this._scheduleRowHeightMeasure(wrapper, grid);
    }
  }

  /**
   * Window resize handler — recomputes the cached column count and nudges
   * the virtual-scroll renderer so the visible range tracks the new
   * viewport. Wired via the debounced `_onResize` listener from `show()`
   * / `hide()`. Without this, going from a tiled window to fullscreen
   * left `_vsColumns` at its small-window value and scrolling misaligned
   * the card grid.
   */
  _handleResize() {
    // What the burst's first resize event saw (see `_onResize`); the next
    // burst reads afresh.
    const latchedAtEnd = this._resizeAtEndLatch === true;
    this._resizeAtEndLatch = null;
    if (!this._container || !this._virtualActive) return;
    const wrapper = this._container.querySelector('.library__grid-wrapper');
    const grid = this._container.querySelector('.library__grid');
    if (!wrapper || !grid) return;

    // At the end of the grid before this resize: end at the end after it
    // (E2-05), as a re-render that keeps the tail does (FT-089). The update
    // below used to keep the old scrollTop, which at the new row height and
    // column count is somewhere short of the new end: rows short after a
    // narrower window. Read before anything here changes the layout; the
    // last scroll's reading counts, because a narrower window has already
    // grown the extent under the old scrollTop by the time this runs. And
    // a scroll-anchoring scroll in between has overwritten even that, so the
    // burst's first event counts most.
    const atEnd = latchedAtEnd || !!this._vsAtEnd || !!this._vsTailPin
      || wrapper.scrollTop >= wrapper.scrollHeight - wrapper.clientHeight - Math.max(this._vsRowHeight || 0, 1);

    const isListMode = this._viewMode === 'list';
    const newColumns = isListMode ? 1 : this._measureGridColumns(grid, wrapper);

    if (newColumns !== this._vsColumns) {
      this._vsColumns = newColumns;
      this._vsLastState = null;   // force a full range recompute
    }

    // Re-measure the ROW HEIGHT too, not just the column count.
    //
    // Columns are `minmax(220px, 1fr)` and the thumbnail is 16/9, so card
    // height is a function of card WIDTH — which changes on every resize,
    // including ones that leave the column count alone. Measured live: the
    // same card is 181px tall at a 1280px window and 173px at 1920px. Only
    // `_vsColumns` was refreshed here, so the row height kept whatever value
    // it was first measured at and the scroll arithmetic drifted further
    // from reality the more the window was resized.
    if (!isListMode) {
      const measured = this._measureRowHeight(grid);
      if (measured && Math.abs(measured - this._vsRowHeight) > 1) {
        this._vsMeasuredRowHeight = measured;
        this._vsRowHeight = measured;
        this._vsLastState = null;
      }
    }
    // Anchored past the last row, as the row measure re-anchors a kept tail:
    // the range clamps to the last screenful and the restore to the real
    // end, which `_settleTailPin` then holds while the cards settle.
    if (atEnd) {
      this._vsTailPinSeq = (this._vsTailPinSeq || 0) + 1;
      this._vsTailPin = this._vsTailPinSeq;
      this._vsTailPinTop = wrapper.scrollTop;
      const rows = Math.ceil((this._filteredItems?.length || 0) / Math.max(1, this._vsColumns));
      this._pendingScrollRestore = rows * this._vsRowHeight;
    }
    // Always refresh — `_virtualScrollUpdate` reads `wrapper.clientHeight`
    // fresh each call, so height-only resizes still update the visible
    // range even when the column count didn't change.
    this._virtualScrollUpdate(wrapper, grid);
    if (atEnd) this._settleTailPin(this._vsTailPin);
  }

  _lazyLoadVisibleThumbnails(grid) {
    const cards = grid.querySelectorAll('.library__card, .library__list-item');
    // During fast scroll, don't fire backend thumbnail calls — each one
    // costs IPC + (potentially) ffmpeg subprocess time and adds main-
    // thread pressure. Mark cards as needing load and dispatch when
    // the scroll settles via _drainPendingThumbnailsOnScrollEnd. Cache
    // hits ARE handled inline by _createCard, so already-rendered
    // thumbnails persist across scroll without delay.
    // Defer on speed, not on the mere fact of scrolling — see the handler.
    const skipForScroll = !!this._scrolling && shouldDeferLoads(this._scrollVelocity);
    for (const card of cards) {
      const videoPath = card.dataset.videoPath;
      if (videoPath && !card.dataset.loaded) {
        if (skipForScroll && card.dataset.loaded !== 'true') {
          // Defer — mark as 'pending-scroll' so the scroll-end drain
          // picks it up without re-querying the DOM.
          card.dataset.loaded = 'pending-scroll';
        } else {
          card.dataset.loaded = 'pending';
          this._queueThumbnail(card, videoPath);
        }
      }
      // Speed-stats compute is renderer-side (cache lookup + small
      // JSON parse, fast). Skip it during scroll too just to keep the
      // main thread cleaner; it's cheap to defer.
      if (videoPath && !card.dataset.speedLoaded && !skipForScroll) {
        card.dataset.speedLoaded = 'pending';
        const video = this._videosByPath?.get(videoPath);
        if (video) this._loadSpeedStatsForVideo(video, card);
      }
    }
  }

  /**
   * Pick up any cards we deferred queueing during fast scroll. Called
   * from the scroll handler's stop-detection setTimeout so backend
   * thumbnail calls fire only when the user has actually settled on
   * a viewport position, not while they're flicking through.
   */
  _drainPendingThumbnailsOnScrollEnd() {
    const grid = this._container?.querySelector('.library__grid');
    if (!grid) return;
    const cards = grid.querySelectorAll('.library__card[data-loaded="pending-scroll"], .library__list-item[data-loaded="pending-scroll"]');
    for (const card of cards) {
      const videoPath = card.dataset.videoPath;
      if (!videoPath) continue;
      card.dataset.loaded = 'pending';
      this._queueThumbnail(card, videoPath);
    }
    // Speed-stats too — mirror the deferred-during-scroll behaviour, but
    // SPREAD ACROSS FRAMES. This used to run as one synchronous loop over
    // every rendered card at the exact moment the scroll settled — precisely
    // when the main thread is needed to paint the newly-settled view. Bounded
    // by the rendered range, so tens rather than hundreds, but it landed at
    // the worst possible instant.
    const speedCards = [...grid.querySelectorAll(
      '.library__card:not([data-speed-loaded]), .library__list-item:not([data-speed-loaded])'
    )];
    if (speedCards.length === 0) return;

    // Claim them all up front so a second drain (another scroll settling)
    // can't queue the same cards twice.
    for (const card of speedCards) {
      if (card.dataset.videoPath) card.dataset.speedLoaded = 'pending';
    }

    const batches = chunk(speedCards, 8);
    let i = 0;
    const runBatch = () => {
      const batch = batches[i++];
      if (!batch) return;
      for (const card of batch) {
        const videoPath = card.dataset.videoPath;
        if (!videoPath || !card.isConnected) continue;
        const video = this._videosByPath?.get(videoPath);
        if (video) this._loadSpeedStatsForVideo(video, card);
      }
      if (i < batches.length) requestAnimationFrame(runBatch);
    };
    requestAnimationFrame(runBatch);
  }

  _setViewMode(mode) {
    if (this._viewMode === mode) return;
    this._viewMode = mode;
    this._settings.set('library.viewMode', mode);

    const btnGrid = this._container.querySelector('.view-toggle--grid');
    const btnList = this._container.querySelector('.view-toggle--list');
    if (btnGrid) btnGrid.classList.toggle('view-toggle--active', mode === 'grid');
    if (btnList) btnList.classList.toggle('view-toggle--active', mode === 'list');

    // Row-height estimate depends on view mode — invalidate the measurement so
    // the next render re-measures.
    this._vsMeasuredRowHeight = null;

    this._applyFilters();
  }

  _toggleFolderBrowse() {
    this._folderBrowse = !this._folderBrowse;
    this._settings.set('library.folderBrowse', this._folderBrowse);
    // Preserve _currentFolderPath across toggles — but only if the path still
    // exists in the current folder index (it may have been removed by a rescan
    // after a source change).
    if (this._folderBrowse && this._currentFolderPath &&
        this._folderIndex && !this._folderIndex.has(this._currentFolderPath)) {
      this._currentFolderPath = null;
    }
    const btnFolder = this._container?.querySelector('.view-toggle--folder');
    if (btnFolder) btnFolder.classList.toggle('view-toggle--active', this._folderBrowse);
    this._renderBreadcrumb();
    this._applyFilters();
  }

  _navigateToFolder(folderPath) {
    this._currentFolderPath = folderPath || null;
    this._renderBreadcrumb();
    this._applyFilters();
    // Reset scroll on navigation
    const wrapper = this._container?.querySelector('.library__grid-wrapper');
    if (wrapper) wrapper.scrollTop = 0;
  }

  _renderBreadcrumb() {
    const crumb = this._container?.querySelector('.library__breadcrumb');
    if (!crumb) return;
    // Keep the header path in sync with the breadcrumb so the displayed
    // directory label tracks drill-down / drill-up navigation in folder view.
    this._updateHeaderPath();
    if (!this._folderBrowse) {
      crumb.hidden = true;
      crumb.innerHTML = '';
      return;
    }
    crumb.hidden = false;
    crumb.innerHTML = '';

    const root = document.createElement('button');
    root.className = 'library__breadcrumb-crumb';
    root.textContent = t('library.allSources');
    root.addEventListener('click', () => this._navigateToFolder(null));
    crumb.appendChild(root);

    const trail = this._currentFolderPath && this._folderIndex
      ? breadcrumbOf(this._folderIndex, this._currentFolderPath)
      : [];
    for (const hop of trail) {
      const sep = document.createElement('span');
      sep.className = 'library__breadcrumb-sep';
      sep.appendChild(icon(ChevronRight, { width: 12, height: 12 }));
      crumb.appendChild(sep);

      const btn = document.createElement('button');
      btn.className = 'library__breadcrumb-crumb';
      btn.textContent = hop.label;
      btn.title = hop.path;
      btn.addEventListener('click', () => this._navigateToFolder(hop.path));
      crumb.appendChild(btn);
    }

    // Last crumb is the current folder — mark as active (non-clickable visual)
    const allCrumbs = crumb.querySelectorAll('.library__breadcrumb-crumb');
    if (allCrumbs.length > 0) {
      allCrumbs[allCrumbs.length - 1].classList.add('library__breadcrumb-crumb--active');
    }
  }

  /**
   * Update the header's directory-path label to match the current view state.
   * Folder view tracks `_currentFolderPath`; flat view keeps the
   * collection-ancestor / source-summary behaviour from `show()`.
   */
  /**
   * Show / hide the "Searching in: ..." scope pill beneath the header. Only
   * surfaces when the user has an active query in folder-view and is drilled
   * into a folder — at root there's no "current folder" distinction to make.
   * Clicking the toggle flips `_searchGlobalOverride` and re-applies filters.
   */
  /**
   * Build a videoPath → [collectionName, categoryName, ...] map so
   * fuzzySearch can score hits against user-assigned context even when the
   * filename itself doesn't contain the query. Heavier than searching just
   * names, so only called when a search query is active.
   */
  _buildSearchContextMap() {
    const map = new Map();
    const add = (path, label) => {
      if (!path || !label) return;
      const list = map.get(path);
      if (list) list.push(label);
      else map.set(path, [label]);
    };

    // The phone's order (backend/web-remote/search-context.js): collections,
    // playlists, categories. Playlists, categories and the video -> category
    // map live at the config ROOT, not under `settings`, so `get()` never
    // sees them: it read `library.categories` / `library.videoCategories`,
    // both always empty, and had no playlists at all, so a category or
    // playlist name found its videos on the phone and not here (FT-046).
    const collections = this._settings.get('library.collections') || [];
    for (const col of collections) {
      if (!col?.name) continue;
      const paths = col.videoPaths || [];
      for (const p of paths) add(p, col.name);
    }

    const playlists = typeof this._settings.getPlaylists === 'function' ? this._settings.getPlaylists() : [];
    for (const pl of playlists || []) {
      if (!pl?.name) continue;
      for (const p of pl.videoPaths || []) add(p, pl.name);
    }

    const categories = (typeof this._settings.getCategories === 'function' ? this._settings.getCategories() : null) || [];
    const videoCategories = (typeof this._settings.getAllVideoCategories === 'function'
      ? this._settings.getAllVideoCategories() : null) || {};
    const catById = new Map();
    for (const c of categories) if (c?.id) catById.set(c.id, c.name || '');
    for (const [videoPath, catIds] of Object.entries(videoCategories)) {
      if (!Array.isArray(catIds)) continue;
      for (const id of catIds) {
        const name = catById.get(id);
        if (name) add(videoPath, name);
      }
    }

    return map;
  }

  /**
   * Toggle a small hint next to the sort dropdown explaining why sort is
   * ignored while the search box has text. Called from `_applyFilters` on
   * every render so the hint tracks the current query state.
   */
  _updateRelevanceHint() {
    const hint = this._container?.querySelector('.library__sort-hint');
    if (!hint) return;
    const active = !!this._searchQuery;
    hint.hidden = !active;
    if (active && !hint.textContent) {
      hint.textContent = ' (relevance)';
    }
  }

  // ============================================================
  // Filter / sort pickers (post-redesign 2026-04-27)
  // ============================================================

  // Translation keys, not literal labels — resolved at render time so a
  // locale switch updates the picker without rebuilding the option list.
  // Five FIELDS, with direction on a separate toggle — the list was ten
  // entries that were really 5 x 2 (Dave, 2026-08-06). `defaultDir` is the
  // direction each field is normally wanted in, applied when you pick it:
  // newest-first for date, A-Z for name, fastest-first for speed.
  static _SORT_OPTIONS = [
    { value: 'name',      defaultDir: 'asc' },
    { value: 'dateAdded', defaultDir: 'desc' },
    { value: 'duration',  defaultDir: 'asc' },
    { value: 'avgSpeed',  defaultDir: 'desc', isSpeed: true },
    { value: 'maxSpeed',  defaultDir: 'desc', isSpeed: true },
  ];

  // `field:dir` -> the existing directional string. Reused for the trigger
  // button so it still reads "Name A-Z" / "Duration Long-Short" rather than
  // a vaguer "Name, descending" — the specific wording is more useful than
  // the generic one, and these strings already exist in all 8 locales.
  static _SORT_LABELS = {
    'name:asc': 'library.sortNameAsc',
    'name:desc': 'library.sortNameDesc',
    'dateAdded:desc': 'library.sortDateAddedDesc',
    'dateAdded:asc': 'library.sortDateAddedAsc',
    'duration:asc': 'library.sortDurationAsc',
    'duration:desc': 'library.sortDurationDesc',
    'avgSpeed:asc': 'library.sortAvgSpeedAsc',
    'avgSpeed:desc': 'library.sortAvgSpeedDesc',
    'maxSpeed:asc': 'library.sortMaxSpeedAsc',
    'maxSpeed:desc': 'library.sortMaxSpeedDesc',
  };

  // Stash's two sorts (Stash "next" lot, 2026-11-19; DESIGN-stash-s1.md (j)
  // #3, #10): rows of the same picker that show only while Stash is on
  // (`settings.stash.enabled`), sorting linked videos by Stash's rating and
  // last played (library-search.js sortVideos; no value sorts last). Kept
  // apart from the five fields every library has; turning Stash off puts a
  // Stash sort back to Name A-Z (sorts are session-only, nothing is stored).
  static _STASH_SORT_OPTIONS = [
    { value: 'stashRating',     defaultDir: 'desc', isStash: true },
    { value: 'stashLastPlayed', defaultDir: 'desc', isStash: true },
  ];

  static _STASH_SORT_LABELS = {
    'stashRating:desc': 'library.sortStashRatingDesc',
    'stashRating:asc': 'library.sortStashRatingAsc',
    'stashLastPlayed:desc': 'library.sortStashLastPlayedDesc',
    'stashLastPlayed:asc': 'library.sortStashLastPlayedAsc',
  };

  /** Every sort field the picker has rows for (Stash's hidden while it is off). */
  static _allSortOptions() {
    return [...Library._SORT_OPTIONS, ...Library._STASH_SORT_OPTIONS];
  }

  /** Is `field` one of Stash's sorts? */
  static _isStashSort(field) {
    return Library._STASH_SORT_OPTIONS.some((o) => o.value === field);
  }

  // The Tags filter shows this many rows per facet (most used first, and
  // every ticked one) until "Show all (n)"; the find box lists every match.
  static _TAG_FACET_LIMIT = 10;

  // A card's (or list row's) tag line shows this many tags, then "+N".
  static _CARD_TAG_LIMIT = 3;

  /**
   * The sort to actually apply, as `[field, dir]`.
   *
   * The FIELD comes from the visible selection where there is one, so the
   * grid can never disagree with the picker. The DIRECTION comes from the
   * per-field memory — it is NOT in the radio's value.
   *
   * That split is the whole point: radio values used to be `name:asc`, and
   * `_applyFilters` read `checked.value` straight into `_sortKey`. When the
   * picker moved to five bare fields those values became `name`, so the
   * direction was silently dropped, `_sortKey` was clobbered to a
   * direction-less string, and `split(':')` handed `undefined` to the
   * sorter, which fell back to ascending every time. The label flipped
   * (that happens before this runs) while the grid never re-sorted.
   */
  _effectiveSort() {
    const checked = this._container?.querySelector(
      '#library-sort-pop input[name="library-sort"]:checked',
    );
    const [storedField, storedDir] = this._sortParts();
    const field = checked?.value || storedField;
    // A Stash sort while Stash is off (its rows are hidden) is Name A-Z.
    if (Library._isStashSort(field) && !this._stashOn()) return ['name', this._sortDirs?.name || 'asc'];
    const dir = this._sortDirs?.[field]
      // Only trust the stored direction when it belongs to this field.
      || (field === storedField ? storedDir : null)
      || Library._allSortOptions().find((o) => o.value === field)?.defaultDir
      || 'asc';
    return [field, dir];
  }

  /**
   * Per-field direction memory, created on demand. Flipping Name to Z-A and
   * coming back to it later should still be Z-A, not silently reset.
   *
   * On demand, and never nulled, because every row handler dereferences it.
   * It used to be built inline in `_buildSortPicker` (which runs once) while
   * `_syncSortForActiveTab` set it to null on a tab switch — so after one
   * switch every click on the sort picker threw, and the picker looked
   * frozen on the old choice while the grid sat on A-Z (Dave, 2026-08-20).
   */
  _ensureSortDirs() {
    if (!this._sortDirs) {
      this._sortDirs = Object.fromEntries(
        Library._allSortOptions().map((o) => [o.value, o.defaultDir]),
      );
      const [curField, curDir] = this._sortParts();
      if (this._sortDirs[curField]) this._sortDirs[curField] = curDir;
    }
    return this._sortDirs;
  }

  /** Current sort as `[field, dir]`. `_sortKey` stays the source of truth. */
  _sortParts() {
    const [field, dir] = String(this._sortKey || 'name:asc').split(':');
    return [field || 'name', dir === 'desc' ? 'desc' : 'asc'];
  }

  /**
   * Build the Sort dropdown picker. The picker's options match the
   * pre-redesign `<select>` exactly — same values, same labels,
   * same `_syncSortForActiveTab` disable rules. Visual treatment is
   * a radio list (single choice, instantly applied).
   */
  _buildSortPicker() {
    const btn = this._container.querySelector('#library-sort-btn');
    const pop = this._container.querySelector('#library-sort-pop');
    const labelEl = btn.querySelector('.library__picker-label');
    const iconSlot = btn.querySelector('.library__picker-icon');
    iconSlot.replaceChildren(icon(ArrowDownAZ, { width: 14, height: 14 }));

    this._ensureSortDirs();

    const labelFor = (field, dir) => {
      const key = Library._SORT_LABELS[`${field}:${dir}`] || Library._STASH_SORT_LABELS[`${field}:${dir}`];
      return key ? t(key) : t('library.sort');
    };

    pop.replaceChildren();
    const rows = [];

    // Redraw every row: wording, arrow and checked state all follow the
    // field's current direction, so each row describes itself.
    const refresh = () => {
      const dirs = this._ensureSortDirs();
      const [curField] = this._sortParts();
      for (const row of rows) {
        const dir = dirs[row.field];
        const selected = row.field === curField;
        row.radio.checked = selected;
        row.text.textContent = labelFor(row.field, dir);
        row.arrow.textContent = dir === 'asc' ? '↑' : '↓';
        row.item.classList.toggle('library__picker-item--selected', selected);
        // Only the selected row is re-clickable to flip, so only it needs
        // to advertise that.
        row.item.title = selected
          ? t('library.sortSwitchTo', { order: labelFor(row.field, dir === 'asc' ? 'desc' : 'asc') })
          : '';
      }
      labelEl.firstChild?.remove?.();
      labelEl.textContent = labelFor(curField, dirs[curField]);
    };
    // Anything that changes the sort from outside the picker (the tab sync)
    // must redraw through this, or the rows, the arrows and the trigger
    // button drift apart from `_sortKey`.
    this._refreshSortPicker = refresh;

    const addRow = (opt) => {
      const item = document.createElement('label');
      item.className = 'library__picker-item library__picker-item--sort';
      item.dataset.value = opt.value;
      if (opt.isSpeed) item.dataset.isSpeed = 'true';
      if (opt.isStash) item.dataset.stash = 'true';

      const radio = document.createElement('input');
      radio.type = 'radio';
      radio.name = 'library-sort';
      radio.value = opt.value;

      const text = document.createElement('span');
      text.className = 'library__picker-item-label';

      const arrow = document.createElement('span');
      arrow.className = 'library__sort-arrow';
      // Decorative — the wording already states the direction.
      arrow.setAttribute('aria-hidden', 'true');

      item.append(radio, text, arrow);
      pop.appendChild(item);
      rows.push({ field: opt.value, item, radio, text, arrow });

      // Selecting a DIFFERENT field. Fires for mouse (via the label) and for
      // keyboard arrow-key navigation, which a click handler alone misses.
      radio.addEventListener('change', () => {
        if (!radio.checked) return;
        this._sortKey = `${opt.value}:${this._ensureSortDirs()[opt.value]}`;
        refresh();
        this._closePicker(pop, btn);
        if (!this._scanning) this._applyFilters();
      });

      // Re-clicking the ALREADY-selected row flips its direction. `change`
      // never fires for an already-checked radio, so these two don't
      // overlap. Popover stays open so the wording change is visible and
      // reversible in place.
      //
      // Listener on the RADIO, not the label. Clicking a label forwards a
      // synthetic click to its control, which bubbles back up — so a
      // label-mounted handler runs TWICE for one user click and the flip
      // undid itself (Dave, 2026-08-06). `preventDefault` suppressed the
      // forward under jsdom, which is why the tests passed while the real
      // thing did nothing. On the radio it is exactly one invocation
      // whether the user hits the dot, the words, or the row padding.
      radio.addEventListener('click', () => {
        if (radio.disabled) return;
        const [curField] = this._sortParts();
        if (curField !== opt.value) return; // selection — `change` handles it
        const dirs = this._ensureSortDirs();
        dirs[opt.value] = dirs[opt.value] === 'asc' ? 'desc' : 'asc';
        this._sortKey = `${opt.value}:${dirs[opt.value]}`;
        refresh();
        if (!this._scanning) this._applyFilters();
      });
    };
    for (const opt of Library._SORT_OPTIONS) addRow(opt);

    // Stash's rows (the "next" lot) exist only while Stash is on: added
    // after the five and removed as it is switched, so with Stash off the
    // picker is exactly as before. _syncSortForActiveTab calls this.
    this._syncStashSortRows = () => {
      const on = this._stashOn();
      let changed = false;
      for (const opt of Library._STASH_SORT_OPTIONS) {
        const at = rows.findIndex((r) => r.field === opt.value);
        if (on && at < 0) { addRow(opt); changed = true; }
        else if (!on && at >= 0) { rows[at].item.remove(); rows.splice(at, 1); changed = true; }
      }
      return changed;
    };
    this._syncStashSortRows();

    refresh();

    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      this._togglePicker(pop, btn);
    });
    this._wirePickerDismissal(pop, btn);
  }

  /**
   * Build the Filters dropdown picker. Tab + VR live here as radio
   * groups. Active filters are reflected in the chip strip below
   * the header (rendered separately by `_renderFilterChips`).
   */
  _buildFiltersPicker() {
    const btn = this._container.querySelector('#library-filters-btn');
    const pop = this._container.querySelector('#library-filters-pop');
    const iconSlot = btn.querySelector('.library__picker-icon');
    iconSlot.replaceChildren(icon(SlidersHorizontal, { width: 14, height: 14 }));

    pop.replaceChildren();

    const tabSection = this._buildPickerSection(t('library.filterMatchStatus'), 'tab', [
      { value: 'all', label: t('library.filterAll') },
      { value: 'matched', label: t('library.filterMatched') },
      { value: 'unmatched', label: t('library.filterUnmatched') },
      // Scripts no video uses, as cards to play and put in playlists (Dave,
      // 2026-11-26: "lets have one called scripts which is just scripts so
      // somone can still make playlists etc with them").
      { value: 'scripts', label: t('library.filterScripts') },
    ], () => this._activeTab, (val) => {
      // Reuse the existing tab switcher — preserves all downstream
      // behaviour (sort options re-disable on unmatched, etc.).
      this._switchTab(val);
      this._renderFilterChips();
      this._updateFiltersBadge();
    });
    pop.appendChild(tabSection);

    const vrSection = this._buildPickerSection(t('library.filterVR'), 'vr', [
      { value: 'all', label: t('library.filterAll') },
      { value: 'vr', label: t('library.filterVROnly') },
      { value: 'flat', label: t('library.filterNonVR') },
    ], () => this._vrFilter || 'all', (val) => {
      this._vrFilter = val;
      this._renderFilterChips();
      this._updateFiltersBadge();
      if (!this._scanning) this._applyFilters();
    });
    pop.appendChild(vrSection);

    // Where it plays from (2026-11-23): only once there are saved streams.
    if ((this._settings.get(SETTING_STREAMS) || []).length) {
      pop.appendChild(this._buildPickerSection(t('library.streams.filterTitle'), 'media', [
        { value: 'all', label: t('library.filterAll') },
        { value: 'local', label: t('library.streams.filterLocal') },
        { value: 'streams', label: t('library.streams.filterStreams') },
      ], () => this._mediaFilter || 'all', (val) => {
        this._mediaFilter = val;
        this._renderFilterChips();
        this._updateFiltersBadge();
        if (!this._scanning) this._applyFilters();
      }));
    }

    // Stash (the "next" lot): "Rated N stars or more" and "Organised in
    // Stash"; the section shows only while Stash is on.
    pop.appendChild(this._buildStashPickerSection());

    // Tags (P1, Round 3): facet groups with counts, a find box, Category and
    // "Tags from". Its rows are built as the picker opens, from the one tag
    // index, so a header render costs nothing and the counts are current.
    pop.appendChild(this._buildTagsPickerSection());

    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (pop.hidden) this._renderTagsPickerBody();
      this._togglePicker(pop, btn);
    });
    this._wirePickerDismissal(pop, btn);

    this._updateFiltersBadge();
  }

  // --- The Stash filter and sorts (Stash "next" lot, 2026-11-19) ---
  //
  // DESIGN-stash-s1.md (j) #3, #10: "Rated N stars or more" (Stash's
  // rating100, 20 per star) and "Organised in Stash" in the Filters picker,
  // and the Stash rating / last played sorts. For LINKED videos only
  // (stash-scene-fields.js: a link whose data counts, the linked server's
  // scene; an unlinked or unrated video is not "rated N stars"). Read from
  // the renderer's copy of main's data, never a request. Shown only while
  // Stash is on; one chip each (`stash-rating`, `stash-organized`);
  // session-only like every filter here, and turning Stash off drops them.

  /** Is Stash on? `settings.stash.enabled` exactly true. */
  _stashOn() {
    try { return this._settings?.get?.('stash.enabled') === true; } catch { return false; }
  }

  /** The Stash filter's state, created on first use (session-only, never stored). */
  _stashFilterState() {
    if (!this._stashFilter) this._stashFilter = emptyStashFilter();
    return this._stashFilter;
  }

  /** path -> Stash's fields of the library's linked videos (memoised on the data, the list and the switch). */
  _stashFieldsIndex() {
    const enabled = this._stashOn();
    const videos = this._videos || [];
    const version = stashVersion();
    const memo = this._stashFieldsMemo;
    if (memo && memo.version === version && memo.videos === videos
      && memo.length === videos.length && memo.enabled === enabled) return memo.index;
    let index;
    try { index = stashFieldsIndex(stashData(), videos, { enabled }); } catch { index = new Map(); }
    this._stashFieldsMemo = { version, videos, length: videos.length, enabled, index };
    return index;
  }

  /** The Filters picker's Stash section: a rating row group and "Organised in Stash". */
  _buildStashPickerSection() {
    const sec = document.createElement('section');
    sec.className = 'library__picker-section library__picker-section--stash';
    sec.dataset.filter = 'stash';
    const heading = document.createElement('h3');
    heading.className = 'library__picker-section-title';
    heading.id = 'library-filter-stash-title';
    heading.textContent = t('library.filterStash');
    sec.setAttribute('aria-labelledby', heading.id);
    sec.appendChild(heading);

    const group = document.createElement('div');
    group.className = 'library__picker-options';
    group.setAttribute('role', 'radiogroup');
    group.setAttribute('aria-label', t('library.filterStashRating'));
    for (let stars = 0; stars <= STASH_MAX_STARS; stars++) {
      const lbl = document.createElement('label');
      lbl.className = 'library__picker-item';
      lbl.dataset.value = String(stars);
      const radio = document.createElement('input');
      radio.type = 'radio';
      radio.name = 'library-filter-stash-rating';
      radio.value = String(stars);
      radio.addEventListener('change', () => {
        if (radio.checked) this._setStashFilter({ minStars: stars });
      });
      const txt = document.createElement('span');
      txt.textContent = stars === 0
        ? t('library.filterStashRatingAny')
        : t('library.filterStashRatingAtLeast', { count: stars });
      lbl.append(radio, txt);
      group.appendChild(lbl);
    }
    sec.appendChild(group);

    const org = document.createElement('label');
    org.className = 'library__picker-item';
    const box = document.createElement('input');
    box.type = 'checkbox';
    box.dataset.filterKey = 'stash-organized';
    box.addEventListener('change', () => this._setStashFilter({ organized: box.checked }));
    const orgText = document.createElement('span');
    orgText.textContent = t('library.filterStashOrganised');
    org.append(box, orgText);
    sec.appendChild(org);

    this._syncStashPickerSection(sec);
    return sec;
  }

  /** The Stash section follows the switch and the state (a chip's ×, Clear filters, Stash off). */
  _syncStashPickerSection(sec = this._container?.querySelector('#library-filters-pop .library__picker-section--stash')) {
    if (!sec) return;
    sec.hidden = !this._stashOn();
    const state = this._stashFilterState();
    const min = String(stashMinStars(state));
    for (const radio of sec.querySelectorAll('input[name="library-filter-stash-rating"]')) radio.checked = radio.value === min;
    const box = sec.querySelector('input[data-filter-key="stash-organized"]');
    if (box) box.checked = state.organized === true;
  }

  /** Change the Stash filter (a picker row, a chip's ×): the picker, chips, badge and grid follow. */
  _setStashFilter(patch) {
    const state = this._stashFilterState();
    const next = { ...state, ...patch };
    const minStars = stashMinStars(next);
    const organized = next.organized === true;
    if (minStars === stashMinStars(state) && organized === (state.organized === true)) return false;
    this._stashFilter = { minStars, organized };
    this._syncStashPickerSection();
    this._renderFilterChips();
    this._updateFiltersBadge();
    if (!this._scanning) this._applyFilters();
    return true;
  }

  /** The Stash filter's chips (none while Stash is off). */
  _stashChips() {
    if (!this._stashOn()) return [];
    const state = this._stashFilterState();
    const chips = [];
    const min = stashMinStars(state);
    if (min > 0) chips.push({ key: 'stash-rating', label: t('library.filterChipStashRating', { count: min }) });
    if (state.organized === true) chips.push({ key: 'stash-organized', label: t('library.filterStashOrganised') });
    return chips;
  }

  /** Is this a chip of the Stash filter? */
  _isStashChipKey(key) {
    return key === 'stash-rating' || key === 'stash-organized';
  }

  /** Is the Stash filter hiding anything right now (Stash on, a value picked)? */
  _stashFilterOn() {
    return this._stashOn() && stashFilterActive(this._stashFilter);
  }

  /**
   * Stash turned on or off, or main's Stash data changed. The picker's Stash
   * rows and section follow the switch; off drops a Stash sort (Name A-Z)
   * and the Stash filter (session-only: nothing stored is lost). The grid
   * re-sorts / re-filters once (coalesced) when a Stash sort or filter was
   * reading the data; while the video options dialog is open that render
   * is owed to its close.
   */
  _onStashLibraryChanged() {
    if (!this._container) return;
    const on = this._stashOn();
    const [field] = this._sortParts();
    const owed = Library._isStashSort(field) || stashFilterActive(this._stashFilter);
    if (!on && stashFilterActive(this._stashFilter)) this._stashFilter = emptyStashFilter();
    this._syncStashPickerSection();
    this._syncSortForActiveTab();
    this._renderFilterChips();
    this._updateFiltersBadge();
    if (!owed || this._stashRefreshQueued) return;
    this._stashRefreshQueued = true;
    const pass = this._filterPass || 0;
    setTimeout(() => {
      this._stashRefreshQueued = false;
      if ((this._filterPass || 0) !== pass) return;
      if (this._videoOptionsOpen) { this._renderOwedOnClose = true; return; }
      if (this._openMenu || this._scanning) return;
      if (!this._container?.querySelector('.library__grid')) return;
      this._applyFilters();
    }, 0);
  }

  // --- The Tags filter (DESIGN-video-options.md (e); plan §2.2 "Filtering") ---
  //
  // Every ticked tag, the length buckets OR (video-tags.js filterByTags, mode
  // 'facets'; Dave 2026-11-22); Category (FunSync's own categories) and "Tags from" (the
  // Source facet: EroScripts / the script file / you) are two more facets.
  // One chip per selected value (filter-chips.js `extra`, keyed `tag:<key>`,
  // `category:<id>`, `source:<id>`; an exclude would be `tag-not:<key>`: the
  // engine supports it, the first UI only includes). The state is
  // session-only (Dave's answer 5) and search never matches tags (answer 4).

  /** The Tags filter's state, created on first use (session-only, never stored). */
  _tagFilterState() {
    if (!this._tagFilter) this._tagFilter = { ...emptyTagFilter(), labels: new Map() };
    if (!(this._tagFilter.labels instanceof Map)) this._tagFilter.labels = new Map();
    return this._tagFilter;
  }

  /** The library's one tag index (path -> effective tags), memoised. */
  _tagIndexMemo() {
    if (!this._tagIndexObj) {
      this._tagIndexObj = new LibraryTagIndex({
        settings: () => this._settings,
        videos: () => this._videos || [],
        scriptMeta: () => scriptMetaMap(),
        scriptMetaVersion: () => scriptMetaVersion(),
        // Stash S1: the `stash` source (stash-store.js; off or never set
        // up gives none: the index reads `stash.enabled` itself).
        stashData: () => stashData(),
        stashVersion: () => stashVersion(),
      });
    }
    return this._tagIndexObj;
  }

  /** Tags on cards and list rows (Settings > Appearance; store default false). */
  _showTagsOnCards() {
    return this._settings?.get?.('library.showTagsOnCards') === true;
  }

  /**
   * A tag map or the script files' metadata changed: re-index, refresh an
   * open picker's counts, and re-filter once (coalesced) when the filter or
   * the cards' tag line reads the index. While the video options dialog is
   * open the render is owed to its close; a filter pass that ran since
   * already read the new tags.
   */
  _onTagDataChanged() {
    this._tagIndexObj?.bump();
    if (!this._container) return;
    const pop = this._container.querySelector('#library-filters-pop');
    if (pop && !pop.hidden) this._renderTagsPickerBody();
    if (!tagFilterActive(this._tagFilter) && !this._showTagsOnCards()) return;
    if (this._tagRefreshQueued) return;
    this._tagRefreshQueued = true;
    const pass = this._filterPass || 0;
    setTimeout(() => {
      this._tagRefreshQueued = false;
      if ((this._filterPass || 0) !== pass) return;
      if (this._videoOptionsOpen) { this._renderOwedOnClose = true; return; }
      if (this._openMenu || this._scanning) return;
      if (!this._container?.querySelector('.library__grid')) return;
      this._applyFilters();
    }, 0);
  }

  /** A facet's name, translated (`tags.facet.*`; the dash is not in the key). */
  _tagFacetName(facet) {
    return t(`tags.facet.${facet === 'script-type' ? 'scriptType' : facet}`);
  }

  /** A tag as shown: a length gets its unit ("10-25 min"), anything else its label. */
  _tagShownLabel(tag) {
    if (tag?.facet === 'length') return t('tags.lengthMinutes', { range: tag.label });
    return String(tag?.label ?? '');
  }

  /** The "Tags from" row names: EroScripts / Stash / The script file / You. */
  _tagSourceName(source) {
    if (source === 'eroscripts') return t('library.filterTagSourceEroscripts');
    if (source === 'funscript') return t('library.filterTagSourceFile');
    if (source === 'user') return t('library.filterTagSourceUser');
    if (source === 'stash') return t('tags.source.stash');
    return String(source);
  }

  /**
   * A tag key's facet and label for its chip: what the picker row (or the
   * dialog's chip) said when it was picked, else the index's, else the key
   * itself de-slugged.
   */
  _tagChipInfo(key) {
    const known = this._tagFilterState().labels.get(key)
      || this._tagIndexObj?.peek()?.counts?.get(key);
    if (known) return { facet: known.facet, label: known.label };
    const parsed = parseTagKey(key);
    return { facet: parsed?.facet || 'content', label: parsed?.facet === 'length' ? parsed.value : deslug(parsed?.value || key) };
  }

  /** The chips of the Tags filter, in the order of its picker. */
  _tagChips() {
    const state = this._tagFilterState();
    const chips = [];
    const facetChip = (facet, value, not = false) => t(not ? 'library.filterChipFacetNot' : 'library.filterChipFacet', { facet, value });
    const cats = state.categories.length > 0 && typeof this._settings?.getCategories === 'function'
      ? (this._settings.getCategories() || []) : [];
    for (const id of state.categories) {
      const cat = cats.find((c) => c.id === id);
      chips.push({ key: `category:${id}`, label: facetChip(t('library.filterCategory'), cat ? cat.name : String(id)) });
    }
    for (const key of state.include) {
      const info = this._tagChipInfo(key);
      chips.push({ key: `tag:${key}`, label: facetChip(this._tagFacetName(info.facet), this._tagShownLabel(info)) });
    }
    for (const key of state.exclude) {
      const info = this._tagChipInfo(key);
      chips.push({ key: `tag-not:${key}`, label: facetChip(this._tagFacetName(info.facet), this._tagShownLabel(info), true) });
    }
    for (const source of state.sources) {
      chips.push({ key: `source:${source}`, label: facetChip(t('library.filterTagSource'), this._tagSourceName(source)) });
    }
    return chips;
  }

  /** Is this a chip of the Tags filter? */
  _isTagChipKey(key) {
    return typeof key === 'string' && /^(tag|tag-not|category|source):./.test(key);
  }

  /**
   * Turn one value of the Tags filter on or off, by its chip key
   * (`tag:<key>`, `tag-not:<key>`, `category:<id>`, `source:<id>`). Off is
   * what a chip's × does. `info` ({facet, label}) names a tag for its chip.
   * Nothing is stored. Returns true when the state changed.
   */
  _setTagFilter(chipKey, on, info = null) {
    if (!this._isTagChipKey(chipKey)) return false;
    const state = this._tagFilterState();
    const cut = chipKey.indexOf(':');
    const kind = chipKey.slice(0, cut);
    const value = chipKey.slice(cut + 1);
    const listName = { tag: 'include', 'tag-not': 'exclude', category: 'categories', source: 'sources' }[kind];
    const current = state[listName];
    const has = current.includes(value);
    if (on === has) return false;
    state[listName] = on ? [...current, value] : current.filter((v) => v !== value);
    if (on && info && (kind === 'tag' || kind === 'tag-not')) state.labels.set(value, { facet: info.facet, label: info.label });
    return true;
  }

  /**
   * A category deleted while it was picked leaves the filter (its chip would
   * name nothing and hide every video). Only the session's filter changes.
   */
  _pruneTagFilter(state) {
    if (state.categories.length === 0 || typeof this._settings?.getCategories !== 'function') return;
    const cats = this._settings.getCategories();
    if (!Array.isArray(cats)) return;
    const ids = new Set(cats.map((c) => c?.id));
    const kept = state.categories.filter((id) => ids.has(id));
    if (kept.length === state.categories.length) return;
    state.categories = kept;
    this._renderFilterChips?.();
    this._updateFiltersBadge?.();
  }

  /** After the Tags filter changed: the chips, the badge, the picker's ticks, the grid. */
  _tagFilterChanged() {
    this._syncTagPickerChecks();
    this._renderFilterChips();
    this._updateFiltersBadge();
    if (!this._scanning) this._applyFilters();
  }

  /** The picker's ticks follow the state (a chip's × or Clear filters changed it). */
  _syncTagPickerChecks() {
    const sec = this._container?.querySelector('#library-filters-pop .library__picker-section--tags');
    if (!sec) return;
    const on = new Set(this._tagChips().map((c) => c.key));
    for (const box of sec.querySelectorAll('input[type="checkbox"][data-filter-key]')) {
      box.checked = on.has(box.dataset.filterKey);
    }
  }

  /**
   * "Show videos with this tag" from the video options dialog's chip menu:
   * the Tags filter becomes this one tag (its other picks go; Match status,
   * VR and the search stay, and the video it came from passed them), the
   * grid re-filters, and the focus goes to the grid's first card.
   */
  _showVideosWithTag(key, tag = null) {
    const parsed = parseTagKey(key);
    if (!parsed || !parsed.facet) return false;
    const state = this._tagFilterState();
    state.include = [];
    state.exclude = [];
    state.categories = [];
    state.sources = [];
    const info = tag && typeof tag === 'object' && typeof tag.label === 'string'
      ? { facet: tag.facet || parsed.facet, label: tag.label }
      : null;
    this._setTagFilter(`tag:${parsed.facet}:${parsed.value}`, true, info);
    this._tagFilterChanged();
    const first = this._container?.querySelector('.library__card .library__kebab-btn, .library__list-item .library__list-kebab');
    const chip = this._container?.querySelector(`#library-chips .filter-chip[data-filter-key="tag:${parsed.facet}:${parsed.value}"]`);
    const target = first || chip;
    if (target) {
      try { target.focus({ preventScroll: false }); } catch { /* not focusable */ }
    }
    return true;
  }

  /** The Tags section's shell in the Filters picker: heading, find box, groups. */
  _buildTagsPickerSection() {
    const sec = document.createElement('section');
    sec.className = 'library__picker-section library__picker-section--tags';
    sec.dataset.filter = 'tags';
    const heading = document.createElement('h3');
    heading.className = 'library__picker-section-title';
    heading.id = 'library-filter-tags-title';
    heading.textContent = t('library.filterTags');
    sec.setAttribute('aria-labelledby', heading.id);
    sec.appendChild(heading);

    const find = document.createElement('input');
    find.type = 'search';
    find.className = 'library__tag-find';
    find.placeholder = t('library.filterTagsFind');
    find.setAttribute('aria-label', t('library.filterTagsFindAria'));
    find.setAttribute('autocomplete', 'off');
    find.spellcheck = false;
    find.value = this._tagFindText || '';
    find.addEventListener('input', () => {
      this._tagFindText = find.value;
      this._renderTagGroups();
    });
    sec.appendChild(find);

    const groups = document.createElement('div');
    groups.className = 'library__tag-groups';
    sec.appendChild(groups);

    const note = document.createElement('p');
    note.className = 'library__tag-note';
    note.setAttribute('role', 'status');
    note.hidden = true;
    sec.appendChild(note);
    return sec;
  }

  /**
   * Fill the Tags section from the one tag index: the counts are the number
   * of library videos with each value (copies counted per path, before the
   * duplicate-name collapse). Keeps the find box's text and the focused row.
   */
  _renderTagsPickerBody() {
    const sec = this._container?.querySelector('#library-filters-pop .library__picker-section--tags');
    if (!sec) return;
    const result = this._tagIndexMemo().get();
    const libraryPaths = new Set((this._videos || []).map((v) => v.path));

    const categories = [];
    const cats = typeof this._settings?.getCategories === 'function' ? (this._settings.getCategories() || []) : [];
    const assigned = typeof this._settings?.getAllVideoCategories === 'function' ? (this._settings.getAllVideoCategories() || {}) : {};
    const catCount = new Map();
    for (const [p, ids] of Object.entries(assigned)) {
      if (!libraryPaths.has(p) || !Array.isArray(ids)) continue;
      for (const id of new Set(ids)) catCount.set(id, (catCount.get(id) || 0) + 1);
    }
    for (const cat of cats) {
      const count = catCount.get(cat.id) || 0;
      if (count > 0 || this._tagFilterState().categories.includes(cat.id)) {
        categories.push({ key: `category:${cat.id}`, label: String(cat.name ?? ''), count, cat });
      }
    }

    const byFacet = new Map();
    for (const row of result.counts.values()) {
      if (!byFacet.has(row.facet)) byFacet.set(row.facet, []);
      byFacet.get(row.facet).push(row);
    }
    // A tag picked that no video has now (its last copy was removed) still
    // shows, unticked by nobody, so its chip and its row agree.
    for (const key of [...this._tagFilterState().include, ...this._tagFilterState().exclude]) {
      if (result.counts.has(key)) continue;
      const info = this._tagChipInfo(key);
      if (!byFacet.has(info.facet)) byFacet.set(info.facet, []);
      byFacet.get(info.facet).push({ key, facet: info.facet, label: info.label, count: 0 });
    }

    const sources = SOURCE_FACET
      .map((s) => ({ key: `source:${s}`, source: s, label: this._tagSourceName(s), count: result.sourceCounts[s] || 0 }))
      .filter((r) => r.count > 0 || this._tagFilterState().sources.includes(r.source));

    this._tagPickerData = { categories, byFacet, sources };
    const find = sec.querySelector('.library__tag-find');
    if (find && find.value !== (this._tagFindText || '')) find.value = this._tagFindText || '';
    this._renderTagGroups();
  }

  /** The facet groups, narrowed by the find box (no cap while finding). */
  _renderTagGroups() {
    const sec = this._container?.querySelector('#library-filters-pop .library__picker-section--tags');
    const data = this._tagPickerData;
    if (!sec || !data) return;
    const groupsEl = sec.querySelector('.library__tag-groups');
    const note = sec.querySelector('.library__tag-note');
    const focusedKey = groupsEl.contains(document.activeElement) ? document.activeElement?.dataset?.filterKey : null;
    groupsEl.replaceChildren();
    const query = this._tagFindText || '';
    const on = new Set(this._tagChips().map((c) => c.key));
    const expanded = this._tagFacetsExpanded || (this._tagFacetsExpanded = new Set());
    const LIMIT = Library._TAG_FACET_LIMIT;

    // Tag facets: most used first. Category keeps your categories' order and
    // "Tags from" its own (EroScripts, the script file, you).
    const addGroup = (id, title, rows, rowKey, shown, mark = null, { ordered = false } = {}) => {
      const visible = ordered
        ? facetRows(rows, query, shown).sort((a, b) => rows.indexOf(a) - rows.indexOf(b))
        : facetRows(rows, query, shown);
      if (visible.length === 0) return;
      const set = document.createElement('fieldset');
      set.className = 'library__tag-facet';
      set.dataset.facet = id;
      const legend = document.createElement('legend');
      legend.className = 'library__tag-facet-title';
      legend.textContent = title;
      set.appendChild(legend);
      const capped = !query && !expanded.has(id) && visible.length > LIMIT;
      // Ticked rows always show, even past the cap.
      const list = capped
        ? visible.filter((r, i) => i < LIMIT || on.has(rowKey(r)))
        : visible;
      for (const row of list) {
        const key = rowKey(row);
        const label = document.createElement('label');
        label.className = 'library__picker-item library__tag-option';
        const box = document.createElement('input');
        box.type = 'checkbox';
        box.dataset.filterKey = key;
        box.checked = on.has(key);
        box.setAttribute('aria-label', t('library.filterTagOptionAria', { label: shown(row), count: row.count }));
        box.addEventListener('change', () => {
          const info = row.facet ? { facet: row.facet, label: row.label } : null;
          if (this._setTagFilter(key, box.checked, info)) this._tagFilterChanged();
        });
        label.appendChild(box);
        if (mark) {
          const m = mark(row);
          if (m) label.appendChild(m);
        }
        const text = document.createElement('span');
        text.className = 'library__tag-option-label';
        text.textContent = shown(row);
        label.appendChild(text);
        // Stash's sub-tags (the opt-in "Use Stash's tag aliases and
        // sub-tags", library-tag-filter.js): "includes N sub-tags", as text.
        if (row.subTags > 0) {
          const subNote = subTagNoteText(row, t);
          if (subNote) {
            const sub = document.createElement('span');
            sub.className = 'library__tag-option-subtags';
            sub.textContent = subNote;
            label.appendChild(sub);
            box.setAttribute('aria-label', `${box.getAttribute('aria-label')}, ${subNote}`);
          }
        }
        const count = document.createElement('span');
        count.className = 'library__tag-option-count';
        count.setAttribute('aria-hidden', 'true');
        count.textContent = String(row.count);
        label.appendChild(count);
        set.appendChild(label);
      }
      if (!query && visible.length > LIMIT) {
        const more = document.createElement('button');
        more.type = 'button';
        more.className = 'library__tag-show-all';
        more.dataset.filterKey = `more:${id}`;
        more.textContent = expanded.has(id)
          ? t('library.filterTagsShowFewer')
          : t('library.filterTagsShowAll', { count: visible.length });
        more.addEventListener('click', (e) => {
          e.stopPropagation();
          if (expanded.has(id)) expanded.delete(id); else expanded.add(id);
          this._renderTagGroups();
        });
        set.appendChild(more);
      }
      groupsEl.appendChild(set);
    };

    addGroup('category', t('library.filterCategory'), data.categories, (r) => r.key, (r) => r.label, (r) => {
      try {
        return createCategoryMark(r.cat, { className: 'library__tag-category-mark', size: 10 });
      } catch { return null; }
    }, { ordered: true });
    for (const facet of TAG_FILTER_FACETS) {
      const rows = data.byFacet.get(facet);
      if (rows?.length) addGroup(facet, this._tagFacetName(facet), rows, (r) => `tag:${r.key}`, (r) => this._tagShownLabel(r));
    }
    addGroup('source', t('library.filterTagSource'), data.sources, (r) => r.key, (r) => r.label, null, { ordered: true });

    const empty = groupsEl.children.length === 0;
    note.hidden = !empty;
    if (empty) {
      const nothing = data.categories.length === 0 && data.byFacet.size === 0 && data.sources.length === 0;
      note.textContent = nothing || !query ? t('library.filterTagsEmpty') : t('library.filterTagsNoMatch', { query });
    } else {
      note.textContent = '';
    }
    if (focusedKey) {
      for (const node of groupsEl.querySelectorAll('[data-filter-key]')) {
        if (node.dataset.filterKey === focusedKey) { node.focus(); break; }
      }
    }
  }

  /**
   * Build a labelled radio group for a filter dimension. Used by
   * `_buildFiltersPicker` for both Tab and VR. Returns a section
   * element ready to append.
   */
  _buildPickerSection(title, key, options, getValue, onChange) {
    const sec = document.createElement('section');
    sec.className = 'library__picker-section';
    sec.dataset.filter = key;
    const heading = document.createElement('h3');
    heading.className = 'library__picker-section-title';
    heading.textContent = title;
    sec.appendChild(heading);
    const group = document.createElement('div');
    group.className = 'library__picker-options';
    group.setAttribute('role', 'radiogroup');
    group.setAttribute('aria-label', title);
    const current = getValue();
    for (const opt of options) {
      const lbl = document.createElement('label');
      lbl.className = 'library__picker-item';
      lbl.dataset.value = opt.value;
      const radio = document.createElement('input');
      radio.type = 'radio';
      radio.name = `library-filter-${key}`;
      radio.value = opt.value;
      radio.checked = current === opt.value;
      radio.addEventListener('change', () => {
        if (!radio.checked) return;
        onChange(opt.value);
      });
      const txt = document.createElement('span');
      txt.textContent = opt.label;
      lbl.appendChild(radio);
      lbl.appendChild(txt);
      group.appendChild(lbl);
    }
    sec.appendChild(group);
    return sec;
  }

  /**
   * Render the active-filter chip strip via the shared filter-chips
   * module. Called after every state change to tab / vr filter; also
   * after `_renderWithHeader` rebuilds the DOM. The defaults map
   * deliberately uses `tab: 'all'` not `tab: 'matched'` so the prior
   * default tab ('matched') ALSO surfaces as a chip — gives the user
   * an honest "this is what's filtering your view" indicator and a
   * one-click way to see all videos.
   */
  _renderFilterChips() {
    const container = this._container?.querySelector('#library-chips');
    if (!container) return;
    try { this._renderFilterChipsInner(container); } finally {
      // The Scripts filter's Unassigned / All pills, at the row's right end (2026-11-26).
      if (this._activeTab === 'scripts') {
        container.appendChild(this._scriptsScopePills());
        container.hidden = false;
      }
    }
  }

  _renderFilterChipsInner(container) {
    renderFilterChips({
      container,
      state: { tab: this._activeTab, vr: this._vrFilter || 'all', media: this._mediaFilter || 'all' },
      defaults: { tab: 'all', vr: 'all', media: 'all' },
      labels: {
        tab: { matched: t('library.filterMatched'), unmatched: t('library.filterUnmatched'), scripts: t('library.filterScripts') },
        vr:  { vr: t('library.filterVROnly'), flat: t('library.filterNonVR') },
        media: { local: t('library.streams.filterLocal'), streams: t('library.streams.filterStreams') },
      },
      // One chip per value of the Stash filter (`stash-rating`,
      // `stash-organized`), then of the Tags filter (keyed `tag:<key>`, ...).
      extra: [...this._stashChips(), ...this._tagChips()],
      iconFactory: (_name, size) => icon(X, { width: size, height: size }),
      onRemove: (key) => {
        if (this._isStashChipKey(key)) {
          this._setStashFilter(key === 'stash-rating' ? { minStars: 0 } : { organized: false });
          return;
        }
        if (this._isTagChipKey(key)) {
          // Through the one path that also unticks its picker row.
          if (this._setTagFilter(key, false)) this._tagFilterChanged();
          return;
        }
        if (key === 'tab') {
          // `_switchTab` already redraws the chips and badge and runs
          // `_applyFilters`. A second render here read the scroll position
          // half-way through the first one and its restore ran last, so
          // the X at the bottom of a long list dropped the user mid-list
          // (FT-068, app test V81).
          this._switchTab('all');
          return;
        } else if (key === 'vr') {
          this._vrFilter = 'all';
          // Update the picker radio so reopening shows the new state.
          const pop = this._container.querySelector('#library-filters-pop');
          const radio = pop?.querySelector('input[name="library-filter-vr"][value="all"]');
          if (radio) radio.checked = true;
        } else if (key === 'media') {
          this._mediaFilter = 'all';
          const radio = this._container.querySelector('#library-filters-pop input[name="library-filter-media"][value="all"]');
          if (radio) radio.checked = true;
        }
        this._renderFilterChips();
        this._updateFiltersBadge();
        if (!this._scanning) this._applyFilters();
      },
    });
  }

  /** Update the count badge on the Filters trigger. */
  _updateFiltersBadge() {
    const badge = this._container?.querySelector('#library-filters-badge');
    if (!badge) return;
    const n = countActiveFilters(
      { tab: this._activeTab, vr: this._vrFilter || 'all', media: this._mediaFilter || 'all' },
      { tab: 'all', vr: 'all', media: 'all' },
      [...this._stashChips(), ...this._tagChips()],
    );
    if (n > 0) { badge.textContent = String(n); badge.hidden = false; }
    else { badge.hidden = true; }
  }

  // --- Picker open/close infrastructure ---

  _togglePicker(pop, btn) {
    if (pop.hidden) this._openPicker(pop, btn); else this._closePicker(pop, btn);
  }
  _openPicker(pop, btn) {
    // Close any other open picker first (single-open-at-a-time policy
    // matching the web-remote sheet behaviour — keeps the mental model
    // simple per Norman conceptual model).
    for (const other of this._container.querySelectorAll('.library__picker-pop')) {
      if (other !== pop) {
        const otherBtn = this._container.querySelector(`[aria-controls="${other.id}"]`)
          || this._container.querySelector(`#${other.id.replace('-pop', '-btn')}`);
        this._closePicker(other, otherBtn);
      }
    }
    pop.hidden = false;
    btn.setAttribute('aria-expanded', 'true');
  }
  _closePicker(pop, btn) {
    if (pop.hidden) return;
    pop.hidden = true;
    if (btn) btn.setAttribute('aria-expanded', 'false');
  }
  _wirePickerDismissal(pop, btn) {
    // Outside-click dismissal. Single document-level listener per
    // picker — listeners auto-tear-down on header rebuild because
    // the elements are GC'd when innerHTML reassigns.
    const handler = (e) => {
      if (pop.hidden) return;
      if (pop.contains(e.target) || btn.contains(e.target)) return;
      this._closePicker(pop, btn);
    };
    document.addEventListener('click', handler, { capture: true });
    pop.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        this._closePicker(pop, btn);
        btn.focus();
      }
    });
    // Opened with a click, the focus stays on the button: Escape there
    // closes it too (it did nothing, test day 2026-11-24, B022).
    btn.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape' || pop.hidden) return;
      e.preventDefault();
      e.stopPropagation();
      this._closePicker(pop, btn);
    });
  }

  _updateSearchScope() {
    const pill = this._container?.querySelector('.library__search-scope');
    if (!pill) return;

    const showPill = this._folderBrowse
      && !!this._currentFolderPath
      && !!this._searchQuery;
    if (!showPill) {
      pill.hidden = true;
      pill.innerHTML = '';
      return;
    }
    pill.hidden = false;
    pill.innerHTML = '';

    const label = document.createElement('span');
    label.className = 'library__search-scope-label';
    if (this._searchGlobalOverride) {
      label.textContent = t('library.searchEverywhere');
    } else {
      const folderLabel = this._folderIndex?.get(this._currentFolderPath)?.label
        || this._currentFolderPath.split('/').pop()
        || 'current folder';
      label.textContent = t('library.searchingIn', { folder: folderLabel });
    }
    pill.appendChild(label);

    const toggle = document.createElement('button');
    toggle.className = 'library__search-scope-toggle';
    toggle.textContent = this._searchGlobalOverride ? t('library.limitToFolder') : t('library.searchEverywhere');
    toggle.addEventListener('click', () => {
      this._searchGlobalOverride = !this._searchGlobalOverride;
      this._applyFilters();
    });
    pill.appendChild(toggle);
  }

  /**
   * Resolve the video pool the flat view should render.
   * - When folder browse is on (or we're in the escape-scope branch) and a
   *   sub-folder is selected: descendants of that folder.
   * - When at folder root, no folder index, or no current folder: the full
   *   library.
   * Pure — testable without DOM (just needs the videos / folderIndex / path).
   */
  _getFlatScopeVideos() {
    if (!this._currentFolderPath) return this._videos;
    if (!this._folderIndex) return this._videos;
    const node = this._folderIndex.get(this._currentFolderPath);
    if (!node) return this._videos;
    // Source-root scoping in flat view is identical to "show this source",
    // which the source-picker in the header already handles. Skip — flat-mode
    // shows the full library at the source level.
    if (node.isSourceRoot) return this._videos;
    return descendantsOf(this._folderIndex, this._currentFolderPath);
  }

  /**
   * Pill below the header that surfaces the active folder scope in flat
   * view so the user can see why some videos are missing AND clear it
   * without round-tripping through folder browse. Hidden whenever
   * `_getFlatScopeVideos` would return the full library.
   */
  _updateFolderScope() {
    const pill = this._container?.querySelector('.library__folder-scope');
    if (!pill) return;

    const inFlatView = !this._folderBrowse
      || (this._folderBrowse && this._searchGlobalOverride && !!this._searchQuery);
    const scoped = inFlatView
      && !!this._currentFolderPath
      && this._folderIndex?.has(this._currentFolderPath)
      && !this._folderIndex.get(this._currentFolderPath).isSourceRoot;

    if (!scoped) {
      pill.hidden = true;
      pill.innerHTML = '';
      return;
    }
    pill.hidden = false;
    pill.innerHTML = '';

    const node = this._folderIndex.get(this._currentFolderPath);
    const label = document.createElement('span');
    label.className = 'library__folder-scope-label';
    const folder = node?.label || this._currentFolderPath.split('/').pop() || 'current folder';
    label.textContent = t('library.showingFolder', { folder });
    pill.appendChild(label);

    const clear = document.createElement('button');
    clear.className = 'library__folder-scope-clear';
    clear.type = 'button';
    clear.textContent = t('library.showAll');
    clear.title = t('library.clearFolderScope');
    clear.addEventListener('click', () => this._clearFolderScope());
    pill.appendChild(clear);
  }

  _clearFolderScope() {
    this._currentFolderPath = null;
    this._renderBreadcrumb();
    this._applyFilters();
    const wrapper = this._container?.querySelector('.library__grid-wrapper');
    if (wrapper) wrapper.scrollTop = 0;
  }

  _updateHeaderPath() {
    const el = this._container?.querySelector('.library__dir-path');
    if (!el) return;

    let path = '';
    if (this._folderBrowse && this._currentFolderPath) {
      path = this._currentFolderPath;
    } else if (this._activeCollectionId) {
      const collections = this._settings.get('library.collections') || [];
      const col = collections.find(c => c.id === this._activeCollectionId);
      const sources = this._settings.get('library.sources') || [];
      const syncFolder = col?.syncSource?.folderPath
        || (col?.syncSource?.sourceId
              ? sources.find(s => s.id === col.syncSource.sourceId)?.path
              : null);
      const ancestor = syncFolder
        || (col?.videoPaths?.length ? commonAncestorOfFiles(col.videoPaths) : '');
      if (ancestor) {
        path = ancestor;
      } else {
        const sources = this._settings.get('library.sources') || [];
        const unavailable = this._unavailablePaths || new Set();
        const available = sources.filter(s => s.enabled !== false && !unavailable.has(s.path));
        path = available.length === 1
          ? available[0].path
          : t('library.sourceCount', { count: available.length }); // in the language chosen (B102)
      }
    } else {
      const sources = this._settings.get('library.sources') || [];
      const unavailable = this._unavailablePaths || new Set();
      const available = sources.filter(s => s.enabled !== false && !unavailable.has(s.path));
      path = available.length > 1
        ? available.map(s => s.name).join(', ')
        : (available[0]?.path || '');
    }
    this._headerPath = path;
    el.textContent = path;
    el.title = path;
  }

  _createListItem(video) {
    const row = document.createElement('div');
    row.className = 'library__list-item';
    if (this._selectedPaths.has(video.path)) row.classList.add('library__card--selected');
    row.dataset.videoPath = video.path;

    // Small thumbnail. Same synchronous cache check as _createCard so
    // re-rendered list rows show the thumbnail instantly on scroll
    // instead of flashing back to a placeholder while waiting for the
    // async queue.
    const thumb = document.createElement('div');
    thumb.className = 'library__list-thumb';
    const cachedDataUrl = thumbCache.get(video.path, 0);
    if (cachedDataUrl) {
      const img = document.createElement('img');
      img.alt = '';
      img.decoding = 'async';
      img.src = cachedDataUrl;
      thumb.appendChild(img);
      row.dataset.loaded = 'true';
    } else if (this._noVideoThumbs?.has(video.path)) {
      // Known this session to have no picture (N-05): its tile at once.
      thumb.appendChild(this._noVideoTile(video.name, { stream: !!video._stream }));
      row.dataset.loaded = 'true';
    } else {
      const placeholder = document.createElement('div');
      placeholder.className = 'library__card-placeholder';
      placeholder.appendChild(icon(Clapperboard, { width: 16, height: 16 }));
      thumb.appendChild(placeholder);
    }
    row.appendChild(thumb);

    // Title
    const title = document.createElement('span');
    title.className = 'library__list-title';
    title.textContent = video._stream ? video.name : video.name.replace(/\.[^/.]+$/, '');
    title.title = video.name;
    row.appendChild(title);

    // Its tags, when Settings says so (off by default).
    if (this._showTagsOnCards()) row.appendChild(this._createCardTagLine(video, { list: true }));

    // Heatmap strip (only rendered when a funscript is present)
    if (video.hasFunscript) {
      const heatmap = document.createElement('canvas');
      heatmap.className = 'library__list-heatmap';
      row.appendChild(heatmap);
      // Queued, so every strip of a render is drawn with one layout (V81).
      if (video._heatmapBins) queueRenderBins(heatmap, video._heatmapBins);
    } else {
      row.classList.add('library__list-item--no-heatmap');
    }

    // Badges container
    const badges = document.createElement('div');
    badges.className = 'library__list-badges';
    if (video._stream) badges.appendChild(this._streamBadge(video, 'library__stream-badge--inline'));

    if (video.hasFunscript) {
      const fsBadge = document.createElement('span');
      // Auto-promoted multi-axis is still FunSync's pairing, not the user's (V41).
      const fsManual = video._manualAssociation && !video._autoAssigned;
      fsBadge.className = `library__funscript-badge--inline ${fsManual ? 'library__funscript-badge--manual' : 'library__funscript-badge--auto'}`;
      fsBadge.title = fsManual ? t('library.funscriptManual') : t('library.funscriptAuto');
      fsBadge.appendChild(icon(FileCheck, { width: 14, height: 14, 'stroke-width': 2.5 }));
      // A pairing whose script cannot be found says so (`_scriptMissingStatus`).
      if (this._scriptMissingStatus(video)) this._decorateScriptBadge(fsBadge, video);
      badges.appendChild(fsBadge);
    }

    if (video.hasSubtitle) {
      const subBadge = document.createElement('span');
      subBadge.className = `library__subtitle-badge--inline ${video._manualSubtitle ? 'library__subtitle-badge--manual' : 'library__subtitle-badge--auto'}`;
      subBadge.title = video._manualSubtitle ? t('library.subtitlesManual') : t('library.subtitlesAuto');
      subBadge.appendChild(icon(Captions, { width: 14, height: 14, 'stroke-width': 2.5 }));
      badges.appendChild(subBadge);
    }

    const vrOverridesMap = this._settings.get('library.manualVRType') || {};
    const vrOverride = vrOverridesMap[video.path];
    if (vrOverride === 'vr' || vrOverride === 'flat') {
      const vrBadge = document.createElement('span');
      vrBadge.className = `library__vr-badge library__vr-badge--manual library__vr-badge--${vrOverride}`;
      vrBadge.title = vrOverride === 'vr' ? t('library.vrManual') : t('library.flatManual');
      vrBadge.textContent = vrOverride === 'vr' ? t('library.vrBadge') : t('library.flatBadge');
      badges.appendChild(vrBadge);
    }

    if (video.avgSpeed > 0 || video.maxSpeed > 0) {
      this._addSpeedBadge(badges, { avgSpeed: video.avgSpeed, maxSpeed: video.maxSpeed });
    }

    this._addPlaybackModeBadge(badges, video, { inline: true });

    // Category dots
    const catIds = this._settings.getVideoCategories(video.path);
    if (catIds.length > 0) {
      const allCats = this._settings.getCategories();
      for (const catId of catIds) {
        const cat = allCats.find((c) => c.id === catId);
        if (cat) {
          const dot = createCategoryMark(cat, { className: 'library__card-category-dot', size: 12 });
          dot.title = cat.name;
          badges.appendChild(dot);
        }
      }
    }

    row.appendChild(badges);

    // Duration
    if (video.duration > 0) {
      const dur = document.createElement('span');
      dur.className = 'library__list-duration';
      dur.textContent = this._formatDuration(video.duration);
      row.appendChild(dur);
    }

    // Kebab button
    const kebab = document.createElement('button');
    kebab.className = 'library__list-kebab';
    kebab.appendChild(icon(EllipsisVertical, { width: 16, height: 16 }));
    this._labelOptionsButton(kebab, video);
    kebab.addEventListener('click', (e) => {
      e.stopPropagation();
      this._openVideoOptions(video);
    });
    row.appendChild(this._favouriteButton(video, { list: true }));
    row.appendChild(kebab);
    if (isDisabled(this._settings, video.path)) {
      applyDisabledMark(row, true, { thumb: row.querySelector('.library__list-thumb'), title: row.querySelector('.library__list-title') });
    }

    // Select checkbox (hidden unless select mode)
    const checkbox = document.createElement('div');
    checkbox.className = 'library__card-checkbox';
    checkbox.hidden = !this._selectMode;
    row.appendChild(checkbox);

    // Click to play, or select. Shift enters select mode on its own so the
    // range gesture works without hunting for the Select button first.
    row.addEventListener('click', (e) => {
      if (this._selectMode || e.shiftKey) {
        this._handleSelectionClick(row, video.path, e);
      } else {
        this._playVideo(video);
      }
    });

    // Restore BOTH halves of the selected look. Must run after the checkbox
    // is in the DOM — the class add near the top of this method happens
    // before it exists, which is exactly how the tick went missing.
    this._applySelectionState(row, video.path);

    return row;
  }

  /**
   * Dispatch: build a DOM element for a folder entry, list item, or grid card
   * depending on the item shape and the current view mode.
   */
  _createItemEl(item) {
    if (item && item.isFolder) return this._createFolderCard(item.node, item.count);
    if (item && item._script) return this._createScriptEntry(item);
    return this._viewMode === 'list' ? this._createListItem(item) : this._createCard(item);
  }

  _createFolderCard(node, count) {
    const isList = this._viewMode === 'list';
    const card = document.createElement('div');
    card.className = isList ? 'library__folder-row' : 'library__folder-card';
    card.dataset.folderPath = node.path;

    const thumb = document.createElement('div');
    thumb.className = isList ? 'library__folder-row-thumb' : 'library__folder-thumb';
    this._populateFolderThumb(thumb, node, isList);
    card.appendChild(thumb);

    const info = document.createElement('div');
    info.className = 'library__folder-info';
    const title = document.createElement('div');
    title.className = 'library__folder-title';
    title.textContent = node.label;
    title.title = node.path;
    info.appendChild(title);
    const sub = document.createElement('div');
    sub.className = 'library__folder-count';
    sub.textContent = t('library.videoCount', { count }); // in the language chosen (B102)
    info.appendChild(sub);
    card.appendChild(info);

    // Kebab with "Pin as Collection"
    const kebab = document.createElement('button');
    kebab.className = isList ? 'library__list-kebab' : 'library__kebab-btn';
    kebab.appendChild(icon(EllipsisVertical, { width: 16, height: 16 }));
    kebab.title = t('library.kebabFolderOptions');
    kebab.addEventListener('click', (e) => {
      e.stopPropagation();
      this._showFolderKebabMenu(node, kebab, card);
    });
    card.appendChild(kebab);

    card.addEventListener('click', () => this._navigateToFolder(node.path));
    return card;
  }

  /**
   * Fill a folder card's thumb area. Grid view uses the cached thumbnails of
   * the first 1–4 descendant videos as a mosaic; list view just shows the
   * folder icon. Falls back to the icon when no cached thumbnails exist yet.
   */
  _populateFolderThumb(thumbEl, node, isList) {
    thumbEl.innerHTML = '';
    if (isList) {
      thumbEl.appendChild(icon(Folder, { width: 20, height: 20 }));
      return;
    }
    // User turned off folder previews — show a plain folder icon instead
    // of the video mosaic. Default is ON; only an explicit `false`
    // disables, so untouched installs keep the mosaic.
    if (this._settings?.get?.('library.folderPreviews') === false) {
      thumbEl.appendChild(icon(Folder, { width: 48, height: 48 }));
      return;
    }

    const firstFour = descendantsOf(this._folderIndex, node.path).slice(0, 4);
    const cached = firstFour.map(v => thumbCache.get(v.path, 0));
    const n = cached.filter(Boolean).length;

    if (n === 0) {
      thumbEl.appendChild(icon(Folder, { width: 48, height: 48 }));
      return;
    }
    if (n === 1) {
      const single = document.createElement('div');
      single.className = 'library__folder-mosaic library__folder-mosaic--single';
      const cell = document.createElement('div');
      cell.className = 'library__folder-mosaic-cell';
      cell.style.backgroundImage = `url("${cached.find(Boolean)}")`;
      single.appendChild(cell);
      thumbEl.appendChild(single);
      return;
    }

    const mosaic = document.createElement('div');
    mosaic.className = 'library__folder-mosaic';
    for (let i = 0; i < 4; i++) {
      const cell = document.createElement('div');
      cell.className = 'library__folder-mosaic-cell';
      if (cached[i]) {
        cell.style.backgroundImage = `url("${cached[i]}")`;
      } else {
        cell.classList.add('library__folder-mosaic-cell--empty');
      }
      mosaic.appendChild(cell);
    }
    thumbEl.appendChild(mosaic);
  }

  _showFolderKebabMenu(node, buttonEl, cardEl) {
    // Toggle close if the same button triggers twice (the folder ⋮ is a
    // small menu; a video's ⋮ opens the video options dialog)
    if (this._openMenu && this._openMenuButton === buttonEl) {
      this._closeMenu();
      return;
    }
    this._closeMenu();

    const menu = document.createElement('div');
    menu.className = 'library__kebab-menu';

    const pinItem = document.createElement('button');
    pinItem.className = 'library__kebab-menu-item';
    pinItem.textContent = t('library.pinAsCollection');
    pinItem.addEventListener('click', (e) => {
      e.stopPropagation();
      this._closeMenu();
      this._pinFolderAsCollection(node);
    });
    menu.appendChild(pinItem);

    const selectItem = document.createElement('button');
    selectItem.className = 'library__kebab-menu-item';
    selectItem.textContent = t('library.selectAllInFolder');
    selectItem.addEventListener('click', (e) => {
      e.stopPropagation();
      this._closeMenu();
      this._selectAllInFolder(node);
    });
    menu.appendChild(selectItem);

    // Portal mount — same mechanism as the video kebab menu (refs first,
    // then body-append + fixed positioning; see _positionKebabMenu).
    this._openMenu = menu;
    this._openMenuCard = cardEl;
    this._openMenuButton = buttonEl;
    document.body.appendChild(menu);
    this._positionKebabMenu(menu);

    setTimeout(() => {
      document.addEventListener('click', this._boundCloseMenu, { once: true });
    }, 0);
  }

  _selectAllInFolder(node) {
    if (!node || !this._folderIndex) return;
    const videos = descendantsOf(this._folderIndex, node.path);
    if (videos.length === 0) return;

    // Enter select mode if not already in it
    if (!this._selectMode) this._enterSelectMode();

    // Add every descendant video path to the selection
    for (const v of videos) this._selectedPaths.add(v.path);

    // Re-render so existing visible cards pick up the selected class
    // (new cards use the _createCard check added in fix #1; existing DOM needs updating)
    this._container.querySelectorAll('[data-video-path]').forEach((cardEl) => {
      const p = cardEl.dataset.videoPath;
      if (p) this._applySelectionState(cardEl, p);
    });
    this._updateSelectionCount();
  }

  async _pinFolderAsCollection(node) {
    const paths = descendantsOf(this._folderIndex, node.path).map(v => v.path);
    if (paths.length === 0) {
      const { showToast } = await import('../js/toast.js');
      showToast(t('library.folderEmpty'), 'warn');
      return;
    }
    const name = await Modal.prompt(t('library.pinFolderTitle'), t('library.pinFolderLabel'), node.label);
    if (!name) return;

    // Auto-enable sync-with-source. Pinning a folder has the same
    // intent as syncing: "this folder IS my collection, including any
    // new videos that land in it later". If the folder matches a
    // registered source, track by sourceId (survives path rename);
    // otherwise track by folderPath.
    const sources = this._settings.get('library.sources') || [];
    const canonical = canonicalPath(node.path);
    const matchingSource = sources.find(s => canonicalPath(s.path) === canonical);
    const syncSource = matchingSource
      ? { sourceId: matchingSource.id }
      : { folderPath: canonical };

    const collections = this._settings.get('library.collections') || [];
    const newCol = {
      id: crypto.randomUUID(),
      name,
      videoPaths: [],    // additive-include list (empty — all members come from sync)
      syncSource,
      excludedPaths: [],
    };
    collections.push(newCol);
    this._settings.set('library.collections', collections);

    const { showToast } = await import('../js/toast.js');
    showToast(t('library.pinned', { name, count: paths.length }), 'info');
  }

  /**
   * A card's (or list row's) tag line: the first few of the video's tags
   * (the one tag index, in the engine's facet order), then "+N". Tag names
   * are untrusted text: textContent and a title, never HTML. Empty for a
   * video with no tags (the row still keeps its height on a card).
   */
  _createCardTagLine(video, { list = false } = {}) {
    const line = document.createElement('div');
    line.className = list ? 'library__card-tags library__card-tags--list' : 'library__card-tags';
    let tags = this._cardTagIndex?.get(video?.path);
    if (!this._cardTagIndex) {
      try { tags = this._tagIndexMemo().get().index.get(video?.path); } catch { tags = null; }
    }
    if (!Array.isArray(tags) || tags.length === 0) return line;
    const names = tags.map((tag) => this._tagShownLabel(tag));
    const max = Library._CARD_TAG_LIMIT;
    for (const name of names.slice(0, max)) {
      const chip = document.createElement('span');
      chip.className = 'library__card-tag';
      chip.textContent = name;
      // The longest name gives way first: flex shrinks in proportion to
      // size × factor, so a factor of the name's length CUBED leaves a short
      // tag whole beside a long one, which used to cut it to "t…"
      // (r3-verify-2, 2026-11-18; fixed 2026-11-22). Measured in the app
      // at 160 / 200 / 260 px: "tit" and "big tits" whole beside a 40-char
      // tag; the length alone still trimmed them 1-5 px.
      chip.style.flexShrink = String(Math.pow(Math.min(200, Math.max(1, String(name).length)), 3));
      line.appendChild(chip);
    }
    if (names.length > max) {
      const more = document.createElement('span');
      more.className = 'library__card-tag library__card-tag--more';
      more.textContent = t('library.cardTagsMore', { count: names.length - max });
      line.appendChild(more);
    }
    line.title = names.join(', ');
    return line;
  }

  _createCard(video) {
    const card = document.createElement('div');
    card.className = 'library__card';
    if (this._selectedPaths.has(video.path)) card.classList.add('library__card--selected');
    card.dataset.videoPath = video.path;

    const thumbnail = document.createElement('div');
    thumbnail.className = 'library__card-thumbnail';

    // Synchronous cache check. Without this, every scroll re-renders
    // bare placeholders and even cache-hit thumbnails go through the
    // async _processThumbnailQueue (concurrency-limited, can be
    // backed up by stale in-flight loads for cards that already
    // scrolled out). Result was thumbnails visibly "disappearing" on
    // scroll then re-appearing slowly. Inline cache hit is instant.
    const cachedDataUrl = thumbCache.get(video.path, 0);
    if (cachedDataUrl) {
      const img = document.createElement('img');
      img.alt = '';
      img.decoding = 'async';
      img.src = cachedDataUrl;
      thumbnail.appendChild(img);
      card.dataset.loaded = 'true';
    } else if (this._noVideoThumbs?.has(video.path)) {
      // Known this session to have no picture (N-05): its tile at once.
      thumbnail.appendChild(this._noVideoTile(video.name, { stream: !!video._stream }));
      card.dataset.loaded = 'true';
    } else {
      // Placeholder — kept until the async load completes.
      const placeholder = document.createElement('div');
      placeholder.className = 'library__card-placeholder';
      placeholder.appendChild(icon(Clapperboard, { width: 32, height: 32 }));
      thumbnail.appendChild(placeholder);
    }

    // Hover overlay with play icon
    const overlay = document.createElement('div');
    overlay.className = 'library__card-overlay';
    const playIcon = document.createElement('span');
    playIcon.className = 'library__card-play-icon';
    playIcon.appendChild(icon(Play, { width: 36, height: 36 }));
    overlay.appendChild(playIcon);
    thumbnail.appendChild(overlay);

    // Select checkbox (hidden unless select mode)
    const checkbox = document.createElement('div');
    checkbox.className = 'library__card-checkbox';
    checkbox.hidden = !this._selectMode;
    thumbnail.appendChild(checkbox);

    // Kebab button
    const kebab = document.createElement('button');
    kebab.className = 'library__kebab-btn';
    kebab.appendChild(icon(EllipsisVertical, { width: 16, height: 16 }));
    this._labelOptionsButton(kebab, video);
    kebab.addEventListener('click', (e) => {
      e.stopPropagation();
      this._openVideoOptions(video);
    });
    thumbnail.appendChild(kebab);
    // The heart (zaikechi #381): shown on hover, and always once it is on.
    thumbnail.appendChild(this._favouriteButton(video));

    // Funscript + subtitle badges share a bottom-left flex container.
    // Was hardcoded `left: 6px` for funscript and `left: 26px` for
    // subtitle — meant subtitle-only cards rendered the badge in the
    // wrong place and adding a third badge would collide. The flex
    // container flows them naturally with a `gap` and stays correct
    // regardless of which subset is present.
    if (video.hasFunscript) {
      const badge = document.createElement('span');
      // Auto-promoted multi-axis is still FunSync's pairing, not the user's (V41).
      const fsManual = video._manualAssociation && !video._autoAssigned;
      badge.className = `library__funscript-badge ${fsManual ? 'library__funscript-badge--manual' : 'library__funscript-badge--auto'}`;
      badge.title = fsManual ? t('library.funscriptManual') : t('library.funscriptAuto');
      badge.appendChild(icon(FileCheck, { width: 14, height: 14, 'stroke-width': 2.5 }));
      // A pairing whose script cannot be found says so (`_scriptMissingStatus`).
      if (this._scriptMissingStatus(video)) this._decorateScriptBadge(badge, video);
      this._getOrCreateBadgesContainer(thumbnail).appendChild(badge);
    }
    // A saved stream: not a file on this computer (2026-11-23).
    if (video._stream) this._getOrCreateBadgesContainer(thumbnail).appendChild(this._streamBadge(video));

    if (video.hasSubtitle) {
      const subBadge = document.createElement('span');
      subBadge.className = `library__subtitle-badge ${video._manualSubtitle ? 'library__subtitle-badge--manual' : 'library__subtitle-badge--auto'}`;
      subBadge.title = video._manualSubtitle ? t('library.subtitlesManual') : t('library.subtitlesAuto');
      subBadge.appendChild(icon(Captions, { width: 14, height: 14, 'stroke-width': 2.5 }));
      this._getOrCreateBadgesContainer(thumbnail).appendChild(subBadge);
    }

    // VR override marker — only appears when the user has manually classified
    // this video. Heuristic-only entries get no badge so the grid stays clean.
    const vrOverridesMap = this._settings.get('library.manualVRType') || {};
    const vrOverride = vrOverridesMap[video.path];
    if (vrOverride === 'vr' || vrOverride === 'flat') {
      const vrBadge = document.createElement('span');
      vrBadge.className = `library__vr-badge library__vr-badge--manual library__vr-badge--${vrOverride}`;
      vrBadge.title = vrOverride === 'vr' ? t('library.vrManual') : t('library.flatManual');
      vrBadge.textContent = vrOverride === 'vr' ? t('library.vrBadge') : t('library.flatBadge');
      this._getOrCreateBadgesContainer(thumbnail).appendChild(vrBadge);
    }

    // Category dot badges
    const catIds = this._settings.getVideoCategories(video.path);
    if (catIds.length > 0) {
      const dotsContainer = document.createElement('div');
      dotsContainer.className = 'library__card-category-dots';
      const allCats = this._settings.getCategories();
      for (const catId of catIds) {
        const cat = allCats.find((c) => c.id === catId);
        if (cat) {
          const dot = createCategoryMark(cat, { className: 'library__card-category-dot', size: 12 });
          dot.title = cat.name;
          dotsContainer.appendChild(dot);
        }
      }
      thumbnail.appendChild(dotsContainer);
    }

    // Duration badge on thumbnail (if already known)
    if (video.duration > 0) {
      this._addDurationBadge(thumbnail, video.duration);
    }

    card.appendChild(thumbnail);
    // Disabled (zaikechi #381): shown, dimmed and marked; never chosen by FunSync.
    if (isDisabled(this._settings, video.path)) applyDisabledMark(card, true, { thumb: thumbnail });

    // Heatmap strip between the thumbnail and the title (opt-in, default
    // off — `library.showCardHeatmap`). Deliberately NOT rendered at all
    // when the setting is off, so cards keep their exact current height
    // rather than reserving empty space. When it IS on every card gets a
    // row — a strip, or the muted "unavailable" note for videos with no
    // script — so the grid stays on a uniform baseline either way.
    if (this._showCardHeatmap()) {
      card.appendChild(this._createCardHeatmap(video));
    }

    // Info / title
    const info = document.createElement('div');
    info.className = 'library__card-info';
    const title = document.createElement('div');
    title.className = 'library__card-title';
    title.textContent = video._stream ? video.name : video.name.replace(/\.[^/.]+$/, '');
    title.title = video.name;
    info.appendChild(title);

    // Speed badge in info bar (if stats already computed)
    if (video.avgSpeed > 0 || video.maxSpeed > 0) {
      this._addSpeedBadge(info, { avgSpeed: video.avgSpeed, maxSpeed: video.maxSpeed });
    }

    // Playback-mode badge — sits next to speed in the info bar. Skip-when-single
    // matches the existing pattern: absence = single-axis default, presence =
    // explicitly configured beyond default. Auto-promoted multi-axis videos
    // light up here too, giving visual confirmation that the auto-promote did
    // what the user expected.
    this._addPlaybackModeBadge(info, video);

    card.appendChild(info);

    // A compact tag line (Settings > Appearance, off by default: cards look
    // as before). Like the heatmap row, every card gets one while it is on,
    // so the grid keeps one baseline.
    if (this._showTagsOnCards()) card.appendChild(this._createCardTagLine(video));

    // Click to play, or select. Shift enters select mode on its own so the
    // range gesture works without hunting for the Select button first.
    card.addEventListener('click', (e) => {
      if (this._selectMode || e.shiftKey) {
        this._handleSelectionClick(card, video.path, e);
      } else {
        this._playVideo(video);
      }
    });

    // Hover preview (debounced 300ms, disabled during virtual scroll updates)
    card.addEventListener('mouseenter', () => {
      if (this._scrolling) return;
      this._previewHoverTimer = setTimeout(() => this._startPreview(card, video.path), 300);
    });
    card.addEventListener('mouseleave', () => {
      clearTimeout(this._previewHoverTimer);
      this._stopPreview();
    });

    // Restore BOTH halves of the selected look, after the checkbox exists.
    // See _applySelectionState — the border-only restore at the top of this
    // method is what made the tick disappear on every re-render.
    this._applySelectionState(card, video.path);

    return card;
  }

  // Thumbnail concurrency limiter
  _queueThumbnail(cardEl, videoPath) {
    // `top` is captured once, here, so the priority sort at dequeue time is
    // pure arithmetic. Reading offsetTop per candidate inside the dequeue loop
    // would force a layout flush on every iteration — the opposite of what a
    // scroll-performance fix should do.
    this._pendingThumbnails.push({ cardEl, videoPath, top: cardEl?.offsetTop || 0 });
    this._processThumbnailQueue();
  }

  /** Viewport centre in the scroll container's coordinate space. */
  _viewportCentre() {
    const wrapper = this._container?.querySelector('.library__grid-wrapper');
    if (!wrapper) return 0;
    return wrapper.scrollTop + (wrapper.clientHeight / 2);
  }

  _processThumbnailQueue() {
    // Serve what the user is LOOKING AT first. The queue is filled in DOM
    // order, which means the overscan rows above the viewport were being
    // fetched before the row under the cursor.
    if (this._pendingThumbnails.length > 1) {
      this._pendingThumbnails = prioritiseByDistance(
        this._pendingThumbnails, this._viewportCentre(),
      );
    }

    while (this._activeThumbnails < MAX_CONCURRENT_THUMBNAILS && this._pendingThumbnails.length > 0) {
      const { cardEl, videoPath } = this._pendingThumbnails.shift();
      // Skip cards that have already scrolled out of view since they
      // were queued. Without this, fast scrolling fills the queue with
      // detached-DOM cards whose loads waste backend time and make
      // currently-visible cards wait. The cache is still populated by
      // the eager backend call when present, but we want visible cards
      // to win the queue priority.
      if (!cardEl.isConnected) continue;
      this._activeThumbnails++;

      // Release the slot if this one stalls.
      //
      // THIS IS THE HANG (community #198, multi-drive libraries). A path on a
      // spun-down or disconnected volume blocks in the backend for its full
      // 30s ffmpeg timeout while holding one of four slots. Four such paths
      // and the queue stops entirely — indistinguishable from a frozen app,
      // and only reproducible on a library spanning several drives.
      //
      // The request is NOT cancelled: it keeps running and still populates the
      // cache if it ever completes. Only the SLOT is freed, so responsive
      // drives keep flowing past an unresponsive one.
      let released = false;
      const release = () => {
        if (released) return;
        released = true;
        this._activeThumbnails--;
        this._processThumbnailQueue();
      };
      const stallTimer = setTimeout(() => {
        if (released) return;
        console.warn(
          `[Library] Thumbnail slot stalled >${SLOT_STALL_MS}ms, releasing it: ${videoPath}`
        );
        release();
      }, SLOT_STALL_MS);

      this._loadThumbnail(cardEl, videoPath).finally(() => {
        clearTimeout(stallTimer);
        release();
      });
    }
    // Queue fully drained — end the initial post-scan phase (timing marks
    // + deferred background passes). Subsequent scroll-triggered loads
    // don't re-enter it (the flag stays false).
    if (this._initialThumbsLoading &&
        this._pendingThumbnails.length === 0 &&
        this._activeThumbnails === 0) {
      this._finishInitialThumbsPhase();
    }
  }

  async _loadThumbnail(cardEl, videoPath) {
    try {
      // Check thumbnail cache first
      let result = thumbCache.get(videoPath, 0);
      let dataUrl, duration;

      if (result) {
        dataUrl = result;
      } else {
        const capture = await this._captureVideoFrame(videoPath);
        if (capture?.noVideo) {
          // No picture to grab (an audio file): the logo tile, not the
          // black frame a blank canvas encodes to (N-05).
          this._showNoVideoTile(cardEl, videoPath, capture.duration);
          return;
        }
        dataUrl = capture?.dataUrl || capture;
        duration = capture?.duration;
        // Duration goes in too: the playlists/categories views read it back
        // for their duration badge, so a tile cached here stays complete
        // when those views reuse it.
        if (dataUrl) thumbCache.set(videoPath, 0, dataUrl, duration);

        if (duration) {
          const video = this._videos.find(v => v.path === videoPath);
          if (video) video.duration = duration;
          this._durationCache.set(videoPath, duration);
        }
      }

      if (!dataUrl) {
        // Mark failed so the skeleton shimmer stops — leaving the card
        // 'pending' would animate its placeholder forever on files the
        // backend can't decode.
        cardEl.dataset.loaded = 'failed';
        return;
      }

      const thumbnailContainer = cardEl.querySelector('.library__card-thumbnail') || cardEl.querySelector('.library__list-thumb');
      if (!thumbnailContainer) return;
      // A picture now (a poster the user uploaded for an audio file): the
      // logo tile goes and the next render draws the picture.
      this._noVideoThumbs?.delete(videoPath);
      thumbnailContainer.querySelector('.library__thumb-novideo')?.remove();

      const img = document.createElement('img');
      img.alt = '';
      img.decoding = 'async';
      // Reveal animation class ONLY on the async-load path — the inline
      // cache-hit renders in _createCard/_createListItem must not
      // re-animate on every scroll rebuild.
      img.className = 'library__thumb-img--reveal';
      img.src = dataUrl;
      img.addEventListener('load', () => {
        const placeholder = thumbnailContainer.querySelector('.library__card-placeholder');
        if (placeholder) placeholder.remove();
      });
      thumbnailContainer.insertBefore(img, thumbnailContainer.firstChild);
      cardEl.dataset.loaded = 'true';

      // Duration badge
      if (duration) {
        this._addDurationBadge(thumbnailContainer, duration);

        // Retroactively add duration to list row if it was created before
        // capture populated video.duration (grid view gets it via the badge above).
        if (cardEl.classList.contains('library__list-item')
            && !cardEl.querySelector('.library__list-duration')) {
          const dur = document.createElement('span');
          dur.className = 'library__list-duration';
          dur.textContent = this._formatDuration(duration);
          const kebab = cardEl.querySelector('.library__list-kebab');
          cardEl.insertBefore(dur, kebab || null);
        }
      }
    } catch (err) {
      console.warn('Thumbnail capture failed for', videoPath, err.message);
      // Stop the skeleton shimmer on this card (see the !dataUrl branch).
      try { cardEl.dataset.loaded = 'failed'; } catch { /* card detached */ }
    }
  }

  /**
   * The tile for a file with no picture to show (N-05, Dave 2026-11-08:
   * "audio files just show up as black screens"; also in v0.9.2): the app
   * logo in a muted grey with the file's title, the size of a thumbnail.
   * The list row's thumb is too small for words and has the title beside
   * it, so it shows the logo only (CSS). Shown, never stored: a poster the
   * user uploads for the file replaces it (`_loadThumbnail`), and nothing
   * here touches `library.customThumbnails`.
   */
  _noVideoTile(name, { stream = false } = {}) {
    // The shared builder (no-video-tile.js); a saved stream with no picture
    // of its own is not an audio file (2026-11-23).
    return buildNoVideoTile(name, { stream });
  }

  /** Put the no-picture tile on a card or list row (`_loadThumbnail`). */
  _showNoVideoTile(cardEl, videoPath, duration) {
    (this._noVideoThumbs ||= new Set()).add(videoPath);
    const container = cardEl?.querySelector?.('.library__card-thumbnail')
      || cardEl?.querySelector?.('.library__list-thumb');
    if (!container) return;
    container.querySelector('.library__card-placeholder')?.remove();
    container.querySelector('.library__thumb-novideo')?.remove();
    const video = this._videosByPath?.get?.(videoPath) || this._videos?.find?.((v) => v.path === videoPath);
    container.insertBefore(this._noVideoTile(video?.name || videoPath.split(/[\\/]/).pop(), { stream: isStreamPath(videoPath) }), container.firstChild);
    cardEl.dataset.loaded = 'true';
    if (duration > 0) {
      if (video) video.duration = duration;
      this._durationCache?.set?.(videoPath, duration);
      this._addDurationBadge(container, duration);
      if (cardEl.classList.contains('library__list-item') && !cardEl.querySelector('.library__list-duration')) {
        const dur = document.createElement('span');
        dur.className = 'library__list-duration';
        dur.textContent = this._formatDuration(duration);
        cardEl.insertBefore(dur, cardEl.querySelector('.library__list-kebab') || null);
      }
    }
  }

  /**
   * Frame picker — let the user scrub to a frame and pin it as this
   * video's library thumbnail. WYSIWYG: the <video> element shows the
   * exact frame as the slider moves; on confirm we store the seek % and
   * regenerate the tile at that position. Community request (#180a).
   */
  async _pickCustomThumbnail(video, cardEl) {
    if (video?._stream) return;
    const existing = (this._settings.get('library.customThumbnails') || {})[video.path];
    const startPct = resolveThumbSeekPct(existing);

    await Modal.open({
      title: t('library.customThumbTitle'),
      onRender: (body, close) => {
        const wrap = document.createElement('div');
        wrap.className = 'library__thumb-picker';

        const vid = document.createElement('video');
        vid.className = 'library__thumb-picker-video';
        vid.src = pathToFileURL(video.path);
        vid.muted = true;
        vid.playsInline = true;
        vid.preload = 'auto';

        const slider = document.createElement('input');
        slider.type = 'range';
        slider.min = '0';
        slider.max = '1000';
        slider.step = '1';
        slider.value = String(Math.round(startPct * 1000));
        slider.className = 'library__thumb-picker-slider';
        slider.setAttribute('aria-label', t('library.customThumbTitle'));

        const timeLabel = document.createElement('span');
        timeLabel.className = 'library__thumb-picker-time';
        timeLabel.textContent = '0:00';

        const hint = document.createElement('p');
        hint.className = 'library__thumb-picker-hint';
        hint.textContent = t('library.customThumbHint');

        const actions = document.createElement('div');
        actions.className = 'library__thumb-picker-actions';
        const useBtn = document.createElement('button');
        useBtn.type = 'button';
        useBtn.className = 'library__thumb-picker-use';
        useBtn.textContent = t('library.customThumbUse');
        const cancelBtn = document.createElement('button');
        cancelBtn.type = 'button';
        cancelBtn.className = 'library__thumb-picker-cancel';
        cancelBtn.textContent = t('library.customThumbCancel');
        actions.append(cancelBtn, useBtn);

        const seekToSlider = () => {
          if (vid.duration && isFinite(vid.duration)) {
            const secs = (Number(slider.value) / 1000) * vid.duration;
            vid.currentTime = secs;
            timeLabel.textContent = this._formatDuration(secs);
          }
        };
        slider.addEventListener('input', seekToSlider);
        vid.addEventListener('loadedmetadata', seekToSlider, { once: true });

        cancelBtn.addEventListener('click', () => close());
        useBtn.addEventListener('click', async () => {
          const pct = Number(slider.value) / 1000;
          close();
          await this._saveCustomThumbnail(video, pct, cardEl);
        });

        const bar = document.createElement('div');
        bar.className = 'library__thumb-picker-bar';
        bar.append(slider, timeLabel);

        wrap.append(vid, bar, hint, actions);
        body.appendChild(wrap);
      },
    });
  }

  async _saveCustomThumbnail(video, seekPct, cardEl) {
    const map = { ...(this._settings.get('library.customThumbnails') || {}) };
    map[video.path] = { seekPct };
    this._settings.set('library.customThumbnails', map);
    thumbCache.remove(video.path, 0);
    await this._refreshCardThumbnail(video.path, cardEl);
    const { showToast } = await import('../js/toast.js');
    showToast(t('library.customThumbSaved'), 'success');
  }

  /**
   * Upload-your-own poster image (community #217). Native image picker →
   * main process imports it into the custom-thumbs cache (downscale +
   * re-encode) → stored as `{ type: 'image', imagePath }`, which every
   * thumb surface resolves via customThumbImagePath(). Coexists with the
   * frame picker — whichever was set last wins; Reset clears either.
   */
  async _uploadCustomThumbnail(video, cardEl) {
    const picked = await window.funsync.selectThumbnailImage?.();
    if (!picked?.path) return; // dialog cancelled
    const imported = await window.funsync.importCustomThumbnail?.(video.path, picked.path);
    const { showToast } = await import('../js/toast.js');
    if (!imported?.path) {
      showToast(t('library.customThumbUploadFailed'), 'error');
      return;
    }
    const map = { ...(this._settings.get('library.customThumbnails') || {}) };
    map[video.path] = { type: 'image', imagePath: imported.path };
    this._settings.set('library.customThumbnails', map);
    thumbCache.remove(video.path, 0);
    // Seed the cache with the import's data URL so the tile updates
    // instantly without a read round-trip.
    if (imported.dataUrl) thumbCache.set(video.path, 0, imported.dataUrl);
    await this._refreshCardThumbnail(video.path, cardEl);
    showToast(t('library.customThumbSaved'), 'success');
  }

  async _resetCustomThumbnail(video, cardEl) {
    const map = { ...(this._settings.get('library.customThumbnails') || {}) };
    delete map[video.path];
    this._settings.set('library.customThumbnails', map);
    thumbCache.remove(video.path, 0);
    await this._refreshCardThumbnail(video.path, cardEl);
    const { showToast } = await import('../js/toast.js');
    showToast(t('library.customThumbResetDone'), 'info');
  }

  /**
   * Drop the current tile image + duration badge and re-capture. Called
   * after a custom-thumbnail change; the in-memory cache entry was already
   * removed so `_loadThumbnail` re-fetches at the new seek %.
   */
  async _refreshCardThumbnail(videoPath, cardEl) {
    if (!cardEl) return;
    const container = cardEl.querySelector('.library__card-thumbnail')
      || cardEl.querySelector('.library__list-thumb');
    const badge = container?.querySelector('.library__duration-badge') || null;
    if (container) {
      container.querySelectorAll('img').forEach((img) => img.remove());
      badge?.remove();
    }
    cardEl.dataset.loaded = '';
    await this._loadThumbnail(cardEl, videoPath);
    // The duration is the video's, not the picture's: an uploaded image
    // carries none, so the badge was gone until a reload (triage 2026-11-23).
    if (badge && container && !container.querySelector('.library__duration-badge')) container.appendChild(badge);
  }

  /**
   * Get a single representative frame for a library card. Routes through
   * the backend's ffmpeg by default — much cheaper than the renderer's
   * old hidden-<video> decode (3 concurrent decoders × ~3s each per card
   * was the dominant startup cost for small libraries). The previous
   * <video> path is kept as a fallback in case the backend isn't
   * available (e.g. Python crashed, IPC timeout).
   *
   * Returns { dataUrl, duration } or null on failure.
   *
   * Deduped: concurrent captures for the same path (grid rebuilds reset
   * cards' loaded state mid-flight) share one request via thumb-inflight.
   */
  _captureVideoFrame(videoPath) {
    // A script with no video (2026-11-26): no frame to grab, its tile (Up Next, the queue).
    if (isScriptPath(videoPath)) return Promise.resolve({ noVideo: true, script: true });
    return dedupeThumbRequest(videoPath, () => this._captureVideoFrameUncached(videoPath));
  }

  async _captureVideoFrameUncached(videoPath) {
    // A saved stream has no file to grab a frame from: its saved picture, or
    // the logo tile (never ffmpeg or a <video> on its key).
    if (isStreamPath(videoPath)) {
      const own = customThumbImagePath((this._settings?.get?.('library.customThumbnails') || {})[videoPath]);
      if (own && window.funsync?.readCustomThumbnail) {
        try {
          const img = await window.funsync.readCustomThumbnail(own);
          if (img?.dataUrl) return { dataUrl: img.dataUrl, duration: 0 };
        } catch { /* the tile */ }
      }
      return { noVideo: true, duration: this._videosByPath?.get(videoPath)?.duration || 0 };
    }
    // An audio file has no picture: its tile at once, never ffmpeg or a
    // hidden <video>. Each launch asked ffmpeg for a frame of every .mp3 /
    // .m4a and got a 500 (Dave's log, 2026-11-26). A poster you set wins.
    if (isAudioPath(videoPath)) {
      const own = customThumbImagePath((this._settings?.get?.('library.customThumbnails') || {})[videoPath]);
      if (own && window.funsync?.readCustomThumbnail) {
        try {
          const img = await window.funsync.readCustomThumbnail(own);
          if (img?.dataUrl) return { dataUrl: img.dataUrl, duration: 0 };
        } catch { /* the tile */ }
      }
      return { noVideo: true, audio: true, duration: await audioDuration(videoPath, this._videosByPath?.get(videoPath)?.duration, window.funsync) };
    }
    // Per-video custom-frame override — user picked a specific frame via
    // the kebab "Set thumbnail frame…" action. Falls back to the 10% mark.
    // A pinned frame requests a frame-accurate (`exact`) grab so the tile
    // matches the picker preview; auto thumbs keep the fast keyframe path.
    const custom = (this._settings?.get?.('library.customThumbnails') || {})[videoPath];
    // User-uploaded poster image takes precedence over any frame logic.
    // Read through main (cache dir is main-owned); on failure (file gone,
    // stale settings entry) fall through to the normal frame path.
    const imagePath = customThumbImagePath(custom);
    if (imagePath && window.funsync?.readCustomThumbnail) {
      try {
        const img = await window.funsync.readCustomThumbnail(imagePath);
        if (img?.dataUrl) return { dataUrl: img.dataUrl, duration: 0 };
      } catch { /* fall through to frame path */ }
    }
    const { seekPct, exact } = thumbRequestOpts(custom);
    // Backend ffmpeg path — fast, cached on disk by content hash.
    if (window.funsync?.generateSingleThumbnail) {
      try {
        const result = await window.funsync.generateSingleThumbnail(videoPath, { seekPct, width: 320, exact });
        if (result?.dataUrl) {
          return { dataUrl: result.dataUrl, duration: result.duration || 0 };
        }
      } catch {
        // Fall through to renderer fallback below.
      }
    }
    // Fallback — original renderer-side <video> decode. Honors a pinned
    // frame too (it previously hardcoded the 10% mark).
    return this._captureVideoFrameViaVideoElement(videoPath, exact ? seekPct : null);
  }

  /**
   * Original renderer-side decode. Slow (loads entire video file) but
   * works without a backend. Kept as a safety net for the case where
   * the Python ffmpeg path is broken or unavailable.
   *
   * @param {string} videoPath
   * @param {number|null} [pinnedSeekPct] — user-picked frame position
   *   (0..1); when set, seek there instead of the default 10%/5s mark.
   *   <video> currentTime seeks are frame-accurate, matching the picker.
   */
  _captureVideoFrameViaVideoElement(videoPath, pinnedSeekPct = null) {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;
      video.style.position = 'fixed';
      video.style.left = '-9999px';
      video.style.width = '1px';
      video.style.height = '1px';
      document.body.appendChild(video);

      const cleanup = () => {
        video.removeAttribute('src');
        video.load();
        video.remove();
      };

      const timeout = setTimeout(() => {
        cleanup();
        resolve(null);
      }, 10000);

      // No video track (an audio file, N-05): there is no frame to draw.
      // The canvas used to be encoded anyway, and a blank canvas is a black
      // JPEG, cached and shown as the file's thumbnail (also in v0.9.2).
      const noVideo = () => {
        if (video.videoWidth > 0 && video.videoHeight > 0) return false;
        clearTimeout(timeout);
        const duration = isFinite(video.duration) ? video.duration : 0;
        cleanup();
        resolve({ dataUrl: null, duration, noVideo: true });
        return true;
      };

      video.addEventListener('loadedmetadata', () => {
        if (noVideo()) return;
        const seekTo = (typeof pinnedSeekPct === 'number' && isFinite(pinnedSeekPct))
          ? video.duration * pinnedSeekPct
          : Math.min(video.duration * 0.1, 5);
        video.currentTime = seekTo;
      }, { once: true });

      video.addEventListener('seeked', () => {
        if (noVideo()) return;
        clearTimeout(timeout);
        try {
          const canvas = document.createElement('canvas');
          canvas.width = 320;
          canvas.height = Math.round(320 * (video.videoHeight / video.videoWidth)) || 180;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const dataUrl = canvas.toDataURL('image/jpeg', 0.7);

          const duration = isFinite(video.duration) ? video.duration : 0;
          cleanup();
          resolve({ dataUrl, duration });
        } catch (e) {
          cleanup();
          resolve(null);
        }
      }, { once: true });

      video.addEventListener('error', () => {
        clearTimeout(timeout);
        cleanup();
        resolve(null);
      }, { once: true });

      video.src = pathToFileURL(videoPath);
    });
  }

  /**
   * Read `video.funscriptPath` with stale-path recovery.
   *
   * - If the stored path reads cleanly, returns its content.
   * - If it fails but the same basename exists next to `video.path`, the
   *   association in `library.associations` is updated to the new path
   *   and the recovered content is returned.
   * - If both reads fail, null is returned and the video is marked
   *   (`_markScriptMissing`, in memory, this session): its card says
   *   "Script not found" and the card reads do not retry, so the backend
   *   log is not spammed with ENOENTs on every render. Nothing stored is
   *   touched, ever (Dave, 2026-11-18, "Stop pruning").
   *
   * @returns {Promise<string|null>}
   */
  async _readFunscriptResilient(video, _again = false) {
    const original = video?.funscriptPath;
    if (!original) return null;
    if (video._stream) {
      try { return (await window.funsync.readFunscript(original)) || null; } catch { return null; }
    }
    try {
      const c = await window.funsync.readFunscript(original);
      if (c) {
        if (video._scriptMissing === original) this._clearScriptMissing(video);
        return c;
      }
    } catch { /* fall through */ }

    // Recovery: same basename in the video's directory.
    const basename = original.split(/[\\/]/).pop();
    const sep = video.path && video.path.includes('\\') ? '\\' : '/';
    const dirEnd = video.path
      ? Math.max(video.path.lastIndexOf('\\'), video.path.lastIndexOf('/'))
      : -1;
    if (dirEnd > 0 && basename) {
      const fallback = video.path.slice(0, dirEnd) + sep + basename;
      if (fallback !== original) {
        try {
          const c = await window.funsync.readFunscript(fallback);
          if (c) {
            if (video._manualAssociation && !video._multiAxis && !video._customRouting) {
              this._showUserSingle(video, fallback);
            } else {
              video.funscriptPath = fallback;
            }
            this._healAssociationFunscriptPath(video.path, fallback);
            console.log(`[Library] Recovered funscriptPath ${original} → ${fallback}`);
            return c;
          }
        } catch { /* both gone — fall through */ }
      }
    }

    // Both reads failed. A failed READ is not proof the script is gone: the
    // drive holding it may be unplugged, the file may be locked, the read may
    // have timed out — `read-funscript` returns null for every one of those.
    // This used to prune unconditionally, guarding only the VIDEO's path, so a
    // C: video paired with a script on an unplugged D: lost its association as
    // soon as its card scrolled into view: the 2026-08-11 shape, reopened one
    // call away from the validator that had been fixed for it.
    // Since 2026-11-18 nothing prunes at all (Dave, "Stop pruning"): the
    // video is marked below, so this session stops retrying.
    // The scan paired this script, so a miss is worth a warn even though
    // main.js logs a missing file at debug (V57): once per path per session
    // (FT-043).
    this._noteExpectedScriptMiss(original);
    // Something re-pointed the video while these reads were out: the scan's
    // validator fell back to the video's own script (R4-06), a heal, a new
    // association. This read says nothing about that path, so read it
    // instead. Clearing here wiped the validator's sidecar fallback, and
    // after a reload the video played with no script at all (R4-06 fix-up,
    // real-app verifier 2).
    if (!_again && video.funscriptPath && video.funscriptPath !== original) {
      return this._readFunscriptResilient(video, true);
    }
    // A script the user associated under another name, with the video's own
    // `<video>.funscript` there: play that one for now and keep the
    // association (R4-06).
    let unreadable = original;
    if (this._fallBackToOwnScript(video)) {
      unreadable = video.funscriptPath;
      try {
        const c = await window.funsync.readFunscript(video.funscriptPath);
        if (c) return c;
      } catch { /* its own script cannot be read either */ }
      this._noteExpectedScriptMiss(video.funscriptPath);
    }
    // Nothing stored changes, even when the script is provably gone (Dave,
    // 2026-11-18, "Stop pruning"; this pruned the single slot through
    // `_pruneStaleAssociation` when `_safeToPrune` approved). The video
    // stays paired on screen too: the card keeps its script badge, marked
    // "Script not found" ("Can't check the script right now" while the
    // location does not answer), it stays under Matched, the Script section
    // says the same, and this session does not read it again
    // (`_scriptMissingStatus`). It used to be dropped from the video for the
    // session, so the card said "no script" while the pairing was there.
    // Only what this read found unreadable is marked: not a path something
    // else put there meanwhile.
    if (video.funscriptPath === unreadable) {
      const gone = await this._safeToPrune(unreadable);
      if (video.funscriptPath === unreadable) this._markScriptMissing(video, unreadable, gone ? false : null);
    }
    return null;
  }

  /**
   * One `[Script] expected script not found: <path>` warn per path per
   * session (FT-043). For reads of a script the library PAIRED with a video
   * (an association or the scan's match), never for badge probes: main.js
   * logs every missing file at debug (V57) because it cannot tell the two
   * apart. Shared by the card's read (`_readFunscriptResilient`) and the
   * open's read (`resolvePlayData`), so whichever misses first says it once.
   *
   * `read-funscript` answers null for a file that is not there AND for one
   * it could not read (EPERM, a lock, a drive that did not answer), so the
   * path is asked first: only a file that is provably gone is "not found";
   * anything else is "could not be read" (C-09: an associated script behind
   * a deny ACL was logged "not found" right after main's
   * "read-funscript failed: EPERM"). Not awaited by the readers, so a slow
   * drive never holds up an open; the returned promise is for tests.
   */
  _noteExpectedScriptMiss(path) {
    if (!path) return undefined;
    const missed = (this._expectedScriptMisses ||= new Set());
    if (missed.has(path)) return undefined;
    missed.add(path);
    return this._pathStatus(path).then((status) => {
      if (status === false) console.warn('[Script] expected script not found:', path);
      else console.warn('[Script] expected script could not be read:', path);
    });
  }

  /** Update the funscriptPath on a single-axis association after recovery. */
  _healAssociationFunscriptPath(videoPath, newPath) {
    if (!videoPath || !newPath) return;
    const all = this._settings.get('library.associations') || {};
    if (!all[videoPath]) return;
    const entry = normalizeAssociation(all[videoPath]);
    // Only heal when the single slot is the one that was read. For multi /
    // custom active modes, app.js's _readScriptResilient handles in-place
    // path healing within those slots.
    if (entry.active !== 'single' || entry.single == null) return;
    all[videoPath] = buildAssociationEntry('single', newPath, entry.multi, entry.custom);
    this._settings.set('library.associations', all);
  }

  /**
   * One-shot background pass after scan: walk every entry in
   * `library.associations`, check if its funscriptPath actually exists,
   * and either heal it (file moved next to the video) or prune it (file
   * genuinely gone). Runs concurrently with a small worker pool so it
   * doesn't pile up IPC pressure on big libraries.
   *
   * Idempotent — already-clean entries skip out cheaply. Safe to call
   * after every scan; only does real work when something actually moved.
   */
  /**
   * Read the persistent speed-stats cache from settings and apply
   * cached values to the in-memory video list. Called right after
   * _applyManualAssociations during scan. Lets sort-by-speed work
   * instantly on subsequent app launches without recomputing.
   *
   * Cache is keyed by funscriptPath. The cached entry is invalidated
   * implicitly when the funscript file changes — we don't track mtime
   * because the per-card resilient reader recomputes on read failure
   * anyway, and stale-but-correct values are fine for sort ordering.
   */
  _hydrateSpeedStatsCache() {
    const cache = this._settings.get('library.speedStatsCache') || {};
    if (Object.keys(cache).length === 0) return;
    let hits = 0;
    for (const video of (this._videos || [])) {
      if (!video.funscriptPath) continue;
      const cached = cache[video.funscriptPath];
      // 0/0 is what the backend probe USED to store for a script it could
      // not read (a UTF-8 BOM, FT-044), so a cached 0/0 is "unknown", not
      // "speed 0". Left unset, the video registers without stats, the
      // backend probes it again and the poll below heals the cache. A script
      // that really has no movement just gets 0/0 again.
      if (cached && cached.avgSpeed === 0 && cached.maxSpeed === 0) continue;
      if (cached && cached.avgSpeed != null && cached.maxSpeed != null) {
        video.avgSpeed = cached.avgSpeed;
        video.maxSpeed = cached.maxSpeed;
        hits++;
      }
    }
    if (hits > 0) console.log(`[Library] Hydrated ${hits} speed-stats from cache`);
  }

  /**
   * Read persistent duration cache (keyed by video path) and apply to
   * `_videos` + the in-memory `_durationCache`. Counterpart to
   * `_hydrateSpeedStatsCache` — without this, Sort-by-Duration was a
   * no-op on fresh library loads because the scan doesn't ffprobe and
   * most cards haven't been scrolled past yet.
   */
  _hydrateDurationCache() {
    const cache = this._settings.get('library.durationCache') || {};
    if (Object.keys(cache).length === 0) return;
    let hits = 0;
    for (const video of (this._videos || [])) {
      const cached = cache[video.path];
      if (typeof cached === 'number' && cached > 0 && !video.duration) {
        video.duration = cached;
        this._durationCache.set(video.path, cached);
        hits++;
      }
    }
    if (hits > 0) console.log(`[Library] Hydrated ${hits} durations from cache`);
  }

  /**
   * Hydrate speed stats from the BACKEND's computed values, then
   * persist to the local settings cache.
   *
   * The backend's `_queue_speed_probes` worker (kicked off by
   * `_registerWithBackend` posting to `/api/media/register`) does the
   * actual parsing + computation. We just poll its output. This was
   * previously done in the renderer itself, which was the dominant
   * cost on big libraries (~30s for 962 videos at concurrency 3 over
   * IPC). Moving to the backend frees the renderer's main thread + IPC
   * pipeline; backend Python work happens off-process.
   *
   * Deferred until after the initial thumbnail overlay clears so the
   * polling doesn't compete with the still-running thumbnail / scan
   * pipeline. Polls every 2s for up to 90s, applying any newly-arrived
   * stats on each tick. Stops early when all pending videos have
   * stats.
   *
   * Re-renders visible cards once at end so badges/heatmaps populate.
   */
  async _precomputeSpeedStatsInBackground() {
    const cache = this._settings.get('library.speedStatsCache') || {};
    // A cached 0/0 (FT-044's old failure marker) is waited for too, even when
    // the video already has a speed: the card's own read can compute it
    // before this poll starts, and then the entry stayed 0/0 and the script
    // was read again on every launch (block C verifier 2).
    const zeroCached = (p) => cache[p] && cache[p].avgSpeed === 0 && cache[p].maxSpeed === 0;
    const pending = new Set(
      (this._videos || [])
        .filter(v => !v._stream && v.hasFunscript && v.funscriptPath
          && (v.avgSpeed == null || v.maxSpeed == null || zeroCached(v.funscriptPath)))
        .map(v => v.funscriptPath)
    );
    if (pending.size === 0) return;

    const videosByFsPath = new Map();
    for (const video of this._videos) {
      if (video.funscriptPath) videosByFsPath.set(video.funscriptPath, video);
    }

    let renderQueued = false;
    // Data arrived that the grid has not shown yet. Cleared only by a render
    // that actually ran, so one skipped for an open menu is retried on the
    // next poll even when that poll brings nothing new (V81 review).
    let renderOwed = false;
    const owed = { toDialog: false };
    const queueRender = () => {
      if (renderQueued) return;
      renderQueued = true;
      Promise.resolve().then(() => {
        renderQueued = false;
        if (this._scanning) return;
        // Don't rebuild the grid under an open menu or the video options
        // dialog — same reasoning as the duration poll below. Next poll
        // cycle (2s) will retry once the menu closes (`renderOwed`); the
        // dialog renders on its own close (`_pollRenderDecision`).
        const decision = this._pollRenderDecision(owed);
        if (decision === 'wait') return;
        renderOwed = false;
        if (decision === 'render') this._applyFilters();
      });
    };

    const POLL_INTERVAL_MS = 2000;
    const MAX_WAIT_MS = 90000;
    const startTime = performance.now();
    let cacheDirty = false;

    // Runs on after the last arrival while that render is still owed.
    while ((pending.size > 0 || renderOwed) && (performance.now() - startTime) < MAX_WAIT_MS) {
      // Pause polling while the user is actively scrolling — the
      // fetch + JSON parse on poll responses is small but adds up
      // over hundreds of entries, and any main-thread hitch during
      // a scroll is visible as jank. Just wait a tick and check again.
      if (this._scrolling) {
        await new Promise(r => setTimeout(r, 250));
        continue;
      }
      let stats = {};
      if (pending.size > 0) {
        try {
          stats = await window.funsync.getSpeedStats();
        } catch {
          // Backend unreachable — bail; lazy per-card load remains as fallback.
          break;
        }
      }
      let arrived = false;
      for (const [fsPath, value] of Object.entries(stats || {})) {
        if (!pending.has(fsPath)) continue;
        const video = videosByFsPath.get(fsPath);
        if (video) {
          video.avgSpeed = value.avgSpeed;
          video.maxSpeed = value.maxSpeed;
        }
        cache[fsPath] = { avgSpeed: value.avgSpeed, maxSpeed: value.maxSpeed };
        pending.delete(fsPath);
        cacheDirty = true;
        arrived = true;
      }
      // Only a poll that brought something, or one whose render is still
      // owed, re-renders. Keyed on `cacheDirty`, which stays true, every 2 s
      // poll after the first arrival rebuilt the grid for the rest of the
      // 90 s (V81).
      if (arrived) {
        renderOwed = true;
        owed.toDialog = false; // newer than any render the dialog's close ran
      }
      if (renderOwed) {
        queueRender();
        await Promise.resolve();   // let it run, so `renderOwed` says whether it did
      }
      if (pending.size === 0 && !renderOwed) break;
      await new Promise(r => setTimeout(r, POLL_INTERVAL_MS));
    }

    if (cacheDirty) {
      this._settings.set('library.speedStatsCache', cache);
    }
    if (pending.size > 0) {
      console.log(`[Library] ${pending.size} videos still without speed stats after ${MAX_WAIT_MS}ms — lazy load will catch up`);
    }
  }

  /**
   * Poll the backend's `/api/media/durations` endpoint to hydrate
   * missing `video.duration` fields. Mirror of `_precomputeSpeedStatsInBackground`.
   *
   * Why this exists: the scan doesn't capture duration (ffprobe-per-file
   * would blow scan time on big libraries), thumbnail capture only
   * populates it for cards that get scrolled past AND whose thumbnail
   * isn't cache-hit, and without it Sort-by-Duration was broken.
   * Backend already probes durations on register; this just surfaces
   * the results to the desktop.
   *
   * Polls every 2s for up to 90s, re-renders on progress, persists to
   * `library.durationCache` for next launch.
   */
  async _precomputeDurationsInBackground() {
    const pending = new Set(
      (this._videos || [])
        .filter(v => v.path && !v._stream && (!v.duration || v.duration <= 0))
        .map(v => v.path)
    );
    if (pending.size === 0) return;

    const cache = this._settings.get('library.durationCache') || {};
    const videosByPath = new Map();
    for (const video of this._videos) {
      if (video.path) videosByPath.set(video.path, video);
    }

    let renderQueued = false;
    // Arrived but not rendered yet (see the speed poll).
    let renderOwed = false;
    const owed = { toDialog: false };
    const queueRender = () => {
      if (renderQueued) return;
      renderQueued = true;
      Promise.resolve().then(() => {
        renderQueued = false;
        if (this._scanning) return;
        // Don't rebuild the grid while the user has an open menu or the
        // video options dialog — `_renderGrid` does `grid.innerHTML = ''`
        // which destroys the menu mid-interaction, and the ⋮ the dialog
        // returns to. The next poll iteration (2s later) will call
        // queueRender again (`renderOwed`); by then the menu is usually
        // closed. The dialog renders on its own close.
        const decision = this._pollRenderDecision(owed);
        if (decision === 'wait') return;
        renderOwed = false;
        if (decision === 'render') this._applyFilters();
      });
    };

    const POLL_INTERVAL_MS = 2000;
    const MAX_WAIT_MS = 90000;
    const startTime = performance.now();
    let cacheDirty = false;

    while ((pending.size > 0 || renderOwed) && (performance.now() - startTime) < MAX_WAIT_MS) {
      if (this._scrolling) {
        await new Promise(r => setTimeout(r, 250));
        continue;
      }
      let durations = {};
      if (pending.size > 0) {
        try {
          durations = await window.funsync.getDurations();
        } catch {
          break;
        }
      }
      let arrived = false;
      for (const [videoPath, dur] of Object.entries(durations || {})) {
        if (!pending.has(videoPath)) continue;
        const video = videosByPath.get(videoPath);
        if (video && typeof dur === 'number' && dur > 0) {
          video.duration = dur;
          this._durationCache.set(videoPath, dur);
        }
        cache[videoPath] = dur;
        pending.delete(videoPath);
        cacheDirty = true;
        arrived = true;
      }
      // Only a poll that brought something, or whose render is still owed,
      // re-renders (see the speed poll).
      if (arrived) {
        renderOwed = true;
        owed.toDialog = false;
      }
      if (renderOwed) {
        queueRender();
        await Promise.resolve();
      }
      if (pending.size === 0 && !renderOwed) break;
      await new Promise(r => setTimeout(r, POLL_INTERVAL_MS));
    }

    if (cacheDirty) {
      this._settings.set('library.durationCache', cache);
    }
    if (pending.size > 0) {
      console.log(`[Library] ${pending.size} videos still without duration after ${MAX_WAIT_MS}ms — thumbnail capture will catch up`);
    }
  }

  /**
   * Is this path on a library source that's currently unavailable
   * (e.g. external drive disconnected)? Used to gate prune logic so
   * we don't wipe associations just because the drive is offline.
   * On reconnect the files come back, so the associations should too.
   */
  /**
   * True only when the scan can PROVE this path's file is gone: it sits under
   * a source root that was walked successfully this pass, and it was not in
   * the results. Everything else — source removed, never configured, scan
   * failed, drive offline — is absence without evidence and must not be
   * treated as deletion. See the 325 + 104 association losses in
   * `Library & Data Model.md`.
   */
  _isProvablyGone(absPath) {
    if (!absPath) return false;
    const roots = this._scannedSourceRoots;
    if (!roots || roots.length === 0) return false;
    if (this._isUnderUnavailableSource(absPath)) return false;
    const normalized = canonicalPath(absPath);
    for (const root of roots) {
      const rootNorm = canonicalPath(root);
      if (rootNorm && normalized.startsWith(rootNorm + '/')) return true;
    }
    return false;
  }

  _isUnderUnavailableSource(absPath) {
    if (!absPath) return false;
    // Union of three signals: the periodic reachability probe, sources that
    // actually failed to scan this pass, and subfolders the scan could not
    // open. The second is the stronger evidence and was previously ignored
    // entirely; the third is what the second became for a source with one
    // unreadable folder once the scan stopped failing the whole source (V04).
    const roots = [];
    if (this._unavailablePaths?.size) roots.push(...this._unavailablePaths);
    if (this._failedScanPaths?.size) roots.push(...this._failedScanPaths);
    if (this._skippedScanPaths?.size) roots.push(...this._skippedScanPaths);
    if (roots.length === 0) return false;
    const normalized = canonicalPath(absPath);
    for (const srcPath of roots) {
      const srcNorm = canonicalPath(srcPath);
      if (srcNorm && (normalized === srcNorm || normalized.startsWith(srcNorm + '/'))) return true;
    }
    return false;
  }

  /**
   * Is `scriptPath` PROVABLY gone? Since 2026-11-18 (Dave, "Stop pruning")
   * nothing prunes an association: this only picks the words ("Script not
   * found" vs "Can't check the script right now") for a pairing whose script
   * is missing, and still gates the manual-variant prunes (here and app.js
   * `_pruneStaleManualVariant`). Before, it was the last line of defence
   * before destroying a stored association.
   *
   * A single `fileExists` miss is NOT sufficient evidence that a user's
   * association is stale. The file can be missing because it was deleted, or
   * because its whole location is unreachable — and only the first justifies
   * touching the user's data.
   *
   * So before pruning we ask whether the script's PARENT DIRECTORY answers.
   * A missing file inside a directory that exists is a genuinely dead path.
   * A missing file inside a directory that itself cannot be read is a
   * disconnected drive, and we keep the association untouched.
   *
   * The FILE itself must also be explicitly absent. Callers arrive here after
   * a failed READ as often as after a failed existence check, and a read fails
   * for reasons that are not absence: the file is locked (EBUSY), permissions
   * (EACCES), or the check ran out of time. Only a definite `false` counts.
   *
   * Deliberately fails CLOSED: any error, and we refuse to prune. The cost of
   * keeping a stale pointer is a single unmatched video. The cost of a wrong
   * prune is hours of manual work, as 2026-08-11 demonstrated.
   *
   * @param {string} scriptPath
   * @returns {Promise<boolean>} true only when it is safe to prune
   */
  async _safeToPrune(scriptPath) {
    if (!scriptPath) return false;
    if (this._isUnderUnavailableSource(scriptPath)) return false;
    const dirEnd = Math.max(scriptPath.lastIndexOf('\\'), scriptPath.lastIndexOf('/'));
    if (dirEnd <= 0) return false;
    const dir = scriptPath.slice(0, dirEnd);
    if ((await this._pathStatus(scriptPath)) !== false) return false;
    return (await this._pathStatus(dir)) === true;
  }

  /**
   * Does this path exist? TRI-STATE: `true` present, `false` definitely
   * absent (ENOENT / ENOTDIR), `null` unknown (timed out, permission denied,
   * any other error: electron/path-status.js, FT-002).
   *
   * Prune decisions must not use the singular `fileExists` IPC on its own: it
   * collapses unknown to `false` (main.js `file-exists`), so on a NAS share
   * or a spun-down disk "no answer within the budget" read as "deleted", and
   * so does a file in a folder whose listing is denied. The batch
   * `filesExist` keeps the third state, so ask that, one path at a time.
   * Anything that throws is unknown, never absent.
   *
   * @param {string} p
   * @returns {Promise<boolean|null>}
   */
  async _pathStatus(p) {
    if (!p) return null;
    try {
      const api = window.funsync;
      if (typeof api?.filesExist === 'function') {
        const r = await api.filesExist([p]);
        const v = Array.isArray(r) ? r[0] : undefined;
        return v === true || v === false ? v : null;
      }
      // Older bridge (and test fakes) with only the singular form.
      return !!(await api.fileExists(p));
    } catch {
      return null;
    }
  }

  async _validateAssociationsInBackground() {
    const all = this._settings.get('library.associations') || {};
    const entries = Object.entries(all).filter(([p]) => !isStreamPath(p));
    if (entries.length === 0) return;

    let healed = 0;
    // Counted and logged so a near-miss is visible rather than silent.
    let skippedUnreachable = 0;
    // Pairings whose script is provably gone: kept all the same (Dave,
    // 2026-11-18, "Stop pruning"); counted for the log.
    let keptMissing = 0;
    // Single associations over a video's own sidecar whose file is missing:
    // kept, and how many videos fell back to their sidecar for now (R4-06).
    let keptOverOwn = 0;
    let fellBack = 0;
    const CONCURRENCY = 8;

    // Try to recover a missing script by looking for the same basename in
    // the video's directory. Returns the recovered path or null.
    const tryRecoverPath = async (videoPath, scriptPath) => {
      const basename = scriptPath.split(/[\\/]/).pop();
      const sep = videoPath.includes('\\') ? '\\' : '/';
      const dirEnd = Math.max(videoPath.lastIndexOf('\\'), videoPath.lastIndexOf('/'));
      if (dirEnd <= 0 || !basename) return null;
      const fallback = videoPath.slice(0, dirEnd) + sep + basename;
      if (fallback === scriptPath) return null;
      let exists = false;
      try { exists = !!(await window.funsync.fileExists(fallback)); } catch {}
      return exists ? fallback : null;
    };

    // A multi-axis or custom main that is the script the video plays now:
    // "Script not found" on its card (or "Can't check…"), nothing written.
    const markIfPlaying = async (videoPath, active, scriptPath) => {
      const video = this._videosByPath?.get?.(videoPath);
      if (!video || canonicalPath(video.funscriptPath) !== canonicalPath(scriptPath)) return;
      if (normalizeAssociation(all[videoPath]).active !== active) return;
      this._markScriptMissing(video, scriptPath, (await this._safeToPrune(scriptPath)) ? false : null);
    };

    const validate = async ([videoPath, rawAssoc]) => {
      // Skip entries on currently-unavailable sources (e.g. external
      // drive disconnected). Without this, every funscript on the
      // offline drive returns "doesn't exist" → we'd prune all the
      // user's manual associations as stale, then they'd be gone when
      // the drive came back. On reconnect the files exist again, so
      // the association should still point at them.
      if (this._isUnderUnavailableSource(videoPath)) return;

      // Normalize so we can walk slots uniformly. If the stored entry was
      // legacy-shape we mutate in place on `all` below.
      const entry = normalizeAssociation(rawAssoc);
      let entryChanged = false;
      const wasNew = rawAssoc && typeof rawAssoc === 'object' && 'active' in rawAssoc;
      if (!wasNew) {
        all[videoPath] = entry;
        entryChanged = true;
      }

      // --- single slot ---
      // Tri-state (`_pathStatus`): a check that timed out or errored is
      // UNKNOWN and leaves the entry alone. The singular fileExists folded a
      // timeout into "missing", which on a slow share made a present script
      // look deleted to everything below.
      if (entry.single) {
        const status = await this._pathStatus(entry.single);
        if (status === null) {
          skippedUnreachable++;
        } else if (!status) {
          const recovered = await tryRecoverPath(videoPath, entry.single);
          const video = this._videosByPath?.get?.(videoPath);
          const playsSingle = entry.active === 'single' && video?._manualAssociation
            && canonicalPath(video.funscriptPath) === canonicalPath(entry.single);
          if (recovered) {
            if (playsSingle) this._showUserSingle(video, recovered);
            entry.single = recovered;
            entryChanged = true;
            healed++;
          } else if (this._keepsOwnOverride(videoPath, entry.single)) {
            // Chosen over the video's own sidecar: kept, and the video plays
            // its sidecar until the file is back (R4-06). Never pruned.
            if (playsSingle && this._fallBackToOwnScript(video)) fellBack++;
            keptOverOwn++;
          } else {
            // KEPT, even when the script is provably gone (Dave, 2026-11-18:
            // "Stop pruning"). A pairing goes only when you unpair or remove
            // it; until then the card and the dialog say "Script not found"
            // ("Can't check the script right now" while its location does not
            // answer: a video on C: can hold a script on an unplugged D:, the
            // 2026-08-11 shape). This dropped the single slot when
            // `_safeToPrune` approved; that check now only picks the words.
            const gone = await this._safeToPrune(entry.single);
            if (gone) keptMissing++;
            else skippedUnreachable++;
            if (playsSingle) this._markScriptMissing(video, entry.single, gone ? false : null);
          }
        }
      }

      // --- multi slot main (axes intentionally left alone — user rebuilds
      // via modal if a companion script goes missing) ---
      if (entry.multi?.main) {
        // Unknown (null) is not missing: no heal on a timeout either.
        if ((await this._pathStatus(entry.multi.main)) === false) {
          const recovered = await tryRecoverPath(videoPath, entry.multi.main);
          if (recovered) {
            entry.multi.main = recovered;
            entryChanged = true;
            healed++;
          } else {
            // No prune of multi (never was); the card says so when it plays.
            await markIfPlaying(videoPath, 'multi', entry.multi.main);
          }
        }
      }

      // --- custom slot main route ---
      if (entry.custom?.routes) {
        const main = entry.custom.routes.find(r => r.role === 'main');
        if (main?.scriptPath) {
          if ((await this._pathStatus(main.scriptPath)) === false) {
            const recovered = await tryRecoverPath(videoPath, main.scriptPath);
            if (recovered) {
              main.scriptPath = recovered;
              entryChanged = true;
              healed++;
            } else {
              // No prune of custom (never was); the card says so when it plays.
              await markIfPlaying(videoPath, 'custom', main.scriptPath);
            }
          }
        }
      }

      if (entryChanged) {
        // Rebuild mirror fields to keep downgrade-safety in sync with the
        // healed slot data. Never changes the active pointer: nothing here
        // removes a slot (Dave, 2026-11-18, "Stop pruning").
        all[videoPath] = buildAssociationEntry(entry.active, entry.single, entry.multi, entry.custom);
      }
    };

    // Worker-pool style: chunk entries and await each batch.
    for (let i = 0; i < entries.length; i += CONCURRENCY) {
      await Promise.all(entries.slice(i, i + CONCURRENCY).map(validate));
    }

    if (skippedUnreachable > 0) {
      console.warn(
        `[Library] Association validation: LEFT ${skippedUnreachable} association(s) untouched ` +
        'because their script location was unreachable or did not answer in time. ' +
        'Nothing was pruned for those.'
      );
    }
    if (keptOverOwn > 0) {
      console.warn(
        `[Library] Association validation: KEPT ${keptOverOwn} association(s) whose script is missing `
        + `over the video's own script; ${fellBack} video(s) play their own script until it is back.`
      );
      // The phone and VR read `funscriptPath` from the registry.
      if (fellBack > 0) this._registerWithBackend();
    }
    if (keptMissing > 0) {
      // No toast: nothing was removed. The cards and the Script section say
      // "Script not found" (it was a toast "N association(s) cleared …
      // Re-associate via the kebab menu", English only, until 2026-11-18).
      console.warn(
        `[Library] Association validation: KEPT ${keptMissing} association(s) whose script file is gone; `
        + 'a pairing is removed only by Unpair / Remove (absence is never destructive).'
      );
    }
    if (healed > 0) {
      this._settings.set('library.associations', all);
      console.log(`[Library] Association validation: healed ${healed}.`);
    }
  }

  /**
   * Sibling pass for `library.manualVariants` — same heal-or-prune
   * logic as associations, but variants are stored as
   * { videoPath: [{ label, path, name }, ...] } so we walk the inner
   * arrays. Variants that recover get their path rewritten in place.
   * Variants whose file is gone get dropped from the array.
   */
  async _validateManualVariantsInBackground() {
    const all = this._settings.get('library.manualVariants') || {};
    const videoPaths = Object.keys(all).filter((p) => !isStreamPath(p));
    if (videoPaths.length === 0) return;

    let healed = 0;
    let pruned = 0;
    // Variations whose script is provably gone: kept (Dave, 2026-11-18,
    // "Yes, stop those too"); counted for the log.
    let keptMissing = 0;
    const CONCURRENCY = 8;

    const validateEntry = async (videoPath, variant) => {
      // Present OR unknown (timed out / errored) → untouched. Only a definite
      // "absent" goes on to heal-or-prune. See `_pathStatus`.
      if ((await this._pathStatus(variant.path)) !== false) return { keep: true, changed: false };

      const basename = variant.path.split(/[\\/]/).pop();
      const sep = videoPath.includes('\\') ? '\\' : '/';
      const dirEnd = Math.max(videoPath.lastIndexOf('\\'), videoPath.lastIndexOf('/'));
      if (dirEnd > 0 && basename) {
        const fallback = videoPath.slice(0, dirEnd) + sep + basename;
        if (fallback !== variant.path) {
          let ok = false;
          try { ok = !!(await window.funsync.fileExists(fallback)); } catch {}
          if (ok) {
            variant.path = fallback;
            return { keep: true, changed: true };
          }
        }
      }
      // KEPT, even when provably gone (Dave, 2026-11-18: "Yes, stop those
      // too", the rule the pairings got first). The Script section's
      // Variations list says "Script not found" (with Locate) and does not
      // offer it as Play first; only you remove it. This dropped the entry
      // when `_safeToPrune` approved; now that check only counts it.
      if (await this._safeToPrune(variant.path)) keptMissing++;
      return { keep: true, changed: false };
    };

    // Flatten into one task list so the worker pool covers everything.
    // Skip videos on currently-unavailable sources — same offline-drive
    // protection as the association validator. Without this, every
    // variant on a disconnected drive gets pruned.
    const tasks = [];
    for (const videoPath of videoPaths) {
      if (this._isUnderUnavailableSource(videoPath)) continue;
      for (const variant of all[videoPath] || []) {
        tasks.push({ videoPath, variant });
      }
    }

    // Track which entries to remove per video so we can splice cleanly
    // after the awaits resolve (mutating arrays mid-iteration is messy).
    const toRemove = new Map();  // videoPath → Set<variantRef>

    for (let i = 0; i < tasks.length; i += CONCURRENCY) {
      const batch = tasks.slice(i, i + CONCURRENCY);
      const results = await Promise.all(batch.map(t => validateEntry(t.videoPath, t.variant)));
      for (let j = 0; j < batch.length; j++) {
        const res = results[j];
        const { videoPath, variant } = batch[j];
        if (res.changed) healed += res.keep ? 1 : 0;
        if (!res.keep) {
          pruned++;
          if (!toRemove.has(videoPath)) toRemove.set(videoPath, new Set());
          toRemove.get(videoPath).add(variant);
        }
      }
    }

    if (toRemove.size > 0) {
      for (const [videoPath, refs] of toRemove) {
        const list = (all[videoPath] || []).filter(v => !refs.has(v));
        if (list.length === 0) delete all[videoPath];
        else all[videoPath] = list;
      }
    }

    if (keptMissing > 0) {
      console.warn(`[Library] Variant validation: KEPT ${keptMissing} variation(s) whose script file is gone (removed only by you).`);
    }
    if (healed > 0 || pruned > 0) {
      this._settings.set('library.manualVariants', all);
      console.log(`[Library] Variant validation: healed ${healed}, pruned ${pruned}.`);
    }
  }

  /**
   * A pairing whose script cannot be found stays a pairing everywhere (Dave,
   * 2026-11-18, "Stop pruning"): nothing stored changes, `hasFunscript` and
   * `funscriptPath` stay, so the video stays under Matched; its card badge
   * says "Script not found" ("Can't check the script right now" when the
   * location does not answer), as the dialog's Script section does. In
   * memory, for the path that plays now: a scan, another pairing, or a read
   * that works ends it. Replaces `_pruneStaleAssociation`, which dropped the
   * single slot when `_safeToPrune` approved.
   * @returns {'missing'|'unknown'|null}
   */
  _scriptMissingStatus(video) {
    if (!video?._scriptMissing || video._scriptMissing !== video.funscriptPath) return null;
    return video._scriptMissingStatus === false ? 'missing' : 'unknown';
  }

  /** Mark `scriptPath` (what `video` plays) as not found: `status` false = provably gone. */
  _markScriptMissing(video, scriptPath, status) {
    if (!video || !scriptPath) return;
    video._scriptMissing = scriptPath;
    video._scriptMissingStatus = status === false ? false : null;
    this._paintScriptBadge(video);
  }

  _clearScriptMissing(video) {
    if (!video?._scriptMissing) return;
    video._scriptMissing = null;
    video._scriptMissingStatus = undefined;
    this._paintScriptBadge(video);
  }

  /** The script badge of `video`'s card on screen (found by path), as it stands now. */
  _paintScriptBadge(video, cardEl = null) {
    const card = (cardEl?.isConnected ? cardEl : null) || this._cardForPath(video?.path);
    const badge = card?.querySelector('.library__funscript-badge, .library__funscript-badge--inline');
    if (badge) this._decorateScriptBadge(badge, video);
  }

  /** Title, icon and the --missing class of a script badge for `video`. */
  _decorateScriptBadge(badge, video) {
    const status = this._scriptMissingStatus(video);
    const fsManual = video._manualAssociation && !video._autoAssigned;
    badge.classList.toggle('library__funscript-badge--missing', !!status);
    badge.title = status
      ? t(`videoOptions.script.status.${status}`)
      : (fsManual ? t('library.funscriptManual') : t('library.funscriptAuto'));
    badge.replaceChildren(icon(status ? FileX : FileCheck, { width: 14, height: 14, 'stroke-width': 2.5 }));
    // The red badge opens the video options at the Script section, on its
    // Locate control (Claude's call, design "Locate a missing script"),
    // instead of the card's play; a file dialog never opens from a card
    // click. In select mode (or with Shift) the click stays the card's.
    badge.style.cursor = status ? 'pointer' : '';
    if (status && !badge.dataset.voLocate) {
      badge.dataset.voLocate = '1';
      badge.addEventListener('click', (e) => {
        const v = this.getVideoByPath(video.path) || video;
        if (this._selectMode || e.shiftKey || !this._scriptMissingStatus(v)) return;
        e.stopPropagation();
        e.preventDefault();
        this._openVideoOptions(v, { section: 'script', focusKey: 'script:locate' });
      });
    }
  }

  /** Is the opt-in per-card heatmap strip enabled? Default OFF. */
  _showCardHeatmap() {
    return this._settings.get('library.showCardHeatmap') === true;
  }

  /**
   * Build the card's heatmap row.
   *
   * The script shown is `video.funscriptPath`, which the association pass
   * has already resolved to the single-axis script, the multi-axis MAIN, or
   * the custom-routing main route — so a full multi/custom setup charts its
   * main axis rather than an arbitrary companion.
   *
   * A video with no matched script gets muted "unavailable" text instead of
   * a blank gap, so the row reads as "nothing to show here" rather than as
   * a heatmap that failed to draw.
   */
  _createCardHeatmap(video) {
    const strip = document.createElement('div');
    strip.className = 'library__card-heatmap';
    if (video.hasFunscript && video.funscriptPath) {
      const canvas = document.createElement('canvas');
      canvas.className = 'library__card-heatmap-canvas';
      strip.appendChild(canvas);
      // Bins may already be cached from a previous render or the list view;
      // otherwise _loadSpeedStatsForVideo fills them in when the card comes
      // into view (same lazy, scroll-aware path the speed badge uses).
      // Queued, so every strip of a render is drawn with one layout (V81).
      if (video._heatmapBins) queueRenderBins(canvas, video._heatmapBins);
    } else {
      strip.classList.add('library__card-heatmap--unavailable');
      strip.textContent = t('library.heatmapUnavailable');
    }
    return strip;
  }

  async _loadSpeedStatsForVideo(video, cardEl) {
    if (!video.hasFunscript || !video.funscriptPath) return;
    // Already read this session for this very script: paint what that read
    // left on the video (speed badge, heatmap bins, embedded-axes badge)
    // instead of reading and parsing the file again. It used to read again
    // for every visible card on every render, so every sort re-read the
    // visible scripts off the drive (V81). Painted, not skipped, because a
    // card built while that read was still in flight has none of it yet.
    // A new scan makes new video objects, and a new association a new path:
    // both read.
    if (video._statsReadFor === video.funscriptPath) {
      if (cardEl) this._paintCachedSpeedStats(video, cardEl);
      return;
    }
    // Its script was not found this session (`_markScriptMissing`): the
    // badge says so; no read again on every render.
    if (video._scriptMissing && video._scriptMissing === video.funscriptPath) return;
    try {
      const content = await this._readFunscriptResilient(video);
      if (!content) return;
      const parsed = JSON.parse(content);

      // Rides along on this parse — see _noteEmbeddedAxes. Runs BEFORE the
      // action-count gate below: a combined script whose main `actions`
      // array is short (or absent) still has axes worth badging.
      this._noteEmbeddedAxes(video, parsed, cardEl);

      const actions = parsed?.actions;
      if (actions && actions.length >= 2) {
        const stats = computeSpeedStats(actions);
        video.avgSpeed = stats.avgSpeed;
        video.maxSpeed = stats.maxSpeed;
        if (!video._heatmapBins || video._statsReadFor !== video.funscriptPath) {
          video._heatmapBins = computeBins(actions);
        }
        video._statsReadFor = video.funscriptPath;
        if (cardEl) {
          const target = cardEl.querySelector('.library__card-info')
            || cardEl.querySelector('.library__list-badges');
          if (target) this._addSpeedBadge(target, stats);
          // List view's row strip and the grid card's opt-in strip both
          // draw from the same freshly-computed bins. Queued: reads that
          // land in the same frame draw with one layout (V81).
          const heatmap = cardEl.querySelector('.library__list-heatmap')
            || cardEl.querySelector('.library__card-heatmap-canvas');
          if (heatmap && video._heatmapBins) queueRenderBins(heatmap, video._heatmapBins);
        }
      }
    } catch { /* ignore */ }
  }

  /** This script changed on disk: the next card that shows it reads it again. */
  _forgetScriptRead(scriptPath) {
    if (!scriptPath) return;
    const key = canonicalPath(scriptPath).toLowerCase();
    for (const video of this._videos || []) {
      if (video._statsReadFor && canonicalPath(video._statsReadFor).toLowerCase() === key) {
        video._statsReadFor = null;
      }
    }
  }

  /** What `_loadSpeedStatsForVideo` adds to a card, from the values on the video. Idempotent. */
  _paintCachedSpeedStats(video, cardEl) {
    const info = cardEl.querySelector('.library__card-info');
    const target = info || cardEl.querySelector('.library__list-badges');
    if (target) {
      this._addSpeedBadge(target, { avgSpeed: video.avgSpeed, maxSpeed: video.maxSpeed });
      this._addPlaybackModeBadge(target, video, { inline: !info });
    }
    const heatmap = cardEl.querySelector('.library__list-heatmap')
      || cardEl.querySelector('.library__card-heatmap-canvas');
    if (heatmap && video._heatmapBins) queueRenderBins(heatmap, video._heatmapBins);
  }

  /**
   * Add a speed gauge icon to a container element (info bar or thumbnail).
   * Color based on max speed using the OFS heatmap scale (max 400 units/s).
   */
  _addSpeedBadge(containerEl, stats) {
    if (!containerEl || containerEl.querySelector('.library__speed-badge')) return;
    if (!stats.maxSpeed) return;

    let colorClass;
    if (stats.avgSpeed >= 450) colorClass = 'library__speed-badge--insane';
    else if (stats.avgSpeed >= 350) colorClass = 'library__speed-badge--extreme';
    else if (stats.avgSpeed >= 250) colorClass = 'library__speed-badge--fast';
    else if (stats.avgSpeed >= 150) colorClass = 'library__speed-badge--medium';
    else colorClass = 'library__speed-badge--slow';

    const badge = document.createElement('span');
    badge.className = `library__speed-badge ${colorClass}`;
    badge.title = t('library.speedBadgeTitle', { avg: stats.avgSpeed, max: stats.maxSpeed });
    badge.appendChild(icon(Gauge, { width: 12, height: 12, 'stroke-width': 2.5 }));
    containerEl.appendChild(badge);
  }

  _addDurationBadge(thumbnailEl, durationSec) {
    if (!thumbnailEl || thumbnailEl.querySelector('.library__duration-badge')) return;
    if (!durationSec || durationSec <= 0) return;

    const badge = document.createElement('span');
    badge.className = 'library__duration-badge';
    badge.textContent = this._formatDuration(durationSec);
    thumbnailEl.appendChild(badge);
  }

  _countMultiAxisScripts(multi) {
    if (!multi || typeof multi !== 'object') return 0;
    let n = multi.main ? 1 : 0;
    const axes = multi.axes;
    if (axes && typeof axes === 'object') {
      for (const v of Object.values(axes)) if (v) n++;
    }
    return n;
  }

  /**
   * Record embedded multi-axis suffixes found in an already-parsed
   * funscript, and light the multi badge up on the card.
   *
   * Combined scripts (HereSphere `additional_axes`, OFS `raw`, funscript
   * 2.0 `channels`, the Iwara `axes` array, inline TCode) carry
   * pitch/roll/twist INSIDE the main file. `detectCompanionFiles` sees
   * exactly one script on disk, so the card looked single-axis and
   * there was no way to tell a combined script from a plain one without
   * playing it.
   *
   * Community report 2026-08-29 (EroScripts #309393): "I have a few
   * multiaxis scripts but I don't see them" — every one was a combined
   * file. The badge previously only ever came from `_getEmbeddedAxes`,
   * whose cache filled at PLAY time, which is precisely the moment the
   * badge is no longer useful.
   *
   * Detection piggybacks on the speed-stats read: the file is already in
   * memory and already parsed, so it costs no extra I/O and runs only
   * for cards the user has actually scrolled to. Only the SUFFIXES are
   * kept — holding every axis's action array for a whole library would
   * be a lot of memory for a tooltip. The full arrays are re-read on
   * demand by `detectEmbeddedAxesForPath` when the user extracts.
   */
  _noteEmbeddedAxes(video, parsed, cardEl) {
    // An explicit multi-axis or custom-routing config already owns the
    // badge slot; don't spend the extraction on it.
    if (video._multiAxis) return;
    if (Array.isArray(video._customRouting) && video._customRouting.length > 0) return;

    let suffixes;
    try {
      suffixes = [...extractEmbeddedAxes(parsed).keys()];
    } catch { return; }

    video._embeddedAxes = suffixes.length > 0 ? { suffixes } : null;
    if (!cardEl || suffixes.length === 0) return;

    // Same two targets `_loadSpeedStatsForVideo` uses for the speed
    // badge: the grid card's info bar, or the list row's badge strip.
    const info = cardEl.querySelector('.library__card-info');
    const target = info || cardEl.querySelector('.library__list-badges');
    if (target) this._addPlaybackModeBadge(target, video, { inline: !info });
  }

  _addPlaybackModeBadge(containerEl, video, opts = {}) {
    if (!containerEl) return;
    // Idempotent: the badge is added once at card build and again when
    // the deferred funscript read discovers embedded axes.
    if (containerEl.querySelector(
      '.library__multi-badge, .library__multi-badge--inline, .library__custom-badge, .library__custom-badge--inline'
    )) return;
    const inline = !!opts.inline;
    if (video._multiAxis) {
      const count = this._countMultiAxisScripts(video._multiAxis);
      const badge = document.createElement('span');
      badge.className = inline ? 'library__multi-badge--inline' : 'library__multi-badge';
      badge.title = count > 0 ? t('library.multiAxisCount', { count }) : t('library.multiAxis');
      badge.appendChild(icon(Layers2, { width: 14, height: 14, 'stroke-width': 2.5 }));
      containerEl.appendChild(badge);
    } else if (Array.isArray(video._customRouting) && video._customRouting.length > 0) {
      const n = video._customRouting.length;
      const badge = document.createElement('span');
      badge.className = inline ? 'library__custom-badge--inline' : 'library__custom-badge';
      badge.title = t('library.customRoutingTitle', { count: n });
      badge.appendChild(icon(Cable, { width: 14, height: 14, 'stroke-width': 2.5 }));
      containerEl.appendChild(badge);
    } else {
      // Embedded multi-axis fallback. Combined funscripts (HereSphere
      // `additional_axes`, OFS-extended `raw`, funscript 2.0 `channels`,
      // sibling-key, inline TCode) carry pitch/roll/twist inside the main
      // file, so no companion files exist to count. Two sources, in
      // order: `video._embeddedAxes`, filled by `_noteEmbeddedAxes` off
      // the deferred per-card funscript read (so the badge shows without
      // ever playing the video); and the app's play-time cache, which
      // also covers videos loaded from outside the library grid.
      const embedded = video._embeddedAxes
        || this._getEmbeddedAxes?.(video.funscriptPath);
      if (embedded && embedded.suffixes && embedded.suffixes.length > 0) {
        const n = embedded.suffixes.length;
        const badge = document.createElement('span');
        badge.className = inline ? 'library__multi-badge--inline' : 'library__multi-badge';
        badge.title = t('library.multiAxisEmbedded', {
          count: n, axes: embedded.suffixes.join(', '),
        });
        badge.appendChild(icon(Layers2, { width: 14, height: 14, 'stroke-width': 2.5 }));
        containerEl.appendChild(badge);
      }
    }
  }

  /**
   * Get or create the bottom-left flex container that holds funscript +
   * subtitle badges on a card thumbnail. Used by the initial render and
   * by the dynamic add code paths (manual associate / change). The
   * container layouts the badges with `gap` so the layout stays correct
   * regardless of which subset of badges is present — replaces the
   * prior hardcoded `left: 6px` / `left: 26px` offset hack.
   */
  _getOrCreateBadgesContainer(thumbnailEl) {
    let container = thumbnailEl.querySelector('.library__card-badges');
    if (!container) {
      container = document.createElement('div');
      container.className = 'library__card-badges';
      thumbnailEl.appendChild(container);
    }
    return container;
  }

  _formatDuration(sec) {
    const totalSec = Math.floor(sec);
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    const s = totalSec % 60;
    if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    return `${m}:${String(s).padStart(2, '0')}`;
  }

  // --- Hover Video Preview ---

  _ensurePreviewVideo() {
    if (this._previewVideo) return;

    // Singleton — reuse for all hovers (avoids Electron memory leak #18277)
    const video = document.createElement('video');
    video.muted = true;
    video.playsInline = true;
    video.preload = 'auto';
    video.style.cssText = 'position:fixed;left:-9999px;width:1px;height:1px;';
    document.body.appendChild(video);

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 180;

    this._previewVideo = video;
    this._previewCanvas = canvas;
    this._previewCtx = canvas.getContext('2d');
  }

  _startPreview(cardEl, videoPath) {
    if (isStreamPath(videoPath)) return;
    // Gate: user turned off moving previews (perf on large libraries).
    // Default is ON — only an explicit `false` disables, so libraries
    // that never touched the setting keep the animated hover preview.
    if (this._settings?.get?.('library.movingPreviews') === false) return;

    // Gate: don't preview if a video is actively playing
    if (this._isVideoPlaying) return;

    // Gate: skip audio-only files (no video to preview)
    const ext = videoPath.split('.').pop().toLowerCase();
    if (['mp3', 'wav', 'ogg', 'flac', 'aac', 'wma', 'm4a'].includes(ext)) return;

    this._ensurePreviewVideo();
    this._previewGeneration++;
    const gen = this._previewGeneration;

    const video = this._previewVideo;
    video.src = pathToFileURL(videoPath);

    video.addEventListener('loadeddata', () => {
      if (gen !== this._previewGeneration) return;

      // Skip if no video track (audio-only file that slipped through)
      if (video.videoWidth === 0 || video.videoHeight === 0) return;

      // Set canvas aspect ratio
      this._previewCanvas.height = Math.round(320 * (video.videoHeight / video.videoWidth));

      // Seek to 25% of duration
      if (isFinite(video.duration) && video.duration > 0) {
        video.currentTime = video.duration * 0.25;
      }
    }, { once: true });

    video.addEventListener('seeked', () => {
      if (gen !== this._previewGeneration) return;
      this._startPreviewLoop(cardEl, gen);
    }, { once: true });

    video.addEventListener('error', () => {
      // Preview failed — silently ignore, static thumbnail stays
    }, { once: true });
  }

  _startPreviewLoop(cardEl, gen) {
    if (gen !== this._previewGeneration) return; // stale — another hover started

    // Find the thumbnail container (grid or list)
    const thumb = cardEl.querySelector('.library__card-thumbnail') || cardEl.querySelector('.library__list-thumb');
    if (!thumb) return;

    // Remove any existing preview canvas to prevent duplicates
    const existing = thumb.querySelector('.library__preview-canvas');
    if (existing) existing.remove();

    // Insert canvas overlay — use opacity, NOT display:none (Electron leak #22417)
    const canvas = this._previewCanvas;
    canvas.className = 'library__preview-canvas';
    thumb.appendChild(canvas);

    // Fade in
    requestAnimationFrame(() => canvas.classList.add('library__preview-canvas--visible'));

    // Start drawing frames
    const video = this._previewVideo;
    const ctx = this._previewCtx;
    const drawFrame = () => {
      if (gen !== this._previewGeneration) return;
      try {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      } catch { /* cross-origin or other error */ }
      this._previewRaf = requestAnimationFrame(drawFrame);
    };

    video.play().catch(() => {});
    this._previewRaf = requestAnimationFrame(drawFrame);

    // Auto-cycle through positions every 3 seconds
    const positions = [0.25, 0.45, 0.65, 0.85, 0.1];
    this._previewCycleIndex = 0;
    this._previewCycleTimer = setInterval(() => {
      if (gen !== this._previewGeneration) return;
      this._previewCycleIndex = (this._previewCycleIndex + 1) % positions.length;
      if (isFinite(video.duration) && video.duration > 0) {
        video.currentTime = video.duration * positions[this._previewCycleIndex];
      }
    }, 3000);
  }

  _stopPreview() {
    this._previewGeneration++; // invalidate any pending operations

    if (this._previewRaf) {
      cancelAnimationFrame(this._previewRaf);
      this._previewRaf = null;
    }
    if (this._previewCycleTimer) {
      clearInterval(this._previewCycleTimer);
      this._previewCycleTimer = null;
    }
    if (this._previewHoverTimer) {
      clearTimeout(this._previewHoverTimer);
      this._previewHoverTimer = null;
    }

    if (this._previewVideo) {
      this._previewVideo.pause();
      this._previewVideo.removeAttribute('src');
      this._previewVideo.load(); // release media resource
    }

    // Remove canvas from card (fade out then remove)
    if (this._previewCanvas) {
      const canvas = this._previewCanvas;
      canvas.classList.remove('library__preview-canvas--visible');
      setTimeout(() => {
        if (canvas.parentElement) canvas.remove();
      }, 200);
    }
  }

  // --- Video options dialog (DESIGN-video-options.md (b), build stage 2a) ---
  //
  // A video's ⋮ (grid card and list row) opens the video options dialog
  // (video-options-dialog.js). It replaced the accordion menu here
  // (`_showKebabMenu` / `_makeKebabGroup`): every item of it lives in one of
  // the dialog's sections now. The folder ⋮ keeps its small menu below.

  /**
   * The heart on a card or list row (zaikechi #381): one click makes the
   * video a favourite (it joins the Favourites playlist) or not. A toggle
   * button (aria-pressed) that says which way it goes; it repaints itself,
   * never the grid, so the scroll and the focus stay put.
   */
  _favouriteButton(video, { list = false } = {}) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = list ? 'library__list-fav' : 'library__fav-btn';
    btn.appendChild(icon(Heart, { width: 16, height: 16 }));
    const paint = (on) => {
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
      const label = t(on ? 'library.favourites.remove' : 'library.favourites.add', { name: video?.name || '' });
      btn.title = label;
      btn.setAttribute('aria-label', label);
    };
    paint(isFavourite(this._settings, video?.path));
    btn.addEventListener('click', async (e) => {
      e.stopPropagation();
      const on = await toggleFavourite(this._settings, video.path, t('library.favourites.playlistName'));
      paint(on);
      this.onMarksChanged?.(video.path);
    });
    return btn;
  }

  /** Repaint a video's Disabled look after a change made elsewhere (the player, Video options, the review list). */
  refreshDisabled(videoPath) {
    if (!this._container || typeof videoPath !== 'string') return;
    const on = isDisabled(this._settings, videoPath);
    for (const el of this._container.querySelectorAll('.library__card, .library__list-item')) {
      if (el.dataset.videoPath !== videoPath) continue;
      applyDisabledMark(el, on, {
        thumb: el.querySelector('.library__card-thumbnail, .library__list-thumb'),
        title: el.querySelector('.library__list-title'),
      });
    }
    // The phone learns at its next list read; one register for a burst of changes.
    clearTimeout(this._disabledRegisterTimer);
    this._disabledRegisterTimer = setTimeout(() => this._registerWithBackend?.(), 800);
  }

  /** Repaint a video's hearts after a change made elsewhere (the player, Video options). */
  refreshFavourite(videoPath) {
    if (!this._container || typeof videoPath !== 'string') return;
    const on = isFavourite(this._settings, videoPath);
    for (const el of this._container.querySelectorAll('.library__card, .library__list-item')) {
      if (el.dataset.videoPath !== videoPath) continue;
      const btn = el.querySelector('.library__fav-btn, .library__list-fav');
      if (!btn) continue;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
      const video = this._videos?.find((v) => v.path === videoPath);
      const label = t(on ? 'library.favourites.remove' : 'library.favourites.add', { name: video?.name || '' });
      btn.title = label;
      btn.setAttribute('aria-label', label);
    }
  }

  /** The ⋮ says what it opens: this video's options (design (b)). */
  _labelOptionsButton(btn, video) {
    // "Video options (Alt+Enter)": it opens a dialog now, not a menu, and the
    // hover text teaches the keyboard way in (Dave, 2026-11-18: keep the ⋮,
    // better tooltip).
    btn.title = t('videoOptions.openTitle');
    btn.setAttribute('aria-haspopup', 'dialog');
    btn.setAttribute('aria-label', t('videoOptions.openAria', { name: video?.name || '' }));
  }

  /** True while a ⋮ menu or the video options dialog is open. */
  _isMenuOrDialogOpen() {
    return !!this._openMenu || !!this._videoOptionsOpen;
  }

  /**
   * May a background poll (speed stats, durations) rebuild the grid now?
   *   'wait'    a menu or the video options dialog is open. `_renderGrid`
   *             empties the grid: an open menu went with it, and so did the
   *             ⋮ the dialog gives the focus back to. A skip for the dialog
   *             is the dialog's to render, once, on close
   *             (`_renderOwedOnClose`);
   *   'done'    the dialog's close has rendered what this poll skipped. A
   *             second render now would take the focus off the ⋮ again;
   *   'render'  go ahead.
   * @param {{toDialog: boolean}} owed the poll's own note (cleared by an arrival)
   * @returns {'wait'|'done'|'render'}
   */
  _pollRenderDecision(owed) {
    if (owed.toDialog && !this._videoOptionsOpen && !this._renderOwedOnClose) {
      owed.toDialog = false;
      return 'done';
    }
    if (this._isMenuOrDialogOpen()) {
      if (this._videoOptionsOpen) {
        this._renderOwedOnClose = true;
        owed.toDialog = true;
      }
      return 'wait';
    }
    owed.toDialog = false;
    return 'render';
  }

  /**
   * The card (grid) or row (list) on screen for `path`, or null. Found by
   * path each time: a card captured before a dialog or a re-render is gone
   * by the time a write lands (design (b)). Compared as strings, so a path
   * with quotes or brackets needs no selector escaping.
   */
  _cardForPath(path) {
    if (!path || !this._container) return null;
    for (const el of this._container.querySelectorAll('[data-video-path]')) {
      if (el.dataset.videoPath === path) return el;
    }
    return null;
  }

  /** Focus the ⋮ of `path`'s card, when it is on screen. */
  _focusOptionsButton(path) {
    const btn = this._cardForPath(path)?.querySelector('.library__kebab-btn, .library__list-kebab');
    if (!btn) return false;
    try { btn.focus({ preventScroll: true }); } catch { return false; }
    return document.activeElement === btn;
  }

  /**
   * Open the video options dialog for `video` and wait until the user is
   * done with it. Then the render the polls owe runs, and only after it the
   * focus goes back to the ⋮, found again by path (the render rebuilt the
   * card). Play in the dialog plays the video as a card click does.
   * @param {object} video
   * @param {{section?: string, focusKey?: string}} [opts]
   */
  async _openVideoOptions(video, opts = {}) {
    if (!video?.path || this._videoOptionsOpen) return;
    this._closeMenu();
    this._dismissQueueContextMenu();
    const path = video.path;
    this._videoOptionsOpen = true;
    this._renderOwedOnClose = false;
    let result = null;
    try {
      const { openVideoOptionsDialog } = await import('./video-options-dialog.js');
      result = await openVideoOptionsDialog(this._videoOptionsHost(), video, opts);
    } catch (err) {
      console.warn('[Library] video options failed:', err?.message || err);
    } finally {
      this._videoOptionsOpen = false;
    }
    if (this._renderOwedOnClose) {
      this._renderOwedOnClose = false;
      if (!this._scanning && this._container?.querySelector('.library__grid')) this._applyFilters();
    }
    if (result?.kind === 'play') {
      this._playVideo(this.getVideoByPath(path) || video);
      return;
    }
    // "Show videos with this tag" (the Tags section's chip menu): the dialog
    // has closed; the filter applies and the focus goes to the grid.
    if (result?.kind === 'tag' && typeof result.key === 'string') {
      if (this._showVideosWithTag(result.key, result.tag || null)) return;
    }
    this._focusOptionsButton(path);
  }

  /**
   * What the video options dialog may use of the library. The dialog writes
   * through the model's plans (`settings` is the DataService); these do the
   * rest: the big actions it reuses, and the card and filters after a write.
   */
  _videoOptionsHost() {
    const card = (path) => this._cardForPath(path);
    return {
      settings: this._settings,
      getVideo: (path) => this.getVideoByPath(path) || null,
      libraryVideos: () => this._videos || [],
      // `hide()` empties the container: no grid means the library is not on
      // screen, and a big action that left it (a play) does not reopen.
      canReopen: () => !!this._container?.querySelector('.library__grid'),
      canQueue: !!this._onAddToQueue,
      addToQueue: (path, position) => this._onAddToQueue?.(path, position),
      formatDuration: (sec) => this._formatDuration(sec),
      thumbnailUrl: (path) => thumbCache.get(path, 0) || null,
      // "Script not found" only when it is provably gone (the file absent,
      // its folder answers), as the card says it; else unknown.
      pathStatus: async (p) => {
        const s = await this._pathStatus(p);
        if (s !== false) return s;
        return (await this._safeToPrune(p)) ? false : null;
      },
      embeddedAxes: (video) => video?._embeddedAxes || this._getEmbeddedAxes?.(video?.funscriptPath) || null,
      randomVariantOn: () => this._settings.get('player.randomVariantOnPlay') === true,
      collectionContext: () => ({
        sources: this._settings.get('library.sources') || [],
        folderIndex: this._folderIndex || null,
        descendantsOf,
      }),
      // Big actions: the dialog closes, runs one, and opens again.
      changeScript: (video) => this._associateFunscript(video, card(video.path), { chain: true }),
      findOnEroScripts: (video) => this._eroScriptsSearchFlow(video, card(video.path)),
      addVariation: (video) => this._addVariationFlow(video),
      // A saved stream has no folder to write axis files into (2026-11-23).
      extractAxes: this._onExtractEmbeddedAxes ? (video) => (video?._stream ? null : this._onExtractEmbeddedAxes(video)) : null,
      pickFrame: (video) => this._pickCustomThumbnail(video, card(video.path)),
      openVRFormat: this._onOpenVRFormat ? (path) => (isStreamPath(path) ? null : this._onOpenVRFormat(path)) : null,
      // Small ones stack on the dialog.
      changeSubtitle: (video) => this._associateSubtitle(video, card(video.path)),
      uploadImage: (video) => this._uploadCustomThumbnail(video, card(video.path)),
      createCategory: async () => {
        const { promptCreateCategory } = await import('../js/category-create-modal.js');
        return promptCreateCategory({ settings: this._settings });
      },
      // After a write.
      dataChanged: () => { this._renderOwedOnClose = true; },
      categoriesChanged: (path) => {
        if (!path) { this._repaintAllCategoryDots(); return; }
        const el = card(path);
        if (el) this._updateCardCategoryDots(el, path);
      },
      unpairApplied: (video) => this._showUnpaired(video),
      unpairUndone: (video, reapply, o) => this._showPairingRestored(video, reapply, o),
      // Locate (Dave, 2026-11-18): the native picker at the folder the stored
      // path points to (main finds the nearest folder that exists; nothing is
      // created), funscripts only. A path, or null when cancelled.
      locateScript: async (scriptPath) => {
        const picked = await window.funsync?.selectFunscript?.({ defaultPath: scriptPath });
        return typeof picked?.path === 'string' && picked.path ? picked.path : null;
      },
      // A new script for the pairing that plays (Locate) or its Undo: the
      // same apply path as an Unpair's Undo (the card, the filters).
      pairingChanged: (video, reapply) => this._showPairingRestored(video, reapply),
      subtitleChanged: (video, subPath) => this._showSubtitleState(video, subPath),
      thumbnailChanged: (video) => {
        thumbCache.remove(video.path, 0);
        return this._refreshCardThumbnail(video.path, card(video.path));
      },
      // The grid does not rebuild under the dialog (design (b)): the VR
      // filter and badge follow in the render the close runs (review-a RA-6).
      vrChanged: () => { this._renderOwedOnClose = true; },
      // The playing video's delta goes on the devices at once (app.js
      // re-reads it; a video that is not playing gets it at its next load).
      syncOffsetChanged: (path) => {
        const app = typeof window !== 'undefined' ? window.app : null;
        if (app && typeof app._videoSyncOffsetPath === 'function' && app._videoSyncOffsetPath() === path) {
          app._applyVideoSyncOffset?.();
        }
      },
      // The Tags section's EroScripts login and expiry (Get tags needs the
      // login, Dave's answer 6): main's session says "logged in" (what every
      // EroScripts request uses), the EroScripts panel's PUBLIC login and
      // handleSessionExpired keep the saved session and the panel in step.
      // Reached through window.app, as `_tearDownLiveRoutingIfEditing` does.
      eroscripts: {
        isLoggedIn: async () => {
          try { return (await window.funsync?.eroscriptsStatus?.())?.loggedIn === true; } catch { return false; }
        },
        login: async () => {
          const panel = typeof window !== 'undefined' ? window.app?.eroscriptsPanel : null;
          if (!panel || typeof panel.login !== 'function') return false;
          return (await panel.login()) === true;
        },
        // The panel's answer goes back ('valid' / 'unknown': the login was
        // kept, so the section says the refusal instead; 'expired' /
        // 'loggedOut': log in again), so the section needs no second ask
        // (2d's TODO, fixed in Round 3).
        sessionExpired: async () => {
          const panel = typeof window !== 'undefined' ? window.app?.eroscriptsPanel : null;
          if (panel && typeof panel.handleSessionExpired === 'function') return panel.handleSessionExpired();
          return undefined;
        },
        // The session check as the section opens and after a refusal (Dave,
        // 2026-11-18): the panel's own, which keeps its answer for a few
        // minutes. A getter, read at each use: with no panel there is no
        // check (undefined), exactly as the section's own fallback.
        get checkSession() {
          const panel = typeof window !== 'undefined' ? window.app?.eroscriptsPanel : null;
          if (!panel || typeof panel.checkSession !== 'function') return undefined;
          return (opts) => panel.checkSession(opts);
        },
      },
      // The Tags section (Round 3): the library's one tag index for its
      // suggestions and Make a category, the script file's own metadata
      // (script-meta-store.js), and "Show videos with this tag" (the dialog
      // closes with `{kind: 'tag', key}` and `_openVideoOptions` applies it).
      tagIndex: () => this._tagIndexMemo().get(),
      getScriptMeta: (scriptPath) => getScriptMeta(scriptPath),
      scriptMetaMap: () => scriptMetaMap(),
      canShowVideosWithTag: true,
      // Saved streams (2026-11-23): its page in the browser, and Remove.
      openExternal: (url) => window.funsync?.openExternal?.(url),
      removeStream: (key) => this.removeStream(key),
      // Delete the video's files (DESIGN.md §2.18).
      deleteVideo: (video) => this.deleteVideo(video),
      // Favourite / Disabled changed in the dialog (zaikechi #381): the card and the player follow.
      onMarksChanged: (videoPath) => {
        this.refreshFavourite(videoPath);
        this.refreshDisabled(videoPath);
        this.onMarksChanged?.(videoPath);
      },
      // A saved stream: its page in the browser, no file to look at (2026-11-23).
      showInFolder: (path) => (isStreamPath(path)
        ? window.funsync?.openExternal?.(this._videosByPath?.get(path)?.pageUrl || '')
        : window.funsync?.showInFolder?.(path)),
      statFile: async (path) => {
        if (isStreamPath(path)) return null;
        const stats = await window.funsync?.statVideoFiles?.([path]);
        const size = stats?.[path]?.size;
        return Number.isFinite(size) ? size : null;
      },
      copyText: async (text) => {
        await navigator.clipboard.writeText(text);
        return true;
      },
      // Stash S1 (File > Stash, the Tags section's Stash row, Find in
      // Stash…): see _stashHost.
      stash: this._stashHost(),
    };
  }

  /**
   * `host.stash`, what the video options dialog uses of the Stash link
   * (Stash S1; DESIGN-stash-s1.md (f) "The video options dialog"). Main
   * owns the Stash data and does every change (stage s1-2a-main's IPC); each
   * change resolves main's reply (`{ok: true, undoId}` or `{ok: false,
   * code}`, the `undoId` passed back to `undo` as given) plus `view`,
   * the video's view model read after the change landed. Scene ids are
   * main's opaque ids from the view; pass them back as given. The library
   * re-indexes on its own when the data changes (onStashChanged).
   *
   * - enabled()            Stash is on (`settings.stash.enabled === true`)
   * - view(path)           stash-tags.js stashVideoView (null when off)
   * - data(), version(), onChanged(cb)   the renderer's copy (stash-store.js)
   * - syncVideo(path)      Sync this video (`{ok, kind: 'video', counts, …}`)
   * - choose(path, sceneId)            Use this scene / Use it anyway (`by: 'chosen'`)
   * - refuse(path, target, sceneId?)   Not this scene (`'link'`, with the scene it named) / None of these, Ignore (`'check'`)
   * - unlink(path, sceneId?)           Unlink (the scene the block showed)
   * - link(path, sceneId)  a Find in Stash… pick (`by: 'manual'`)
   * - undo(path, undoId)   Undo any of the above
   * - search(q)            Find in Stash…: one search per press
   * - openInStash(path, sceneId?)  main opens `<address>/scenes/<id>` in the browser
   */
  _stashHost() {
    const enabled = () => this._settings?.get?.('stash.enabled') === true;
    const videoOf = (path) => this.getVideoByPath(path) || null;
    const view = (path) => {
      const v = videoOf(path);
      return stashVideoView(stashData(), path, { size: v?.size, duration: v?.duration, enabled: enabled() });
    };
    const withView = (path, reply) => ({ ...(reply || {}), view: view(path) });
    return {
      enabled,
      view,
      data: () => stashData(),
      version: () => stashVersion(),
      onChanged: (cb) => onStashChanged(cb),
      syncVideo: async (path) => (isStreamPath(path) ? null : withView(path, await syncStashVideo(videoOf(path) || { path }))),
      choose: async (path, sceneId) => withView(path, await chooseStashScene(path, sceneId)),
      // `sceneId`: the scene the dialog named (RA-S1-3); main checks it.
      refuse: async (path, target, sceneId) => withView(path, await refuseStashScene(path, target, sceneId)),
      unlink: async (path, sceneId) => withView(path, await unlinkStashVideo(path, sceneId)),
      link: async (path, sceneId) => withView(path, await linkStashScene(path, sceneId)),
      undo: async (path, undoId) => withView(path, await undoStash(undoId)),
      search: (q) => searchStash(q),
      openInStash: (path, sceneId) => openStashScene(path, sceneId),
    };
  }

  /**
   * Alt+Enter on a focused control inside a card (its ⋮ is the card's only
   * Tab stop): that video's options.
   */
  _handleCardOptionsKey(e) {
    if (e.key !== 'Enter' || !e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return;
    const target = e.target;
    if (!target || typeof target.closest !== 'function' || !this._container?.contains(target)) return;
    const cardEl = target.closest('.library__card, .library__list-item');
    const video = cardEl ? this.getVideoByPath(cardEl.dataset.videoPath) : null;
    if (!video) return;
    e.preventDefault();
    this._openVideoOptions(video);
  }

  /** "+ Add variation…" from the dialog: the Associate dialog's own flow. */
  async _addVariationFlow(video) {
    const picked = await this._showVariantSearchModal(video, { multiple: true });
    if (picked) await this._addVariantsWithNaming(video, picked);
  }

  /**
   * Position the kebab menu as a fixed-position portal anchored to the
   * kebab button that opened it. The menu lives on document.body (not
   * inside the card) so nothing can ever clip it: fixed positioning
   * escapes the grid-wrapper's overflow AND every stacking context, so
   * the menu overlays the filter bar / top bar when there's no room
   * below. Placement: below the button, right-aligned; flips above when
   * the bottom would clip; clamps to the viewport with the menu's own
   * max-height+scroll as the final safety net. Must be called AFTER the
   * menu is in the DOM (it measures), and again whenever a group
   * expand/collapse changes the height. Scrolling the grid closes the
   * menu (existing behavior), so the fixed anchor can't go stale.
   */
  _positionKebabMenu(menu) {
    const btn = this._openMenuButton;
    if (!menu || !btn) return;
    const margin = 8;
    const gap = 4;
    const btnRect = btn.getBoundingClientRect();
    menu.style.position = 'fixed';
    menu.style.right = 'auto';
    const menuRect = menu.getBoundingClientRect();
    // Right-align to the button, clamped inside the viewport.
    let left = btnRect.right - menuRect.width;
    left = Math.max(margin, Math.min(left, window.innerWidth - menuRect.width - margin));
    // Below by default; above if below would clip; pin to the viewport
    // edge if neither direction fully fits (max-height scroll takes over).
    let top = btnRect.bottom + gap;
    if (top + menuRect.height > window.innerHeight - margin) {
      const above = btnRect.top - gap - menuRect.height;
      top = above >= margin
        ? above
        : Math.max(margin, window.innerHeight - margin - menuRect.height);
    }
    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
  }

  _closeMenu() {
    if (this._openMenu) {
      // Closing with the focus inside the menu (an item was chosen, by
      // mouse or keyboard) hands it back to the kebab that opened it, as a
      // menu button does. Removing the menu used to drop it to <body>, and a
      // dialog the item opened (Add to Playlist, Assign Category) gave it
      // back to <body> as well: keyboard users lost their place (block C
      // verifier 1; also in v0.9.2).
      const returnTo = this._openMenu.contains(document.activeElement) ? this._openMenuButton : null;
      this._openMenu.remove();
      this._openMenu = null;
      if (returnTo?.isConnected) {
        try { returnTo.focus({ preventScroll: true }); } catch { /* not focusable */ }
      }
    }
    this._openMenuCard = null;
    this._openMenuButton = null;
    // Listener was attached in capture phase; match here.
    document.removeEventListener('click', this._boundCloseMenu, true);
  }

  /**
   * Capture-phase document click listener. Only closes the menu when
   * the click is genuinely outside the open menu (and outside the
   * button that opened it — that button's own handler toggles).
   * The previous implementation closed on any document click, which
   * triggered intermittently when a click on a menu item slipped past
   * `e.stopPropagation()` (rare timing window when virtual scroll
   * re-rendered between menu open and item click).
   */
  _handleOutsideClick(e) {
    if (!this._openMenu) return;
    const target = e?.target;
    if (target && (target === this._openMenu || this._openMenu.contains(target))) {
      // Click is inside the menu — the item's own handler will close it.
      return;
    }
    if (target && this._openMenuButton && (target === this._openMenuButton || this._openMenuButton.contains(target))) {
      // Click is on the kebab button itself — its handler toggles the menu.
      return;
    }
    this._closeMenu();
  }

  /**
   * The Associate dialog. After its EroScripts search or its Add variation
   * flow it opens itself again; `opts.chain` (the video options dialog's
   * Change…) waits for that reopened run as well, so the options come back
   * only when the user is done here. Without it, as always, the call ends
   * when the first dialog's choice has run.
   */
  async _associateFunscript(video, cardEl, opts = {}) {
    const allScripts = this._allFunscripts;
    const unmatchedScripts = this._unmatchedFunscripts;
    const ranked = unmatchedScripts.length > 0 ? rankFunscriptMatches(video.name, unmatchedScripts) : [];
    // None of them matches the name: offer every script in the video's own
    // folder instead of "No funscripts found" (CB-17).
    const folderScripts = ranked.length === 0 ? funscriptsInFolderOf(video.path, allScripts) : [];

    // Auto-detect companion files from directory
    const mainFsPath = video.funscriptPath || '';
    const allPaths = allScripts.map(f => f.name);
    const detected = mainFsPath ? detectCompanionFiles(mainFsPath.split(/[\\/]/).pop(), allPaths) : [];

    // Embedded multi-axis detection — files that bundle pitch/roll/twist
    // INSIDE the main funscript instead of distributing as companions.
    // Probe on-demand if the user hasn't played the file yet so the
    // Multi-Axis tab can show "embedded in main" indicators for axes
    // that aren't on disk as separate files.
    let embeddedInfo = null;
    if (mainFsPath) {
      embeddedInfo = this._getEmbeddedAxes?.(mainFsPath);
      if (!embeddedInfo && this._detectEmbeddedAxesForPath) {
        embeddedInfo = await this._detectEmbeddedAxesForPath(mainFsPath);
      }
    }
    const embeddedSuffixes = new Set((embeddedInfo?.suffixes) || []);

    // Load existing config — normalize to the parallel-slot shape so the
    // modal can preselect the last-active mode and also pre-populate the
    // other panes from their saved slots.
    const existingAssoc = this._settings.get('library.associations') || {};
    const existingEntry = normalizeAssociation(existingAssoc[video.path]);
    const existingActive = existingEntry.active;
    const isMulti = existingActive === 'multi';
    const isCustom = existingActive === 'custom';
    const savedSingle = existingEntry.single || null;
    const savedMulti = existingEntry.multi || null;
    const savedCustom = existingEntry.custom || null;

    const chosen = await Modal.open({
      title: t('library.assoc.title'),
      onRender: (body, close) => {
        // --- Mode radio ---
        const modeRow = document.createElement('div');
        modeRow.className = 'library__assoc-mode';

        const radioSingle = document.createElement('input');
        radioSingle.type = 'radio';
        radioSingle.name = 'assoc-mode';
        radioSingle.id = 'assoc-single';
        radioSingle.value = 'single';
        radioSingle.checked = !isMulti && !isCustom;

        const labelSingle = document.createElement('label');
        labelSingle.htmlFor = 'assoc-single';
        labelSingle.textContent = t('library.assoc.modeSingle');

        const radioMulti = document.createElement('input');
        radioMulti.type = 'radio';
        radioMulti.name = 'assoc-mode';
        radioMulti.id = 'assoc-multi';
        radioMulti.value = 'multi';
        radioMulti.checked = isMulti;

        const labelMulti = document.createElement('label');
        labelMulti.htmlFor = 'assoc-multi';
        labelMulti.textContent = t('library.assoc.modeMulti');

        const radioCustom = document.createElement('input');
        radioCustom.type = 'radio';
        radioCustom.name = 'assoc-mode';
        radioCustom.id = 'assoc-custom';
        radioCustom.value = 'custom';
        radioCustom.checked = isCustom;

        const labelCustom = document.createElement('label');
        labelCustom.htmlFor = 'assoc-custom';
        labelCustom.textContent = t('library.assoc.modeCustom');

        modeRow.appendChild(radioSingle);
        modeRow.appendChild(labelSingle);
        modeRow.appendChild(radioMulti);
        modeRow.appendChild(labelMulti);
        modeRow.appendChild(radioCustom);
        modeRow.appendChild(labelCustom);
        body.appendChild(modeRow);

        // --- Single axis panel ---
        const singlePanel = document.createElement('div');
        singlePanel.className = 'library__assoc-panel';
        singlePanel.hidden = isMulti || isCustom;

        // Current script info. Reflects the saved single-axis slot, not
        // whichever mode happens to be active — otherwise switching to the
        // Single pane while Custom is active would misleadingly show the
        // custom-routing main script as "current".
        const currentSection = document.createElement('div');
        currentSection.className = 'library__assoc-current';

        const autoFunscriptPath = !video._manualAssociation ? (video.funscriptPath || null) : null;
        const singleCurrentPath = savedSingle || autoFunscriptPath;
        const singleCurrentIsManual = !!savedSingle;
        if (singleCurrentPath) {
          const currentName = singleCurrentPath.split(/[\\/]/).pop();
          const currentLabel = document.createElement('span');
          currentLabel.className = 'library__assoc-current-label';
          currentLabel.textContent = t('library.assoc.current');
          const currentFile = document.createElement('span');
          currentFile.className = 'library__assoc-current-name';
          currentFile.textContent = currentName;
          currentFile.title = singleCurrentPath;
          const currentType = document.createElement('span');
          currentType.className = 'library__assoc-current-type';
          currentType.textContent = singleCurrentIsManual ? t('library.assoc.currentManual') : t('library.assoc.currentAuto');
          // No ✕ here any more (Dave, 2026-11-18, review-a RA-2): it deleted
          // the whole entry, a Multi Axis set and a Custom Routing you made
          // with it, with no confirm and no Undo. This dialog only picks
          // scripts; unpairing is the video options dialog's Script section
          // (Unpair funscript, Remove a set: a confirm and an exact Undo).
          currentSection.append(currentLabel, currentFile, currentType);
        } else {
          const noScript = document.createElement('span');
          noScript.className = 'library__assoc-current-none';
          noScript.textContent = t('library.assoc.noScript');
          currentSection.appendChild(noScript);
        }
        singlePanel.appendChild(currentSection);

        // Change section header
        const changeHeader = document.createElement('div');
        changeHeader.className = 'library__assoc-section-header';
        changeHeader.textContent = singleCurrentPath ? t('library.assoc.changeTo') : t('library.assoc.selectScript');
        singlePanel.appendChild(changeHeader);

        // Fuzzy ranked list
        if (ranked.length > 0) {
          const list = document.createElement('div');
          list.className = 'modal-list';
          for (const match of ranked) {
            const row = document.createElement('button');
            row.className = 'modal-list-item';
            const label = document.createElement('span');
            label.className = 'modal-list-item-label';
            label.textContent = match.name;
            row.appendChild(label);
            const badge = document.createElement('span');
            const scoreClass = match.score >= 70 ? '--high' : match.score >= 40 ? '--medium' : '--low';
            badge.className = `library__match-score library__match-score${scoreClass}`;
            badge.textContent = `${match.score}%`;
            row.appendChild(badge);
            row.addEventListener('click', () => close({ mode: 'single', path: match.path, name: match.name }));
            list.appendChild(row);
          }
          singlePanel.appendChild(list);
        } else if (folderScripts.length > 0) {
          // Scripts next to the video, none named like it (CB-17): say so,
          // and list them all, by name. Not when one IS named like it: the
          // video's own paired `<video>.funscript` (or a variant of it) is
          // never in the unmatched list the ranking reads, so the note said
          // "No script here is named like this video" over a list holding it
          // (R4 fix-up, real-app verifier 2).
          const stem = (n) => String(n || '').replace(/\.[^./\\]+$/, '').toLowerCase();
          const videoStem = stem(video.name);
          const namedLike = !!videoStem && folderScripts.some((s) => {
            const st = stem(s.name);
            return st === videoStem || st.startsWith(`${videoStem}.`);
          });
          if (!namedLike) {
            const note = document.createElement('div');
            note.className = 'modal-message modal-message--muted library__assoc-no-name-match';
            note.textContent = t('library.assoc.noNameMatch');
            singlePanel.appendChild(note);
          }
          const list = document.createElement('div');
          list.className = 'modal-list';
          for (const script of folderScripts) {
            const row = document.createElement('button');
            row.className = 'modal-list-item';
            const label = document.createElement('span');
            label.className = 'modal-list-item-label';
            label.textContent = script.name;
            label.title = script.path;
            row.appendChild(label);
            row.addEventListener('click', () => close({ mode: 'single', path: script.path, name: script.name }));
            list.appendChild(row);
          }
          singlePanel.appendChild(list);
        } else {
          const msg = document.createElement('div');
          msg.className = 'modal-message modal-message--muted';
          msg.textContent = t('library.assoc.noFunscripts');
          singlePanel.appendChild(msg);
        }

        const divider = document.createElement('div');
        divider.className = 'library__suggestion-divider';
        singlePanel.appendChild(divider);

        const browseRow = document.createElement('button');
        browseRow.className = 'modal-list-item library__assoc-action';
        browseRow.textContent = t('library.assoc.browse');
        browseRow.addEventListener('click', async () => {
          const result = await window.funsync.selectFunscript();
          if (result) close({ mode: 'single', path: result.path, name: result.name });
        });
        singlePanel.appendChild(browseRow);

        // Search EroScripts for THIS video. The standalone panel always
        // targets the currently-loaded video, so attaching a script to
        // something in the library meant opening it first and backing out
        // again. Hands control back to the caller like addVariantFlow does,
        // rather than nesting a modal inside a modal.
        const eroRow = document.createElement('button');
        eroRow.className = 'modal-list-item library__assoc-action library__assoc-action--ero';
        eroRow.textContent = t('library.assoc.searchEroScripts');
        eroRow.addEventListener('click', () => close({ mode: 'eroSearchFlow' }));
        singlePanel.appendChild(eroRow);

        // Save button — commits the single-axis slot as active without
        // forcing the user to re-pick a script. Needed because the parallel-
        // slot model means flipping the radio to Single isn't enough on its
        // own; without an explicit save the active pointer stays on whatever
        // it was (multi / custom) and the modal reopens on that mode.
        // Disabled when there's nothing to save (no saved single AND no
        // auto-detected funscript) — user must pick a script first.
        const singleSaveBtn = document.createElement('button');
        singleSaveBtn.className = 'library__assoc-save-btn';
        singleSaveBtn.textContent = t('library.assoc.save');
        singleSaveBtn.disabled = !singleCurrentPath;
        singleSaveBtn.addEventListener('click', () => {
          if (!singleCurrentPath) return;
          close({
            mode: 'single',
            path: singleCurrentPath,
            name: singleCurrentPath.split(/[\\/]/).pop(),
          });
        });
        singlePanel.appendChild(singleSaveBtn);

        // Variations section
        const varDivider = document.createElement('div');
        varDivider.className = 'library__suggestion-divider';
        singlePanel.appendChild(varDivider);

        const varSection = document.createElement('div');
        varSection.className = 'library__assoc-variants';

        const varHeader = document.createElement('div');
        varHeader.className = 'library__assoc-section-header';
        const autoVariants = video.variants || [];
        // The user's single association, when it is what the video plays
        // (not fallen back to its own script): its row is tagged "manual".
        const userSingleKey = existingActive === 'single' && savedSingle && !video._assocFallbackFrom
          ? canonicalPath(savedSingle) : null;
        const manualVariants = (this._settings.get('library.manualVariants') || {})[video.path] || [];
        // Track which set each variant came from so we know which can be
        // removed via the modal (manual ones only — auto variants are
        // file-driven and would just reappear on the next scan).
        const variantList = [
          ...autoVariants.map(v => ({ ...v, _isManual: false })),
          ...manualVariants.map(v => ({ ...v, _isManual: true })),
        ];
        const updateHeader = () => {
          const remainingRows = varSection.querySelectorAll('.library__assoc-variant-row').length;
          varHeader.textContent = remainingRows > 0
            ? t('library.assoc.variationsCount', { count: remainingRows })
            : t('library.assoc.variations');
        };
        varHeader.textContent = variantList.length > 0
          ? t('library.assoc.variationsCount', { count: variantList.length })
          : t('library.assoc.variations');
        varSection.appendChild(varHeader);

        // FN-03: each row is named as the player's menu names it (an
        // unlabelled script by its file, never "Default"); the script the
        // video opens on is marked "main", and the one playing now (this
        // video in the player) is highlighted and announced as current.
        const mainKey = video.funscriptPath ? canonicalPath(video.funscriptPath) : null;
        const mainRowAt = mainKey ? variantList.findIndex((v) => canonicalPath(v.path) === mainKey) : -1;
        const playingPath = this._getPlayingScript?.(video.path) || null;
        const playingKey = playingPath ? canonicalPath(playingPath) : null;
        for (const [rowAt, v] of variantList.entries()) {
          const vRow = document.createElement('div');
          vRow.className = 'library__assoc-variant-row';
          const playing = !!playingKey && canonicalPath(v.path) === playingKey;
          if (playing) {
            vRow.classList.add('library__assoc-variant-row--playing');
            vRow.setAttribute('aria-current', 'true');
          }
          const vName = document.createElement('span');
          vName.className = 'library__assoc-variant-name';
          vName.textContent = variantDisplayName(v) || v.label;
          vName.title = v.name || v.path;
          vRow.appendChild(vName);
          if (rowAt === mainRowAt) {
            const mainTag = document.createElement('span');
            mainTag.className = 'library__assoc-variant-main';
            mainTag.textContent = t('variants.mainTag');
            vRow.appendChild(mainTag);
          }

          if (v._isManual) {
            // Remove button — drops the entry from settings.library.manualVariants
            // for this video. The file stays on disk; this just unlinks it
            // from the variant selector for this video.
            const removeBtn = document.createElement('button');
            removeBtn.type = 'button';
            removeBtn.className = 'library__assoc-variant-remove';
            removeBtn.textContent = '✕';
            removeBtn.title = t('library.assoc.removeVariation');
            removeBtn.addEventListener('click', (e) => {
              e.stopPropagation();
              const all = this._settings.get('library.manualVariants') || {};
              const list = (all[video.path] || []).filter(x => x.path !== v.path);
              if (list.length === 0) delete all[video.path];
              else all[video.path] = list;
              this._settings.set('library.manualVariants', all);
              vRow.remove();
              updateHeader();
            });
            vRow.appendChild(removeBtn);
          } else if (userSingleKey && canonicalPath(v.path) === userSingleKey) {
            // The user's own single association, which leads the list since
            // R4-06: theirs, so "manual" as on the Current row above (it is
            // cleared with that row's ✕), not "auto" (C-03).
            const manualTag = document.createElement('span');
            manualTag.className = 'library__assoc-variant-tag library__assoc-variant-tag--manual';
            manualTag.textContent = t('library.assoc.currentManual');
            manualTag.title = t('library.funscriptManual');
            vRow.appendChild(manualTag);
          } else {
            // Auto-detected variant — show a small "auto" tag so users
            // understand why it can't be removed via this UI.
            const autoTag = document.createElement('span');
            autoTag.className = 'library__assoc-variant-tag';
            autoTag.textContent = t('library.assoc.autoVariantTag');
            autoTag.title = t('library.assoc.autoVariantTitle');
            vRow.appendChild(autoTag);
          }

          varSection.appendChild(vRow);
        }

        const addVarBtn = document.createElement('button');
        addVarBtn.className = 'modal-list-item library__assoc-action';
        addVarBtn.textContent = t('library.assoc.addVariation');
        addVarBtn.addEventListener('click', async () => {
          close({ mode: 'addVariantFlow' });
        });
        varSection.appendChild(addVarBtn);

        singlePanel.appendChild(varSection);
        body.appendChild(singlePanel);

        // --- Multi axis panel ---
        const multiPanel = document.createElement('div');
        multiPanel.className = 'library__assoc-panel library__assoc-multi-panel';
        multiPanel.hidden = !isMulti;

        // Build a lookup of detected companions by suffix
        const detectedMap = new Map();
        for (const c of detected) {
          detectedMap.set(c.axis.suffix, c.path);
        }

        // Pre-fill from the saved multi slot regardless of which mode is
        // currently active — the new shape keeps all three configs in
        // parallel, so opening the multi pane always shows the user's last
        // multi setup if they had one. Falls back to the single-axis script
        // as the main when there's no saved multi yet.
        const existingAxes = savedMulti?.axes || {};

        // Main axis row
        const axisRows = [];
        const mainRow = this._createAxisDropdown(t('library.assoc.axisMain'), 'main', allScripts, savedMulti?.main || (video.funscriptPath || ''), video.name);
        multiPanel.appendChild(mainRow.row);
        axisRows.push(mainRow);

        // Axis rows for relevant axes
        const shownAxes = AXIS_DEFINITIONS.filter(a => ['vib', 'surge', 'sway', 'twist', 'roll', 'pitch'].includes(a.suffix));
        for (const axisDef of shownAxes) {
          // Pre-fill: existing config > detected companion > empty
          const preValue = existingAxes[axisDef.suffix] || '';
          const detectedPath = detectedMap.get(axisDef.suffix);
          const defaultVal = preValue || (detectedPath ? this._findScriptByName(allScripts, detectedPath) : '');

          const axisRow = this._createAxisDropdown(`${axisDef.label} (${axisDef.tcode})`, axisDef.suffix, allScripts, defaultVal, video.name);

          // Embedded indicator — when the main funscript bundles this
          // axis internally AND no companion file is available, the
          // dropdown has nothing to point at. Show an "✓ Embedded in
          // main" note so the user knows the axis IS active (driven
          // by the in-memory feed at playback time) and can choose to
          // extract it to a proper companion file.
          if (embeddedSuffixes.has(axisDef.suffix) && !defaultVal) {
            const note = document.createElement('span');
            note.className = 'library__assoc-embedded-note';
            note.textContent = '✓ Embedded in main';
            note.title = 'This axis lives inside the main funscript file. Pop the kebab and click "Extract embedded axes…" to save it as a separate companion file.';
            note.style.cssText = 'margin-left:8px; font-size:11px; color:var(--badge-multi); font-weight:500;';
            axisRow.row.appendChild(note);
          }

          multiPanel.appendChild(axisRow.row);
          axisRows.push(axisRow);
        }

        // If any embedded axes were detected, surface a single
        // "Extract all to companion files" button at the top of the
        // multi panel so the user has one-click access from inside the
        // modal too (mirrors the kebab item).
        if (embeddedSuffixes.size > 0 && this._onExtractEmbeddedAxes) {
          const extractRow = document.createElement('div');
          extractRow.className = 'library__assoc-axis-row';
          const btn = document.createElement('button');
          btn.className = 'library__assoc-save-btn';
          btn.textContent = `Extract ${embeddedSuffixes.size} embedded ${embeddedSuffixes.size === 1 ? 'axis' : 'axes'} to companion files`;
          btn.title = `Save ${[...embeddedSuffixes].join(', ')} as separate .funscript files alongside this video.`;
          btn.addEventListener('click', () => {
            this._onExtractEmbeddedAxes(video);
            close(null);
          });
          extractRow.appendChild(btn);
          // Insert ABOVE the per-axis rows so the user sees the option
          // before scrolling through dropdowns.
          multiPanel.insertBefore(extractRow, mainRow.row.nextSibling);
        }

        // Buttplug.io vibration checkbox
        const bpRow = document.createElement('div');
        bpRow.className = 'library__assoc-axis-row library__assoc-bp-row';
        const bpCheck = document.createElement('input');
        bpCheck.type = 'checkbox';
        bpCheck.id = 'assoc-bp-vib';
        bpCheck.checked = !!savedMulti?.buttplugVib;
        const bpLabel = document.createElement('label');
        bpLabel.htmlFor = 'assoc-bp-vib';
        bpLabel.textContent = t('library.assoc.useButtplugVib');
        bpRow.appendChild(bpCheck);
        bpRow.appendChild(bpLabel);
        multiPanel.appendChild(bpRow);

        // Save button
        const saveBtn = document.createElement('button');
        saveBtn.className = 'library__assoc-save-btn';
        saveBtn.textContent = t('library.assoc.save');
        saveBtn.addEventListener('click', () => {
          const axes = {};
          for (const ar of axisRows) {
            if (ar.key !== 'main' && ar.select.value) {
              axes[ar.key] = ar.select.value;
            }
          }
          const mainSelect = axisRows.find(r => r.key === 'main');
          close({
            mode: 'multi',
            main: mainSelect?.select.value || '',
            axes,
            buttplugVib: bpCheck.checked,
          });
        });
        multiPanel.appendChild(saveBtn);

        body.appendChild(multiPanel);

        // --- Custom Routing panel ---
        const customPanel = document.createElement('div');
        customPanel.className = 'library__assoc-panel';
        customPanel.hidden = !isCustom;

        const knownDevices = this._settings.get('knownDevices') || [];
        // Pre-fill from the saved custom slot regardless of active mode — same
        // parallel-slot rationale as the multi pane above.
        const existingRoutes = savedCustom?.routes || [];
        const routes = existingRoutes.length > 0
          ? existingRoutes.map(r => ({ ...r }))
          : [{ deviceId: '', scriptPath: video.funscriptPath || '', scriptName: video.funscriptPath?.split(/[\\/]/).pop() || '', role: 'main' }];

        const renderCustomRoutes = () => {
          customPanel.innerHTML = '';

          for (let i = 0; i < routes.length; i++) {
            const route = routes[i];
            const isMain = route.role === 'main';

            const row = document.createElement('div');
            row.className = 'library__custom-route';

            // Header
            const header = document.createElement('div');
            header.className = 'library__custom-route-header';
            const title = document.createElement('span');
            title.textContent = isMain ? t('library.assoc.routeMain') : t('library.assoc.routeNumbered', { n: i + 1 });
            title.className = 'library__custom-route-title';
            header.appendChild(title);
            if (!isMain) {
              const delBtn = document.createElement('button');
              delBtn.className = 'library__assoc-current-clear';
              delBtn.textContent = '✕';
              delBtn.title = t('library.assoc.removeRoute');
              delBtn.addEventListener('click', () => { routes.splice(i, 1); renderCustomRoutes(); });
              header.appendChild(delBtn);
            }
            row.appendChild(header);

            // Device dropdown
            const devRow = document.createElement('div');
            devRow.className = 'library__custom-route-field';
            const devLabel = document.createElement('span');
            devLabel.textContent = t('library.assoc.device');
            devLabel.className = 'library__assoc-axis-label';
            const devSelect = document.createElement('select');
            devSelect.className = 'connection-panel__device-select';
            const defaultOpt = document.createElement('option');
            defaultOpt.value = '';
            defaultOpt.textContent = knownDevices.length > 0 ? t('library.assoc.selectDevice') : t('library.assoc.connectDeviceFirst');
            devSelect.appendChild(defaultOpt);
            for (const kd of knownDevices) {
              const opt = document.createElement('option');
              opt.value = kd.id;
              opt.textContent = kd.label;
              devSelect.appendChild(opt);
            }
            // Preselect — buttplug knownDevices now use a composite id
            // (`buttplug:Name#Index`) so two same-name devices show as
            // distinct options. Match the route to its knownDevice by
            // deviceId + buttplugIndex; fall back to exact id for legacy
            // routes and non-buttplug device types.
            const matchedKd = (knownDevices || []).find((kd) => {
              if (kd.type === 'buttplug') {
                const name = kd.name || kd.label;
                if (`buttplug:${name}` !== route.deviceId) return false;
                if (Number.isFinite(route.buttplugIndex)) {
                  return kd.buttplugIndex === route.buttplugIndex;
                }
                return true;
              }
              return kd.id === route.deviceId;
            });
            devSelect.value = matchedKd?.id || '';
            devSelect.addEventListener('change', () => {
              const known = (knownDevices || []).find(kd => kd.id === devSelect.value);
              if (known && known.type === 'buttplug') {
                // Strip the `#Index` suffix from the composite id so
                // `route.deviceId` stays name-only — the matcher compares
                // against `buttplug:${dev.name}` and the extra disambiguation
                // is carried by `buttplugIndex` below.
                const name = known.name || known.label;
                route.deviceId = `buttplug:${name}`;
              } else {
                route.deviceId = devSelect.value;
              }
              // Snapshot the current Intiface index at save-time. It's stable
              // across Intiface restarts unless the user resets/reinstalls,
              // so _loadCustomRouting prefers it over the rename-sensitive
              // name match. Lookup happens from knownDevices (populated on
              // every Buttplug connect) so this works without a live manager
              // reference in the library view.
              if (known && typeof known.buttplugIndex === 'number') {
                route.buttplugIndex = known.buttplugIndex;
              } else {
                delete route.buttplugIndex;
              }
            });
            devRow.appendChild(devLabel);
            devRow.appendChild(devSelect);

            // Test-pulse button — lets the user confirm they picked the right
            // hardware before saving. Catches mis-selection AND the BLE-stalled
            // case where Intiface says "connected" but nothing actually moves.
            if (this._onTestDevice) {
              const testBtn = document.createElement('button');
              testBtn.type = 'button';
              testBtn.className = 'library__assoc-test-btn';
              testBtn.textContent = t('library.assoc.test');
              testBtn.title = t('library.assoc.testTitle');
              testBtn.addEventListener('click', async () => {
                if (!route.deviceId) return;
                testBtn.disabled = true;
                const origText = testBtn.textContent;
                testBtn.textContent = '…';
                const { showToast } = await import('../js/toast.js');
                try {
                  const result = await this._onTestDevice(route.deviceId, route.buttplugIndex);
                  if (result?.ok) {
                    testBtn.textContent = '✓';
                  } else {
                    testBtn.textContent = '✕';
                    testBtn.title = result?.reason || t('library.assoc.testFailed');
                    showToast(t('library.assoc.testFailedToast', { reason: result?.reason || 'unknown error' }), 'warn');
                  }
                } catch (err) {
                  testBtn.textContent = '✕';
                  showToast(t('library.assoc.testErrorToast', { message: err.message }), 'error');
                } finally {
                  setTimeout(() => {
                    testBtn.disabled = false;
                    testBtn.textContent = origText;
                    testBtn.title = t('library.assoc.testTitle');
                  }, 1200);
                }
              });
              devRow.appendChild(testBtn);
            }

            row.appendChild(devRow);

            // Script picker
            const scriptRow = document.createElement('div');
            scriptRow.className = 'library__custom-route-field';
            const scriptLabel = document.createElement('span');
            scriptLabel.textContent = t('library.assoc.script');
            scriptLabel.className = 'library__assoc-axis-label';
            const scriptName = document.createElement('span');
            scriptName.className = 'library__custom-route-script';
            scriptName.textContent = route.scriptName || route.scriptPath?.split(/[\\/]/).pop() || t('library.assoc.scriptNone');
            scriptName.title = route.scriptPath || '';
            const browseBtn = document.createElement('button');
            browseBtn.className = 'connection-panel__btn';
            browseBtn.style.cssText = 'min-width:auto;padding:4px 10px;font-size:11px';
            browseBtn.textContent = t('library.assoc.selectScriptBtn');
            browseBtn.addEventListener('click', async () => {
              // A route's script, not a variation: the picker says so (block
              // C verifier 2; it read "Select Script for Variation").
              const picked = await this._showVariantSearchModal(video, { title: t('library.assoc.routeScriptSearchTitle') });
              if (picked) {
                route.scriptPath = picked.path;
                route.scriptName = picked.name;
                scriptName.textContent = picked.name;
                scriptName.title = picked.path;
              }
            });
            scriptRow.appendChild(scriptLabel);
            scriptRow.appendChild(scriptName);
            scriptRow.appendChild(browseBtn);
            row.appendChild(scriptRow);

            customPanel.appendChild(row);
          }

          // Add Route button
          const addBtn = document.createElement('button');
          addBtn.className = 'modal-list-item library__assoc-action';
          addBtn.textContent = t('library.assoc.addRoute');
          addBtn.addEventListener('click', () => {
            routes.push({ deviceId: '', scriptPath: '', scriptName: '', role: 'axis' });
            renderCustomRoutes();
          });
          customPanel.appendChild(addBtn);

          // Save button
          const saveBtn = document.createElement('button');
          saveBtn.className = 'library__assoc-save-btn';
          saveBtn.style.marginTop = '12px';
          saveBtn.textContent = t('library.assoc.save');
          saveBtn.addEventListener('click', () => {
            const mainRoute = routes.find(r => r.role === 'main');
            if (!mainRoute || !mainRoute.scriptPath) return;
            close({ mode: 'custom', routes: routes.filter(r => r.scriptPath) });
          });
          customPanel.appendChild(saveBtn);
        };

        renderCustomRoutes();
        body.appendChild(customPanel);

        // --- Radio toggle ---
        radioSingle.addEventListener('change', () => {
          singlePanel.hidden = false;
          multiPanel.hidden = true;
          customPanel.hidden = true;
        });
        radioMulti.addEventListener('change', () => {
          singlePanel.hidden = true;
          multiPanel.hidden = false;
          customPanel.hidden = true;
        });
        radioCustom.addEventListener('change', () => {
          singlePanel.hidden = true;
          multiPanel.hidden = true;
          customPanel.hidden = false;
        });
      },
    });

    if (!chosen) return;

    // No "Switching will replace it" confirm — the three configs now live
    // in parallel slots, so switching active modes is lossless. The
    // previously-active config stays saved under its own slot and is one
    // radio-click away.

    if (chosen.mode === 'single') {
      this._applyAssociation(video, cardEl, chosen.path, chosen.name);
    } else if (chosen.mode === 'multi') {
      const hasAny = !!chosen.main || Object.values(chosen.axes || {}).some(Boolean);
      if (!hasAny) return;
      this._applyMultiAxisAssociation(video, cardEl, chosen);
    } else if (chosen.mode === 'custom') {
      this._applyCustomRoutingAssociation(video, cardEl, chosen.routes);
    } else if (chosen.mode === 'addVariant') {
      await this._addVariantWithNaming(video.path, chosen.path, chosen.name);
    } else if (chosen.mode === 'eroSearchFlow') {
      await this._eroScriptsSearchFlow(video, cardEl);
      // Reopen so the new association is visible where it was requested —
      // same courtesy as the variant flow below.
      const again = this._associateFunscript(video, cardEl, opts);
      if (opts.chain) await again;
      return;
    } else if (chosen.mode === 'addVariantFlow') {
      // Full flow: fuzzy search → naming → reopen association modal.
      // Browse... takes several files, named in one step (N-04).
      const picked = await this._showVariantSearchModal(video, { multiple: true });
      if (picked) {
        await this._addVariantsWithNaming(video, picked);
      }
      // Reopen the association modal so the user can continue
      const again = this._associateFunscript(video, cardEl, opts);
      if (opts.chain) await again;
      return;
    }
  }

  /**
   * The EroScripts search for one video (the Associate dialog's row, and the
   * video options dialog's Find on EroScripts…): what it downloads becomes the
   * video's pairing, as before.
   */
  async _eroScriptsSearchFlow(video, cardEl) {
    if (video?._stream) return;
    const { showEroScriptsSearchModal } = await import('./eroscripts-inline-search.js');
    // The app's editor hooks (R4-07), like the EroScripts panel's
    // `confirmBeforeDownload` / `onScriptDownloaded`: the editor's
    // unsaved-changes question before a file it holds (or this video's
    // script, when it is the open video) is written, and the load of what
    // was written afterwards. Unset (no app), the search asks nothing more.
    const picked = await showEroScriptsSearchModal(video, {
      confirmBeforeWrite: (savePaths) => (typeof this.confirmBeforeEroDownload === 'function'
        ? this.confirmBeforeEroDownload(video.path, savePaths)
        : true),
    });
    // The files were written after the last library scan, so the modal's
    // dropdowns would have no option matching them and would reopen blank.
    if (picked) {
      const fresh = picked.mode === 'multi'
        ? [picked.main, ...Object.values(picked.axes || {})]
        : [picked.path];
      this.registerFunscripts(
        fresh.filter(Boolean).map((path) => ({ path, name: path.split(/[\\/]/).pop() })),
      );
    }
    if (picked?.mode === 'single') {
      this._applyAssociation(video, cardEl, picked.path, picked.name);
    } else if (picked?.mode === 'multi') {
      this._applyMultiAxisAssociation(video, cardEl, picked);
    }
    if (picked?.topic) {
      // The record names the main script saved, with the topic JSON's tags (RB-2).
      const { recordDownloadTags } = await import('../js/script-tags.js');
      recordDownloadTags(this._settings, video.path, {
        topic: picked.topic, answer: picked.topicAnswer, scriptPath: picked.mode === 'multi' ? picked.main : picked.path,
      });
    }
    // The open video's script, or a file the editor holds, was just
    // replaced: the engine and the editor load the new file (R4-07).
    if (picked && typeof this.onEroDownloadWritten === 'function') {
      try {
        await this.onEroDownloadWritten(video.path, {
          mainPath: picked.mode === 'multi' ? picked.main : picked.path,
          written: picked.written || [],
        });
      } catch (err) {
        console.warn('[EroInline] loading the download failed:', err?.message || err);
      }
    }
  }

  _applyCustomRoutingAssociation(video, cardEl, routes) {
    const associations = this._settings.get('library.associations') || {};
    const entry = normalizeAssociation(associations[video.path]);
    associations[video.path] = buildAssociationEntry(
      'custom',
      // Preserve any auto-paired funscript into the single slot so
      // round-tripping custom → single doesn't strand the user with a
      // blank pane and no fuzzy-search hit on the original script.
      entry.single || video.funscriptPath || null,
      entry.multi,
      { routes },
    );
    this._settings.set('library.associations', associations);

    this._syncVideoStateForActive(video, 'custom', { routes });
    this._tearDownLiveRoutingIfEditing(video);
    this._applyFilters();
  }

  /**
   * Show fuzzy-ranked funscript search modal for adding a variation.
   * Returns { path, name } or null if cancelled; with `multiple` (the
   * variation flow, N-04) Browse... can answer a list of them. A route's
   * script picker (Custom Routing) asks for one.
   */
  async _showVariantSearchModal(video, { title, multiple = false } = {}) {
    const allScripts = this._allFunscripts || [];
    const ranked = allScripts.length > 0 ? rankFunscriptMatches(video.name, allScripts, 0) : [];

    return Modal.open({
      title: title || t('library.assoc.variantSearchTitle'),
      onRender: (body, close) => {
        if (ranked.length > 0) {
          const list = document.createElement('div');
          list.className = 'modal-list';

          for (const match of ranked.slice(0, 30)) {
            const row = document.createElement('button');
            row.className = 'modal-list-item';

            const label = document.createElement('span');
            label.className = 'modal-list-item-label';
            label.textContent = match.name;
            row.appendChild(label);

            if (match.score > 0) {
              const badge = document.createElement('span');
              const scoreClass = match.score >= 70 ? '--high' : match.score >= 40 ? '--medium' : '--low';
              badge.className = `library__match-score library__match-score${scoreClass}`;
              badge.textContent = `${match.score}%`;
              row.appendChild(badge);
            }

            row.addEventListener('click', () => close({ path: match.path, name: match.name }));
            list.appendChild(row);
          }
          body.appendChild(list);
        }

        const divider = document.createElement('div');
        divider.className = 'library__suggestion-divider';
        body.appendChild(divider);

        const browseRow = document.createElement('button');
        browseRow.className = 'modal-list-item library__assoc-action';
        browseRow.textContent = t('library.assoc.browse');
        browseRow.addEventListener('click', async () => {
          const result = await window.funsync.selectFunscript(multiple ? { multiple: true } : undefined);
          if (result) close(result);
        });
        body.appendChild(browseRow);
      },
    });
  }

  /**
   * The Associate dialog's + Add Variation with what its picker answered:
   * one file or several (N-04). One: the one-file naming dialog, as before.
   * Several: one naming step for all (variant-bulk-add.js). A file the
   * video's variation list already holds (its script, the scan's variants,
   * its manual ones), or picked twice, is skipped and said so. Only
   * `library.manualVariants` is written, appended to.
   */
  async _addVariantsWithNaming(video, picked) {
    if (!video?.path) return;
    const manual = (this._settings.get('library.manualVariants') || {})[video.path] || [];
    const listed = [
      ...(video.funscriptPath ? [{ path: video.funscriptPath, label: '' }] : []),
      ...(video.variants || []),
      ...manual,
    ];
    const plan = planVariantAdds(pickedFiles(picked), {
      listedPaths: listed.map((v) => v.path),
      listedLabels: listed.map((v) => v.label),
    });
    if (plan.add.length === 0) {
      if (plan.skipped.length > 0) {
        const { showToast } = await import('../js/toast.js');
        showToast(t('variants.alreadyListed', {
          count: plan.skipped.length,
          names: plan.skipped.map((s) => s.name).join(', '),
        }), 'info', 4000);
      }
      return;
    }
    if (plan.add.length === 1 && plan.skipped.length === 0) {
      await this._addVariantWithNaming(video.path, plan.add[0].path, plan.add[0].name);
      return;
    }
    const named = await showBulkVariantNaming(plan);
    if (!named?.length) return;
    const all = this._settings.get('library.manualVariants') || {};
    all[video.path] = [...(all[video.path] || []), ...named];
    this._settings.set('library.manualVariants', all);
    const { showToast } = await import('../js/toast.js');
    showToast(t('variants.bulkAdded', { count: named.length }), 'success', 2500);
  }

  /**
   * Show naming modal for a variant, then save it.
   * Reuses the same flow as the player's "Add variation" naming modal.
   */
  async _addVariantWithNaming(videoPath, fsPath, fsName) {
    const nameNoExt = fsName.replace(/\.funscript$/i, '');
    const parenMatches = [...nameNoExt.matchAll(/\(([^)]+)\)/g)].map(m => m[1].trim());
    const dotParts = nameNoExt.split('.');
    const dotSuffix = dotParts.length > 1 ? dotParts[dotParts.length - 1].trim() : null;

    const suggestions = [];
    const seen = new Set();
    for (const s of parenMatches) {
      const lower = s.toLowerCase();
      if (!seen.has(lower)) { seen.add(lower); suggestions.push(s); }
    }
    if (dotSuffix && !seen.has(dotSuffix.toLowerCase())) suggestions.push(dotSuffix);
    if (!seen.has(nameNoExt.toLowerCase())) suggestions.push(nameNoExt);

    const label = await Modal.open({
      title: t('library.variantNamingTitle'),
      onRender: (body, close) => {
        const hint = document.createElement('div');
        hint.className = 'library__collection-count';
        hint.style.marginBottom = '10px';
        hint.textContent = fsName;
        body.appendChild(hint);

        if (suggestions.length > 0) {
          const sugLabel = document.createElement('div');
          sugLabel.className = 'library__collection-count';
          sugLabel.style.marginBottom = '6px';
          sugLabel.textContent = t('library.variantSuggestionsLabel');
          body.appendChild(sugLabel);

          const sugList = document.createElement('div');
          sugList.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px';
          for (const sug of suggestions) {
            const btn = document.createElement('button');
            btn.className = 'library__assoc-save-btn';
            btn.style.cssText = 'padding:6px 14px;font-size:13px';
            btn.textContent = sug;
            btn.addEventListener('click', () => close(sug));
            sugList.appendChild(btn);
          }
          body.appendChild(sugList);
        }

        const divider = document.createElement('div');
        divider.className = 'nav-bar__library-divider';
        divider.style.margin = '8px 0';
        body.appendChild(divider);

        const customLabel = document.createElement('div');
        customLabel.className = 'library__collection-count';
        customLabel.style.marginBottom = '6px';
        customLabel.textContent = t('library.variantCustomLabel');
        body.appendChild(customLabel);

        const input = document.createElement('input');
        input.type = 'text';
        input.className = 'modal-input';
        input.placeholder = t('library.variantPlaceholder');
        input.style.marginBottom = '12px';
        body.appendChild(input);

        const confirmBtn = document.createElement('button');
        confirmBtn.className = 'library__assoc-save-btn';
        confirmBtn.style.cssText = 'display:block;width:66%;margin:0 auto';
        confirmBtn.textContent = t('library.variantConfirm');
        confirmBtn.addEventListener('click', () => { const v = input.value.trim(); if (v) close(v); });
        body.appendChild(confirmBtn);

        input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { const v = input.value.trim(); if (v) close(v); } });
        input.focus();
      },
    });

    if (!label) return;

    const manualVariants = this._settings.get('library.manualVariants') || {};
    if (!manualVariants[videoPath]) manualVariants[videoPath] = [];
    // Never the name of an entry already listed (the scan's or a hand-added
    // one): pins, the phone and the pop-out pick a variation by its label.
    const taken = [...(this._videosByPath?.get?.(videoPath)?.variants || []), ...manualVariants[videoPath]].map((v) => v?.label);
    manualVariants[videoPath].push({ label: uniqueVariantLabel(label, taken), path: fsPath, name: fsName });
    this._settings.set('library.manualVariants', manualVariants);
  }

  _createAxisDropdown(label, key, allScripts, preValue, videoName) {
    const row = document.createElement('div');
    row.className = 'library__assoc-axis-row';

    const lbl = document.createElement('label');
    lbl.className = 'library__assoc-axis-label';
    lbl.textContent = label;
    row.appendChild(lbl);

    const wrapper = document.createElement('div');
    wrapper.className = 'library__searchable-select';

    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'library__searchable-select-input';
    input.placeholder = key === 'main' ? t('library.searchableMainPlaceholder') : t('library.searchableAxisPlaceholder');

    // Hidden value holder
    const valueHolder = { value: '' };

    // Pre-fill
    if (preValue) {
      const match = allScripts.find(s => s.path === preValue || s.name === preValue);
      if (match) {
        input.value = match.name;
        valueHolder.value = match.path;
      }
    }

    const dropdown = document.createElement('div');
    dropdown.className = 'library__searchable-select-dropdown';
    dropdown.hidden = true;

    // Rank scripts by fuzzy match to video name for initial ordering
    const ranked = videoName
      ? rankFunscriptMatches(videoName, allScripts, 0)
      : allScripts.map(s => ({ name: s.name, path: s.path, score: 0 }));

    // Normalize the same way fuzzy-match does so the filter treats
    // dashes / underscores / dots as word separators. Without this,
    // a query like "movie title" wouldn't match a funscript named
    // "movie-title.funscript" because the literal substring isn't
    // present. Also handles the reverse (user types "movie-title"
    // looking for "movie title"). Mirrors `normalize()` in
    // renderer/js/fuzzy-match.js without the extension strip — we
    // want the .funscript suffix to be queryable too.
    const normalizeForFilter = (s) =>
      String(s).toLowerCase().replace(/[_.\-]/g, ' ').replace(/\s+/g, ' ').trim();

    const renderOptions = (filter) => {
      dropdown.innerHTML = '';
      const query = normalizeForFilter(filter || '');

      let items = ranked;
      if (query) {
        items = ranked.filter(s => normalizeForFilter(s.name).includes(query));
      }

      if (items.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'library__searchable-select-empty';
        empty.textContent = t('collectionModal.noMatches');
        dropdown.appendChild(empty);
        return;
      }

      for (const item of items.slice(0, 30)) { // cap at 30 visible
        const opt = document.createElement('button');
        opt.className = 'library__searchable-select-option';
        opt.textContent = item.name;
        if (item.path === valueHolder.value) opt.classList.add('library__searchable-select-option--active');
        opt.addEventListener('mousedown', (e) => {
          e.preventDefault(); // prevent input blur
          input.value = item.name;
          valueHolder.value = item.path;
          dropdown.hidden = true;
        });
        dropdown.appendChild(opt);
      }

      // Clear option
      const clearOpt = document.createElement('button');
      clearOpt.className = 'library__searchable-select-option library__searchable-select-clear';
      clearOpt.textContent = key === 'main' ? t('library.searchableClear') : t('library.searchableNone');
      clearOpt.addEventListener('mousedown', (e) => {
        e.preventDefault();
        input.value = '';
        valueHolder.value = '';
        dropdown.hidden = true;
      });
      dropdown.appendChild(clearOpt);
    };

    input.addEventListener('focus', () => {
      renderOptions(input.value);
      dropdown.hidden = false;
    });

    input.addEventListener('input', () => {
      renderOptions(input.value);
      dropdown.hidden = false;
    });

    input.addEventListener('blur', () => {
      // Delay to allow mousedown on option to fire first
      setTimeout(() => { dropdown.hidden = true; }, 150);
    });

    wrapper.appendChild(input);
    wrapper.appendChild(dropdown);
    row.appendChild(wrapper);

    // Expose a select-like interface for the save button
    const select = { get value() { return valueHolder.value; } };
    return { row, select, key };
  }

  _findScriptByName(allScripts, filename) {
    const f = allScripts.find(s => s.name === filename || s.path.endsWith(filename));
    return f ? f.path : '';
  }

  _applyMultiAxisAssociation(video, cardEl, config) {
    const multi = {
      main: config.main,
      axes: config.axes,
      buttplugVib: config.buttplugVib,
    };
    const associations = this._settings.get('library.associations') || {};
    const entry = normalizeAssociation(associations[video.path]);
    associations[video.path] = buildAssociationEntry(
      'multi',
      // Preserve any auto-paired funscript into the single slot so
      // round-tripping multi → single doesn't strand the user with a
      // blank pane and no fuzzy-search hit on the original script.
      entry.single || video.funscriptPath || null,
      multi,
      entry.custom,
    );
    this._settings.set('library.associations', associations);

    this._syncVideoStateForActive(video, 'multi', multi);
    this._tearDownLiveRoutingIfEditing(video);

    // Re-render to update badges in both grid and list views
    this._applyFilters();

    // Compute speed stats for main script (async, updates card when done)
    if (config.main) {
      this._loadSpeedStatsForVideo(video, null);
    }
  }

  async _applyAssociation(video, cardEl, fsPath, fsName) {
    // Save in settings — preserve other slots, just flip active + single.
    const associations = this._settings.get('library.associations') || {};
    const entry = normalizeAssociation(associations[video.path]);
    associations[video.path] = buildAssociationEntry(
      'single',
      fsPath,
      entry.multi,
      entry.custom,
    );
    this._settings.set('library.associations', associations);

    // Update video object — critically, clear any previous multi-axis or
    // custom-routing state. Without this, switching from custom → single
    // looks right in the modal but `_playFromLibrary` reads `video._customRouting`
    // from the video object and attaches it to funscriptData, so custom
    // routing still engages on playback. Worse, playback's self-heal path
    // can write routing back to settings, clobbering the single-axis slot.
    this._syncVideoStateForActive(video, 'single', fsPath);
    this._tearDownLiveRoutingIfEditing(video);

    // Remove from unmatched list
    this._unmatchedFunscripts = this._unmatchedFunscripts.filter((fs) => fs.path !== fsPath);

    // Update funscript badge on card — list view uses a different class,
    // so fall back. Without this, list-view kebab → Associate Funscript
    // threw a null-deref at `badge = thumbnailContainer.querySelector(...)`
    // (setting was saved, but the throw ate the speed-stats computation).
    const thumbnailContainer = cardEl.querySelector('.library__card-thumbnail')
      || cardEl.querySelector('.library__list-thumb');
    if (thumbnailContainer) {
      let badge = thumbnailContainer.querySelector('.library__funscript-badge');
      if (!badge) {
        badge = document.createElement('span');
        // Append into the shared bottom-left badges container so the
        // funscript + subtitle layout stays consistent (was appended
        // directly to the thumbnail; with the flex-container layout
        // that puts the badge outside the layout flow).
        this._getOrCreateBadgesContainer(thumbnailContainer).appendChild(badge);
      }
      badge.className = 'library__funscript-badge library__funscript-badge--manual';
      badge.title = t('library.funscriptManual');
      if (!badge.querySelector('svg')) {
        badge.appendChild(icon(FileCheck, { width: 14, height: 14, 'stroke-width': 2.5 }));
      }
    }

    // Compute and show speed badge
    try {
      const content = await window.funsync.readFunscript(fsPath);
      if (content) {
        const parsed = JSON.parse(content);
        const actions = parsed?.actions;
        if (actions && actions.length >= 2) {
          const stats = computeSpeedStats(actions);
          video.avgSpeed = stats.avgSpeed;
          video.maxSpeed = stats.maxSpeed;
          const info = cardEl.querySelector('.library__card-info');
          if (info) this._addSpeedBadge(info, stats);
        }
      }
    } catch { /* ignore */ }

    // Re-apply filters (video now has funscript so it should move between tabs)
    this._applyFilters();
  }

  _switchTab(tab) {
    if (this._activeTab === tab) return;
    const crossesScripts = (tab === 'scripts') !== (this._activeTab === 'scripts');
    this._activeTab = tab;
    if (crossesScripts && this._selectMode) this._exitSelectMode();

    // Sync the radio in the Filters picker (if currently rendered) so
    // re-opening the dropdown reflects the new state. Defensive: the
    // picker may not exist in early lifecycle paths.
    const radio = this._container?.querySelector(
      `#library-filters-pop input[name="library-filter-tab"][value="${tab}"]`,
    );
    if (radio) radio.checked = true;

    this._syncSortForActiveTab({ reset: true });
    this._renderFilterChips();
    this._updateFiltersBadge();
    this._applyFilters();
  }

  /** Enable/disable speed sort options for the active tab, and drop the
   * current sort only if it cannot survive the new one. Unmatched videos have
   * no script → no speed stats, so speed sorts are meaningless there. */
  _syncSortForActiveTab({ reset = false } = {}) {
    const pop = this._container?.querySelector('#library-sort-pop');
    if (!pop) return;
    // Reset the sort only when the CURRENT one is invalid for the tab we're
    // moving to. It used to reset on every switch, which threw away a
    // perfectly valid Duration or Recently Added sort on a flick to Unmatched
    // and back — and dropped the user on A-Z with the picker still showing
    // their choice (Dave, 2026-08-20).
    const [curField] = this._sortParts();
    const curIsSpeed = !!Library._SORT_OPTIONS.find((o) => o.value === curField)?.isSpeed;
    const stashOn = this._stashOn();
    // A Stash sort cannot survive Stash being off, on any tab (Stash "next"
    // lot): back to Name A-Z, through the same redraw.
    if ((reset && curIsSpeed && this._activeTab === 'unmatched') || (Library._isStashSort(curField) && !stashOn)) {
      this._sortKey = 'name:asc';
      this._ensureSortDirs().name = 'asc';
      // Through the picker's own redraw, so the rows, arrows, checked state
      // and trigger label can't disagree with `_sortKey`.
      this._refreshSortPicker?.();
    }
    // Stash's rows exist only while Stash is on.
    if (this._syncStashSortRows?.()) this._refreshSortPicker?.();
    // Disable speed-sort options when the user has filtered to the
    // unmatched tab (those videos have no funscripts → no speed stats).
    pop.querySelectorAll('.library__picker-item').forEach((item) => {
      const radio = item.querySelector('input[type="radio"]');
      if (!radio) return;
      const isSpeed = item.dataset.isSpeed === 'true';
      const disabled = (this._activeTab === 'unmatched' && isSpeed)
        || (this._activeTab === 'scripts' && radio.value !== 'name');
      radio.disabled = disabled;
      item.classList.toggle('library__picker-item--disabled', disabled);
    });
  }

  /**
   * Reset every active filter (search query, tab, VR filter) and
   * re-render. Wired to the "Clear filters" CTA in the no-results
   * empty-state — single click rescues the user from a filtered-into-
   * the-corner view (Shneiderman #6 reversibility).
   *
   * Updates THREE surfaces: the chip strip (`_renderFilterChips`), the
   * Filters-trigger badge counter (`_updateFiltersBadge`), AND the
   * picker popover's radio buttons (which are built once at
   * `_buildFiltersPicker` time and don't auto-sync to state changes).
   * Without the radio sync, opening the picker after Clear-filters
   * showed the chips gone but the radios still ticked at the old
   * values — visible-state vs actual-state divergence.
   */
  _clearAllFilters() {
    this._searchQuery = '';
    this._activeTab = 'all';
    this._vrFilter = 'all';
    this._mediaFilter = 'all';
    this._searchGlobalOverride = false;
    // The Tags filter too (its ticks follow in _syncTagPickerChecks below).
    this._tagFilter = { ...emptyTagFilter(), labels: new Map() };
    this._tagFindText = '';
    const tagFind = this._container?.querySelector('#library-filters-pop .library__tag-find');
    if (tagFind) tagFind.value = '';
    this._syncTagPickerChecks?.();
    // The Stash filter too (its picker rows follow).
    this._stashFilter = emptyStashFilter();
    this._syncStashPickerSection?.();
    // Sync the search input + clear button if the panel is rendered
    const searchInput = this._container?.querySelector('.library__search-input');
    if (searchInput) searchInput.value = '';
    const searchClear = this._container?.querySelector('.library__search-clear');
    if (searchClear) searchClear.hidden = true;
    // Sync the filters-picker radios to the cleared state.
    const pop = this._container?.querySelector('#library-filters-pop');
    if (pop) {
      const tabRadio = pop.querySelector('input[name="library-filter-tab"][value="all"]');
      if (tabRadio) tabRadio.checked = true;
      const vrRadio = pop.querySelector('input[name="library-filter-vr"][value="all"]');
      if (vrRadio) vrRadio.checked = true;
    }
    // Back on 'all', so speed sorts are meaningful again — without this the
    // rows stayed disabled after clearing filters from the Unmatched tab.
    this._syncSortForActiveTab();
    this._applyFilters();
    this._renderFilterChips?.();
    this._updateFiltersBadge?.();
  }

  _applyFilters() {
    // A pass that reads the tag index as it is now (see _onTagDataChanged).
    this._filterPass = (this._filterPass || 0) + 1;
    // When a collection becomes active (or changes) while folder view is on,
    // auto-navigate to the collection's common-ancestor folder so the user
    // lands INSIDE the folder they pinned — not one level above with a single
    // folder card to click through. Guarded by `_folderCollectionId` so
    // navigation within the same collection (breadcrumb clicks, drilling into
    // subfolders) isn't clobbered by subsequent `_applyFilters` calls.
    if (this._folderBrowse && this._activeCollectionId !== this._folderCollectionId) {
      this._folderCollectionId = this._activeCollectionId;
      if (this._activeCollectionId && this._folderIndex) {
        const collections = this._settings.get('library.collections') || [];
        const col = collections.find(c => c.id === this._activeCollectionId);
        const sources = this._settings.get('library.sources') || [];
        // Prefer the sync folder directly for synced collections.
        const syncFolder = col?.syncSource?.folderPath
          || (col?.syncSource?.sourceId
                ? sources.find(s => s.id === col.syncSource.sourceId)?.path
                : null);
        if (syncFolder) {
          const canonical = canonicalPath(syncFolder);
          this._currentFolderPath = this._folderIndex.has(canonical) ? canonical : null;
        } else if (col?.videoPaths?.length) {
          const ancestor = commonAncestorOfFiles(col.videoPaths);
          if (ancestor && this._folderIndex.has(ancestor)) {
            this._currentFolderPath = ancestor;
          } else {
            this._currentFolderPath = null;
          }
        } else {
          this._currentFolderPath = null;
        }
      } else {
        // Switched back to "All Sources" from a collection — return to root.
        this._currentFolderPath = null;
      }
      this._renderBreadcrumb();
    }

    // The Tags filter and the cards' tag line read the one tag index; it is
    // only built (or checked) when one of them is on.
    const tagState = this._tagFilterState();
    this._pruneTagFilter(tagState);
    const tagActive = tagFilterActive(tagState);
    const tagsOnCards = this._showTagsOnCards();
    const tagResult = (tagActive || tagsOnCards) ? this._tagIndexMemo().get() : null;
    this._cardTagIndex = tagsOnCards ? tagResult.index : null;
    const categoriesOf = (p) => (typeof this._settings.getVideoCategories === 'function'
      ? this._settings.getVideoCategories(p) || [] : []);
    // Stash's filter (only while Stash is on): its fields are read once.
    const stashState = this._stashFilterState();
    const stashFilterOn = this._stashFilterOn();
    const stashIndex = stashFilterOn ? this._stashFieldsIndex() : null;

    // Core filter pipeline, reusable per-subtree in folder-browse mode.
    const runFilters = (inputVideos) => {
      let out = inputVideos;
      if (this._activeCollectionId) {
        const collections = this._settings.get('library.collections') || [];
        const col = collections.find(c => c.id === this._activeCollectionId);
        if (col) {
          // Synced collections (syncSource set) expand membership live
          // from the folder index — new videos in the sync folder
          // auto-appear without requiring Edit→Select All→Save. Legacy
          // collections fall through to the frozen videoPaths snapshot
          // (the helper short-circuits when syncSource is unset).
          const sources = this._settings.get('library.sources') || [];
          const pathSet = expandSyncedMembership(col, sources, this._folderIndex, descendantsOf);
          out = out.filter(v => pathSet.has(v.path));
        } else {
          this._activeCollectionId = null;
        }
      }
      if (this._activeTab === 'matched') out = out.filter(v => v.hasFunscript);
      else if (this._activeTab === 'unmatched') out = out.filter(v => !v.hasFunscript);
      const vrOf = (v) => isVRVideo(v._stream ? { ...v, path: v.name } : v);
      if (this._vrFilter === 'vr') out = out.filter(vrOf);
      else if (this._vrFilter === 'flat') out = out.filter(v => !vrOf(v));
      if (this._mediaFilter === 'streams') out = out.filter((v) => v._stream);
      else if (this._mediaFilter === 'local') out = out.filter((v) => !v._stream);
      // Stash: before the duplicate-name collapse too (a link is per path).
      if (stashFilterOn) out = applyStashFilter(out, stashState, stashIndex);
      // Tags, Category, "Tags from": BEFORE the duplicate-name collapse
      // below (design (e)): tags are stored per path, so the copy dedupe
      // would drop may be the one that has them. Search never matches tags
      // (Dave's answer 4): nothing of the index goes into its contextMap.
      if (tagActive) out = applyTagFilter(out, tagState, { index: tagResult.index, categoriesOf });
      if (this._searchQuery) {
        out = fuzzySearch(out, this._searchQuery, {
          searchPaths: true,
          // Path hits count from each source folder down, never the folders
          // above it (app test V35). The web remote passes the same.
          pathRoots: (this._settings.get('library.sources') || []).map(s => s?.path),
          contextMap: this._buildSearchContextMap(),
        });
      }
      // Last step on purpose: it collapses exactly what would otherwise be
      // shown, so it applies to search results too, and after fuzzySearch
      // it keeps the best-RANKED copy rather than an arbitrary one.
      if (this._settings.get('library.hideDuplicateNames') === true) {
        out = dedupeByName(out);
      }
      return out;
    };

    // Read the sort key from the dropdown directly so the visible
    // selection is always the source of truth — if anything in the
    // codebase ever stomps `_sortKey` without also updating the
    // picker, the visual UX still matches what the user sees
    // selected. Falls back to `_sortKey` (and ultimately 'name:asc')
    // when the picker isn't in the DOM yet (early renders). Updated
    // 2026-04-27: now reads the checked radio in the new sort
    // popover instead of a `<select>`'s value.
    const [sortField, sortDir] = this._effectiveSort();
    // Keep `_sortKey` in sync so the next show()/_renderWithHeader pass
    // restores the right value when it (re)builds the picker.
    this._sortKey = `${sortField}:${sortDir}`;
    // Stash's sorts read Stash's fields (none while Stash is off: then the
    // field was put back to Name by _effectiveSort).
    const sortOptions = Library._isStashSort(sortField) ? { stash: this._stashFieldsIndex() } : {};
    const countEl = this._container.querySelector('.library__video-count');

    // Keep the search-scope + folder-scope pills in sync with current state.
    this._updateSearchScope();
    this._updateFolderScope();
    this._updateRelevanceHint();

    // --- Flat view ---
    // Also taken when folder view is on but the user escaped search scope via
    // the "Search everywhere" pill — render a flat matching list until they
    // clear the query or flip the pill back.
    // Scripts (2026-11-26): the scripts no video uses, flat (no folders), by
    // name; the search finds them by name and path. Collections, VR, streams,
    // Stash and tags are about videos and do not apply.
    if (this._activeTab === 'scripts') {
      const all = this._scriptsScope === 'all' ? this._allScriptItems() : this._scriptItems();
      let shown = all;
      if (this._searchQuery) {
        shown = fuzzySearch(all, this._searchQuery, {
          searchPaths: true,
          pathRoots: (this._settings.get('library.sources') || []).map(s => s?.path),
        });
      } else {
        shown = sortVideos(all, 'name', sortField === 'name' ? (sortDir || 'asc') : 'asc');
      }
      if (countEl) {
        countEl.textContent = this._searchQuery
          ? t('library.scriptCountFiltered', { filtered: shown.length, total: all.length })
          : t('library.scriptCount', { count: shown.length });
      }
      this._renderGrid(shown);
      return;
    }

    const scopeEscaped = this._folderBrowse && this._searchGlobalOverride && !!this._searchQuery;
    if (!this._folderBrowse || scopeEscaped) {
      // When the user toggles folder→flat from inside a sub-folder, scope the
      // flat list to descendants of that folder (mental model: "I'm browsing
      // sub2, flip to flat, show only sub2 videos"). Falls back to the full
      // library when _currentFolderPath is null (i.e. they were at the folder
      // root, or never opened folder browse). _updateFolderScope renders a
      // dismissable "Showing: <folder> ✕" pill so the user can see and clear
      // the scope (Norman: visibility of cause-of-state).
      const scoped = this._getFlatScopeVideos();
      let filtered = runFilters(scoped);
      // When searching, fuzzySearch returns results already ranked by
      // relevance — re-running sortVideos (name/duration/etc.) would throw
      // that ranking away and the exact-title match could sink below
      // alphabetically-earlier partial matches.
      if (!this._searchQuery) {
        filtered = sortVideos(filtered, sortField, sortDir || 'asc', sortOptions);
      }
      // Denominator for the search-count display reflects the scoped pool,
      // not the global library — otherwise "5 / 800" is misleading when the
      // user only intended to search within sub2.
      const totalForCount = scoped.length;
      if (countEl) {
        countEl.textContent = this._searchQuery
          ? t('library.videoCountFiltered', { filtered: filtered.length, total: totalForCount })
          : t('library.videoCount', { count: filtered.length });
      }
      this._renderGrid(filtered);
      return;
    }

    // --- Folder-browse view ---
    const index = this._folderIndex;
    if (!index) { this._renderGrid([]); return; }

    const items = [];
    let totalVideos = 0;

    if (this._currentFolderPath === null) {
      // Root — list enabled sources with non-zero filtered descendants
      const sources = this._settings.get('library.sources') || [];
      const folderEntries = [];
      for (const src of sources) {
        if (src.enabled === false) continue;
        const canonical = canonicalPath(src.path);
        const node = index.get(canonical);
        if (!node) continue;
        const filtered = runFilters(descendantsOf(index, canonical));
        if (filtered.length === 0) continue;
        folderEntries.push({ isFolder: true, node, count: filtered.length });
        totalVideos += filtered.length;
      }
      folderEntries.sort((a, b) => compareNames(a.node.label, b.node.label));
      items.push(...folderEntries);
      // Saved streams have no folder: they follow the source folders here.
      // Folder view showed them nowhere (test day 2026-11-26, B099).
      const streams = runFilters(this._videos.filter((v) => isStreamPath(v.path)));
      const streamItems = this._searchQuery ? streams : sortVideos(streams, sortField, sortDir || 'asc', sortOptions);
      items.push(...streamItems);
      totalVideos += streamItems.length;
    } else {
      const node = index.get(this._currentFolderPath);
      if (node) {
        // Subfolders first, non-empty only, alphabetical
        const folderEntries = [];
        for (const childPath of node.childFolders) {
          const childNode = index.get(childPath);
          if (!childNode) continue;
          const filtered = runFilters(descendantsOf(index, childPath));
          if (filtered.length === 0) continue;
          folderEntries.push({ isFolder: true, node: childNode, count: filtered.length });
          totalVideos += filtered.length;
        }
        folderEntries.sort((a, b) => compareNames(a.node.label, b.node.label));

        // Then videos directly in this folder, filtered + sorted (but keep
        // fuzzy ranking intact when searching — see flat-view branch).
        const filteredDirect = runFilters(node.videos);
        const directVideos = this._searchQuery
          ? filteredDirect
          : sortVideos(filteredDirect, sortField, sortDir || 'asc', sortOptions);

        items.push(...folderEntries);
        items.push(...directVideos);
        totalVideos += directVideos.length;
      }
    }

    if (countEl) {
      const folderCount = items.filter(i => i.isFolder).length;
      // In the language chosen: it was English in every language (B099).
      if (this._searchQuery) {
        countEl.textContent = t('library.videoCountFiltered', { filtered: totalVideos, total: this._videos.length });
      } else if (folderCount > 0) {
        countEl.textContent = `${t('library.folderCount', { count: folderCount })} · ${t('library.videoCount', { count: totalVideos })}`;
      } else {
        countEl.textContent = t('library.videoCount', { count: totalVideos });
      }
    }

    this._renderGrid(items);
  }

  /**
   * The in-memory side of an Unpair, once `library.associations` is written:
   * the video options dialog's Unpair funscript, or its Remove of the
   * playing set you made (Multi Axis / Custom Routing over the video's own
   * script), whose plans may keep a set you saved in another slot (entry
   * left with `active: null`, nothing of it plays).
   * Either way the video plays its own script, or none, from here on.
   */
  _showUnpaired(video, cardEl = null) {
    // The script the scan paired by name, if any, is the video's again: the
    // next scan would pair it anyway (R4-06).
    this._rememberOwnScript(video);
    const own = video._ownFunscriptPath || null;
    video.hasFunscript = !!own;
    video.funscriptPath = own;
    video.variants = video._ownVariants;
    video._assocFallbackFrom = null;
    video._statsReadFor = null;
    // What the card knew from the REMOVED script is not this video's any more
    // (C-04): the rebuilt card kept its speed badge (`_addSpeedBadge` keeps a
    // badge it finds) until a grid / list toggle, and the re-register app.js
    // sends for this change would hand the backend that speed under the new
    // script. Unknown now: the card's read paints the video's own script,
    // and the backend probes it.
    video.avgSpeed = null;
    video.maxSpeed = null;
    video._heatmapBins = null;
    video._embeddedAxes = null;
    video._manualAssociation = false;
    video._autoAssigned = false;
    video._multiAxis = null;
    video._customRouting = null;

    this._tearDownLiveRoutingIfEditing(video);

    if (!own) {
      const card = (cardEl?.isConnected ? cardEl : null) || this._cardForPath(video.path);
      const badge = card?.querySelector('.library__funscript-badge');
      if (badge) badge.remove();
    }
    // Every caller re-filters here: a video left with no script leaves the
    // Matched view now. The kebab's Remove Funscript skipped this when the
    // video had no script of its own, so its card stayed under Matched until
    // something else re-rendered (FT-045). The phone and the headset get the
    // change from app.js's re-register on `library.associations`.
    this._applyFilters();
  }

  /**
   * Undo of an Unpair: the entry is back as it was (the model wrote it);
   * the pairing it plays goes back on the video through the same path a
   * Save in the Associate dialog takes, then the filters run again. The
   * speed badge is read again (the card's read and the poll).
   * @param {object} video
   * @param {{kind: string, config: *}|null} reapply the active config
   * @param {{fallbackFrom?: string|null}} [o] the script that could not be
   *   read when it was unpaired (`_assocFallbackFrom` then): the video played
   *   its own script meanwhile (R4-06), and does so again after the Undo,
   *   rather than point at the unreadable one until the next scan (review-a
   *   RA-8). In memory only, as `_fallBackToOwnScript` always is.
   */
  _showPairingRestored(video, reapply, { fallbackFrom = null } = {}) {
    if (!video) return;
    if (reapply) this._syncVideoStateForActive(video, reapply.kind, reapply.config);
    if (fallbackFrom && reapply?.kind === 'single'
      && canonicalPath(video.funscriptPath) === canonicalPath(fallbackFrom)) {
      this._fallBackToOwnScript(video);
    }
    video.avgSpeed = null;
    video.maxSpeed = null;
    video._heatmapBins = null;
    this._tearDownLiveRoutingIfEditing(video);
    this._applyFilters();
  }

  /**
   * Set the VR type of many videos at once (the multi-select toolbar).
   * `mode` is `'vr'`, `'flat'`, or `'reset'`. Writes once and re-renders
   * once at the end, regardless of how many paths are touched.
   */
  async _bulkSetVRType(paths, mode) {
    if (!Array.isArray(paths) || paths.length === 0) return;
    const map = { ...(this._settings.get('library.manualVRType') || {}) };
    let changed = 0;
    for (const p of paths) {
      if (!p) continue;
      if (mode === 'reset') {
        if (p in map) { delete map[p]; changed++; }
      } else if (mode === 'vr' || mode === 'flat') {
        if (map[p] !== mode) { map[p] = mode; changed++; }
      }
    }
    this._settings.set('library.manualVRType', map);
    this._applyFilters();

    const { showToast } = await import('../js/toast.js');
    if (mode === 'vr') showToast(t('library.bulkMarkedVR', { count: paths.length }), 'info', 2000);
    else if (mode === 'flat') showToast(t('library.bulkMarkedFlat', { count: paths.length }), 'info', 2000);
    else showToast(t('library.bulkVrReset', { count: changed }), 'info', 2000);
  }

  /**
   * Sync the video's in-memory funscript state (hasFunscript, funscriptPath,
   * _multiAxis, _customRouting) to reflect a given active mode. Clears the
   * slots that the new mode doesn't own so `_playFromLibrary` routes through
   * the correct path. Pass `config` for single=string, multi=object,
   * custom={routes}. Pass null for `active` to clear everything.
   */
  /** Lookup a scanned video record by its absolute path. Returns undefined if
   * the library hasn't scanned this path (e.g. source was removed). */
  getVideoByPath(videoPath) {
    if (!videoPath) return undefined;
    const video = this._videos.find(v => v.path === videoPath);
    if (video || !isScriptPath(videoPath)) return video;
    // A script (2026-11-26): a playlist entry, Next, Up Next. One no video
    // uses, or (the Scripts filter's All) one a video uses too.
    return this._scriptItems().find((s) => s.path === videoPath)
      || this._allScriptItems().find((s) => s.path === videoPath);
  }

  /**
   * The scripts no video uses (loose-scripts.js), as items for the Scripts
   * filter, cards and playlists. Rebuilt when the scan's lists change.
   */
  _scriptItems() {
    const unmatched = this._unmatchedFunscripts || [];
    const videos = this._videos || [];
    const memo = this._scriptItemsMemo;
    if (memo && memo.unmatched === unmatched && memo.videos === videos && memo.count === videos.length) return memo.items;
    const items = looseScripts(unmatched, videos).map(scriptItem);
    this._scriptItemsMemo = { unmatched, videos, count: videos.length, items };
    return items;
  }

  /**
   * Every script that plays on its own, each with the video that uses it, if
   * any (the Scripts filter's All). Rebuilt when the scan's lists change.
   */
  _allScriptItems() {
    const all = this._allFunscripts || [];
    const videos = this._videos || [];
    const memo = this._allScriptItemsMemo;
    if (memo && memo.all === all && memo.videos === videos && memo.count === videos.length) return memo.items;
    const items = allScripts(all, videos).map(scriptItem);
    this._allScriptItemsMemo = { all, videos, count: videos.length, items };
    return items;
  }

  /**
   * The Scripts filter's pills, at the right of the chips row (Dave,
   * 2026-11-26: "a pill group on the right hand side of the row shared by
   * the applied filter chips, to show unassigned by default and all as an
   * option which shows all scripts regardless of whether they have an
   * assigned video or not"). A radio group: arrows move and choose.
   */
  _scriptsScopePills() {
    const group = document.createElement('div');
    group.className = 'library__scripts-scope';
    group.setAttribute('role', 'radiogroup');
    group.setAttribute('aria-label', t('library.scripts.scopeAria'));
    const options = [['unassigned', t('library.scripts.scopeUnassigned')], ['all', t('library.scripts.scopeAll')]];
    const choose = (value, focus = false) => {
      if (this._scriptsScope !== value) {
        this._scriptsScope = value;
        if (this._selectMode) this._exitSelectMode();
        this._renderFilterChips();
        this._applyFilters();
      }
      if (focus) this._container?.querySelector(`.library__scripts-scope-btn[data-scope="${value}"]`)?.focus();
    };
    for (const [value, label] of options) {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'library__scripts-scope-btn';
      b.dataset.scope = value;
      b.textContent = label;
      const on = this._scriptsScope === value;
      b.classList.toggle('library__scripts-scope-btn--on', on);
      b.setAttribute('role', 'radio');
      b.setAttribute('aria-checked', on ? 'true' : 'false');
      b.tabIndex = on ? 0 : -1;
      b.addEventListener('click', () => choose(value));
      b.addEventListener('keydown', (e) => {
        if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
        e.preventDefault();
        const i = options.findIndex(([v]) => v === value);
        const step = e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 1;
        choose(options[(i + step + options.length) % options.length][0], true);
      });
      group.appendChild(b);
    }
    return group;
  }

  /**
   * A script's card or list row (the Scripts filter, 2026-11-26): the
   * no-picture tile marked as a script, its name, ⋮ for its menu. Click
   * plays it in the script player; select mode selects it (for Add to
   * playlist). No thumbnail, preview, heart or video options: it is not a video.
   */
  _createScriptEntry(item) {
    const list = this._viewMode === 'list';
    const el = document.createElement('div');
    el.className = list ? 'library__list-item library__list-item--script' : 'library__card library__card--script';
    if (this._selectedPaths.has(item.path)) el.classList.add('library__card--selected');
    el.dataset.videoPath = item.path;
    el.dataset.loaded = 'true';            // no picture to fetch
    const thumb = document.createElement('div');
    thumb.className = list ? 'library__list-thumb' : 'library__card-thumbnail';
    thumb.appendChild(buildNoVideoTile(item.name, { script: true, compact: list }));
    if (!list) {
      const overlay = document.createElement('div');
      overlay.className = 'library__card-overlay';
      const playIcon = document.createElement('span');
      playIcon.className = 'library__card-play-icon';
      playIcon.appendChild(icon(Play, { width: 36, height: 36 }));
      overlay.appendChild(playIcon);
      thumb.appendChild(overlay);
    }
    const kebab = document.createElement('button');
    kebab.type = 'button';
    kebab.className = list ? 'library__list-kebab' : 'library__kebab-btn';
    kebab.appendChild(icon(EllipsisVertical, { width: 16, height: 16 }));
    kebab.title = t('library.scripts.menuAria', { name: item.name });
    kebab.setAttribute('aria-label', t('library.scripts.menuAria', { name: item.name }));
    kebab.setAttribute('aria-haspopup', 'menu');
    kebab.addEventListener('click', (e) => {
      e.stopPropagation();
      const r = kebab.getBoundingClientRect();
      // Enter / Space on ⋮ (a click with detail 0): the focus goes into the menu (B096).
      this._showScriptMenu(item, r.left, r.bottom + 4, { fromKeyboard: e.detail === 0, opener: kebab });
    });
    const checkbox = document.createElement('div');
    checkbox.className = 'library__card-checkbox';
    checkbox.hidden = !this._selectMode;
    if (list) {
      el.appendChild(thumb);
      const title = document.createElement('div');
      title.className = 'library__list-title';
      title.textContent = item.name;
      title.title = item.path;
      el.appendChild(title);
      if (item.pairedWith) el.appendChild(this._scriptPairedLine(item, 'library__list-sub'));
      el.appendChild(kebab);
      el.appendChild(checkbox);
    } else {
      thumb.appendChild(checkbox);
      thumb.appendChild(kebab);
      el.appendChild(thumb);
      const info = document.createElement('div');
      info.className = 'library__card-info';
      const title = document.createElement('div');
      title.className = 'library__card-title';
      title.textContent = item.name;
      title.title = item.path;
      info.appendChild(title);
      if (item.pairedWith) info.appendChild(this._scriptPairedLine(item, 'library__card-sub'));
      el.appendChild(info);
    }
    el.addEventListener('click', (e) => {
      if (this._selectMode || e.shiftKey) this._handleSelectionClick(el, item.path, e);
      else this._playVideo(item);
    });
    this._applySelectionState(el, item.path);
    return el;
  }

  /** A script's menu (⋮ or right-click): Play, Add to playlist, Pair with a video, Show in folder, Delete. */
  _showScriptMenu(item, x, y, { fromKeyboard = false, opener = null } = {}) {
    this._showQueueContextMenu(x, y, item.path, [
      [t('library.scripts.play'), () => this._playVideo(item), 'play'],
      [t('library.addToPlaylist'), () => { this._addPathsToPlaylist([item.path]); }, 'playlist'],
      // A script a video uses (All) is that video's: it is not paired again
      // or deleted from here (deleting it would take the video's script).
      ...(this._onPairScript && !item.pairedWith ? [[t('library.scripts.pair'), () => this._onPairScript(item), 'pair']] : []),
      [t('library.scripts.showInFolder'), () => { window.funsync?.showInFolder?.(item.path); }, 'folder'],
      // Gone, its card goes: the delete rescans but does not redraw (T306).
      ...(item.pairedWith ? [] : [[t('library.scripts.delete'), () => {
        Promise.resolve(this.deleteLooseScript(item))
          .then((gone) => { if (gone && this._activeTab === 'scripts') this._applyFilters(); })
          .catch((err) => console.warn('[Scripts] delete failed:', err?.message || err));
      }, 'delete']]),
    ], { fromKeyboard, opener });
  }

  /** "With <video>": the video a script belongs to (the Scripts filter's All). */
  _scriptPairedLine(item, className) {
    const line = document.createElement('div');
    line.className = className;
    const video = String(item.pairedWith).replace(/\.[^/.]+$/, '');
    line.textContent = t('library.scripts.pairedWith', { video });
    line.title = line.textContent;
    return line;
  }

  /** Every funscript the last scan found, as `{name, path}`. Cached from
   *  `ensureScanned()` — callers must NOT re-run `scanDirectory` for this
   *  (a full recursive walk + stat pass that blocks the UI for seconds on a
   *  large library). */
  getAllFunscripts() {
    return this._allFunscripts || [];
  }

  /**
   * Add newly-created funscripts to the cached scan list.
   *
   * `_allFunscripts` is populated once when the library is scanned, and the
   * association modal builds its dropdowns from it — matching a saved value
   * with `allScripts.find(s => s.path === preValue)`. A file written AFTER
   * that scan (an EroScripts download, say) therefore has no matching
   * option, so the modal renders an empty field even though the association
   * saved correctly. Worse, saving from that empty state would overwrite the
   * good association with blanks.
   *
   * Cheaper and more predictable than re-running `scanDirectory`, which is a
   * full recursive walk. Idempotent — re-registering an existing path is a
   * no-op.
   *
   * @param {Array<{name: string, path: string}>} entries
   */
  registerFunscripts(entries) {
    if (!Array.isArray(entries) || entries.length === 0) return;
    if (!Array.isArray(this._allFunscripts)) this._allFunscripts = [];
    const seen = new Set(this._allFunscripts.map((f) => f.path));
    for (const entry of entries) {
      if (!entry?.path || seen.has(entry.path)) continue;
      seen.add(entry.path);
      this._allFunscripts.push({
        name: entry.name || entry.path.split(/[\\/]/).pop(),
        path: entry.path,
      });
    }
  }

  /** Absolute paths of every funscript the last scan found. Used to recover
   *  a configured script that moved (see app.js `_recoverOrgasmPaths`), where
   *  there is no video directory to search next to. */
  getAllFunscriptPaths() {
    return this.getAllFunscripts().map((f) => f.path).filter(Boolean);
  }

  /**
   * Persist a freshly-downloaded script as a single-axis association for the
   * given videoPath and refresh the in-memory library entry so the badge
   * shows up on return to the library view. Preserves any existing multi/
   * custom slots. Returns true if the video was found and updated.
   */
  associateDownloadedScript(videoPath, scriptPath) {
    if (!videoPath || !scriptPath) return false;
    if (isStreamPath(videoPath)) return this.setStreamScript(videoPath, scriptPath);
    const video = this._videos.find(v => v.path === videoPath);
    if (!video) return false;

    const associations = this._settings.get('library.associations') || {};
    const entry = normalizeAssociation(associations[videoPath]);
    associations[videoPath] = buildAssociationEntry(
      'single',
      scriptPath,
      entry.multi,
      entry.custom,
    );
    this._settings.set('library.associations', associations);

    this._syncVideoStateForActive(video, 'single', scriptPath);
    this._applyFilters();
    return true;
  }

  /**
   * Note, once per scanned video object, the script the SCAN paired with it
   * by name (its own `<video>.funscript`, or null) and the scan's variants,
   * before an association replaces them (R4-06). An association made this
   * session is never taken for the video's own script.
   */
  _rememberOwnScript(video) {
    if (!video || video._ownScriptKnown) return;
    video._ownScriptKnown = true;
    const byScan = video.hasFunscript && video.funscriptPath
      && (!video._manualAssociation || video._autoAssigned);
    video._ownFunscriptPath = byScan ? video.funscriptPath : null;
    video._ownVariants = Array.isArray(video.variants) ? video.variants : [];
  }

  /**
   * Point the in-memory video at a SINGLE association the user made (R4-06).
   * It wins over the scan's sidecar, which stays reachable: the variant list
   * leads with the associated script (index 0 is what a load plays, see
   * variant-select.js) and keeps every scanned variant, the sidecar
   * included, after it. Nothing is written.
   */
  _showUserSingle(video, scriptPath) {
    this._rememberOwnScript(video);
    video.hasFunscript = true;
    video.funscriptPath = scriptPath;
    video._manualAssociation = true;
    video._assocFallbackFrom = null;
    video.variants = this._variantsLeadingWith(video._ownVariants || [], scriptPath, video._ownFunscriptPath);
  }

  /**
   * A Multi Axis or Custom Routing pairing on a video that also has its own
   * `<video>.funscript`: the variant list leads with the script that PLAYS
   * (the set's main, the main route's script), as a single association's
   * does (R4-06 note, TODO triage 2026-11-23, also in v0.9.2). The scan's
   * list put the sidecar first, so the menu named it as playing and picking
   * it did nothing (index 0 is taken as already active). The sidecar stays
   * in the list, after it. No main script (axes only): the list as it is.
   */
  _leadVariantsWithPlayed(video, mainPath) {
    if (!video || !mainPath) return;
    this._rememberOwnScript(video);
    video.variants = this._variantsLeadingWith(video._ownVariants || [], mainPath, video._ownFunscriptPath);
  }

  /** `variants` with `scriptPath` first (its own entry, or a new one named
   *  after the file), every other entry after it in order. `ownPath`, the
   *  script the scan paired by name, joins an EMPTY list: the scan gives a
   *  fuzzy-paired script no variant list, so while a single association won
   *  that script was in no variant menu until Remove (C-08).
   *  An empty list with no own script still gets the associated script as
   *  its one entry (N-02): it is what the video plays. Left empty, the
   *  player's menu named "Default" after whatever the editor held, so after
   *  Add variation the association was in no entry and could not be picked
   *  again, and after a reload the new variation was shown as playing. */
  _variantsLeadingWith(variants, scriptPath, ownPath = null) {
    let list = Array.isArray(variants) ? variants : [];
    const key = canonicalPath(scriptPath);
    if (key && list.length === 0 && ownPath && canonicalPath(ownPath) !== key) {
      // Labelled as the scan labels a video's unlabelled script.
      list = [{ label: 'Default', path: ownPath, name: String(ownPath).split(/[\\/]/).pop() }];
    }
    if (!key || canonicalPath(list[0]?.path) === key) return list;
    const listed = list.find((v) => canonicalPath(v?.path) === key);
    const name = String(scriptPath).split(/[\\/]/).pop();
    const first = listed || { label: name.replace(/\.funscript$/i, ''), path: scriptPath, name };
    return [first, ...list.filter((v) => v !== listed)];
  }

  /**
   * The variant list to show for `videoPath` given a fresh scan of its
   * folder (app.js `_refreshCurrentVariantsFromDisk`, on opening the variant
   * menu). A user's association over the video's own sidecar leads with the
   * script that plays (single, a Multi Axis set's main, the main route's),
   * as at load (R4-06); otherwise the scan's list as it is.
   */
  variantsForVideo(videoPath, scanned) {
    const list = Array.isArray(scanned) ? scanned : [];
    const video = this._videosByPath?.get?.(videoPath);
    // A Multi Axis set's main or the main route's script leads too (R4-06
    // note, TODO triage 2026-11-23), as at load (_leadVariantsWithPlayed).
    if (!video?._manualAssociation || video._assocFallbackFrom || !video.funscriptPath) return list;
    return this._variantsLeadingWith(list, video.funscriptPath, video._ownFunscriptPath);
  }

  /**
   * The user's single association cannot be read (missing, offline, locked)
   * and the scan found the video's own script: play that one FOR NOW (R4-06).
   * In memory only: the association is kept (absence is never destructive;
   * `_keepsOwnOverride` stops every prune of it) and applies again at the
   * next scan or reload once its file is back. Returns true when it fell back.
   */
  _fallBackToOwnScript(video) {
    if (!video?._ownFunscriptPath || video._multiAxis || video._customRouting) return false;
    if (!video._manualAssociation || video._assocFallbackFrom) return false;
    if (canonicalPath(video._ownFunscriptPath) === canonicalPath(video.funscriptPath)) return false;
    video._assocFallbackFrom = video.funscriptPath;
    video.hasFunscript = true;
    video.funscriptPath = video._ownFunscriptPath;
    video.variants = video._ownVariants || [];
    video._statsReadFor = null;
    console.warn(`[Associations] Can't read ${video._assocFallbackFrom}: playing ${video.funscriptPath} for now (association kept)`);
    return true;
  }

  /**
   * Does this video's single association point AWAY from a script the scan
   * found for it by name? Then a miss of the associated file is never a
   * reason to drop it: the video plays its own script meanwhile and the
   * association applies again when the file is back (R4-06).
   */
  _keepsOwnOverride(videoPath, singlePath) {
    const video = this._videosByPath?.get?.(videoPath);
    const own = video?._ownFunscriptPath;
    return !!(own && singlePath && canonicalPath(own) !== canonicalPath(singlePath));
  }

  _syncVideoStateForActive(video, active, config) {
    this._rememberOwnScript(video);
    video._multiAxis = null;
    video._customRouting = null;
    video._assocFallbackFrom = null;
    video.variants = video._ownVariants;
    // Re-read the script on the next render, even at the same path: an
    // EroScripts download can overwrite the file it was associated with.
    video._statsReadFor = null;
    // Every caller is a save the user made, so the pairing is theirs now.
    video._autoAssigned = false;
    if (active === 'single') {
      this._showUserSingle(video, config);
    } else if (active === 'multi') {
      const hasAnyScript = !!config.main || Object.values(config.axes || {}).some(Boolean);
      video.hasFunscript = hasAnyScript;
      video.funscriptPath = config.main || null;
      video._manualAssociation = true;
      video._multiAxis = config;
      this._leadVariantsWithPlayed(video, config.main);
    } else if (active === 'custom') {
      const routes = config.routes || [];
      const mainRoute = routes.find(r => r.role === 'main');
      video.hasFunscript = !!mainRoute?.scriptPath;
      video.funscriptPath = mainRoute?.scriptPath || null;
      video._manualAssociation = true;
      video._customRouting = routes;
      this._leadVariantsWithPlayed(video, mainRoute?.scriptPath);
    } else {
      video.hasFunscript = false;
      video.funscriptPath = null;
      video._manualAssociation = false;
    }
  }

  /**
   * If the user is editing the currently-playing video's association, tear
   * down the app-level live routing state so the new active mode takes
   * effect immediately on the current playback instead of sticking with
   * whatever routing was loaded at play-time.
   */
  _tearDownLiveRoutingIfEditing(video) {
    if (!window.app || window.app._currentCustomRoutingVideoPath !== video.path) return;
    window.app._customRoutingActive = false;
    window.app._currentCustomRoutes = null;
    window.app._currentCustomRoutingVideoPath = null;
    if (window.app.buttplugSync) {
      window.app.buttplugSync._customRoutingActive = false;
      window.app.buttplugSync._axisAssignmentMap.clear();
      window.app.buttplugSync.clearAxisActions();
    }
    if (window.app.tcodeSync) {
      window.app.tcodeSync.clearAxisActions();
    }
  }

  // --- Subtitle Association ---

  async _associateSubtitle(video, cardEl) {
    if (this._unmatchedSubtitles.length > 0) {
      const ranked = rankFunscriptMatches(video.name, this._unmatchedSubtitles);

      const chosen = await Modal.open({
        title: t('library.associateSubtitleTitle'),
        onRender: (body, close) => {
          if (ranked.length > 0) {
            const list = document.createElement('div');
            list.className = 'modal-list';

            for (const match of ranked) {
              const row = document.createElement('button');
              row.className = 'modal-list-item';

              const label = document.createElement('span');
              label.className = 'modal-list-item-label';
              label.textContent = match.name;
              row.appendChild(label);

              const badge = document.createElement('span');
              const scoreClass = match.score >= 70 ? '--high' : match.score >= 40 ? '--medium' : '--low';
              badge.className = `library__match-score library__match-score${scoreClass}`;
              badge.textContent = `${match.score}%`;
              row.appendChild(badge);

              row.addEventListener('click', () => close({ path: match.path, name: match.name }));
              list.appendChild(row);
            }

            body.appendChild(list);
          } else {
            const msg = document.createElement('div');
            msg.className = 'modal-message modal-message--muted';
            msg.textContent = t('library.noSubtitleMatches');
            body.appendChild(msg);
          }

          const divider = document.createElement('div');
          divider.className = 'library__suggestion-divider';
          body.appendChild(divider);

          const browseRow = document.createElement('button');
          browseRow.className = 'modal-list-item library__assoc-action';
          browseRow.textContent = t('library.assoc.browse');
          browseRow.addEventListener('click', async () => {
            const result = await window.funsync.selectSubtitle();
            close(result);
          });
          body.appendChild(browseRow);
        },
      });

      if (!chosen) return;
      this._applySubtitleAssociation(video, cardEl, chosen.path, chosen.name);
    } else {
      const result = await window.funsync.selectSubtitle();
      if (!result) return;
      this._applySubtitleAssociation(video, cardEl, result.path, result.name);
    }
  }

  _applySubtitleAssociation(video, cardEl, subPath, subName) {
    const associations = this._settings.get('library.subtitleAssociations') || {};
    associations[video.path] = subPath;
    this._settings.set('library.subtitleAssociations', associations);

    // Remove from unmatched list
    this._unmatchedSubtitles = this._unmatchedSubtitles.filter((s) => s.path !== subPath);

    this._showSubtitleState(video, subPath, cardEl);
  }

  _removeSubtitleAssociation(video, cardEl) {
    const associations = this._settings.get('library.subtitleAssociations') || {};
    delete associations[video.path];
    this._settings.set('library.subtitleAssociations', associations);

    this._showSubtitleState(video, null, cardEl);
  }

  /**
   * The video's subtitle in memory and on its card after a pairing you made
   * was set, unpaired or put back (`subPath` null: none of yours). The card
   * is the one given while it is still on screen, else found by path: the
   * dialog that asked may have outlived the card it was opened from, and a
   * null card used to throw here (DESIGN-video-options.md (b)).
   */
  _showSubtitleState(video, subPath, cardEl = null) {
    if (!video) return;
    video.hasSubtitle = !!subPath;
    video.subtitlePath = subPath || null;
    video._manualSubtitle = !!subPath;

    const card = (cardEl?.isConnected ? cardEl : null) || this._cardForPath(video.path);
    if (!card) return;
    if (!subPath) {
      card.querySelector('.library__subtitle-badge')?.remove();
      return;
    }
    // Update subtitle badge on card — list view uses a different class.
    const thumbnailContainer = card.querySelector('.library__card-thumbnail')
      || card.querySelector('.library__list-thumb');
    if (thumbnailContainer) {
      let badge = thumbnailContainer.querySelector('.library__subtitle-badge');
      if (!badge) {
        badge = document.createElement('span');
        this._getOrCreateBadgesContainer(thumbnailContainer).appendChild(badge);
      }
      badge.className = 'library__subtitle-badge library__subtitle-badge--manual';
      badge.title = t('library.subtitleManualTitle');
      if (!badge.querySelector('svg')) {
        badge.appendChild(icon(Captions, { width: 14, height: 14, 'stroke-width': 2.5 }));
      }
    }
  }

  async _playVideo(video) {
    // Build a file-like object for app.loadVideo
    const fileData = {
      name: video.name,
      path: video.path,
      _isPathBased: true,
    };
    // A script with no video (2026-11-26): the app plays it in the script
    // player (_playFromLibrary sees the .funscript path); nothing of a
    // video's (its sidecars, subtitle, variants) is read for it.
    if (video._script) {
      if (video._playContextOverride) {
        fileData._playContext = video._playContextOverride;
        delete video._playContextOverride;
      } else {
        const at = this._filteredVideos ? this._filteredVideos.indexOf(video) : -1;
        if (at >= 0) {
          fileData._playContext = { source: 'library', sourceLabel: 'library', sourceContext: {}, list: this._filteredVideos.map((v) => v.path), index: at };
        }
      }
      delete video._autoPlayOnNextLoad;
      this._onPlayVideo(fileData, null, null, []);
      return;
    }
    // A saved stream: the app looks its page up and plays the fresh stream.
    if (video._stream) {
      fileData._stream = true;
      fileData.pageUrl = video.pageUrl;
      fileData.duration = video.duration || null;
    }

    // Snapshot the current visible list so Up Next can advance through the
    // user's filtered/sorted view. Snapshot is immutable for this play
    // session — sort/filter changes during playback don't retroactively
    // alter "next" (Norman: conceptual model).
    //
    // Up Next auto-advance routes back through this method with the next
    // video and a `_playContextOverride` so the original snapshot keeps
    // travelling forward (same list, index + 1) regardless of whether
    // the user changed filters mid-playback.
    if (video._playContextOverride) {
      fileData._playContext = video._playContextOverride;
      delete video._playContextOverride;
    } else {
      const ctxIndex = this._filteredVideos ? this._filteredVideos.indexOf(video) : -1;
      if (ctxIndex >= 0) {
        fileData._playContext = {
          source: 'library',
          sourceLabel: 'library',
          sourceContext: {},
          list: this._filteredVideos.map((v) => v.path),
          index: ctxIndex,
        };
      }
    }
    if (video._autoPlayOnNextLoad) {
      fileData._autoPlayOnLoad = true;
      delete video._autoPlayOnNextLoad;
    }

    const { funscriptData, subtitleData, variants } = await this.resolvePlayData(video);
    this._onPlayVideo(fileData, funscriptData, subtitleData, variants);
    // Its script was expected and not read: say so when it is there but
    // cannot be reached (a locked folder), once per script (R3-18).
    if (video.hasFunscript && video.funscriptPath && !funscriptData?.textContent) {
      noticeUnreadableScript(video.funscriptPath);
    }
  }

  /**
   * Everything playing `video` loads besides the file itself: its main
   * script with the companion axis files (`_multiAxis`) and custom routing
   * (`_customRouting`) attached, its subtitle and its script variants.
   *
   * Shared by a click (`_playVideo`), every Play All item (app.js
   * `_loadQueueItemContent`) and a playlist or category card click (FT-070),
   * so each loads exactly what a click on the library card does. Play All
   * used to read the main script only, and a multi-axis user got single-axis
   * output for the whole playlist (V72). It never touches the one-shot flags
   * (`_playContextOverride`, `_autoPlayOnNextLoad`): those ride a click.
   * `scriptError` is what a failed script read threw; `triedSidecar` is the
   * `<name>.funscript` it looked for quietly (FT-069), or null, so a caller
   * with its own guess doesn't read the same file again.
   */
  async resolvePlayData(video) {
    // If funscript is available, read it and build a funscript file-like object
    let funscriptData = null;
    let scriptError = null;
    let triedSidecar = null;
    if (video.hasFunscript && video.funscriptPath) {
      try {
        const readPath = video.funscriptPath;
        let content = await window.funsync.readFunscript(readPath);
        // A script associated under another name that cannot be read, with
        // the video's own `<video>.funscript` there: play that for now, keep
        // the association (R4-06). `variants` below is read after this.
        // Also when the scan's validator fell back while this read was out
        // (R4-06 fix-up): read what the video points at now.
        if (!content && (this._fallBackToOwnScript(video)
          || (video.funscriptPath && video.funscriptPath !== readPath))) {
          this._noteExpectedScriptMiss(video._assocFallbackFrom || readPath);
          content = await window.funsync.readFunscript(video.funscriptPath);
        }
        if (content) {
          const fsName = video.funscriptPath.split(/[\\/]/).pop();
          funscriptData = {
            name: fsName,
            textContent: content,
            // The file this copy came from. app.js caches this file's
            // embedded axes under it (the library badge and kebab look up
            // by `video.funscriptPath`), reads it again if the unsaved-edits
            // question saves it first, and points the script editor at it,
            // so a Save writes the script that was opened (R3 fix-up; it
            // used to derive `<video>.funscript`, a different file for an
            // association).
            _funscriptPath: video.funscriptPath,
          };

          // Attach multi-axis config if present
          if (video._multiAxis) {
            funscriptData._multiAxis = video._multiAxis;
          }
          // Attach custom routing config if present
          if (video._customRouting) {
            funscriptData._customRouting = video._customRouting;
          }
        } else {
          // Opening the video expected this script and it was not there
          // (moved, renamed, deleted, or its drive unplugged): `read-funscript`
          // answers null and logs at debug only, so say it here (FT-043).
          this._noteExpectedScriptMiss(video.funscriptPath);
        }
      } catch (err) {
        console.warn('Failed to read funscript:', err.message);
        scriptError = err;
      }
    } else if (!video.funscriptPath && !video._manualAssociation && !video._customRouting && video.path && !video._stream) {
      // (A saved stream has no folder to find a script beside.)
      // The record has no script and the user chose none: a
      // `<name>.funscript` dropped beside the video since the last scan
      // (there is no folder watcher) is played, as Play All and a playlist
      // card already did (FT-069). Quiet: most such videos really have no
      // script, so a miss is no toast and no warning. Nothing is stored; the
      // card catches up at the next Refresh.
      const sidecar = /\.[^/\\.]+$/.test(video.path)
        ? video.path.replace(/\.[^/\\.]+$/, '.funscript')
        : `${video.path}.funscript`;
      triedSidecar = sidecar;
      let content = null;
      try { content = await window.funsync.readFunscript(sidecar); } catch { /* quiet */ }
      if (content) {
        console.info('[Library] playing a script added since the last scan:', sidecar);
        funscriptData = {
          name: sidecar.split(/[\\/]/).pop(),
          textContent: content,
          _funscriptPath: sidecar,
        };
        // A scan-found companion set without a main (vib-only) rides along.
        if (video._multiAxis) funscriptData._multiAxis = video._multiAxis;
      }
    }

    // Attach multi-axis config even without a main funscript (vib-only case)
    if (!funscriptData && video._multiAxis) {
      funscriptData = { name: '', textContent: null, _multiAxis: video._multiAxis };
    }
    // Attach custom routing even if main script couldn't be read
    if (!funscriptData && video._customRouting) {
      funscriptData = { name: '', textContent: null, _customRouting: video._customRouting };
    }

    // If subtitle is available, read it and build a subtitle file-like object
    let subtitleData = null;
    if (video.hasSubtitle && video.subtitlePath) {
      try {
        const content = await window.funsync.readFunscript(video.subtitlePath); // reuse text reader
        if (content) {
          const subName = video.subtitlePath.split(/[\\/]/).pop();
          subtitleData = {
            name: subName,
            textContent: content,
          };
        }
      } catch (err) {
        console.warn('Failed to read subtitle:', err.message);
      }
    }

    return { funscriptData, subtitleData, variants: video.variants || [], scriptError, triedSidecar };
  }

  _registerWithBackend() {
    // Re-register videos with the VR content server / web remote backend.
    // Also pushes collections/playlists/categories so the phone can browse
    // the same groupings the desktop shows (view-only — no CRUD on phone).
    const port = this._settings.get('backend.port') || 5123;
    // Custom thumbnails reach the phone too (F7): the backend applies
    // frame pins to its thumb generation and serves uploaded posters
    // (validated inside the custom-thumbs dir, fetched lazily once).
    if (this._customThumbsDir === undefined) {
      this._customThumbsDir = null; // sentinel: fetch in flight
      window.funsync.getCustomThumbsDir?.()
        .then((dir) => {
          this._customThumbsDir = dir || null;
          // This registration went without the folder, and the backend
          // serves a poster only from a known one: after a reload the phone
          // and the headset showed the generated frame instead of the user's
          // poster until Library > Refresh (N-05, TODO triage 2026-11-23).
          // Once more, now with it, when some video has a poster.
          const thumbs = this._settings.get('library.customThumbnails') || {};
          if (dir && Object.values(thumbs).some((c) => customThumbImagePath(c))) this._registerWithBackend();
        })
        .catch(() => { this._customThumbsDir = null; });
    }
    // Fire-and-forget with a bounded retry: the backend now boots in
    // PARALLEL with the window, so the first post-scan registration can
    // race uvicorn coming up. A missed registration = empty phone/VR
    // Browse list until a manual refresh, so retry a few times instead.
    //
    // Each attempt builds its payload afresh, and a newer call supersedes
    // this one's retries, so a late retry never lands an older library,
    // VR override or grouping over a newer one. Mark as VR, then Reset VR,
    // while the backend restarts would otherwise leave HereSphere on 'vr'
    // whichever retry happened to land last (V68).
    const gen = (this._backendRegisterGen = (this._backendRegisterGen || 0) + 1);
    const attempt = (tryNo) => {
      if (gen !== this._backendRegisterGen) return;
      // Playlists, categories, and videoCategories live at the top of the
      // data-service cache (not under `settings.`), so use the dedicated
      // accessors. Collections live inside settings so `get()` is correct.
      //
      // Inline the per-video VR override so the backend (DeoVR/HereSphere
      // metadata + phone payload) agrees with the desktop without each
      // route having to re-read the settings map separately.
      const vrOverrides = this._settings.get('library.manualVRType') || {};
      // Each video's variation list as the desktop menu has it (FN-04, Dave
      // 2026-11-16: "yes variations should show on phone"): the hand-added
      // ones (`library.manualVariants`, under the video's own path, read
      // only: no re-home, nothing written) after the scan's, each with the
      // name the desktop shows and its "main" mark (FN-03). The phone, and
      // the backend's `?variant=` lookup, read the list from here.
      const manualVariants = this._settings.get('library.manualVariants') || {};
      // The phone's Flat view (#426): a video's saved spherical VR format
      // (projection, eye, view), so it opens as the desktop shows it.
      const vrFormats = this._settings.get('library.vrFormat') || {};
      // Disabled (zaikechi #381): the phone skips them in its Play all, Shuffle and Up Next too.
      const disabledMap = this._settings.get('library.disabledVideos') || {};
      // Saved streams stay on the desktop: the phone and VR play files the backend serves.
      const videosWithOverride = this._videos.filter((v) => !v._stream).map(v => {
        const override = vrOverrides[v.path];
        const variants = remoteVariantList(v, manualVariants[v.path]);
        const vrFormat = remoteVRFormat(vrFormats[v.path]);
        const extra = vrFormat ? { variants, vrFormat } : { variants };
        if (Object.prototype.hasOwnProperty.call(disabledMap, v.path)) extra.disabled = true;
        return override === 'vr' || override === 'flat'
          ? { ...v, ...extra, manualVRType: override }
          : { ...v, ...extra };
      });
      const payload = {
        videos: videosWithOverride,
        customThumbnails: Object.fromEntries(Object.entries(this._settings.get('library.customThumbnails') || {})
          .filter(([p]) => !isStreamPath(p))),
        customThumbsDir: this._customThumbsDir || undefined,
        // Sources are needed by the phone's folder-browse tree view — it
        // uses {id, name, path} to seed the source-root nodes so the tree
        // walker knows where to stop climbing.
        sources: this._settings.get('library.sources') || [],
        collections: this._settings.get('library.collections') || [],
        playlists: this._settings.getPlaylists ? this._settings.getPlaylists() : [],
        categories: this._settings.getCategories ? this._settings.getCategories() : [],
        videoCategories: (this._settings._cache && this._settings._cache.videoCategories) || {},
      };
      try {
        fetch(`http://127.0.0.1:${port}/api/media/register`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        }).then((res) => {
          if (!res.ok) throw new Error(`register ${res.status}`);
        }).catch(() => {
          if (tryNo < 5) setTimeout(() => attempt(tryNo + 1), 2000);
        });
      } catch { /* ignore */ }
    };
    attempt(0);
  }

  _escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  // --- Playlist / Category integration ---

  /**
   * Rebuild the category marks on every card currently in the DOM.
   *
   * Cheap: only rendered cards are touched, and virtual scrolling means that
   * is a screenful, not the whole library. Anything scrolled out gets the
   * new mark when it is next built.
   */
  _repaintAllCategoryDots() {
    if (!this._container) return;
    const cards = this._container.querySelectorAll('[data-video-path]');
    for (const card of cards) {
      const path = card.dataset.videoPath;
      if (path) this._updateCardCategoryDots(card, path);
    }
  }

  _updateCardCategoryDots(cardEl, videoPath) {
    // Fallback for list view so dots appear immediately after assign,
    // not only after the next re-render.
    const thumbnail = cardEl.querySelector('.library__card-thumbnail')
      || cardEl.querySelector('.library__list-thumb');
    if (!thumbnail) return;

    // Remove existing dots
    const existing = thumbnail.querySelector('.library__card-category-dots');
    if (existing) existing.remove();

    const catIds = this._settings.getVideoCategories(videoPath);
    if (catIds.length === 0) return;

    const dotsContainer = document.createElement('div');
    dotsContainer.className = 'library__card-category-dots';
    const allCats = this._settings.getCategories();
    for (const catId of catIds) {
      const cat = allCats.find((c) => c.id === catId);
      if (cat) {
        const dot = createCategoryMark(cat, { className: 'library__card-category-dot', size: 12 });
        dot.title = cat.name;
        dotsContainer.appendChild(dot);
      }
    }
    thumbnail.appendChild(dotsContainer);
  }

  // --- Multi-select mode ---

  _toggleSelectMode() {
    if (this._selectMode) {
      this._exitSelectMode();
    } else {
      this._enterSelectMode();
    }
  }

  _enterSelectMode() {
    this._selectMode = true;
    this._selectedPaths = new Set();

    const btn = this._container.querySelector('.library__select-mode-btn');
    if (btn) btn.textContent = t('library.selectModeCancel');

    const bar = this._container.querySelector('.library__selection-bar');
    if (bar) {
      bar.hidden = false;
      // Scripts (2026-11-26): only Add to playlist applies to a script.
      bar.querySelectorAll('.library__selection-action').forEach((b) => {
        b.hidden = this._activeTab === 'scripts' && b.dataset.action !== 'playlist';
      });
    }

    // Show checkboxes on all cards
    this._container.querySelectorAll('.library__card-checkbox').forEach((cb) => {
      cb.hidden = false;
    });
    this._updateSelectionCount();
  }

  _exitSelectMode() {
    this._selectMode = false;
    this._selectedPaths = new Set();
    this._selectionAnchor = null;

    if (!this._container) return;

    const btn = this._container.querySelector('.library__select-mode-btn');
    if (btn) btn.textContent = t('library.selectModeEnter');

    const bar = this._container.querySelector('.library__selection-bar');
    if (bar) bar.hidden = true;

    // Hide checkboxes and remove selected state
    this._container.querySelectorAll('.library__card-checkbox').forEach((cb) => {
      cb.hidden = true;
      cb.classList.remove('library__card-checkbox--checked');
    });
    this._container.querySelectorAll('.library__card--selected').forEach((card) => {
      card.classList.remove('library__card--selected');
    });
  }

  /**
   * Push `_selectedPaths` onto one card's DOM — border AND tick together.
   *
   * Bug, 2026-08-06 (Dave): selecting items showed the border and the tick,
   * then the tick vanished as soon as anything caused a re-render. Card
   * creation restored `library__card--selected` from `_selectedPaths` but
   * never re-applied `library__card-checkbox--checked`, so the two halves of
   * "this is selected" drifted apart on every rebuild — and with virtual
   * scrolling, cards rebuild constantly.
   *
   * Both states now come from ONE place, so they cannot disagree. Called on
   * creation, on toggle, and on bulk select.
   */
  _applySelectionState(el, videoPath) {
    if (!el) return;
    const selected = this._selectedPaths.has(videoPath);
    el.classList.toggle('library__card--selected', selected);
    const cb = el.querySelector('.library__card-checkbox');
    if (cb) {
      // Visibility belongs here too: a card rebuilt WHILE in select mode was
      // getting `hidden` from the creation-time value, which is correct, but
      // keeping it in one place means bulk paths can't miss it either.
      cb.hidden = !this._selectMode;
      cb.classList.toggle('library__card-checkbox--checked', selected);
    }
  }

  /**
   * Single entry point for a click while selecting.
   *
   * Shift extends from the anchor; a plain click toggles and sets a new
   * anchor. Shift ENTERS select mode if it is not already on, so the gesture
   * works straight from browsing.
   */
  _handleSelectionClick(cardEl, videoPath, e) {
    const shift = !!(e && e.shiftKey);
    if (!this._selectMode) {
      // Preserve any anchor across the mode switch — _enterSelectMode clears
      // the selection, and we want the range that follows to still work.
      const keep = this._selectionAnchor;
      this._enterSelectMode();
      this._selectionAnchor = keep;
    }

    if (shift) {
      const paths = rangeBetween(this._filteredItems, this._selectionAnchor, videoPath);
      // ADDITIVE, not replace. Someone bulk-tagging across several ranges
      // should not lose the earlier ones to a mis-click; Cancel Select is the
      // escape hatch. Explorer replaces here, but this mode is explicit.
      for (const p of paths) this._selectedPaths.add(p);
      this._selectionAnchor = nextAnchor(this._selectionAnchor, videoPath, true);
      this._repaintSelection();
      this._updateSelectionCount();
      return;
    }

    this._toggleCardSelection(cardEl, videoPath);
    this._selectionAnchor = nextAnchor(this._selectionAnchor, videoPath, false);
  }

  /**
   * Push `_selectedPaths` onto every card currently in the DOM.
   *
   * Only the rendered window needs touching: selection lives in the Set, and
   * `_applySelectionState` restores it on card creation, so items further down
   * a range render correctly when the user scrolls to them. Virtual scrolling
   * would otherwise make an off-screen range invisible.
   */
  _repaintSelection() {
    this._container?.querySelectorAll('[data-video-path]').forEach((el) => {
      const p = el.dataset.videoPath;
      if (p) this._applySelectionState(el, p);
    });
  }

  /** Ctrl+A — select everything in the current filter, entering select mode. */
  selectAllVisible() {
    if (!this._selectMode) this._enterSelectMode();
    const paths = allSelectablePaths(this._filteredItems);
    for (const p of paths) this._selectedPaths.add(p);
    this._repaintSelection();
    this._updateSelectionCount();
    return paths.length;
  }

  _toggleCardSelection(card, videoPath) {
    if (this._selectedPaths.has(videoPath)) {
      this._selectedPaths.delete(videoPath);
    } else {
      this._selectedPaths.add(videoPath);
    }
    this._applySelectionState(card, videoPath);
    this._updateSelectionCount();
  }

  _updateSelectionCount() {
    const countEl = this._container?.querySelector('.library__selection-count');
    if (countEl) {
      const n = this._selectedPaths.size;
      countEl.textContent = t('library.selectionCount', { count: n });
    }
  }

  async _bulkAddToPlaylist() {
    if (this._selectedPaths.size === 0) return;
    if (await this._addPathsToPlaylist([...this._selectedPaths])) this._exitSelectMode();
  }

  /**
   * Ask which playlist, then add these paths in ONE write. With no playlist
   * yet, name one first. Returns whether anything was added.
   */
  async _addPathsToPlaylist(paths) {
    if (!paths?.length) return false;
    const playlists = this._settings.getPlaylists();
    if (playlists.length === 0) {
      const name = await Modal.prompt(t('library.createPlaylistFirstTitle'), t('library.createPlaylistFirstLabel'));
      if (!name) return false;
      const pl = await this._settings.addPlaylist(name);
      this._settings.addVideosToPlaylist(pl.id, paths);
      return true;
    }
    const items = playlists.map((pl) => ({
      id: pl.id,
      label: pl.name,
      subtitle: t('library.videoCountSubtitle', { count: pl.videoPaths.length }),
    }));
    const selectedId = await Modal.selectFromList(t('library.addToPlaylistTitle'), items);
    if (!selectedId) return false;
    // ONE write for all of them (triage 2026-11-23): one addVideoToPlaylist
    // per video rewrote config.json each time, 7-14 ms apiece.
    this._settings.addVideosToPlaylist(selectedId, paths);
    return true;
  }

  async _bulkAssignCategory() {
    if (this._selectedPaths.size === 0) return;
    const categories = this._settings.getCategories();
    const items = categories.map((c) => ({ id: c.id, label: c.name }));
    const { promptCreateCategory } = await import('../js/category-create-modal.js');
    const selectedId = await Modal.selectFromList(t('library.assignCategoryTitle'), items, {
      createLabel: t('library.newCategoryInlineLabel'),
      onCreateNew: () => promptCreateCategory({ settings: this._settings }),
    });
    if (selectedId) {
      // One write for the whole selection (TODO triage 2026-11-23), as the
      // bulk Add to playlist.
      this._settings.assignCategoryToVideos([...this._selectedPaths], selectedId);
      for (const path of this._selectedPaths) {
        // Update dots on visible cards
        const card = this._container?.querySelector(`[data-video-path="${CSS.escape(path)}"]`);
        if (card) this._updateCardCategoryDots(card, path);
      }
      this._exitSelectMode();
    }
  }

  /**
   * Bulk "Assign script to selected" (zaikechi #209/#221 — the enabler
   * for many-videos-per-script + balance-shuffle-by-script): multi-select
   * N videos → native funscript picker ONCE. NON-DESTRUCTIVE (Dave,
   * 2026-08-04): a video that already has a main script keeps it — the
   * picked script is added as a VARIATION instead (manualVariants, same
   * shape as the player's "+ Add variation" flow). Only videos with no
   * script at all get it as their single-axis association (existing
   * multi/custom slots preserved). Registers with the backend so the
   * phone/VR see new pairings.
   */
  async _bulkAssignScript() {
    if (this._selectedPaths.size === 0) return;
    const picked = await window.funsync.selectFunscript();
    if (!picked?.path) return; // dialog cancelled
    // Saved streams keep their script on their own record (2026-11-23).
    for (const p of [...this._selectedPaths]) {
      if (isStreamPath(p)) { this.setStreamScript(p, picked.path); this._selectedPaths.delete(p); }
    }
    if (this._selectedPaths.size === 0) { this.onStreamsChanged(); return; }
    const associations = { ...(this._settings.get('library.associations') || {}) };
    const manualVariants = { ...(this._settings.get('library.manualVariants') || {}) };
    // Variation label = script filename without extension (same default the
    // single-video add-variation naming modal suggests).
    const variantLabel = (picked.name || picked.path.split(/[\\/]/).pop() || '')
      .replace(/\.funscript$/i, '');
    let assignedMain = 0;
    let addedVariation = 0;
    for (const path of this._selectedPaths) {
      const video = this._videosByPath?.get(path) || (this._videos || []).find((v) => v.path === path);
      const entry = normalizeAssociation(associations[path]);
      // A one-video folder's first script (FT-102) is only offered, not the
      // video's own: with the setting on the picked script went in as a
      // variation behind it, so the video went on playing "Round 1".
      const folderMain = !!video?._folderVariantMain && !video._manualAssociation;
      const mainPath = (folderMain ? null : video?.funscriptPath) || entry.single || null;
      if (!mainPath) {
        // No script yet → the picked script becomes the main association.
        associations[path] = buildAssociationEntry('single', picked.path, entry.multi, entry.custom);
        if (video && folderMain) {
          // It leads the menu (index 0 is what a load plays); the folder's
          // scripts stay after it.
          this._showUserSingle(video, picked.path);
        } else if (video) {
          video.hasFunscript = true;
          video.funscriptPath = picked.path;
          video._manualAssociation = true;
        }
        assignedMain++;
      } else {
        // Has a main script → NEVER overwrite; add as a variation instead.
        if (mainPath === picked.path) continue; // it already IS the main
        const list = manualVariants[path] ? [...manualVariants[path]] : [];
        if (!list.some((v) => v.path === picked.path)) {
          list.push({ label: variantLabel, path: picked.path, name: picked.name || variantLabel });
          manualVariants[path] = list;
          addedVariation++;
        }
      }
    }
    if (assignedMain > 0) this._settings.set('library.associations', associations);
    if (addedVariation > 0) this._settings.set('library.manualVariants', manualVariants);
    // Phone / VR content server must see the new pairings too.
    this._registerWithBackend();
    const { showToast } = await import('../js/toast.js');
    showToast(t('library.bulkScriptAssigned', {
      count: assignedMain + addedVariation,
      name: picked.name || '',
    }), 'success');
    this._exitSelectMode();
    // Re-render so cards pick up funscript badges / move to the Matched tab.
    this._applyFilters();
  }

  async _bulkPromptVRType() {
    if (this._selectedPaths.size === 0) return;
    const items = [
      { id: 'vr', label: t('library.vrOptionMark'), subtitle: t('library.vrOptionMarkSub') },
      { id: 'flat', label: t('library.vrOptionFlat'), subtitle: t('library.vrOptionFlatSub') },
      { id: 'reset', label: t('library.vrOptionReset'), subtitle: t('library.vrOptionResetSub') },
    ];
    const choice = await Modal.selectFromList(t('library.setVRTitle'), items);
    if (!choice) return;
    const paths = Array.from(this._selectedPaths);
    await this._bulkSetVRType(paths, choice);
    this._exitSelectMode();
  }

  async _bulkAddToCollection() {
    if (this._selectedPaths.size === 0) return;
    const collections = this._settings.get('library.collections') || [];
    if (collections.length === 0) {
      const { showToast } = await import('../js/toast.js');
      showToast(t('library.noLibrariesYet'), 'info');
      return;
    }
    const items = collections.map(c => ({
      id: c.id,
      label: c.name,
      subtitle: t('library.videoCount', { count: c.videoPaths.length }), // in the language chosen (B102)
    }));
    const selectedId = await Modal.selectFromList(t('library.addToCollectionTitle'), items);
    if (selectedId) {
      const idx = collections.findIndex(c => c.id === selectedId);
      if (idx >= 0) {
        // Route through the sync-aware helper so synced collections get
        // the right mutation (un-exclude vs additive include) rather
        // than a blind videoPaths push.
        const { addVideoToCollection } = await import('../js/collection-sync.js');
        const sources = this._settings.get('library.sources') || [];
        let col = collections[idx];
        for (const path of this._selectedPaths) {
          const { col: next } = addVideoToCollection(col, path, sources, this._folderIndex, descendantsOf);
          col = next;
        }
        collections[idx] = col;
        this._settings.set('library.collections', collections);
      }
      this._exitSelectMode();
    }
  }

  /**
   * Delegated contextmenu handler. A right-click on a card shows the quick
   * menu at the cursor (SCOPE-queue-panel.md §4.6): Play next, Add to queue,
   * All options… (DESIGN-video-options.md (a)). A KEYBOARD contextmenu
   * (Shift+F10, the Menu key) on a focused control in a card opens the video
   * options dialog instead: the keydown that made it set `_contextMenuByKey`
   * (a mouse press clears it), and the focus is in that card.
   */
  _handleCardContextMenu(e) {
    const byKey = this._contextMenuByKey;
    this._contextMenuByKey = false;
    const card = e.target?.closest?.('.library__card, .library__list-item');
    if (!card || !this._container?.contains(card)) return;
    const path = card.dataset.videoPath;
    if (!path) return;
    e.preventDefault();
    const scriptEntry = isScriptPath(path) ? this.getVideoByPath(path) : null;
    if (scriptEntry?._script) {
      const r = card.getBoundingClientRect();
      this._showScriptMenu(scriptEntry, byKey ? r.left + 16 : e.clientX, byKey ? r.top + 16 : e.clientY,
        { fromKeyboard: byKey, opener: card.querySelector('.library__kebab-btn, .library__list-kebab') });
      return;
    }
    const focused = document.activeElement;
    if (byKey && focused && card.contains(focused)) {
      const video = this.getVideoByPath(path);
      if (video) {
        this._openVideoOptions(video);
        return;
      }
    }
    this._showQueueContextMenu(e.clientX, e.clientY, path);
  }

  _showQueueContextMenu(x, y, path, entries = null, { fromKeyboard = false, opener = null } = {}) {
    // Dismiss any existing one
    this._dismissQueueContextMenu();
    const menu = document.createElement('div');
    menu.className = 'library__queue-context-menu';
    menu.setAttribute('role', 'menu');
    menu.style.position = 'fixed';
    menu.style.left = `${x}px`;
    menu.style.top = `${y}px`;
    const item = (text, run, pos = null) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.setAttribute('role', 'menuitem');
      if (pos) btn.dataset.pos = pos;
      btn.textContent = text;
      btn.addEventListener('click', () => {
        this._dismissQueueContextMenu();
        run();
      });
      return btn;
    };
    if (entries) {
      // A script's own menu (the Scripts filter, 2026-11-26).
      for (const [text, run, pos] of entries) menu.appendChild(item(text, run, pos));
    } else if (this._onAddToQueue) {
      // "Play next" first, in the order of the options dialog's header.
      menu.appendChild(item(t('queuePanel.contextAddToQueueNext'), () => this._onAddToQueue?.(path, 'next'), 'next'));
      menu.appendChild(item(t('queuePanel.contextAddToQueue'), () => this._onAddToQueue?.(path, 'end'), 'end'));
      const sep = document.createElement('div');
      sep.className = 'library__queue-context-separator';
      sep.setAttribute('role', 'separator');
      menu.appendChild(sep);
    }
    if (!entries) {
      menu.appendChild(item(t('library.contextAllOptions'), () => {
        const video = this.getVideoByPath(path);
        if (video) this._openVideoOptions(video);
      }, 'options'));
    }
    document.body.appendChild(menu);
    this._activeQueueContextMenu = menu;
    // Reposition if it overflows viewport
    const rect = menu.getBoundingClientRect();
    if (rect.right > window.innerWidth) menu.style.left = `${window.innerWidth - rect.width - 8}px`;
    if (rect.bottom > window.innerHeight) menu.style.top = `${window.innerHeight - rect.height - 8}px`;
    // Auto-dismiss: a click or right-click outside closes THIS menu. Both
    // listeners go when it closes, however it closes (an item, Escape, All
    // options…, a click away): left behind, the next right-click's new menu
    // was removed by the old menu's contextmenu listener, so the quick menu
    // opened once per session (verify-1, review-a RA-5).
    const dismiss = (ev) => {
      if (this._activeQueueContextMenu === menu && !menu.contains(ev.target)) this._dismissQueueContextMenu();
    };
    this._activeQueueContextMenuArm = setTimeout(() => {
      this._activeQueueContextMenuArm = null;
      document.addEventListener('click', dismiss);
      document.addEventListener('contextmenu', dismiss);
    }, 0);
    this._activeQueueContextMenuDismiss = dismiss;
    // Escape closes it, and only it (capture, so the player's own Escape —
    // the queue panel, the A-B loop — does not act on the same press).
    const onKey = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopImmediatePropagation();
      this._dismissQueueContextMenu();
    };
    document.addEventListener('keydown', onKey, true);
    this._activeQueueContextMenuKey = onKey;
    // The keyboard (B096, test day 2026-11-26): a script card's ⋮ opened with
    // Enter left the focus on ⋮ and the arrows went nowhere, so nothing in it
    // could be reached. Now Down / Up / Home / End move through the items
    // (the WAI-ARIA menu pattern, menu-keys.js), opened from the keyboard the
    // first item takes the focus, and when it closes (Escape, a choice) the
    // focus goes back to what opened it.
    menu.addEventListener('keydown', (ev) => {
      if (ev.altKey || ev.ctrlKey || ev.metaKey || ev.shiftKey) return;
      if (moveMenuFocus(menu, ev.key)) ev.preventDefault();
    });
    this._activeQueueContextMenuOpener = opener && opener.isConnected ? opener : null;
    if (fromKeyboard) focusMenuFromKeyboard(menu);
  }

  _dismissQueueContextMenu() {
    if (this._activeQueueContextMenu) {
      const hadFocus = this._activeQueueContextMenu.contains(document.activeElement);
      this._activeQueueContextMenu.remove();
      this._activeQueueContextMenu = null;
      // Back to its opener (B096) when the focus was in it.
      const opener = this._activeQueueContextMenuOpener;
      this._activeQueueContextMenuOpener = null;
      if (hadFocus && opener?.isConnected) opener.focus();
    }
    if (this._activeQueueContextMenuKey) {
      document.removeEventListener('keydown', this._activeQueueContextMenuKey, true);
      this._activeQueueContextMenuKey = null;
    }
    if (this._activeQueueContextMenuArm) {
      clearTimeout(this._activeQueueContextMenuArm);
      this._activeQueueContextMenuArm = null;
    }
    if (this._activeQueueContextMenuDismiss) {
      document.removeEventListener('click', this._activeQueueContextMenuDismiss);
      document.removeEventListener('contextmenu', this._activeQueueContextMenuDismiss);
      this._activeQueueContextMenuDismiss = null;
    }
  }

}
